-- Source: Sheets Dump/. Regenerate with `make import`.
-- mcq_questions: 757 questions for subject accounts.

MERGE INTO mcq_questions AS t
USING (
    SELECT v.question_code, c.id AS chapter_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.difficulty, v.points, v.hint, v.explanation
    FROM (VALUES
        ('acc11-01-mcq-0001', 1, 'During Chandragupta Maurya''s regime in India, which minister wrote ''Arthashastra'', containing references to maintaining accounting records?', 'Birbal', 'Kautilya', 'Charaka', 'Aryabhata', 'b', 1, 3, 'Think of the famous ancient Indian political strategist also known as Chanakya.', 'In India during Chandragupta Maurya''s regime, Minister Kautilya wrote ''Arthashastra'', where references regarding the way of maintaining accounting records can be traced.'),
        ('acc11-01-mcq-0002', 1, 'In Indian accounting history, what traditional name was given to the historical system of maintaining accounting records traced back to Kautilya''s Arthashastra?', 'Jama Kharcha', 'Khatauni', 'Vahi Khata', 'Deshi Nama', 'd', 1, 3, 'Look for the specific indigenous term mentioned in the chapter''s evolution section.', 'After the references in Arthashastra, the Indian historical method of maintaining accounting records was called ''Deshi Nama''.'),
        ('acc11-01-mcq-0003', 1, 'According to the historical evolution of accounting described in the text, in which century were the records of debit and credit first found?', '12th century', '16th century', '14th century', '10th century', 'a', 1, 3, 'This century predates Luca Pacioli''s treatise by roughly three hundred years.', 'The records of debit and credit were found in the 12th century itself, when agents managed properties for wealthy owners.'),
        ('acc11-01-mcq-0004', 1, 'In which year did the Italian merchant Luca De Bargo Pacioli introduce the Double-Entry Book-keeping system?', '1594', '1794', '1494', '1894', 'c', 1, 3, 'It was in the late 15th century, just two years after Columbus reached the Americas.', 'In the year 1494, Luca De Bargo Pacioli, an Italian merchant, introduced the Double-Entry Book-keeping system.'),
        ('acc11-01-mcq-0005', 1, 'During the Industrial Revolution in the 18th and 19th centuries, what key structural characteristic of Joint Stock Companies necessitated comprehensive financial accounting systems?', 'Separation of ownership from management', 'Mandatory adoption of cash basis accounting', 'Complete restriction of external bank borrowings', 'Elimination of corporate tax liabilities', 'a', 2, 5, 'Consider who owns the company versus who runs day-to-day operations.', 'Joint Stock Companies emerged with large-scale operations involving separation of ownership from management, requiring detailed records to safeguard the interests of owners and investors.'),
        ('acc11-01-mcq-0006', 1, 'Which specialized branch of accounting emerged in the 20th century primarily due to the need for financial analysis to support managerial decision-making?', 'Social Responsibility Accounting', 'Deshi Nama', 'Management Accounting', 'Forensic Accounting', 'c', 1, 3, 'Its name directly reflects its purpose of assisting managers.', 'In the 20th century, the need for analysis of financial information for managerial decision making caused the emergence of Management Accounting.'),
        ('acc11-01-mcq-0007', 1, 'In the 21st century, accounting has gradually developed from being individual-centric into which advanced domain due to widespread growth in business activities?', 'Government Budgeting', 'Tax Audit Accounting', 'Social Responsibility Accounting', 'Single-Entry Book-keeping', 'c', 1, 3, 'Think of the concept linking corporate operations to society''s welfare in modern times.', 'Though accounting was individual-centric in the initial stages, it has gradually developed into Social Responsibility Accounting in the 21st century.'),
        ('acc11-01-mcq-0008', 1, 'Who defined book-keeping as ''The art of analyzing and recording business transactions, reporting results of business operations through periodic statements and interpreting such results for purposes of effective control of future operations''?', 'Nocth Cott', 'Richard E. Strahelm', 'J. R. Batliboi', 'R. N. Carter', 'b', 1, 3, 'Identify the author whose definition explicitly highlights reporting through periodic statements and effective control of future operations.', 'Richard E. Strahelm defined book-keeping with a focus on analyzing, recording, reporting periodic results, and interpreting them for effective control of future operations.'),
        ('acc11-01-mcq-0009', 1, 'Which scholar defined book-keeping simply as ''an art of recording business dealings in a set of books''?', 'J. R. Batliboi', 'Prof. Robert N. Anthony', 'Kohler', 'Luca Pacioli', 'a', 1, 3, 'This is the shortest definition of book-keeping given in the textbook.', 'J. R. Batliboi gave the concise definition: ''Book-keeping is an art of recording business dealings in a set of books.'''),
        ('acc11-01-mcq-0010', 1, 'According to Nocth Cott, book-keeping is specifically defined as an art of recording in the books of accounts:', 'All personal transactions of company directors', 'The qualitative performance of human capital', 'The managerial forecasts and production estimates', 'The monetary aspects of commercial or financial transactions', 'd', 1, 3, 'Focus on Nocth Cott''s specific emphasis on ''monetary aspects''.', 'Nocth Cott defined book-keeping as ''an art of recording in the books of accounts the monetary aspects of commercial or financial transactions.'''),
        ('acc11-01-mcq-0011', 1, 'According to R. N. Carter, book-keeping is the science and art of correctly recording in books of accounts all those transactions that result in:', 'Transfer of money or money''s worth', 'Future social responsibility pledges', 'Generation of untaxed personal gains', 'Transfer of legal title of real estate', 'a', 1, 3, 'Look for the phrase dealing with money or its economic equivalent.', 'R. N. Carter defined book-keeping as ''the science and art of correctly recording in the books of accounts, all those business transactions that results in transfer or money or money''s worth.'''),
        ('acc11-01-mcq-0012', 1, 'Which of the following is an authentic feature of book-keeping as stated in the chapter?', 'Analytical interpretation of national GDP trends is performed', 'Only financial transactions are recorded based on rules and regulations', 'Records are prepared for an indefinite period without any time frame', 'Both monetary and non-monetary personal sentiments are recorded', 'b', 1, 3, 'Book-keeping strictly restricts its scope to financial events following established norms.', 'The features of book-keeping clearly state that only financial transactions are recorded, it is for a specific period, and records are based on rules and regulations.'),
        ('acc11-01-mcq-0013', 1, 'Which of the following is NOT an objective of book-keeping?', 'To know the profit or loss of the business during the financial year', 'To formulate the nation''s annual foreign monetary policy', 'To know what the businessman owes to others and what others owe to him', 'To serve as a permanent record that can be produced as evidence', 'b', 1, 3, 'Eliminate the macroeconomic function of the government/central bank.', 'Formulating national monetary policy is a central bank function, not an objective of micro-level business book-keeping.'),
        ('acc11-01-mcq-0014', 1, 'How does book-keeping specifically benefit a ''Customer'' according to the chapter''s utility section?', 'Enables them to understand the financial position and be assured about the supply of goods', 'Grants them voting rights at the annual general board meeting', 'Ensures they receive dividend payments each quarter', 'Assists them in auditing the company''s internal tax files', 'a', 2, 5, 'Customers want to know if their supplier is stable enough to keep delivering orders.', 'Under Utility of Book-keeping: ''Customer can easily understand financial position of the business. He can be assured about supply of goods.'''),
        ('acc11-01-mcq-0015', 1, 'Why is book-keeping important for a businessman when legal disputes arise?', 'It allows the businessman to evade judicial summons', 'It serves as financial evidence to be produced in a court of law', 'It automatically dismisses claims filed by creditors', 'It replaces the need for hiring a legal attorney', 'b', 1, 3, 'Books of accounts act as documented, permanent proof.', 'Book-keeping provides a permanent record that serves as financial evidence that can be produced in a court of law in case of disputes.'),
        ('acc11-01-mcq-0016', 1, 'In terms of operational stages in accounting, which of the following statements correctly distinguishes Book-keeping from Accountancy?', 'Book-keeping deals only with auditing, whereas Accountancy deals with data entry', 'Accountancy is the primary stage, whereas Book-keeping is the secondary stage', 'Both Book-keeping and Accountancy operate exclusively at the terminal stage', 'Book-keeping is the primary stage and base for accounting, while Accountancy includes secondary stages of analysis and interpretation', 'd', 2, 5, 'One provides the baseline recording, and the other builds upon it to analyze and interpret.', 'Book-keeping is the primary stage and provides the foundation, whereas Accountancy encompasses both the primary base and the secondary stage of analysis and interpretation.'),
        ('acc11-01-mcq-0017', 1, 'In the structural division of labor in an organization, who is typically responsible for Book-keeping versus Accountancy?', 'Junior staff is responsible for keeping records (book-keeping), while senior staff is responsible for keeping accounts (accountancy)', 'Both functions are exclusively reserved for government tax inspectors', 'Board of Directors do book-keeping, while apprentices handle accountancy', 'Senior staff is responsible for book-keeping, and junior staff for accountancy', 'a', 2, 5, 'Recording routine entries requires basic operational skills, while compiling reports requires senior expertise.', 'As per the distinction table, junior staff is responsible for keeping records in book-keeping, whereas senior staff is responsible for keeping accounts in accountancy.'),
        ('acc11-01-mcq-0018', 1, 'What are the primary end results (outcomes) of Book-keeping compared to Accountancy?', 'Book-keeping results in Balance Sheet; Accountancy results in Journal only', 'Book-keeping results in Share Certificates; Accountancy results in Petty Cash Books', 'Book-keeping results in Journal and Ledger; Accountancy results in Profit & Loss Account and Balance Sheet', 'Book-keeping results in Cash Flow Statements; Accountancy results in Purchase Invoices', 'c', 2, 5, 'Day-to-day books of original entry versus final annual financial statements.', 'Book-keeping basically results in the Journal and Ledger, while Accountancy produces the final financial statements: Profit and Loss A/c and Balance Sheet.'),
        ('acc11-01-mcq-0019', 1, 'Why can management NOT take critical business decisions solely based on book-keeping data without accountancy?', 'Book-keeping entries are erased at the end of every week', 'Book-keeping is prepared exclusively in foreign currencies', 'Book-keeping provides only raw day-to-day records without analytical interpretation and compiled reports', 'Book-keeping data is legally invalid in business', 'c', 2, 5, 'Book-keeping does not perform analysis or synthesize high-level reports.', 'Book-keeping does not involve analysis or interpretation. Accountants analyze and interpret book-keeping data and compile it into reports that management relies upon for decisions.'),
        ('acc11-01-mcq-0020', 1, 'Who defined Accountancy as ''the entire body of the theory and process of accounting''?', 'R. N. Carter', 'Kohler', 'Prof. Robert N. Anthony', 'J. R. Batliboi', 'b', 1, 3, 'A concise definition of the discipline''s entire body of theory.', 'Kohler defined Accountancy as: ''Accountancy refers to the entire body of the theory and process of accounting.'''),
        ('acc11-01-mcq-0021', 1, 'Prof. Robert N. Anthony defined accounting as a means of doing what in monetary terms regarding business transactions?', 'Inspecting, taxing, licensing and liquidating', 'Eliminating, concealing, discounting and bargaining', 'Printing, advertising, marketing and auctioning', 'Collecting, summarizing, analyzing and reporting', 'd', 1, 3, 'Look for the four operational stages mentioned in his quotation.', 'Prof. Robert N. Anthony defined accounting as: ''Nearly every business enterprise has an accounting system. It is a means of collecting, summarizing, analyzing and reporting in monetary terms information about the business transactions.'''),
        ('acc11-01-mcq-0022', 1, 'Under the Cash Basis of accounting, when are revenues and expenses recognized?', 'When sales orders are received and purchase contracts are drafted', 'At the start of the government fiscal calendar year', 'When invoices are mailed, regardless of payment date', 'When actual cash is received and actual cash is paid, respectively', 'd', 1, 3, 'Recognition strictly depends on the physical movement of currency.', 'Under cash basis of accounting, revenue is recognized when cash is received and expenses are recognized when cash is paid.'),
        ('acc11-01-mcq-0023', 1, 'Which of the following groups commonly adopts the Cash Basis of accounting?', 'Professionals such as Doctors, Lawyers, CAs, and Not-for-Profit Organisations', 'Joint Stock trading companies listed on stock exchanges', 'Commercial banks and public limited retail chains', 'Large multinational manufacturing corporations', 'a', 2, 5, 'Think of service providers like medical and legal practitioners.', 'The cash method of accounting is usually followed by professionals such as Doctors, Lawyers, Chartered Accountants (CA), and Not-for-Profit Organisations.'),
        ('acc11-01-mcq-0024', 1, 'Under the Accrual (Mercantile) basis of accounting, revenue is recognized when:', 'It is earned or accrued during the accounting period, whether received or not', 'The firm prepares its closing income tax returns', 'It is realized in physical banknotes only', 'The customer fully settles their account after three years', 'a', 2, 5, 'Focus on the occurrence of earning rather than cash receipt.', 'Under the accrual basis, revenue is recognized when it is earned or accrued during the period, whether received or not, and expenses are recognized when incurred whether paid or not.'),
        ('acc11-01-mcq-0025', 1, 'Which of the following statements is TRUE regarding the Mixed or Hybrid basis of accounting?', 'Revenues and assets are generally recorded on cash basis, expenses on accrual basis, and laws in India prohibit its use', 'Revenues and assets are recorded on accrual basis while expenses are on cash basis', 'It is universally mandatory for all registered public companies in India', 'It completely omits recording liabilities and assets', 'a', 2, 5, 'Remember the legal standing of this hybrid method under Indian legislation.', 'Under mixed basis, revenues and assets are generally recorded on cash basis whereas expenses are taken on accrual basis. The laws in India prohibit the use of this method.'),
        ('acc11-01-mcq-0026', 1, 'According to the chapter, which two primary qualitative characteristics make accounting information useful for decision-making?', 'Complexity and Confidentiality', 'Prudence and Secrecy', 'Relevance and Reliability', 'Brevity and Modernity', 'c', 2, 5, 'They form the first two core qualitative attributes discussed in section 1.6.', 'Reliability is described as one of the two primary qualities (relevance and reliability) that make accounting information useful for decision-making.'),
        ('acc11-01-mcq-0027', 1, 'Why might information regarding plant and machinery be less reliable than information about certain current assets?', 'Because plant and machinery have no historical cost records', 'Because current assets are never depreciated or consumed', 'Because of differences in the uncertainty of realization', 'Because plant and machinery are always acquired through barter', 'c', 2, 5, 'Recall the exact reason given in the text regarding uncertainty.', 'As stated in the text, information regarding plant and machinery may be less reliable than certain information about current assets because of differences in uncertainty of realization.'),
        ('acc11-01-mcq-0028', 1, 'To possess the quality of ''Relevance'', accounting information must have which key attributes?', 'Timeliness, predictive value, and feedback value', 'Theoretical ambiguity and legal immunity', 'Subjectivity, artistic calligraphy, and historical obscurity', 'Speculative inflation, secrecy, and high cost', 'a', 2, 5, 'Relevant information helps predict future outcomes and correct past expectations on time.', 'Relevant accounting information must be capable of making a difference in a decision; it must have timeliness, predictive (dedicative) and feedback value.'),
        ('acc11-01-mcq-0029', 1, 'The qualitative characteristic of ''Understandability'' requires financial information to be:', 'Disclosed exclusively to the proprietor and kept hidden from lenders', 'Presented in a form and with terminology adapted to the user''s range of understanding', 'Encoded in complex cryptographic notations known only to senior auditors', 'Abbreviated to a single net profit percentage figure', 'b', 1, 3, 'Information must be perceptible and clear to a wide circle of users.', 'Understandable financial accounting information presents data that can be understood by users, expressed in a form and terminology adapted to the user''s range of understanding.'),
        ('acc11-01-mcq-0030', 1, 'What core principle does ''Comparability'' imply when presenting accounting information?', 'Recording every item at zero net value', 'Reporting like things in a similar fashion and unlike things differently', 'Changing accounting methods every fiscal quarter', 'Merging business accounts with the proprietor''s domestic bills', 'b', 2, 5, 'Consistency in reporting similar economic transactions enables comparison.', 'Comparability implies to have like things reported in a similar fashion and unlike things reported differently, allowing comparisons across firms and periods.'),
        ('acc11-01-mcq-0031', 1, 'Which type of transaction is strictly NOT recorded in the books of accounts?', 'Non-monetary (Barter) transaction', 'Cash transaction', 'Bank overdraft transaction', 'Credit transaction', 'a', 1, 3, 'Accounting books record only monetary transactions involving money or money''s worth.', 'Only monetary transactions (which involve an exchange of money or money''s worth) are recorded in the books of accounts. Non-monetary (barter) transactions are not recorded.'),
        ('acc11-01-mcq-0032', 1, 'A transaction in which cash is not paid or received immediately at the time of the transaction, but at a later date, is termed as:', 'Cash Transaction', 'Fictitious Transaction', 'Credit Transaction', 'Barter Transaction', 'c', 1, 3, 'Settlement of cash is postponed to the future.', 'A credit transaction is one in which cash is not paid or received immediately at the time of a transaction but is paid or received at a later date.'),
        ('acc11-01-mcq-0033', 1, 'A brief explanation of a business transaction written in brackets below a journal entry, usually starting with ''Being'' or ''For'', is known as:', 'Ledger Folio', 'Narration', 'Posting', 'Voucher', 'b', 1, 3, 'It narrates the context of the entry.', 'A brief explanation of the business transaction for which an entry is passed is called a narration. It appears in brackets below the journal entry.'),
        ('acc11-01-mcq-0034', 1, 'In accounting terminology, what does the term ''Goods'' specifically refer to?', 'Merchandise, commodities, articles or things purchased or manufactured by a trader for the purpose of sale to earn profit', 'Outstanding legal claims pending before a judicial magistrate', 'All permanent fixed properties owned by the owner for personal comfort', 'Only cash balances lying in current bank accounts', 'a', 1, 3, 'Articles meant for resale in the normal course of business.', 'The term ''goods'' refers to merchandise, commodities, articles or things in which a trader trades, purchased or manufactured for the purpose of sale and to earn profit.'),
        ('acc11-01-mcq-0035', 1, 'Why is Capital treated as a liability from the viewpoint of the business enterprise?', 'Because this amount is payable by the business enterprise to the owner at the time of closure of the business', 'Because it represents money borrowed from illegal money lenders', 'Because the owner will be charged income tax by the business', 'Because capital must be written off as bad debts annually', 'a', 2, 5, 'Remember the separate entity concept: the business owes the investment back to its owner.', 'Under the business entity concept, capital is a liability of the business because the enterprise must repay this invested amount to the owner upon closure.'),
        ('acc11-01-mcq-0036', 1, 'If a proprietor pays his son''s college tuition fees or his personal residential mobile bill from the business bank account, this transaction is classified as:', 'Deferred Revenue Expenditure', 'Drawings', 'Bad Debts', 'Capital Expenditure', 'b', 2, 5, 'Funds or assets taken out of the business for personal or domestic use.', 'The amount of cash or value of goods/assets withdrawn from the business by the owner for personal use is called drawings.'),
        ('acc11-01-mcq-0037', 1, 'A customer who owes money to the business for goods purchased on credit is called a ________, whereas a supplier to whom the business owes money is called a ________.', 'Debtor; Creditor', 'Creditor; Debtor', 'Lender; Borrower', 'Proprietor; Partner', 'a', 1, 3, 'One owes to the business; the business owes to the other.', 'A debtor is a person who owes money to the business (received goods on credit). A creditor is a person to whom the business owes money.'),
        ('acc11-01-mcq-0038', 1, 'An irrecoverable amount from a debtor is known as ''Bad Debts''. In accounting, Bad Debts are classified as:', 'Capital Profit', 'Fixed Liability', 'Revenue Loss', 'Fictitious Asset', 'c', 1, 3, 'It is an uncollectible operational loss arising in the ordinary course of trading.', 'An irrecoverable amount from a debtor is known as Bad Debts, and it is a revenue loss to the business.'),
        ('acc11-01-mcq-0039', 1, 'Which of the following represents a Capital Expenditure?', 'Payment of annual employee salaries of ₹1,50,000', 'Payment of monthly office rent of ₹20,000', 'Payment of electricity bills for the factory', 'Expenditure incurred to construct an extension to the factory building', 'd', 2, 5, 'Look for expenditure that acquires or increases the value of a fixed asset with long-term benefit.', 'Capital expenditure is incurred to acquire a fixed asset or increase its value, providing long-term non-recurring benefits (e.g., extension of building).'),
        ('acc11-01-mcq-0040', 1, 'What is the key characteristic of Revenue Expenditure?', 'It is always shown on the asset side of the Balance Sheet', 'It increases the permanent capital of the owner', 'It is a normal day-to-day operating expense from which no future benefit is expected beyond the short term (less than one year)', 'It gives benefits lasting for more than ten years', 'c', 2, 5, 'These are routine operational running expenses.', 'Revenue expenditure provides short-term benefit (less than one year), does not increase earning capacity, represents normal day-to-day expenses, and appears in Trading or P&L A/c.'),
        ('acc11-01-mcq-0041', 1, 'A company spends ₹10,00,000 on a massive advertising campaign whose marketing benefit will last for 5 years. In the first year, how is this expenditure treated?', 'It is treated as a trade discount and excluded completely from the books', 'The written-off portion is debited to Profit & Loss A/c, and the unwritten amount is shown on the asset side of the Balance Sheet', 'The entire ₹10,00,000 is written off immediately to capital as drawings', 'It is recorded as a contingent liability in the footnote', 'b', 3, 10, 'This is Deferred Revenue Expenditure: amortized over multiple years.', 'Deferred revenue expenditure is written off over a number of years. The written-off amount is debited to P&L A/c and the unwritten balance is shown as an asset on the Balance Sheet.'),
        ('acc11-01-mcq-0042', 1, 'Goods with a catalogue list price of ₹10,000 are sold to Rohan at a 10% Trade Discount. What amount will be recorded in the books of accounts of the seller and buyer?', '₹1,000 as cash discount received', 'Net value of ₹9,000, and Trade Discount does not appear in the books of accounts separately', '₹10,00,000 in the purchase/sales account and ₹1,000 in a separate Trade Discount account', '₹11,000 including estimated future interest', 'b', 2, 5, 'Trade discount is deducted directly from catalogue price; it never gets its own ledger entry.', 'Trade discount is deducted from catalogue price and recorded at net payable value (₹9,000). Hence, trade discount does not appear separately in the books of accounts.'),
        ('acc11-01-mcq-0043', 1, 'What is the primary purpose of allowing a Cash Discount, and how is it recorded in the books?', 'To adjust catalogue prices for bulk wholesale orders; not shown in accounts', 'To encourage prompt or spot payment; it appears in the books of accounts as it is a loss to the seller and gain to the buyer', 'To reduce import customs duties; recorded as a fixed asset', 'To compensate for damaged goods; it is omitted from the books', 'b', 2, 5, 'Cash discount incentivizes quick settlement and represents an actual financial gain/loss.', 'Cash discount is a concession given to encourage prompt or spot payment. Since it represents a loss to the seller and gain to the buyer, it appears in the books of accounts.'),
        ('acc11-01-mcq-0044', 1, 'A person whose total assets amount to ₹20,00,000 and total debts/liabilities amount to ₹50,00,000, and who is unable to meet obligations from any source, will be declared by the court as:', 'Underwriter', 'Solvent', 'Creditor', 'Insolvent', 'd', 2, 5, 'His liabilities significantly exceed his realizable assets.', 'A person whose liabilities are more than his assets and is unable to pay off debts is an insolvent person once the court is satisfied.'),
        ('acc11-01-mcq-0045', 1, 'For income tax purposes in India, an accounting year begins on ________ and ends on ________.', '1st July; 30th June', '1st January; 31st December', '1st Diwali; Last day of Vikram Samvat', '1st April; 31st March', 'd', 1, 3, 'Standard Indian financial fiscal calendar.', 'Now for income tax purposes in India, an accounting year starts on 1st April and ends on 31st March.'),
        ('acc11-01-mcq-0046', 1, 'Which of the following entities is classified as a ''Not for Profit Concern'' based on the chapter''s definition?', 'A commercial textile manufacturing company', 'A private retail supermarket chain', 'An automobile wholesale dealership', 'A charitable hospital or sports club formed for rendering social service', 'd', 1, 3, 'Established not to earn profits, but to render services in art, health, sports, or education.', 'A Not for Profit Concern is established not for making profit but for rendering services to society (e.g., Schools, Hospitals, Sports Clubs).'),
        ('acc11-01-mcq-0047', 1, 'Goodwill is defined as the reputation of a business expressed in terms of money. What type of asset is Goodwill?', 'Contingent Asset', 'Fictitious Asset', 'Intangible Asset', 'Tangible Current Asset', 'c', 1, 3, 'It has monetary value and superior earning power, but no physical substance.', 'Goodwill is the reputation of a business expressed in monetary terms and is classified as an intangible asset.'),
        ('acc11-01-mcq-0048', 1, 'If goods are sold for ₹50,000 and all expenses incurred to generate that revenue during the period amount to ₹60,000, what is the net business result and its impact on capital?', 'Loss of ₹10,000; decreases capital', 'Drawings of ₹10,000; increases liabilities', 'Profit of ₹10,000; increases capital', 'Bad debt of ₹60,000; leaves capital unchanged', 'a', 2, 5, 'When cost and expenses exceed sales proceeds, the difference erodes the owner''s stake.', 'When cost price/expenses (₹60,000) exceed selling price (₹50,000), it is a loss of ₹10,000. Losses decrease the capital of the business.'),
        ('acc11-01-mcq-0049', 1, 'According to the chapter, how does ''Revenue'' differ from ''Income''?', 'Revenue decreases capital, while income increases liabilities', 'Revenue is money from illegal sources, while income is from legal sales', 'Revenue is income from normal business activities (like sales of goods/services), while income includes revenue as well as earnings from interest, dividend, commission, etc.', 'Revenue is only received in gold, while income is received in bank currency', 'c', 2, 5, 'Look at the textbook distinctions under sections 1.7.9 (c) and (d).', 'Revenue is income that a business has from its normal activities (sale of goods/services), whereas income is the broader revenue arising from business transactions, including interest, dividends, and commission.'),
        ('acc11-01-mcq-0050', 1, 'Which of the following lists contains ONLY Current Assets?', 'Debtors, Bills Receivable, Cash in Hand, Stock', 'Bank Overdraft, Creditors, Bills Payable', 'Capital, Reserves, Long-term Loans', 'Land and Building, Plant and Machinery, Goodwill', 'a', 2, 5, 'Assets held for the operating year that convert readily into liquid cash.', 'Current assets are held for the operating year and can be converted into cash easily (e.g., Debtors, Bills Receivable, Cash in Hand, Cash at Bank, Stock).'),
        ('acc11-01-mcq-0051', 1, 'What is a Fictitious Asset according to the chapter?', 'Amounts owed by solvent government departments', 'An imaginary asset not represented by tangible possession and having no realizable value (e.g., Deferred revenue expenses)', 'Cash deposited in foreign exchange accounts', 'A valuable tangible piece of real estate in a prime city', 'b', 2, 5, 'It has no market resale value and represents unamortized past expense.', 'Fictitious assets are not represented by tangible possession or property; they are imaginary assets with no realizable value, such as deferred revenue expenditure.'),
        ('acc11-01-mcq-0052', 1, 'A business has Capital of ₹4,00,000 and Creditors of ₹2,00,000. Using the accounting equation given in the chapter, what is the value of Total Equity (Assets)?', '₹4,00,000', '₹8,00,000', '₹6,00,000', '₹2,00,000', 'c', 2, 5, 'Total Equity (Assets) = Liabilities + Capital.', 'Total Equity (Assets) = Liabilities + Capital = ₹2,00,000 + ₹4,00,000 = ₹6,00,000.'),
        ('acc11-01-mcq-0053', 1, 'If total assets of a business are ₹1,50,000 and the Owner''s Capital is ₹1,00,000, what is Creditors Equity (Liabilities)?', '₹2,50,000', '₹15,000', '₹50,000', '₹50,00,000', 'c', 2, 5, 'Creditors Equity (Liabilities) = Assets - Capital.', 'Creditors Equity (Liabilities) = Assets - Capital = ₹1,50,000 - ₹1,00,000 = ₹50,000.'),
        ('acc11-01-mcq-0054', 1, 'A pending lawsuit by an employee claiming ₹5,000 compensation against the firm depends on a future court verdict. How should this be presented in the financial statements?', 'Debited directly to the Capital Account as drawings', 'Not included on the liability side, but disclosed simply as information by way of a footnote to the Balance Sheet', 'Recorded in the sales daybook as accrued turnover', 'Shown on the liability side of the Balance Sheet as a fixed liability', 'b', 2, 5, 'It is not yet a confirmed liability, so it appears outside the main balance sheet totals.', 'As a contingent liability is not a confirmed liability, it does not affect current financial position directly; it is shown by way of a footnote to the Balance Sheet.'),
        ('acc11-01-mcq-0055', 1, 'A proprietor rents a building for ₹50,000 per year. Half of the building is used for his business office and the other half for his personal residence. According to the Business Entity Concept, how much should be charged as business rent expense?', '₹50,000 as capital expenditure', '₹50,000 as office rent expense', '₹0, because personal transactions cancel business expenses', '₹25,000 as office rent expense, and ₹25,000 deducted as drawings from capital', 'd', 3, 10, 'Separate the owner''s domestic usage from the firm''s commercial usage.', 'Under the Business Entity concept, only business expenses are recognized. Since half the building is personal, ₹25,000 is business rent and the remaining ₹25,000 is treated as drawings.'),
        ('acc11-01-mcq-0056', 1, 'Under the Money Measurement Concept, which of the following business events will CANNOT be recorded in the books of accounts?', 'Purchase of 5 computers for ₹1,50,000', 'Sale of 10 office chairs for ₹8,000', 'Payment of office electricity bill of ₹4,000', 'A strike by factory workers and the high efficiency of the management team', 'd', 2, 5, 'Accounting records only events that can be expressed quantitatively in monetary terms.', 'Qualitative aspects like employee strikes, working conditions, or management efficiency cannot be expressed in terms of money, so they are not recorded.'),
        ('acc11-01-mcq-0057', 1, 'A business purchased furniture for ₹3,00,000. Three years later, the market replacement value jumps to ₹5,00,000. According to the Cost Concept, at what value should the asset be accounted for?', 'Immediately marked up to ₹5,00,000 to reflect market value', 'Recorded at acquisition cost less systematic depreciation, ignoring market fluctuations', 'Averaged between ₹3,00,000 and ₹5,00,000', 'Written off to ₹0 as an obsolete asset', 'b', 2, 5, 'Acquisition cost remains the basis for subsequent accounting, minus depreciation.', 'Under the Cost Concept, assets are recorded at historical acquisition cost. Subsequent changes in market value are not considered, except for systematic depreciation.'),
        ('acc11-01-mcq-0058', 1, 'A company adopts the fixed installment method for charging depreciation from year to year. Which accounting concept does this practice illustrate?', 'Consistency Concept', 'Materiality Convention', 'Realization Concept', 'Business Entity Concept', 'a', 2, 5, 'Following the same policies and accounting methods across periods.', 'The Consistency Concept states that accounting policies adopted should be continuous or consistent throughout the business from one period to another.'),
        ('acc11-01-mcq-0059', 1, 'The closing stock in a factory has a cost price of ₹25,000 and a net market realizable value of ₹35,000. Under the Conservatism principle, what value will be recorded in the books?', '₹25,000', '₹60,000', '₹30,000', '₹35,000', 'a', 2, 5, 'Anticipate no profit, but provide for all possible losses (record at the lower of cost or market price).', 'Conservatism dictates playing safe by anticipating no profits but providing for all losses. Closing inventory is valued at the lower of cost or market price (₹25,000).'),
        ('acc11-01-mcq-0060', 1, 'Which basic accounting assumption presumes that an enterprise will continue its operational existence for the foreseeable future and not be liquidated?', 'Money Measurement Concept', 'Periodicity Concept', 'Cash Basis Concept', 'Going Concern Concept', 'd', 1, 3, 'The business is assumed to be an ongoing enterprise.', 'The Going Concern Concept is the basic assumption that a business will continue its operations in the future and not close down.'),
        ('acc11-01-mcq-0061', 1, 'A firm receives a purchase order for goods worth ₹1,00,000 in May 2017. Goods worth ₹60,000 are delivered to the customer in June 2017, and cash is received in September 2017. In which month should the sale of ₹60,000 be recognized as revenue?', 'June 2017 (when goods are sold and delivered)', 'September 2017 (when cash is collected)', 'Equally divided across May, June, and September', 'May 2017 (when order is placed)', 'a', 3, 10, 'Sales revenue is realized when sales are effected and goods are delivered.', 'As per the principle of realization, revenue is recognized when sales are effected or services rendered, irrespective of when cash is collected. Thus, sale is recorded in June 2017.'),
        ('acc11-01-mcq-0062', 1, 'On 1st October 2015, a company deposits ₹1,00,000 with a bank for one year at 10% interest per annum payable upon maturity on 30th September 2016. At the financial year-end on 31st March 2016, how should the interest be accounted for under the Accrual concept?', 'The entire deposit must be written off as deferred revenue expenditure', 'Full year interest of ₹10,000 must be recorded in October 2015', 'No interest should be recorded until cash is received on 30th September 2016', 'Accrued interest of ₹5,000 (for 6 months) must be recognized as earned income for the period ending 31st March 2016', 'd', 3, 10, 'Recognize income as it is earned during the period (10% on ₹1,00,000 for 6 months).', 'Under the accrual concept, revenue earned during the accounting period must be recognized whether received or not. For 6 months (Oct to Mar), ₹5,000 interest has accrued and must be recorded.'),
        ('acc11-01-mcq-0063', 1, 'When Akshay starts a business with ₹5,00,000 cash, what are the two simultaneous effects according to the Dual Aspect Concept?', 'Business receives Cash of ₹5,00,000 (asset) and owes ₹5,00,000 to Akshay as Capital (liability)', 'Bank Overdraft increases by ₹5,00,000 and Fixed Assets decrease by ₹5,00,000', 'Cash increases by ₹5,00,000 and Drawings increase by ₹5,00,000', 'Creditors increase by ₹5,00,000 and Bad Debts increase by ₹5,00,000', 'a', 2, 5, 'For every debit, there is an equal corresponding credit creating the equation Assets = Capital + Liabilities.', 'Under the Dual Aspect concept, the business receives ₹5,00,000 cash (asset) and creates an equal corresponding liability towards Akshay known as Capital.'),
        ('acc11-01-mcq-0064', 1, 'What does the Disclosure Principle mandate regarding financial statements?', 'Proprietors must reveal their personal family wills and domestic bank statements', 'Financial statements must honestly disclose full and fair material information regarding the financial position and performance', 'Only profitable transactions should be reported to tax authorities', 'Companies must publish the home addresses and phone numbers of all their customers', 'b', 1, 3, 'Full and fair presentation of the entity''s financial affairs.', 'The Disclosure concept mandates that accounts must disclose all material information, presenting a full and fair view of financial position and performance.'),
        ('acc11-01-mcq-0065', 1, 'Why is the Materiality convention regarded as an exception to the Full Disclosure principle?', 'Because it requires disclosing every single pencil bought in minute detail', 'Because it allows companies to fabricate fake profits', 'Because it forces firms to abandon double-entry book-keeping', 'Because insignificant and irrelevant items that do not influence user decisions need not be separately disclosed', 'd', 2, 5, 'Insignificant details do not need elaborate individual reporting.', 'Materiality convention is an exception to full disclosure because unimportant or trivial items that do not influence economic decisions of users need not be disclosed in detail.'),
        ('acc11-01-mcq-0066', 1, 'The Matching Concept in accounting requires that:', 'The number of employees hired must match the units of machinery installed', 'Revenues earned during an accounting period are matched with the expenses incurred during that period to earn those revenues', 'Total debits must match bank overdraft balances only', 'Cash discounts given must exactly match trade discounts received', 'b', 2, 5, 'Revenues and related expenses must align within the same time window to determine true profit.', 'Matching concept requires that revenues of a specific accounting period must be matched with the expenses incurred during that period to generate those revenues.'),
        ('acc11-01-mcq-0067', 1, 'According to Kohler, Accounting Standards are defined as:', '''Codes of conduct imposed by customs, laws or professional bodies for the benefit of public accountants and accountants generally''', '''Statutory fines imposed on unprofitable small businesses''', '''Mathematical formulas invented to compute corporate taxes''', '''International treaties governing border currency exchange''', 'a', 1, 3, 'Look for his quote regarding professional ''codes of conduct''.', 'In the words of Kohler: ''Accounting standards are codes of conduct imposed by customs, laws or professional bodies for the benefit of public accountants and accountants generally.'''),
        ('acc11-01-mcq-0068', 1, 'Which of the following is an explicit reason for the ''Need for Accounting Standards'' stated in the chapter?', 'To replace all tax laws with custom trade guidelines', 'To help accountants follow uniform procedures and facilitate meaningful comparison of financial statements', 'To allow companies to hide their debt liabilities', 'To eliminate the need for computer systems in offices', 'b', 1, 3, 'Standards ensure uniformity, reliability, and comparability across entities.', 'Accounting standards are needed to follow uniform procedures, promote better understanding, enhance reliability, facilitate comparison, and meet legal requirements.'),
        ('acc11-01-mcq-0069', 1, 'International Financial Reporting Standards (IFRS) are formulated and issued by which international body?', 'United Nations Trade Commission', 'Federal Reserve System', 'International Accounting Standard Board (IASB)', 'World Bank Financial Division', 'c', 1, 3, 'IASB stands for International Accounting Standard Board.', 'International Financial Reporting Standards (IFRS) are issued by the International Accounting Standard Board (IASB).'),
        ('acc11-01-mcq-0070', 1, 'On which date did the Council of the Institute of Chartered Accountants of India (ICAI) constitute the Accounting Standards Board (ASB)?', '21st April 1977', '15th August 1947', '1st January 1991', '31st March 2001', 'a', 1, 3, 'Formed in April 1977.', 'The Council of the ICAI constituted the Accounting Standards Board (ASB) on 21st April, 1977.'),
        ('acc11-01-mcq-0071', 1, 'What are ''Ind AS'' as described in the chapter?', 'A software package developed by ICAI for automated tax calculation', 'The existing Indian Accounting Standards converged with IFRS and modified for Indian practices, customs, and traditions', 'Guidelines issued exclusively for barter trade in rural markets', 'Unmodified US GAAP standards applied directly to Indian agricultural cooperatives', 'b', 2, 5, 'Result of convergence between Indian Accounting Standards and IFRS.', 'Ind AS are the converged standards: International Financial Reporting Standards modified in accordance with Indian accounting practices, customs, and traditions.'),
        ('acc11-01-mcq-0072', 1, 'How many accounting standards had been issued by the Council of the Institute of Chartered Accountants of India (ICAI) as mentioned in the chapter?', '21', '50', '12', '31', 'd', 1, 3, 'The textbook explicitly states: ''The Council of the ICAI has so far issued ______ accounting standards.''', 'As per Section 1.9 of the textbook: ''The Council of the Institute of Chartered Accountants of India has so far issued thirty one accounting standards.'''),
        ('acc11-01-mcq-0073', 1, 'According to AS-1 (Disclosure of Accounting Policies), where should the accounting policies followed in the preparation of financial statements normally be disclosed?', 'Filed confidentially with the local police department', 'Kept secret by the managing director', 'Spread randomly across various journal pages', 'Form a part of the financial statements and normally be disclosed in one place', 'd', 2, 5, 'They must be readily accessible in a single designated section.', 'Under AS-1, the accounting policies followed should form a part of the financial statements and normally be disclosed in one place.'),
        ('acc11-01-mcq-0074', 1, 'According to AS-2, how should inventories in general be valued in financial statements?', 'At original cost plus 20% estimated gross margin', 'At replacement cost only', 'At current catalogue retail price', 'At the lower of historical cost and net realizable value', 'd', 2, 5, 'Rule of prudence: cost or net realizable value, whichever is less.', 'According to AS-2 (Valuation of Inventories), inventories in general should be valued at the lower of historical cost and net realizable cost.'),
        ('acc11-01-mcq-0075', 1, 'Which Indian Accounting Standard specifies that a cash flow statement must be prepared and presented for the period for which the Profit and Loss Account is prepared?', 'AS-12', 'AS-1', 'AS-3', 'AS-9', 'c', 1, 3, 'This standard is dedicated to cash flows.', 'AS-3 deals with Cash Flow Statements and mandates its preparation and presentation for the period for which the P&L account is prepared.'),
        ('acc11-01-mcq-0076', 1, 'What does AS-6 (Depreciation Accounting) mandate regarding the depreciation of an asset?', 'Assets should never be depreciated until they are sold as scrap', 'Depreciation must equal 50% of the asset cost in every single year', 'The depreciable amount should be allocated on a systematic basis for each accounting period during the useful life of an asset', 'Depreciation must only be charged when the business earns extraordinary profits', 'c', 2, 5, 'Systematic allocation over useful life.', 'According to AS-6, the depreciation amount of an asset should be allocated on a systematic basis for each accounting period during the useful life of an asset.'),
        ('acc11-01-mcq-0077', 1, 'Under AS-8, how should the costs of Research and Development be accounted for?', 'Capitalized permanently as tangible land', 'Treated as non-monetary barter exchange', 'Recorded as personal drawings of the researchers', 'Charged as an expense of the period in which they are actually incurred', 'd', 2, 5, 'Expensed immediately in the year incurred.', 'According to AS-8, the amount of research and development costs should be charged as an expense of the period in which they are actually incurred.'),
        ('acc11-01-mcq-0078', 1, 'What is the primary subject matter governed by Accounting Standard AS-9?', 'Basis required for recognition of revenue items in the Profit and Loss Account of an enterprise', 'Calculation of corporate income tax surcharges', 'Allocation of government grants to charity', 'Valuation of factory buildings and raw materials', 'a', 1, 3, 'Deals with revenue recognition.', 'AS-9 deals with Revenue Recognition—laying down conditions to recognize revenue items that arise from various transactions in the Profit and Loss Account.'),
        ('acc11-01-mcq-0079', 1, 'Under AS-10, what components comprise the historical cost of a fixed asset?', 'Original cost only, excluding freight or installation', 'The anticipated future selling price after ten years', 'Original cost plus any attributable cost of bringing the asset to its working condition for its intended use', 'The market value on the date of final disposal', 'c', 2, 5, 'Include acquisition price plus direct costs needed to get the asset ready for operation.', 'According to AS-10, the cost of fixed assets comprises the original cost and any attributable cost of bringing the asset to its working condition for its intended use.'),
        ('acc11-01-mcq-0080', 1, 'According to AS-12, when should government grants be recognized in the books of an enterprise?', 'Only after the enterprise closes down its operations permanently', 'When the government announces its annual political manifesto', 'Whenever the proprietor withdraws capital for personal expenses', 'When there is an assurance that the enterprise will comply with the conditions attached to them', 'd', 2, 5, 'Recognition requires reasonable certainty of fulfilling attached stipulations.', 'According to AS-12, government grants should be recognized when there is an assurance that the enterprise will comply with the conditions attached to them.'),
        ('acc11-01-mcq-0081', 1, 'How does AS-13 require ''Current Investments'' and ''Long-term Investments'' to be carried in financial statements?', 'Both must be written off completely in the year of purchase', 'Both must be carried at fair market value at all times', 'Current investments at cost; long-term investments at scrap value', 'Current investments at lower of cost or fair value; long-term investments always carried at cost price', 'd', 3, 10, 'Short-term follows lower of cost or market; long-term stays at historical cost.', 'Under AS-13, current investments are carried at the lower of cost or fair value, while long-term investments are carried at cost price.'),
        ('acc11-01-mcq-0082', 1, 'Under AS-22, tax expenses for the period included in determining net profit or loss comprise which components?', 'Property tax and customs duty only', 'Sales tax and excise duty', 'Current tax and deferred tax', 'Penalty fees and legal fines', 'c', 2, 5, 'It involves both current tax obligation and timing difference deferred tax.', 'According to AS-22, tax expenses for the period comprise current tax and deferred tax, and should be included in the determination of net profit or loss.'),
        ('acc11-01-mcq-0083', 1, 'In financial accounting, what type of account is a ''Bank Overdraft''?', 'Fixed Asset', 'Fictitious Asset', 'Current Liability', 'Owners'' Equity', 'c', 1, 3, 'It is an amount due to the bank repayable within a short period.', 'Bank Overdraft is an amount payable by the business to the bank for temporary credit extended; hence, it is a current liability.'),
        ('acc11-01-mcq-0084', 1, 'If a business has total assets of ₹5,00,000 and outside liabilities of ₹2,00,000, what is the Owner''s Equity (Capital)?', '₹10,00,000', '₹2,50,000', '₹7,00,000', '₹3,00,000', 'd', 2, 5, 'Owner''s Equity = Assets - Liabilities.', 'Owner''s Equity (Capital) = Assets - Liabilities = ₹5,00,000 - ₹2,00,000 = ₹3,00,000.'),
        ('acc11-01-mcq-0085', 1, 'According to section 1.7.10 of the chapter, what two items are included in ''Net Worth''?', 'Deferred Expenses and Bad Debts', 'Gross Sales and Cost of Goods Sold', 'Capital and Reserves', 'Bank Overdraft and Trade Creditors', 'c', 2, 5, 'Net worth represents the total equity belonging to the owner.', 'As explicitly stated in section 1.7.10: ''Net worth includes Capital and Reserves.'''),
        ('acc11-02-mcq-0001', 2, 'The Double Entry Book-keeping System owes its origin to which Italian merchant and on which date?', 'Luca D. Bargo Pacioli on 10th November 1494', 'J.R. Batliboi on 10th December 1494', 'Luca D. Bargo Pacioli on 15th December 1594', 'R.N. Carter on 10th November 1594', 'a', 1, 3, 'Recall the Italian merchant and the historical date celebrated as International Accounting Day.', 'According to the chapter, the Double Entry Book-keeping System owes its origin to Italian Merchant Luca D. Bargo Pacioli on 10th November 1494.'),
        ('acc11-02-mcq-0002', 2, 'International Accounting Day is celebrated worldwide on which date?', '10th December', '10th November', '15th December', '12th November', 'b', 1, 3, 'It coincides with the date Luca Pacioli introduced the double entry system in 1494.', '10th November is celebrated as International Accounting Day because Luca Pacioli originated the Double Entry System on this date in 1494.'),
        ('acc11-02-mcq-0003', 2, 'What is the foundational principle underlying every business transaction in the Double Entry System?', 'Every transaction affects only cash and bank balances.', 'Only credit transactions require a two-fold entry in books of accounts.', 'Every transaction has two aspects where one party is the receiver of the benefit and the other is the giver.', 'Transactions are recorded only when profit or loss is realized.', 'c', 1, 3, 'Think about the dual aspects of benefit exchange in every transaction.', 'The chapter explains that every business transaction involves two persons, accounts, or parties wherein one is the receiver of the benefit and the other is the giver of the benefit.'),
        ('acc11-02-mcq-0004', 2, 'The Indian system of recording accounting information in languages like Marathi, Hindi, Urdu, and Gujarati is also known as:', 'English System', 'Accrual Ledger System', 'Double Entry System', 'Mahajani Deshinama System', 'd', 1, 3, 'Identify the traditional name given to the indigenous Indian accounting method.', 'The Indian accounting system maintains records in Indian languages and is known as the Mahajani Deshinama system.'),
        ('acc11-02-mcq-0005', 2, 'In the Indian System (Mahajani Deshinama), transactions are maintained in long books known as:', 'Bahi-Khata and Kird', 'Journal and Ledger', 'Day Book and Cash Book', 'Passbook and Balance Sheet', 'a', 1, 3, 'Recall the traditional terms for the long accounting books used in Indian business.', 'In the Indian system, transactions are recorded or maintained in long books known as Bahi-Khata and Kird.'),
        ('acc11-02-mcq-0006', 2, 'Why is the Indian System of accounting categorized as an unscientific and conventional method?', 'It does not record transactions in any systematic books.', 'It is not based on the principles of the Double Entry System.', 'It uses English currency terms exclusively.', 'It only records transactions once every decade.', 'b', 2, 5, 'Consider whether it follows modern scientific dual-aspect principles.', 'The Indian system is not based on the Double Entry system of accounting and thus is not considered a scientific accounting system; it is based on tradition/convention.'),
        ('acc11-02-mcq-0007', 2, 'Which accounts are exclusively maintained under the Single Entry System?', 'Real accounts and Nominal accounts', 'Assets accounts and Liabilities accounts only', 'Cash book and Personal accounts', 'Expenses accounts and Income accounts only', 'c', 1, 3, 'Recall the two specific types of records maintained in this incomplete English method.', 'The Single Entry System of accounting records only the Cash book and Personal accounts, ignoring impersonal accounts.'),
        ('acc11-02-mcq-0008', 2, 'Why is the Single Entry System described as an incomplete recording system?', 'It records all transactions twice in different currencies.', 'It is legally mandatory for all large joint-stock corporations.', 'It cannot record cash receipts under any circumstances.', 'It changes with the convenience of business and does not provide accurate financial information.', 'd', 2, 5, 'Look for the reason relating to arbitrary recording and lack of full financial visibility.', 'It is known as an incomplete recording system because it changes with the convenience of business for recording transactions and does not provide accurate information about financial position.'),
        ('acc11-02-mcq-0009', 2, 'According to the cycle of Double Entry Book-keeping presented in the chapter, which step immediately follows ''Recording of transactions (Journal)''?', 'Posting Entries to Ledger', 'Dual Effects of Transactions', 'Preparation of Trial Balance', 'Preparation of Final Accounts', 'a', 1, 3, 'Follow the sequence: Dual effects -> Journal -> Ledger posting -> Balancing -> Trial Balance -> Final Accounts.', 'In the circular flow diagram of Double Entry Book-keeping, step 2 is Recording of transactions (Journal) and step 3 is Posting Entries to Ledger.'),
        ('acc11-02-mcq-0010', 2, 'What is the penultimate (5th) stage in the elements of the Double Entry Book-keeping System cycle prior to preparing Final Accounts?', 'Dual Effects of Transactions', 'Preparation of Trial Balance', 'Balancing of Ledger Accounts', 'Posting Entries to Ledger', 'b', 2, 5, 'It is the summary statement prepared after balancing ledgers to verify arithmetical accuracy before final accounts.', 'The sequence shown in the textbook diagram is: 1. Dual Effects, 2. Recording in Journal, 3. Posting to Ledger, 4. Balancing of Ledger Accounts, 5. Preparation of Trial Balance, and 6. Preparation of Final Accounts.'),
        ('acc11-02-mcq-0011', 2, 'Who defined Double Entry by stating: ''Every business transaction has a two fold effect and that it affects two accounts in opposite directions...''?', 'R.N. Carter', 'Luca Pacioli', 'J.R. Batliboi', 'Adam Smith', 'c', 1, 3, 'Name the authority cited for the primary definition of the Double Entry System in Section 2.2.', 'The definition starting with ''Every business transaction has a two fold effect...'' is given by J.R. Batliboi.'),
        ('acc11-02-mcq-0012', 2, 'Who defined an account as: ''a ledger record in a summarized form of all the transactions that have taken place with the particular person or thing specified''?', 'Amol Patil', 'G.R. Batliboi', 'Luca Pacioli', 'Carter', 'd', 1, 3, 'Recall the second author who defined an Account specifically focusing on ''a ledger record in a summarized form''.', 'Carter defined an account as: ''An account is a ledger record in a summarized form of all the transactions that have taken place with the particular person or thing specified.'''),
        ('acc11-02-mcq-0013', 2, 'G.R. Batliboi defines an account as a summarized record of transactions affecting:', 'One person, one kind of property or one class of gain or loss', 'Only external banks and loan institutions', 'Cash inflows and cash outflows of a government entity', 'Proprietor''s private personal assets and liabilities', 'a', 1, 3, 'Recall Batliboi''s exact words identifying person, property, and gain/loss.', 'G.R. Batliboi defines an account: ''An account is summarized record of transactions affecting one person, one kind of property or one class of gain or loss.'''),
        ('acc11-02-mcq-0014', 2, 'Which of the following is a basic principle of the Double Entry Book-keeping System?', 'Total debits must always exceed total credits to reflect profit.', 'Every debit has an equal and corresponding credit of the same amount.', 'Only cash transactions require equal debit and credit entries.', 'Personal accounts are credited when they receive a benefit.', 'b', 1, 3, 'Identify the fundamental equilibrium rule of double entry bookkeeping.', 'A core principle of Double Entry Book-keeping is that ''Every debit has an equal and corresponding credit of the same amount.'''),
        ('acc11-02-mcq-0015', 2, 'Which advantage of Double Entry Book-keeping ensures that arithmetical accuracy of accounting work can be checked?', 'Common Acceptance', 'Single Entry Conversion', 'Accuracy', 'Conventional Practice', 'c', 1, 3, 'Look for the specific advantage header that states ''it also checks arithmetical accuracy''.', 'Under the advantage ''Accuracy'', the text states that recording both aspects gives complete accuracy and checks arithmetical accuracy.'),
        ('acc11-02-mcq-0016', 2, 'Why does the Double Entry System enjoy ''Common Acceptance'' across financial institutions and government authorities?', 'Because it ignores credit transactions completely.', 'Because it eliminates the need to balance ledger accounts.', 'Because it allows businesses to alter entries conveniently.', 'Because it follows universal accounting principles.', 'd', 2, 5, 'Consider the global standardization of accounting rules.', 'Under ''Common Acceptance'', the textbook states that Double Entry is widely accepted because it follows universal accounting principles.'),
        ('acc11-02-mcq-0017', 2, 'What is the Conventional Accounting System primarily based on?', 'Practicability and rules used by common agreement', 'Strict statutory legislation enacted by Parliament', 'Computerized double-entry software algorithms', 'International Financial Reporting Standards only', 'a', 1, 3, 'The text states it is based on practicability and conventions agreed upon over time.', 'Conventional Accounting System is based on practicability, where accounting conventions mean rules which by common agreement are used in accounting.'),
        ('acc11-02-mcq-0018', 2, 'In standard accounting format, which sides represent Debit (Dr.) and Credit (Cr.) respectively?', 'Debit is the right-hand side and Credit is the left-hand side.', 'Debit is the left-hand side and Credit is the right-hand side.', 'Debit is the top side and Credit is the bottom side.', 'Debit is the outer margin and Credit is the inner ledger column.', 'b', 1, 3, 'Recall the definitions: Left-hand side vs Right-hand side.', 'The chapter explicitly defines: ''Left hand side of an Account is called Debit (Dr) side'' and ''Right hand side of an Account is called Credit (Cr) side.'''),
        ('acc11-02-mcq-0019', 2, 'Accounts relating to individual human beings such as Sunita''s A/c, Ashok''s A/c, or Suha''s A/c are classified as:', 'Artificial Personal Accounts', 'Representative Personal Accounts', 'Natural Personal Accounts', 'Tangible Real Accounts', 'c', 1, 3, 'These relate to living human persons.', 'Natural Person''s Accounts are accounts relating to individual human beings (e.g., Rajesh''s A/c, Sunita''s A/c, Ashok''s A/c).'),
        ('acc11-02-mcq-0020', 2, 'Which of the following accounts is an example of an Artificial Personal Account?', 'Sushma''s A/c', 'Prepaid Wages A/c', 'Patent A/c', 'Pune Municipal Corporation A/c', 'd', 2, 5, 'Look for an entity, association, or organization created by law.', 'Artificial Personal Accounts include accounts of organizations and bodies created by law, such as Pune Municipal Corporation A/c, Bank of India A/c, and Radhika Sports Club A/c.'),
        ('acc11-02-mcq-0021', 2, 'Accounts relating to outstanding and prepaid expenses or accrued incomes are categorized as:', 'Representative Personal Accounts', 'Natural Personal Accounts', 'Nominal Accounts', 'Intangible Real Accounts', 'a', 2, 5, 'These accounts represent a person or group of persons to whom amounts are payable or receivable.', 'Representative Personal Accounts represent certain persons or groups in business dealings; accounts relating to outstanding and prepaid items fall under this category.'),
        ('acc11-02-mcq-0022', 2, 'Real Accounts represent:', 'Expenses, losses, incomes, and gains', 'Assets and properties owned by the business', 'Human beings and legal entities dealing with the firm', 'Outstanding obligations to employees only', 'b', 1, 3, 'Recall what physical and non-physical properties of a business are called.', 'Real accounts represent assets and properties owned by the business.'),
        ('acc11-02-mcq-0023', 2, 'Which of the following is categorized as an Intangible Real Account?', 'Machinery A/c', 'Computer A/c', 'Goodwill A/c', 'Live Stock A/c', 'c', 1, 3, 'Identify the asset that cannot be seen, touched, or felt, but has measurable monetary value.', 'Intangible Real Accounts are assets that cannot be seen, touched, or felt but can be measured in terms of money, such as Goodwill A/c, Patents A/c, Trademarks A/c, and Copyrights A/c.'),
        ('acc11-02-mcq-0024', 2, 'Assets that can be seen, touched, and felt (such as Machinery, Motor Car, and Stock of Goods) are called:', 'Nominal Accounts', 'Representative Personal Accounts', 'Artificial Personal Accounts', 'Tangible Real Accounts', 'd', 1, 3, 'Physical assets that have a concrete form are termed tangible.', 'Tangible Real Accounts represent assets and properties that can be seen, touched, and felt.'),
        ('acc11-02-mcq-0025', 2, 'Accounts of expenses, losses, income, and gains are known as:', 'Nominal Accounts', 'Personal Accounts', 'Real Accounts', 'Representative Accounts', 'a', 1, 3, 'Recall the traditional account type for revenue, expense, gain, and loss items.', 'The accounts of expenses, losses, income, and gains are called Nominal accounts.'),
        ('acc11-02-mcq-0026', 2, 'Which of the following represents an Income/Gain under Nominal Accounts?', 'Stationery A/c', 'Commission Received A/c', 'Depreciation A/c', 'Audit Fees A/c', 'b', 2, 5, 'Distinguish between an expense/loss and a revenue/gain.', 'Commission Received A/c, Interest Received A/c, and Discount Received A/c represent incomes/gains under Nominal accounts, while Stationery, Depreciation, and Audit Fees are expenses/losses.'),
        ('acc11-02-mcq-0027', 2, 'What is the Golden Rule of Debit and Credit for Personal Accounts?', 'Debit what comes in, Credit what goes out', 'Debit all expenses and losses, Credit all incomes and gains', 'Debit the receiver, Credit the giver', 'Debit increase in asset, Credit decrease in asset', 'c', 1, 3, 'Think of the person receiving benefit versus giving benefit.', 'The traditional Golden Rule for Personal Accounts is ''Debit the receiver, Credit the giver.'''),
        ('acc11-02-mcq-0028', 2, 'What is the Golden Rule of Debit and Credit for Real Accounts?', 'Debit decrease in liability, Credit increase in liability', 'Debit the giver, Credit the receiver', 'Debit all incomes, Credit all losses', 'Debit what comes in, Credit what goes out', 'd', 1, 3, 'Consider movement of assets/properties into or out of the business.', 'The Golden Rule for Real Accounts is ''Debit what comes in, Credit what goes out.'''),
        ('acc11-02-mcq-0029', 2, 'What is the Golden Rule of Debit and Credit for Nominal Accounts?', 'Debit all expenses and losses, Credit all incomes and gains', 'Debit what comes in, Credit what goes out', 'Debit the receiver, Credit the giver', 'Debit all assets, Credit all liabilities', 'a', 1, 3, 'Focus on the treatment of operational costs versus earnings.', 'The Golden Rule for Nominal Accounts is ''Debit all expenses and losses, Credit all incomes and gains.'''),
        ('acc11-02-mcq-0030', 2, 'Under the Modern Approach, accounts are divided into which five categories?', 'Personal, Real, Nominal, Tangible, and Intangible', 'Assets, Liabilities, Capital, Expenses/Losses, and Revenues/Gains', 'Bahi-Khata, Kird, Journal, Ledger, and Trial Balance', 'Natural, Artificial, Representative, Current, and Fixed', 'b', 1, 3, 'Identify the five fundamental account types in modern accounting theory.', 'Under the Modern Approach, all accounts are divided into five categories: Assets, Liabilities, Capital, Expenses/Losses, and Revenues/Gains.'),
        ('acc11-02-mcq-0031', 2, 'Under the Modern Approach, how are increases and decreases in Assets and Expenses recorded?', 'Increase is credited and decrease is debited.', 'Both increase and decrease are debited.', 'Increase is debited and decrease is credited.', 'Both increase and decrease are credited.', 'c', 2, 5, 'Assets and expenses share the same debit-increase normal behavior.', 'The modern rule states: Increase in asset/expense is debited, and decrease in asset/expense is credited.'),
        ('acc11-02-mcq-0032', 2, 'Under the Modern Approach, what is the rule for recording changes in Liabilities, Capital, and Revenues?', 'Increase is debited and decrease is credited.', 'Decrease is credited and increase is debited.', 'Increase is debited and decrease is ignored.', 'Increase is credited and decrease is debited.', 'd', 2, 5, 'These credit-balance accounts increase on the credit side.', 'According to the modern approach: Increase in liabilities, capital, and revenues/gains is credited, while decrease is debited.'),
        ('acc11-02-mcq-0033', 2, 'When ₹5,000 advertisement is paid in cash to Imran, why is Imran''s Account NOT debited?', 'Because only the nature of the expense (Advertisement) is to be considered in cash transactions.', 'Because Imran is an artificial person.', 'Because Imran is the giver of benefit.', 'Because personal accounts are never debited in double entry.', 'a', 2, 5, 'Review Note 1 in Section 2.5 of the chapter regarding nominal cash expenses.', 'As noted explicitly in the chapter: ''Advertisement paid to Imran, here Imran''s Account is not affected. The nature of expense is only to be considered.'''),
        ('acc11-02-mcq-0034', 2, 'Why is ''Purchased Goods from Sunil ₹13,000'' treated as a credit transaction rather than a cash transaction?', 'Goods purchases are always on credit by definition.', 'The name of the person is given and cash payment is not mentioned.', 'Sunil is a proprietary account.', 'Sunil''s account is a Nominal account.', 'b', 2, 5, 'Review Note 2 in Section 2.5 regarding how credit transactions are identified.', 'The chapter note specifies: ''This is considered as credit sale/purchase, because name of the person is given and payment/sale for cash is not given.'''),
        ('acc11-02-mcq-0035', 2, 'When proprietor pays wife''s mobile bill of ₹4,200 from business cash, which account is debited under the Modern Approach and what effect does it represent?', 'Mobile Bill A/c; Increase in Expense', 'Cash A/c; Increase in Asset', 'Drawings A/c; Decrease in Capital', 'Wife''s Personal A/c; Increase in Liability', 'c', 3, 10, 'Personal expenses of the owner paid from business funds are Drawings, reducing equity.', 'Paying personal/family expenses from business cash debits Drawings A/c, which represents a decrease in Capital under the Modern Approach.'),
        ('acc11-02-mcq-0036', 2, 'When cash of ₹10,000 is withdrawn from Bank for office use, what are the modern classification effects on the accounts involved?', 'Decrease in Asset (Cash A/c) and Increase in Asset (Bank A/c)', 'Increase in Expense (Cash A/c) and Decrease in Capital (Bank A/c)', 'Decrease in Liability (Bank A/c) and Increase in Revenue (Cash A/c)', 'Increase in Asset (Cash A/c) and Decrease in Asset (Bank A/c)', 'd', 2, 5, 'Both Cash and Bank are assets; one asset increases while the other decreases.', 'Withdrawing cash from bank for office use involves Cash A/c (Asset increases -> Debit) and Bank A/c (Asset decreases -> Credit).'),
        ('acc11-02-mcq-0037', 2, 'Under the Traditional Approach, when a firm receives commission of ₹4,500 in cash, what are the two accounts involved and their classifications?', 'Cash A/c (Real) and Commission A/c (Nominal)', 'Cash A/c (Nominal) and Commission A/c (Real)', 'Bank A/c (Personal) and Commission A/c (Personal)', 'Cash A/c (Personal) and Commission A/c (Real)', 'a', 2, 5, 'Cash is property/asset, while commission received is an earning/income.', 'Cash A/c is a Real account (comes in -> debited) and Commission A/c is a Nominal account (income -> credited).'),
        ('acc11-02-mcq-0038', 2, 'Under the traditional classification of accounts, ''Prepaid Insurance A/c'' is categorized as a:', 'Nominal Account', 'Representative Personal Account', 'Tangible Real Account', 'Intangible Real Account', 'b', 2, 5, 'Prepaid and outstanding items represent persons or groups in business dealings.', 'Prepaid Insurance represents an amount paid in advance to a person/party and is classified as a Representative Personal Account.'),
        ('acc11-02-mcq-0039', 2, 'Under traditional classification, which of the following accounts is a Nominal Account?', 'Copyright A/c', 'Outstanding Salary A/c', 'Loss by Fire A/c', 'Laptop A/c', 'c', 2, 5, 'Look for an account representing a business loss rather than an asset or liability.', 'Loss by Fire A/c represents an expense/loss and is therefore a Nominal Account. Copyright and Laptop are Real accounts; Outstanding Salary is a Representative Personal account.'),
        ('acc11-02-mcq-0040', 2, 'How is ''Bank Overdraft A/c'' classified under the Modern Approach?', 'Asset Account', 'Capital Account', 'Expense Account', 'Liability Account', 'd', 2, 5, 'Bank overdraft is an amount owed to the bank, representing an obligation.', 'Bank Overdraft represents a short-term obligation/amount payable to the bank, classified under Liabilities A/c in the Modern Approach.'),
        ('acc11-02-mcq-0041', 2, 'In Illustration 5, which of the following accounts is classified under ''Assets''?', 'Live Stock', 'Bills Payable', 'Sundry Creditors', 'Discount Received', 'a', 2, 5, 'Animals owned by a business for commercial purposes are property.', 'In the textbook''s Illustration 5 classification table, ''Live Stock'' is classified under Assets, whereas Creditors and Bills Payable are Liabilities, and Discount Received is an Income.'),
        ('acc11-02-mcq-0042', 2, 'Under the Modern Approach, ''Repairs and Maintenance A/c'' and ''Audit Fees A/c'' are classified under:', 'Assets', 'Expenses and Losses', 'Revenues and Gains', 'Liabilities', 'b', 1, 3, 'These are routine operational costs incurred to run and maintain the business.', 'Both Repairs & Maintenance and Audit Fees represent costs of operations and are classified under Expenses and Losses.'),
        ('acc11-02-mcq-0043', 2, 'What does the fundamental Accounting Equation state?', 'Liabilities = Assets + Capital', 'Capital = Total Assets + Outsider''s Liabilities', 'Assets = Liabilities + Capital', 'Assets + Liabilities = Capital', 'c', 1, 3, 'Total economic resources equal claims of creditors plus owner''s equity.', 'The fundamental accounting equation signifies that assets of a business are always equal to the total of liabilities and capital: Assets = Liabilities + Capital.'),
        ('acc11-02-mcq-0044', 2, 'How can Capital be derived from the fundamental accounting equation?', 'Capital = Total Assets + Outsider''s Liabilities', 'Capital = Total Assets × Outsider''s Liabilities', 'Capital = Outsider''s Liabilities - Total Assets', 'Capital = Total Assets - Outsider''s Liabilities', 'd', 1, 3, 'Rearrange Assets = Liabilities + Capital to solve for Capital.', 'As given in Section 2.8: Capital = Total Assets - Outsider''s Liabilities.'),
        ('acc11-02-mcq-0045', 2, 'If a business has Total Assets of ₹60,000 and Outsider''s Liabilities of ₹10,000, what is the Capital?', '₹50,000', '₹70,000', '₹60,000', '₹10,000', 'a', 2, 5, 'Subtract outsider liabilities from total assets.', 'Capital = Total Assets - Outsider''s Liabilities = ₹60,000 - ₹10,000 = ₹50,000.'),
        ('acc11-02-mcq-0046', 2, 'A business purchases machinery from H.P. Co. on credit for ₹10,000 after commencing business with ₹50,000 cash. What is the new equation?', 'Assets ₹50,000 = Liabilities ₹10,000 + Capital ₹40,000', 'Assets ₹60,000 = Liabilities ₹10,000 + Capital ₹50,000', 'Assets ₹60,000 = Liabilities ₹0 + Capital ₹60,000', 'Assets ₹40,000 = Liabilities ₹10,000 + Capital ₹30,000', 'b', 2, 5, 'Machinery adds ₹10,000 to Assets and creates ₹10,000 in Sundry Creditors (Liabilities).', 'Cash (₹50,000) + Machinery (₹10,000) = Assets ₹60,000. Liabilities (Sundry Creditors) = ₹10,000; Capital = ₹50,000. Thus, ₹60,000 = ₹10,000 + ₹50,000.'),
        ('acc11-02-mcq-0047', 2, 'In Illustration 1, Rohit Sharma received dividend of ₹500 and paid ₹500 for advertisement. How do these two transactions affect Total Assets and Capital?', 'Assets increase by ₹1,000 and Capital decreases by ₹1,000.', 'Assets decrease by ₹500 and Capital increases by ₹500.', 'Both Assets and Capital remain net unchanged because the ₹500 receipt cancels out the ₹500 payment.', 'Liabilities increase by ₹500 and Capital increases by ₹500.', 'c', 2, 5, 'Dividend adds ₹500 to cash and capital; advertisement expense subtracts ₹500 from cash and capital.', 'Receiving dividend adds ₹500 to Assets and Capital. Paying advertisement subtracts ₹500 from Assets and Capital. The net effect on both Total Assets and Capital is zero.'),
        ('acc11-02-mcq-0048', 2, 'In Illustration 2, Rupali purchases Machinery for cash ₹5,000. What is the impact on the total of Assets in the accounting equation?', 'Total assets increase by ₹5,000.', 'Total assets decrease by ₹5,000.', 'Liabilities increase by ₹5,000.', 'Total assets remain unchanged because one asset increases while another decreases by ₹5,000.', 'd', 2, 5, 'Machinery comes in (+₹5,000) and Cash goes out (-₹5,000).', 'Purchasing machinery for cash increases Machinery by ₹5,000 and decreases Cash by ₹5,000, leaving total assets unchanged at ₹25,000.'),
        ('acc11-02-mcq-0049', 2, 'In Illustration 3, what is the accounting equation effect when ''Goods destroyed by fire ₹1,000'' occurs?', 'Assets decrease by ₹1,000 and Capital decreases by ₹1,000', 'Assets decrease by ₹1,000 and Liabilities increase by ₹1,000', 'Assets increase by ₹1,000 and Capital increases by ₹1,000', 'Liabilities decrease by ₹1,000 and Capital decreases by ₹1,000', 'a', 3, 10, 'Goods (stock/asset) are reduced, and a loss reduces the owner''s equity.', 'Goods destroyed by fire reduces stock (Assets -₹1,000) and represents a business loss which reduces Capital (-₹1,000).'),
        ('acc11-02-mcq-0050', 2, 'How does ''Depreciation on Motor Car for 1 year ₹1,000'' affect the Accounting Equation?', 'Increases Motor Car and increases Liabilities', 'Decreases Motor Car (Asset) and decreases Capital (Expense/Loss)', 'Decreases Liabilities and increases Capital', 'Decreases Cash and decreases Capital', 'b', 3, 10, 'Depreciation is a reduction in the book value of an asset due to wear and tear, charged as an expense.', 'As shown in Illustration 3, depreciation reduces the value of Motor Car (Assets -₹1,000) and reduces Capital (-₹1,000) as an operational expense.'),
        ('acc11-02-mcq-0051', 2, 'In Illustration 4, when Nima deposits cash of ₹2,000 into Bank of India, what is the effect on the accounting equation?', 'Assets -₹2,000, Liabilities 0, Capital -₹2,000', 'Assets +₹2,000, Liabilities +₹2,000, Capital 0', 'Assets (+₹2,000 Bank, -₹2,000 Cash), Liabilities 0, Capital 0', 'Assets 0, Liabilities -₹2,000, Capital +₹2,000', 'c', 2, 5, 'One asset account increases while another asset account decreases by the same amount.', 'Depositing cash into bank increases Bank balance (+₹2,000) and decreases Cash in hand (-₹2,000), resulting in zero net change to total assets, liabilities, and capital.'),
        ('acc11-02-mcq-0052', 2, 'When goods costing ₹12,000 are sold at a profit of ₹2,000 (Illustration 5), what are the exact effects on Assets, Liabilities, and Capital?', 'Assets: -₹2,000; Liabilities: 0; Capital: -₹2,000', 'Assets: +₹12,000; Liabilities: +₹2,000; Capital: +₹10,000', 'Assets: +₹14,000; Liabilities: 0; Capital: +₹14,000', 'Assets: -₹12,000 and +₹14,000 (Net +₹2,000); Liabilities: 0; Capital: +₹2,000', 'd', 3, 10, 'Stock leaves at cost (₹12,000), cash/receivable enters at selling price (₹14,000), and profit goes to capital.', 'Stock decreases by ₹12,000 (cost) and Cash/Debtors increase by ₹14,000 (selling price), giving a net asset increase of ₹2,000. Profit of ₹2,000 increases Capital.'),
        ('acc11-02-mcq-0053', 2, 'In Illustration 5, Mr. Mehta withdrew cash for personal use ₹2,500. How does this transaction affect the accounting equation?', 'Assets decrease by ₹2,500 and Capital decreases by ₹2,500', 'Assets decrease by ₹2,500 and Liabilities decrease by ₹2,500', 'Assets decrease by ₹2,500 and Capital increases by ₹2,500', 'Liabilities increase by ₹2,500 and Capital decreases by ₹2,500', 'a', 2, 5, 'Drawings reduce cash held by the business and reduce the proprietor''s investment.', 'Drawings reduce Cash (Assets -₹2,500) and simultaneously reduce owner''s equity (Capital -₹2,500).'),
        ('acc11-02-mcq-0054', 2, 'In Q.7 of the Chapter Exercise, what is the accounting equation effect when ''Goods stolen ₹1,000'' occurs?', 'Assets: -₹1,000; Liabilities: -₹1,000; Capital: 0', 'Assets: -₹1,000; Liabilities: 0; Capital: -₹1,000', 'Assets: +₹1,000; Liabilities: 0; Capital: +₹1,000', 'Assets: 0; Liabilities: +₹1,000; Capital: -₹1,000', 'b', 3, 10, 'Theft represents an abnormal loss of stock, impacting inventory and equity.', 'Goods stolen reduces stock/assets by ₹1,000 and is an abnormal loss which directly reduces capital by ₹1,000.'),
        ('acc11-02-mcq-0055', 2, 'In Q.7 of the Chapter Exercise, taking a ''Loan from Bank ₹7,000'' results in:', 'Increase in Assets ₹7,000 and Increase in Capital ₹7,000', 'Decrease in Assets ₹7,000 and Increase in Liabilities ₹7,000', 'Increase in Assets ₹7,000 and Increase in Liabilities ₹7,000', 'Increase in Liabilities ₹7,000 and Decrease in Capital ₹7,000', 'c', 2, 5, 'Bank balance/cash increases and a bank borrowing obligation is created.', 'Taking a loan from a bank increases Assets (Cash/Bank +₹7,000) and increases Liabilities (Bank Loan +₹7,000).'),
        ('acc11-02-mcq-0056', 2, 'Which of the following accounts is correctly classified as a Personal Account in the Chapter Exercise (Q.6)?', 'Cartage A/c', 'Loose Tools A/c', 'Royalty A/c', 'Siddhivinayak Trust A/c', 'd', 2, 5, 'Trusts and institutions created under law are Artificial Personal Accounts.', 'Siddhivinayak Trust A/c represents an artificial entity/institution and is classified as a Personal Account. Loose Tools is Real; Royalty and Cartage are Nominal.'),
        ('acc11-02-mcq-0057', 2, 'Under the classification in Exercise Q.6, ''Stock of Stationery A/c'' and ''Office Equipment A/c'' are classified as:', 'Real Accounts', 'Nominal Accounts', 'Representative Personal Accounts', 'Artificial Personal Accounts', 'a', 2, 5, 'Unused stationery inventory and office equipment are properties/assets owned by the business.', 'Office Equipment and Stock of Stationery are tangible assets owned by the business, hence classified as Real Accounts.'),
        ('acc11-02-mcq-0058', 2, 'Under Exercise Q.6, how is ''Goods distributed as free sample A/c'' classified under traditional rules?', 'Real Account', 'Nominal Account', 'Personal Account', 'Representative Account', 'b', 2, 5, 'Free samples are an advertisement/sales promotion expense.', 'Goods distributed as free sample is an advertisement/business promotion expense and is therefore a Nominal Account.'),
        ('acc11-02-mcq-0059', 2, 'Under Exercise Q.6, ''Income Received in Advance A/c'' is classified as which type of account?', 'Nominal Account', 'Real Account', 'Representative Personal Account', 'Tangible Real Account', 'c', 2, 5, 'Pre-received revenues represent an obligation to a person or client.', 'Income Received in Advance represents a liability owed to specific clients/customers and is classified as a Representative Personal Account.'),
        ('acc11-02-mcq-0060', 2, 'Under Exercise Q.6, ''Loss on Sale of Furniture A/c'' is classified as:', 'Real Account', 'Representative Personal Account', 'Personal Account', 'Nominal Account', 'd', 1, 3, 'It records a capital loss incurred on the sale of an asset.', 'Any loss incurred in business is classified under Nominal Accounts.'),
        ('acc11-02-mcq-0061', 2, 'Under Exercise Q.6, which type of account is ''Indian Railways A/c''?', 'Artificial Personal Account', 'Real Account', 'Nominal Account', 'Natural Personal Account', 'a', 2, 5, 'Indian Railways is a statutory/government organizational body.', 'Indian Railways is an artificial legal entity/organization created by law, making it an Artificial Personal Account.'),
        ('acc11-02-mcq-0062', 2, 'Under Exercise Q.6, ''Income Tax A/c'' of a sole proprietor is classified under which primary category?', 'Nominal Account (Business Expense)', 'Personal Account (Drawings)', 'Real Account (Asset)', 'Representative Impersonal Account', 'b', 3, 10, 'Income tax on a proprietor''s income is a personal expense treated as drawings.', 'Income Tax paid for a sole proprietor is a personal obligation/drawings of the owner, classified as a Personal Account.'),
        ('acc11-02-mcq-0063', 2, 'Which of the following transactions results simultaneously in an ''Increase in Assets'' and ''Decrease in Assets''?', 'Commenced business with cash ₹50,000', 'Paid salary to staff ₹2,000', 'Purchased furniture for cash ₹5,000', 'Took a bank loan ₹10,000', 'c', 2, 5, 'Buying an asset using ready cash swaps one asset for another.', 'Purchasing furniture for cash increases Furniture (Asset increases) and decreases Cash (Asset decreases), leaving total assets unchanged.'),
        ('acc11-02-mcq-0064', 2, 'Which of the following transactions represents a ''Decrease in Assets'' and ''Decrease in Capital''?', 'Purchased goods on credit from Mandar', 'Cash deposited into Bank', 'Received interest ₹4,000 in cash', 'Paid salary ₹2,900 in cash', 'd', 2, 5, 'Paying an expense in cash reduces liquid assets and reduces owner''s equity.', 'Paying salary reduces Cash (Asset decreases) and as an expense, it reduces owner''s equity (Capital decreases).'),
        ('acc11-02-mcq-0065', 2, 'Which of the following transactions illustrates a ''Decrease in Liabilities'' and ''Decrease in Assets''?', 'Paid ₹5,000 cash to Creditors', 'Bought machinery on credit ₹15,000', 'Sold goods for cash ₹8,000', 'Introduced additional capital ₹7,000', 'a', 2, 5, 'Repaying an outsider creditor with cash reduces both the debt and cash balance.', 'Paying creditors decreases creditor obligations (Liabilities decrease) and reduces Cash balance (Assets decrease).'),
        ('acc11-02-mcq-0066', 2, 'In Practical Problem 1, when Rajasaheb sells old mobile for ₹2,000 cash, which account is credited according to the traditional approach?', 'Sales A/c', 'Old Mobile A/c', 'Cash A/c', 'Rajasaheb''s Capital A/c', 'b', 2, 5, 'When a specific fixed asset/property is sold, its own asset account is credited, not Sales A/c.', 'Selling an old mobile is the disposal of an asset (Mobile goes out -> Old Mobile A/c credited), whereas Sales A/c is only credited when trading goods are sold.'),
        ('acc11-02-mcq-0067', 2, 'In Practical Problem 1, when interest of ₹700 is received from Radhika, why is Interest A/c credited instead of Radhika''s A/c?', 'Radhika is an artificial person.', 'Radhika is the receiver of the benefit.', 'Interest received is an income (Nominal Account rule: Credit all incomes and gains).', 'Personal accounts cannot receive money in cash.', 'c', 2, 5, 'When income is received in cash, the nominal revenue account is credited regardless of the person paying it.', 'When revenue is earned and received, the Nominal account representing the income (Interest A/c) is credited, not the person who paid it.'),
        ('acc11-02-mcq-0068', 2, 'In Practical Problem 4, Mr. Swaraj purchases furniture on credit from S.M Furniture Mart for ₹25,000. What is the immediate effect on the accounting equation?', 'Both Assets and Liabilities decrease by ₹25,000', 'Assets increase by ₹25,000; Capital increases by ₹25,000; Liabilities remain unchanged', 'Assets decrease by ₹25,000; Liabilities increase by ₹25,000', 'Assets increase by ₹25,000; Liabilities increase by ₹25,000; Capital remains unchanged', 'd', 2, 5, 'Furniture is an asset and buying on credit creates a creditor liability.', 'Furniture Mart becomes a creditor (Liabilities +₹25,000) and Furniture enters the business (Assets +₹25,000), leaving Capital unchanged.'),
        ('acc11-02-mcq-0069', 2, 'If a transaction causes an Increase in Assets and an Increase in Capital, which transaction could it be?', 'Proprietor introduced additional capital in cash', 'Purchased goods on credit', 'Withdrew cash from bank for office use', 'Paid electricity bill', 'a', 2, 5, 'Bringing new funds into the business increases cash and increases equity.', 'Introducing additional capital brings Cash into the business (Assets increase) and increases owner''s equity (Capital increases).'),
        ('acc11-02-mcq-0070', 2, 'State whether the statement is True or False: ''Outstanding expense is a nominal account.''', 'True, because all expense accounts are nominal accounts.', 'False, because outstanding expense represents a liability owed to persons and is a representative personal account.', 'True, because it is recorded in the profit and loss account.', 'False, because it is a tangible real account.', 'b', 2, 5, 'Adding a prefix/suffix like ''Outstanding'' or ''Prepaid'' changes an expense into a personal account.', 'As tested in Exercise Q.4(1), Outstanding Expense is NOT a nominal account; it is a Representative Personal Account representing persons to whom payment is due.'),
        ('acc11-02-mcq-0071', 2, 'State whether the statement is True or False: ''Capital account is a real account.''', 'True, because capital represents physical cash in the business.', 'True, because it appears on the Balance Sheet.', 'False, because Capital account represents the proprietor and is a personal account.', 'False, because Capital account is a nominal account of profits.', 'c', 2, 5, 'Capital represents the business proprietor.', 'In Exercise Q.4(2), the statement is False because Capital Account represents the business proprietor (a person) and is classified as a Personal Account.'),
        ('acc11-02-mcq-0072', 2, 'State whether the statement is True or False: ''Drawings account is a nominal account.''', 'True, because it represents an expense of the enterprise.', 'False, because Drawings account is a tangible real account.', 'True, because it reduces the net profit of the business.', 'False, because Drawings account represents the proprietor who withdraws assets and is a personal account.', 'd', 2, 5, 'Drawings represents the owner withdrawing money/goods for personal use.', 'In Exercise Q.4(5), the statement is False because Drawings account represents the proprietor withdrawing money for private use, making it a Personal Account.'),
        ('acc11-02-mcq-0073', 2, 'State whether the statement is True or False: ''Bank loan account is a nominal account.''', 'False, because Bank loan account represents a financial institution/lender and is a personal account.', 'True, because it involves payment of interest expenses.', 'True, because it is an impersonal liability.', 'False, because Bank loan account is an intangible real account.', 'a', 2, 5, 'A bank loan is a liability owed to a banking institution.', 'In Exercise Q.4(13), Bank loan account is an artificial personal account (or liability), not a nominal account.'),
        ('acc11-02-mcq-0074', 2, 'State whether the statement is True or False: ''Trademark account is a personal account.''', 'True, because a trademark is owned by a person.', 'False, because Trademark account is an intangible asset and classified as a Real account.', 'True, because it is registered under intellectual property law.', 'False, because Trademark account is an expense/nominal account.', 'b', 2, 5, 'Trademarks are intellectual property assets.', 'In Exercise Q.4(15), Trademark account is an Intangible Real Account because it is a property/asset of the business, not a personal account.'),
        ('acc11-02-mcq-0075', 2, 'State whether the statement is True or False: ''Personal transactions of the proprietor are recorded in the books of account of business.''', 'True, because the proprietor and business are legally identical in all respects.', 'True, because all personal household expenses reduce taxable income.', 'False, because only business monetary transactions are recorded; personal transactions are recorded only if they affect business funds as capital or drawings.', 'False, because double entry forbids recording any transactions related to the owner.', 'c', 2, 5, 'Recall the business entity principle separating owner from business.', 'Personal transactions of the proprietor are not recorded in the business books unless they involve introducing capital or withdrawing business resources as drawings.'),
        ('acc11-02-mcq-0076', 2, 'When Mr. Manohar sells goods costing ₹20,000 at a profit of ₹5,000 in cash (Activity 4), what are the amounts recorded in the accounting equation?', 'Assets decrease by ₹5,000; Capital decreases by ₹5,000', 'Assets increase by ₹20,000; Capital increases by ₹20,000', 'Assets increase by ₹5,000; Liabilities increase by ₹5,000', 'Assets decrease by ₹20,000 and increase by ₹25,000; Capital increases by ₹5,000', 'd', 3, 10, 'Cash received is ₹25,000, stock removed is ₹20,000, and profit earned is ₹5,000.', 'Selling goods costing ₹20,000 for ₹25,000 cash reduces stock by ₹20,000, increases cash by ₹25,000 (net asset increase of ₹5,000), and adds the ₹5,000 profit to Capital.'),
        ('acc11-02-mcq-0077', 2, 'In Practical Problem 3, Mr. Vaibhav starts with ₹1,00,000 cash, buys goods on credit ₹9,000, buys laptop for cash ₹10,000, sells goods to Rina on credit ₹12,000, receives interest ₹2,500, and pays telephone bill ₹1,300. What is his final Capital?', '₹1,01,200', '₹1,00,000', '₹1,10,200', '₹1,02,500', 'a', 3, 10, 'Initial Capital + Interest Received - Telephone bill = Final Capital.', 'Initial Capital = ₹1,00,000. Interest received (+₹2,500) and telephone bill (-₹1,300) affect capital. Final Capital = 1,00,000 + 2,500 - 1,300 = ₹1,01,200.'),
        ('acc11-02-mcq-0078', 2, 'In Practical Problem 4, Mr. Swaraj has bank balance ₹1,10,000, buys furniture on credit ₹25,000, buys goods on credit ₹15,000, buys machinery for cash ₹10,000, pays electricity bill ₹3,500, and goods destroyed by fire ₹1,500. What are the total Liabilities at the end?', '₹25,000', '₹40,000', '₹15,000', '₹50,000', 'b', 3, 10, 'Add the two credit purchases: Furniture Mart and Yuvraj.', 'Liabilities consist of creditors for furniture (₹25,000) and creditors for goods/Yuvraj (₹15,000), totaling ₹40,000.'),
        ('acc11-02-mcq-0079', 2, 'In Practical Problem 5, Rohit has starting cash ₹50,000, buys goods on credit from Manoj ₹6,000, cash purchases ₹5,000, pays wages ₹3,000, sells goods to Santosh on credit ₹7,000, and receives commission ₹1,000. What is Rohit''s final Capital?', '₹50,000', '₹54,000', '₹48,000', '₹45,000', 'c', 3, 10, 'Starting Capital ₹50,000 - Wages ₹3,000 + Commission ₹1,000.', 'Capital starts at ₹50,000. Wages paid reduce capital by ₹3,000, and commission received increases capital by ₹1,000. Final Capital = 50,000 - 3,000 + 1,000 = ₹48,000.'),
        ('acc11-03-mcq-0001', 3, 'What is the primary role of a source document in Book-Keeping?', 'To act as legal evidence and proof supporting business transactions recorded in the books', 'To summarize the ledger balances at the close of an accounting year', 'To calculate the net annual profit or loss of the firm', 'To replace the need for entering transactions into the journal book', 'a', 1, 3, 'Think about why an accountant first ensures the reliability of a transaction before recording.', 'According to the chapter, Book-Keeping records transactions on the basis of supporting documents; a document is a legal proof and the base for entering business transactions into the books of accounts. Options B and C describe functions of financial statements, not source documents.'),
        ('acc11-03-mcq-0002', 3, 'Which of the following is explicitly listed in the chapter as a legal or statutory utility of accounting documents?', 'They serve as a substitute for maintaining personal and real accounts', 'They are required for submissions to the Charity Commissioner''s office and court matters', 'They automatically file income tax returns on behalf of the business', 'They eliminate the requirement of preparing a trial balance', 'b', 1, 3, 'Recall the 6 specific utilities listed under Section 3.1 regarding government and legal bodies.', 'The chapter lists among the utilities of accounting documents that they serve as legal evidence for court matters and are required for the Charity Commissioner''s office and payments to state government and local body authorities.'),
        ('acc11-03-mcq-0003', 3, 'A document that supports a payment made by a businessman and serves as legal evidence that a sum of money was paid to a specific person is called a:', 'Debit Note', 'Credit Note', 'Voucher', 'Ledger Folio', 'c', 1, 3, 'Focus on the general term used for payment-supporting documentary evidence.', 'The text defines a voucher as a document that supports a payment made by the businessman and acts as legal evidence that a certain sum has been paid to a specific party. Ledger Folio is merely a page reference.'),
        ('acc11-03-mcq-0004', 3, 'An internal voucher is prepared by an organisation primarily when:', 'A customer makes a large payment via crossed cheque', 'A bank issues a monthly statement of account', 'Goods are purchased on credit from a registered supplier', 'No third-party receipt can be obtained as proof for a transaction, such as taxi or auto fare', 'd', 2, 5, 'Consider transactions like local bus or auto fare where external printed receipts are unavailable.', 'Internal vouchers are created internally by the business and signed by the payee when a receipt cannot be obtained as proof (e.g., taxi fare, bus fare, auto fare). For credit purchases or bank transactions, external documents like invoices or counterfoils are used.'),
        ('acc11-03-mcq-0005', 3, 'Which of the following documents is categorized in the chapter as an ''External Voucher''?', 'Tax Invoice received from a seller for purchasing stationery', 'Bus fare slip prepared internally by the firm''s cashier', 'Petty auto fare voucher signed by an employee', 'Internal wage sheet approved by the business manager', 'a', 2, 5, 'Look for a document received from an agency or party outside the business organisation.', 'External vouchers are documents generated outside the business and received from an outside agency, such as a Tax Invoice received from a seller, electricity bill receipt, Debit Note, or Cash Memo.'),
        ('acc11-03-mcq-0006', 3, 'What is the specific purpose of a ''Journal Voucher'' as stated in the text?', 'It replaces the Cash Book for recording all cash inflows and outflows', 'It is the basic/original voucher on the basis of which transactions are journalised in the Journal book', 'It is sent to a credit customer demanding immediate settlement of dues', 'It serves as a formal contract between a buyer and a supplier', 'b', 1, 3, 'Identify the primary source voucher used specifically to draft journal entries.', 'Under the specimen of Journal voucher, the text states: ''Journal voucher is basic/original voucher on the basis of which the transactions should be Journalised in journal book.'''),
        ('acc11-03-mcq-0007', 3, 'On the basis of which document are entries directly recorded in the Cash Book?', 'Journal Voucher', 'Purchase Return Slip', 'Cash Voucher', 'Credit Memo', 'c', 1, 3, 'This document provides evidence of cash payments and cash receipts.', 'The text states that the evidence of cash payments and receipts is called a cash voucher, and it is the document on the basis of which entries are made in the Cash Book.'),
        ('acc11-03-mcq-0008', 3, 'For a buyer, a Tax Invoice received from the supplier is termed as a/an:', 'Internal Credit Memo', 'Cash Payment Voucher', 'Sales Invoice or Outward Invoice', 'Purchase Invoice or Inward Invoice', 'd', 2, 5, 'Consider the direction in which goods and invoices flow into the buyer''s business.', 'A Tax Invoice is a ''purchase invoice'' or ''inward invoice'' for the buyer, and a ''sales invoice'' or ''outward invoice'' for the seller. Entries in the Purchase Book are made based on inward invoices received.'),
        ('acc11-03-mcq-0009', 3, 'What information does a seller communicate to a customer through a Credit Memo?', 'Details of goods sold on credit for which a certain amount becomes due from the customer', 'A request to the bank to stop payment of a dishonoured cheque', 'A statement showing only the trade discount without listing supplied goods', 'Confirmation that cash has been physically received at the counter', 'a', 2, 5, 'A Credit Memo is also known as an invoice or bill for credit transactions.', 'The chapter explains that a Credit Memo (invoice/bill) is prepared by a seller when goods are sold on credit, informing the customer of goods sold and the amount that has become due.'),
        ('acc11-03-mcq-0010', 3, 'When a customer makes a payment on a future date for credit purchases, the seller acknowledges the receipt of money by issuing a:', 'Credit Memo', 'Receipt', 'Debit Note', 'Tax Invoice', 'b', 1, 3, 'This document acknowledges payment received via cash, cheque, NEFT, or RTGS.', 'At the time of making payment, the receiver is required to acknowledge the payment by preparing a ''Receipt'', on the basis of which entries are recorded in the Cash Book.'),
        ('acc11-03-mcq-0011', 3, 'According to the definition in the chapter, a cheque is an order that is:', 'Conditional upon the banker''s quarterly financial performance', 'Oral or written, payable only after three months of issuance', 'Written and unconditional, directing a specific banker to pay on demand', 'A bilateral agreement signed by both the drawer and drawee simultaneously', 'c', 1, 3, 'Recall the legal definition: ''A cheque is a written unconditional order signed by the Account holder...''', 'The chapter explicitly defines a cheque as ''a written unconditional order signed by the Account holder directing a specific Banker to pay on demand certain sum of money only to a person named therein or to the bearer''.'),
        ('acc11-03-mcq-0012', 3, 'In the context of a cheque, who is the ''Drawee''?', 'The endorsee who presents the cheque at the counter', 'The person in whose favour the cheque is issued', 'The person who writes and signs the cheque', 'The bank on whom the cheque is drawn', 'd', 1, 3, 'The text states that this party is ''always the bank''.', 'The chapter defines the three parties to a cheque: Drawer (who draws the cheque), Drawee (the bank on whom the cheque is drawn; always the bank), and Payee (the person in whose favour it is issued).'),
        ('acc11-03-mcq-0013', 3, 'How can a Bearer Cheque be converted into an Order Cheque?', 'By striking off the word ''Bearer'' on the cheque', 'By drawing two parallel transverse lines across the left top corner', 'By writing ''Account Payee Only'' between two lines', 'By obtaining a counter-signature from the bank manager', 'a', 2, 5, 'Observe the specimen and text regarding how an Order Cheque is created from a standard printed cheque leaf.', 'The text states: ''When the word Bearer is struck off it becomes an Order Cheque.'' Crossing with two parallel lines creates a crossed cheque, not simply an order cheque.'),
        ('acc11-03-mcq-0014', 3, 'What is the legal effect of drawing two parallel transverse lines on the face of a cheque without extra words?', 'The cheque becomes payable in cash to any person holding it at the counter', 'The cheque must be deposited into a bank account and cannot be encashed directly over the counter', 'The cheque can only be drawn against foreign currency balances', 'The cheque is cancelled immediately and cannot be honoured', 'b', 2, 5, 'Recall why crossed cheques are safer for the drawer and drawee.', 'A crossed cheque has to be deposited into a bank account, and payment is made only through the bank, ensuring that payment is received by the rightful person rather than being encashed at the counter.'),
        ('acc11-03-mcq-0015', 3, 'A cheque with two parallel transverse lines containing the words ''Account Payee'' ensures that:', 'The bank pays cash immediately to whoever presents the cheque at the branch counter', 'The cheque can be freely transferred and endorsed to third parties multiple times', 'The amount is credited strictly to the payee''s specific bank account', 'The drawer does not need to maintain a minimum bank balance', 'c', 2, 5, 'Consider the specific restriction imposed by the words ''Account Payee''.', 'In a Crossed Account Payee Cheque, the specific person or organisation deposits the cheque into the bank and the amount is credited to their specific account only.'),
        ('acc11-03-mcq-0016', 3, 'The English word ''Journal'' is derived from which French word, and what is its meaning?', '''JOURNALIER'', which means ''Book''', '''JOURNALISME'', which means ''Writing''', '''JOURNEE'', which means ''Journey''', '''JOUR'', which means ''Day''', 'd', 1, 3, 'The term relates to a daily record.', 'The text specifies: ''The word Journal is derived from the French word JOUR which means a Day. Therefore journal means a daily record.'''),
        ('acc11-03-mcq-0017', 3, 'Who defined a Journal as ''a book, employed to classify or sort out transactions in a form convenient for their subsequent entry in the Ledger''?', 'L.C. Cropper', 'R.N. Carter', 'J.R. Batliboi', 'Eric Kohler', 'a', 1, 3, 'Check the definitions cited under Section 3.2.1.', 'Under definitions, the chapter explicitly cites L.C. Cropper for this definition, whereas Eric Kohler defines it in ''A Dictionary for Accountant''.'),
        ('acc11-03-mcq-0018', 3, 'According to Eric Kohler''s definition in ''A Dictionary for Accountant'', a Journal is:', 'A loose-leaf record of receipts issued to sundry debtors', 'The book of original entry in which are recorded transactions not provided for in specialised journals', 'A permanent register containing only nominal and real accounts', 'A secondary book maintained solely to balance ledger accounts at year-end', 'b', 2, 5, 'Look for the definition referencing transactions ''not provided for in specialised journals''.', 'The chapter quotes Eric Kohler: ''A Journal is the book of original entry are recorded transaction not provided for in specialised journals''.'),
        ('acc11-03-mcq-0019', 3, 'In accounting classification, which of the following is categorized as a ''Secondary Book''?', 'Journal Proper', 'Sales Book', 'Ledger', 'Purchase Book', 'c', 1, 3, 'Primary books include Journal proper and special journals, while secondary book refers to another major book.', 'Section 3.2 explains that primary books include Journal proper and special journals (Purchases Book, Sales Book, etc.), while the secondary book includes the Ledger.'),
        ('acc11-03-mcq-0020', 3, 'Transactions are recorded in the Journal in which specific arrangement?', 'Categorical order based on asset durability', 'Decreasing order of transaction amounts', 'Alphabetical order based on customer name', 'Chronological order (date-wise in order of occurrence)', 'd', 1, 3, 'Transactions are recorded daily as they take place over time.', 'The text explicitly mentions that ''Journal is a book in which the business transactions are first recorded in a chronological order i.e. Date wise in the order in which they take place.'''),
        ('acc11-03-mcq-0021', 3, 'In the standard specimen of a Journal, how many columns are there, and what are their headers from left to right?', '5 columns: Date, Particulars, L.F., Debit Amount (₹), Credit Amount (₹)', '4 columns: Date, Particulars, Folio, Net Amount (₹)', '5 columns: Date, Particulars, C.F., Cash (₹), Bank (₹)', '6 columns: Date, Voucher No., Particulars, L.F., Debit (₹), Credit (₹)', 'a', 1, 3, 'Review the standard format shown in Section 3.3 of the chapter.', 'The specimen of Journal consists of 5 columns: Date, Particulars, L.F. (Ledger Folio), Debit Amount (₹), and Credit Amount (₹).'),
        ('acc11-03-mcq-0022', 3, 'What is ''Narration'' in a journal entry, and how should it begin?', 'The supplier''s tax registration code, beginning with ''GSTIN''', 'A brief explanation of the journal entry written in brackets, beginning with the word ''Being''', 'The ledger page reference written on top of the date column, beginning with ''Ref.''', 'A legal contract number written in red ink, beginning with the word ''Dr.''', 'b', 1, 3, 'It provides clarity about the entry and is placed immediately below the credited account line.', 'The text states: ''Narration is a brief explanation of the Journal Entry. It is written in the bracket and begins with word, Being''.'),
        ('acc11-03-mcq-0023', 3, 'Why is the Ledger Folio (L.F.) column left blank at the exact time of journalising?', 'Because the voucher number must be verified by the bank before posting', 'Because it is an optional column reserved exclusively for external auditors', 'Because the page number in the ledger is entered only when the entry is actually posted to the ledger', 'Because the ledger is prepared prior to writing the journal', 'c', 2, 5, 'Posting happens subsequently after transactions are journalised.', 'As noted in the chapter and Exercise Q.3(5), the L.F. column of the Journal is not recorded at the time of journalising; the page number of the ledger is recorded against each account at the time of posting into the ledger.'),
        ('acc11-03-mcq-0024', 3, 'To distinguish the Ledger Folio numbers from amounts, the chapter mentions that folio numbers may be written in:', 'Italics with blue ink', 'Green ink', 'Pencil only', 'Red ink', 'd', 1, 3, 'Check the note under explanation of columns: ''Folio number may be written in...''', 'Under column 3 (Ledger Folio Number), the text notes: ''The Folio number may be written in red ink to distinguish them from the amount''.'),
        ('acc11-03-mcq-0025', 3, 'When casting a page of the Journal, how are totals carried forward and brought forward to the next page?', 'Written as ''Total c/f'' at the page end and ''Total b/f'' at the start of the next page', 'Written as ''Balance c/d'' at the page end and ''Balance b/d'' at the start of the next page', 'Written as ''Gross Total'' at both the bottom and top of consecutive pages', 'Written as ''Posting Forward'' and ''Posting Inward'' respectively', 'a', 2, 5, 'Look for the abbreviations representing ''carried forward'' and ''brought forward''.', 'The text states: ''...at the end of each page the total of amount columns is carried forward to the next page by writing the words Total c/f in particulars column. The next page will begin with the total brought forward from previous page, by writing the words Total b/f...''.'),
        ('acc11-03-mcq-0026', 3, 'In the visual flowchart ''How transaction travels'' given in Section 3.3, which step immediately precedes ''Journal''?', 'Ascertain two accounts', 'A/c to be debited and A/c to be credited', 'Classification of accounts', 'Source documents', 'b', 2, 5, 'Trace the downward flowchart sequence on page 53.', 'The sequence is: Source documents -> Transactions -> Ascertain two accounts -> Classification of accounts -> Ascertain two effects -> A/c to be debited and A/c to be credited -> Journal.'),
        ('acc11-03-mcq-0027', 3, 'According to the rules of journalising, where is a line drawn to keep entries distinctly separate from each other?', 'In the Date and Ledger Folio columns only', 'Across all five columns of the journal page', 'In the Particulars column only, after each journal entry', 'Only at the very bottom of each journal page', 'c', 1, 3, 'Check Step 10 of ''Steps for Journalising''.', 'Step 10 states: ''After each Journal entry a line is to be drawn in particulars column only to keep the entries of the transactions distinctly separate from each other.'''),
        ('acc11-03-mcq-0028', 3, 'Goods and Services Tax (GST) was officially implemented in India on which date?', '1st July 2018', '1st April 2017', '1st April 2018', '1st July 2017', 'd', 1, 3, 'Recall the exact rollout date mentioned under Section 3.3.1.', 'Section 3.3.1 explicitly states: ''GST is started from 1st of July 2017.'' (Also tested in Exercise Q.7(4)).'),
        ('acc11-03-mcq-0029', 3, 'What code is used in a tax invoice for the classification of services under GST?', 'SAC (Service Accounting Code)', 'IFSC (Indian Financial System Code)', 'MICR (Magnetic Ink Character Recognition)', 'HSN (Harmonised System of Nomenclature)', 'a', 1, 3, 'HSN is used for goods, while services have a dedicated 3-letter code.', 'The text states: ''In the tax invoice for Goods, there is HSN i.e. Harmonised System of Nomenclature code while in service invoice there is SAC. Services are also classified and special code numbers are given. These are called SAC or Service Accounting Code.'''),
        ('acc11-03-mcq-0030', 3, 'Which of the following items is outside the purview of GST according to the chapter note?', 'Mobile phones and dry fruit', 'Petrol, diesel, and electricity', 'LPG cylinder and tea', 'Butter, ghee, and pickles', 'b', 2, 5, 'Read the ''Note'' at the foot of the GST rates table in Section 3.3.1.', 'The note beneath the GST rate schedule specifies: ''Electricity, petrol, diesel etc are not under purview of GST.'' All other listed items fall under 5% or 12% slabs.'),
        ('acc11-03-mcq-0031', 3, 'Under which GST rate slab do essential commodities such as food grains, fresh vegetables, milk, and salt fall?', 'Standard rated I slab (12%)', 'Standard rated II slab (18%)', 'Zero rated (0%)', 'Low rated (5%)', 'c', 1, 3, 'Basic survival essentials carry no indirect tax levy under GST.', 'Under the GST rate table, Zero rated (0%) applies to essential commodities like food grains, fruits, vegetables, milk, salt, and earthen pots, as well as education and healthcare services.'),
        ('acc11-03-mcq-0032', 3, 'According to the chapter''s GST schedule, which rate applies to LPG cylinders, tea, coffee, and railway transport services?', '0% (Zero rated)', '18% (Standard rated II slab)', '12% (Standard rated I slab)', '5% (Low rated)', 'd', 2, 5, 'This tier is designated as ''Low rated'' for commonly used household items.', 'The table lists LPG cylinder, tea, coffee, oil, honey, spices, railway and bus transport services under the Low rated slab of 5%.'),
        ('acc11-03-mcq-0033', 3, 'Consumer goods such as butter, ghee, mobile phones, and printing job work fall under which GST slab in the chapter?', '12% (Standard rated I slab)', '5% (Low rated)', '28% (Highly rated)', '18% (Standard rated II slab)', 'a', 2, 5, 'This is the first of two standard rate slabs.', 'Section 3.3.1 classifies butter, ghee, dry fruit, jam, mobile phones, and printing job work under Standard rated (I slab) at 12%.'),
        ('acc11-03-mcq-0034', 3, 'Which of the following items is categorized under the 28% (Highly rated) GST slab?', 'Earthen pots and public library services', 'Luxury cars, air conditioners, and five-star hotel accommodation', 'Spices, sweets, and taxi transport services', 'Computers, printers, and courier services', 'b', 2, 5, 'Look for luxury, demerit, or heavy consumer durable goods.', 'Luxury cars, motorcycles, AC, washing machine, fridge, aerated water, and five-star hotel accommodation are classified under the 28% Highly rated slab. Computers and courier services fall under 18%.'),
        ('acc11-03-mcq-0035', 3, 'When goods or services are purchased within a state with GST, how is the total tax split?', 'Calculated entirely as an expense without splitting', '100% credited to CGST with no state component', 'Equally divided into CGST (Central GST) and SGST (State GST)', '75% assigned to SGST and 25% to CGST', 'c', 2, 5, 'Observe how an 18% GST rate is split in the textbook examples.', 'In all textbook examples (e.g., Laptop purchase at 18% GST), the total GST is divided equally: CGST at 9% and SGST at 9%.'),
        ('acc11-03-mcq-0036', 3, 'When a business sells goods or services on which GST is levied, which tax accounts are credited in the seller''s books?', 'Input CGST A/c and Input SGST A/c', 'GST Expense A/c and Sales Tax A/c', 'Trade Discount A/c and Output Tax A/c', 'Output CGST A/c and Output SGST A/c', 'd', 2, 5, 'Tax collected on outward sales represents a liability payable to the government.', 'On sales of goods or assets, Output CGST A/c and Output SGST A/c are credited (as shown in Example 2: Sold Motor Car). Input tax accounts are debited on purchases.'),
        ('acc11-03-mcq-0037', 3, 'When goods are purchased on credit from Mrs. Sonali for ₹15,000, what is the correct journal entry?', 'Debit Purchases A/c ₹15,000; Credit Mrs. Sonali''s A/c ₹15,000', 'Debit Purchases A/c ₹15,000; Credit Cash A/c ₹15,000', 'Debit Mrs. Sonali''s A/c ₹15,000; Credit Purchases A/c ₹15,000', 'Debit Goods Inward A/c ₹15,000; Credit Bank A/c ₹15,000', 'a', 1, 3, 'Purchases represent goods coming in, and the supplier is the giver of benefit.', 'Under Section 3.4 Example 2, when goods are bought on credit, Purchases A/c is debited (expenses/goods coming in) and the creditor''s account (Mrs. Sonali''s A/c) is credited.'),
        ('acc11-03-mcq-0038', 3, 'When purchased goods are returned to a supplier, which account is credited?', 'Supplier''s Personal A/c', 'Return Outward A/c (or Purchase Return A/c)', 'Return Inward A/c (or Sales Return A/c)', 'Trading Profit A/c', 'b', 1, 3, 'Goods purchased previously are moving outwards back to the seller.', 'When goods purchased are returned to the supplier, goods go out, so Return Outward A/c (or Purchase Return A/c) is credited, and the supplier''s personal account is debited.'),
        ('acc11-03-mcq-0039', 3, 'Which of the following is NOT listed in the chapter as a valid reason for returning goods to a supplier?', 'Goods are defective or of inferior quality', 'Goods are not according to the sample agreed upon', 'The market price of the goods increased after the delivery was completed', 'Goods are received in excess quantity than ordered', 'c', 2, 5, 'Review the six specific reasons for purchase returns listed on page 56.', 'The chapter lists six reasons: not according to sample, inferior quality, damaged in transit, defective, excess quantity received, and delay in supply. A post-delivery price increase is not a ground for return.'),
        ('acc11-03-mcq-0040', 3, 'A customer, Govind, returns goods worth ₹8,000 that were previously sold to him on credit. What is the correct journal entry?', 'Debit Loss on Returns A/c ₹8,000; Credit Govind''s A/c ₹8,000', 'Debit Sales A/c ₹8,000; Credit Cash A/c ₹8,000', 'Debit Govind''s A/c ₹8,000; Credit Return Outward A/c ₹8,000', 'Debit Return Inward A/c ₹8,000; Credit Govind''s A/c ₹8,000', 'd', 2, 5, 'Goods sold are coming back inwards from the customer.', 'When sold goods are returned by a buyer, Return Inward A/c (or Sales Return A/c) is debited because goods come in, and the customer (Govind''s A/c) is credited as the giver.'),
        ('acc11-03-mcq-0041', 3, 'When a proprietor withdraws goods from the business for personal or household use, what is the accounting rationale for crediting Purchases A/c (or Goods Withdrawn by Proprietor A/c)?', 'The goods taken are assumed to have been withdrawn from total purchases at cost price', 'The withdrawal is treated as a profitable cash sale to an outsider', 'The goods are written off as an uninsurable trading loss', 'The withdrawal reduces the firm''s bank overdraft balance', 'a', 2, 5, 'Consider how goods withdrawn by the owner affect the original stock bought for resale.', 'The text states: ''The goods which are taken by the proprietor are assumed as taken from the total purchases.'' Drawings A/c is debited and Goods withdrawn by proprietor / Purchases A/c is credited.'),
        ('acc11-03-mcq-0042', 3, 'What is the correct journal entry when goods are distributed as free samples to promote a product?', 'Debit Sample Expense A/c; Credit Sales A/c', 'Debit Advertisement A/c; Credit Goods Distributed as Free Sample A/c (or Purchases A/c)', 'Debit Sales A/c; Credit Advertisement A/c', 'Debit Drawings A/c; Credit Cash A/c', 'b', 2, 5, 'Free samples represent a marketing expenditure, and goods leave the business without generating sales revenue.', 'Free samples are distributed for advertisement, so Advertisement A/c is debited (nominal expense) and Goods Distributed as Free Sample / Purchases A/c is credited as goods go out.'),
        ('acc11-03-mcq-0043', 3, 'Uninsured goods worth ₹10,000 are completely destroyed by fire. What is the journal entry to record this loss?', 'Debit Insurance Co. A/c ₹10,000; Credit Purchases A/c ₹10,000', 'Debit Purchases A/c ₹10,000; Credit Loss by Fire A/c ₹10,000', 'Debit Loss by Fire A/c ₹10,000; Credit Goods Destroyed by Fire A/c (or Purchases A/c) ₹10,000', 'Debit Capital A/c ₹10,000; Credit Sales A/c ₹10,000', 'c', 2, 5, 'Since the goods were uninsured, the entire amount is an immediate nominal loss.', 'Section 3.4 (7)(A) shows: When goods are uninsured and destroyed by fire, Loss by fire A/c is debited and Goods destroyed by fire A/c or Purchases A/c is credited.'),
        ('acc11-03-mcq-0044', 3, 'Goods worth ₹20,000 destroyed by fire were insured, and the insurance company admitted the claim in full. Which account is debited?', 'Purchases A/c', 'Cash A/c', 'Loss by Fire A/c', 'Insurance Co. A/c', 'd', 2, 5, 'The insurance company is now a debtor liable to settle the full claim amount.', 'When the full claim is admitted by the insurance company, the company becomes liable to pay, so Insurance Co. A/c is debited and Goods destroyed by fire / Purchases A/c is credited.'),
        ('acc11-03-mcq-0045', 3, 'Goods costing ₹15,000 are damaged in transit. The insurance company admits a claim of ₹10,000. What is the correct combined journal entry?', 'Debit Insurance Co. A/c ₹10,000, Debit Loss in Transit A/c ₹5,000; Credit Goods Lost in Transit A/c ₹15,000', 'Debit Cash A/c ₹10,000; Credit Loss in Transit A/c ₹10,000', 'Debit Insurance Co. A/c ₹15,000; Credit Purchases A/c ₹10,000, Credit Profit A/c ₹5,000', 'Debit Loss in Transit A/c ₹15,000; Credit Insurance Co. A/c ₹10,000, Credit Cash A/c ₹5,000', 'a', 3, 10, 'Debit the accepted claim to the insurer, debit the unrecovered balance as actual loss, and credit total goods lost.', 'When a claim is partly admitted: Insurance Co. A/c is debited for the admitted claim (₹10,000), Loss in transit A/c is debited for the unadmitted loss (₹5,000), and Goods lost in transit A/c (or Purchases A/c) is credited for the total (₹15,000).'),
        ('acc11-03-mcq-0046', 3, 'When goods are stolen by pilferage or theft from a shop, what entry must be passed?', 'Debit Goods Lost A/c; Credit Loss by Theft A/c', 'Debit Loss by Theft A/c; Credit Goods Lost A/c (or Purchases A/c)', 'Debit Sundry Creditors A/c; Credit Purchases A/c', 'Debit Drawings A/c; Credit Cash A/c', 'b', 2, 5, 'Theft represents a physical loss (nominal expense/loss) and reduces available merchandise.', 'Section 3.4 (9) states: ''If the goods are pilfered or lost by theft or stolen it becomes physical loss of goods. Loss by theft A/c Dr. To Goods lost A/c or Purchases A/c''.'),
        ('acc11-03-mcq-0047', 3, 'What distinguishes a ''Simple Journal Entry'' from a ''Compound/Combined Journal Entry''?', 'A simple entry does not require a narration, whereas a compound entry requires two narrations', 'A simple entry is recorded in the Ledger, whereas a compound entry is recorded in the Journal', 'A simple entry affects exactly two accounts (one debit, one credit), whereas a compound entry affects more than two accounts', 'A simple entry involves only cash transactions, whereas a compound entry involves only credit transactions', 'c', 1, 3, 'Recall the definition based on the number of accounts debited and credited.', 'The chapter defines: ''In a simple entry, only two accounts are affected, one account is debited and the other is credited.'' A journal entry containing more than one debit or more than one credit is a combined/compound entry.'),
        ('acc11-03-mcq-0048', 3, 'How is a ''Bearer Cheque'' received from a debtor treated on the date of receipt, according to the chapter''s explanatory notes?', 'It is debited immediately to Bank A/c', 'It is credited to Cheques in Hand A/c', 'It is not recorded until deposited and cleared by the drawee bank', 'It is treated as Cash received and debited to Cash A/c', 'd', 2, 5, 'Refer to Illustration 1 explanatory note dated April 18.', 'Explanatory Note 1 on page 63 states: ''A bearer cheque is received from Vikas. Bearer cheque received is treated as cash received. [Real A/c]... Cash A/c is debited and Vikas A/c is credited.'''),
        ('acc11-03-mcq-0049', 3, 'Which type of discount is an allowance on the printed list price of goods and is NEVER recorded in the books of accounts?', 'Trade Discount', 'Rebate for Prompt Payment', 'Settlement Discount', 'Cash Discount', 'a', 1, 3, 'This discount is deducted directly on the invoice regardless of whether the sale is cash or credit.', 'The text states: ''Trade Discount: It is an allowance given on printed list price of goods... Trade discount is not recorded in the books of accounts.'' Only net invoice price is entered.'),
        ('acc11-03-mcq-0050', 3, 'Cash discount is granted by a seller to a buyer specifically to:', 'Promote bulk purchases of slow-moving inventory', 'Encourage prompt payment', 'Comply with mandatory GST invoicing rules', 'Compensate for transit damages', 'b', 1, 3, 'Think about why a creditor offers a deduction for paying within a short time window.', 'The text defines Cash Discount: ''It is the concession given to encourage prompt payment... It is recorded in the books of accounts.'''),
        ('acc11-03-mcq-0051', 3, 'In the books of the person receiving cash, how is Cash Discount classified and recorded?', 'It is an asset (Real Account) and is debited to Cash A/c', 'It is a liability (Personal Account) and is credited to Creditor''s A/c', 'It is a loss (Nominal Account) and is debited to Discount Allowed A/c', 'It is a gain (Nominal Account) and is credited to Discount Received A/c', 'c', 2, 5, 'The receiver of cash accepts less money than due to expedite receipt.', 'The chapter explains: ''Cash discount is a loss to the receiver of cash and a gain to the giver of cash. Therefore, whenever cash discount is allowed, discount allowed account should be debited in the books of the person who receives cash''.'),
        ('acc11-03-mcq-0052', 3, 'Amar bought goods worth ₹20,000 from Rakesh at a 10% Trade Discount. At what value will the transaction be recorded in Amar''s Purchases A/c?', '₹22,000', '₹2,000', '₹20,000', '₹18,000', 'd', 2, 5, 'Deduct the 10% trade discount directly from the list price before recording.', 'Trade discount (10% of ₹20,000 = ₹2,000) is deducted from the list price and not recorded in the books. Purchases A/c is debited with the net amount of ₹18,000.'),
        ('acc11-03-mcq-0053', 3, 'Kartik owes ₹2,000. He pays ₹1,900 in full settlement and is allowed ₹100 discount. In the receiver''s journal, the entry is:', 'Debit Cash A/c ₹1,900, Debit Discount Allowed A/c ₹100; Credit Kartik''s A/c ₹2,000', 'Debit Cash A/c ₹1,900; Credit Kartik''s A/c ₹1,900', 'Debit Kartik''s A/c ₹2,000; Credit Cash A/c ₹1,900, Credit Discount Received A/c ₹100', 'Debit Cash A/c ₹2,000; Credit Kartik''s A/c ₹1,900, Credit Discount Allowed A/c ₹100', 'a', 2, 5, 'Cash comes in (₹1,900), discount allowed is an expense/loss (₹100), and Kartik''s liability is extinguished (₹2,000).', 'As illustrated in Example 1 on page 64: Cash A/c is debited for ₹1,900, Discount Allowed A/c is debited for ₹100, and Kartik''s A/c is credited for ₹2,000.'),
        ('acc11-03-mcq-0054', 3, 'A business paid ₹980 to creditor Chanda, who allowed a cash discount of ₹20. What is the correct journal entry?', 'Debit Chanda''s A/c ₹980, Debit Discount Allowed A/c ₹20; Credit Cash A/c ₹1,000', 'Debit Chanda''s A/c ₹1,000; Credit Cash A/c ₹980, Credit Discount Received A/c ₹20', 'Debit Cash A/c ₹980, Debit Discount Received A/c ₹20; Credit Chanda''s A/c ₹1,000', 'Debit Purchases A/c ₹1,000; Credit Cash A/c ₹980, Credit Discount Received A/c ₹20', 'b', 2, 5, 'The giver of cash gains a discount, which is credited as Discount Received.', 'Under Example 2 on page 64: Chanda''s A/c is debited ₹1,000, Cash A/c is credited ₹980 (cash going out), and Discount Received A/c is credited ₹20 (gain).'),
        ('acc11-03-mcq-0055', 3, 'When an entrepreneur starts business with Cash ₹1,00,000, Building ₹2,00,000, and a Loan of ₹50,000 from Rakesh, what is the credited amount in Capital A/c?', '₹3,50,000', '₹2,50,000', '₹3,00,000', '₹2,00,000', 'c', 3, 10, 'Capital represents the owner''s net equity (Total Assets brought by owner minus borrowed funds).', 'In Illustration 3 (April 1): Total assets are Cash ₹2,50,000 (including ₹50,000 loan) + Building ₹2,00,000 = ₹4,50,000 (or Cash ₹2,00,000 own + Building ₹2,00,000 = ₹4,00,000). Rakesh''s Loan A/c is credited ₹50,000 separately, so Capital reflects the proprietor''s contribution of ₹3,00,000 (or net assets minus loan).'),
        ('acc11-03-mcq-0056', 3, 'On 10th May, Rajwade Trading placed an order with Ranveer & Sons for goods worth ₹60,000 at 12% GST. What journal entry should be passed on 10th May?', 'Debit Purchases A/c ₹60,000, Input GST A/c ₹7,200; Credit Bank A/c ₹67,200', 'Debit Purchases A/c ₹60,000; Credit Ranveer & Sons A/c ₹60,000', 'Debit Order A/c ₹67,200; Credit Ranveer & Sons A/c ₹67,200', 'No entry is passed because placing an order is an event, not a completed financial transaction', 'd', 2, 5, 'Check the specific note below Illustration 6 regarding transaction dated 10th May.', 'The note explicitly states: ''Transaction dated 10th May is happening of an event and not a transaction hence no journal entry will be passed.'' Book-keeping only records executed financial transactions.'),
        ('acc11-03-mcq-0057', 3, 'A business purchased a horse for ₹40,000 and paid carriage charges of ₹2,000. Which account is debited, and for what total amount?', 'Live Stock A/c for ₹42,000', 'Animal Asset A/c for ₹40,000 and Transport A/c for ₹2,000', 'Purchases A/c for ₹42,000', 'Horse A/c for ₹40,000 and Carriage A/c for ₹2,000', 'a', 2, 5, 'Animals purchased for business use are treated as Live Stock, and initial expenses incurred to bring an asset to working condition are capitalized.', 'In Illustration 7 (April 20) and Exercise Q.3(10), domestic animals bought are debited to ''Live Stock A/c''. Incidental carriage charges (₹2,000) are capitalized into the cost of the asset, giving a total debit of ₹42,000.'),
        ('acc11-03-mcq-0058', 3, 'An amount of ₹1,000 previously written off as Bad Debts was recovered in cash from Varsha. What is the correct journal entry?', 'Debit Varsha''s A/c ₹1,000; Credit Bad Debts A/c ₹1,000', 'Debit Cash A/c ₹1,000; Credit Bad Debts Recovered A/c ₹1,000', 'Debit Cash A/c ₹1,000; Credit Profit and Loss Suspense A/c ₹1,000', 'Debit Cash A/c ₹1,000; Credit Varsha''s A/c ₹1,000', 'b', 2, 5, 'The debtor''s personal account was already closed when written off; recovery is a nominal gain.', 'In Illustration 7 (April 28), the entry is: Cash A/c Dr. ₹1,000 To Bad Debts Recovered A/c ₹1,000. Crediting Varsha''s A/c would wrongly show a payable to her.'),
        ('acc11-03-mcq-0059', 3, 'When shares of Mahindra Company are purchased for ₹60,000 and ₹1,000 is paid as brokerage by cheque, what is the debited account and amount?', 'Debit Demat Purchases A/c ₹61,000', 'Debit Bank Charges A/c ₹1,000 and Debit Investment A/c ₹60,000', 'Debit Investment in Shares in Mahindra Co. A/c ₹61,000', 'Debit Shares A/c ₹60,000 and Debit Brokerage A/c ₹1,000', 'c', 3, 10, 'Incidental acquisition costs such as brokerage on buying investments are capitalized into the total investment cost.', 'In Illustration 8 (April 4), brokerage paid on acquisition of shares is capitalized into the asset cost: ''Investment in Shares in Mahindra Co. A/c Dr. ₹61,000 To Bank A/c ₹61,000''.'),
        ('acc11-03-mcq-0060', 3, 'When transport charges of ₹2,000 are paid on the purchase of a new computer for office use, which account should be debited?', 'Transport Charges A/c', 'Conveyance A/c', 'Purchases A/c', 'Computer A/c', 'd', 2, 5, 'Expenditure incurred to bring a newly purchased capital asset into usable condition is treated as capital expenditure.', 'In Illustration 8 (April 15), transport charges on the purchased computer are debited directly to Computer A/c (Computer A/c Dr. ₹2,000 To Cash A/c ₹2,000), not to general transport expenses.'),
        ('acc11-03-mcq-0061', 3, 'The college fees of the proprietor''s son amounting to ₹1,000 are paid from the business cash box. What is the journal entry?', 'Debit Drawings A/c ₹1,000; Credit Cash A/c ₹1,000', 'Debit Education Expenses A/c ₹1,000; Credit Cash A/c ₹1,000', 'Debit Tuition Fee A/c ₹1,000; Credit Bank A/c ₹1,000', 'Debit Capital A/c ₹1,000; Credit Son''s A/c ₹1,000', 'a', 2, 5, 'Personal expenses of the owner''s family paid from business funds are categorized under Drawings.', 'In Illustration 8 (April 10), paying the proprietor''s son''s college fees is a personal expense: Drawings A/c Dr. ₹1,000 To Cash A/c ₹1,000.'),
        ('acc11-03-mcq-0062', 3, 'At the end of the month, wages of ₹20,000 remain due but unpaid. What is the correct journal entry to record outstanding wages?', 'Debit Wages A/c ₹20,000; Credit Cash A/c ₹20,000', 'Debit Wages A/c ₹20,000; Credit Outstanding Wages A/c ₹20,000', 'Debit Outstanding Wages A/c ₹20,000; Credit Wages A/c ₹20,000', 'Debit Prepaid Wages A/c ₹20,000; Credit Wages A/c ₹20,000', 'b', 2, 5, 'Wages is an incurred nominal expense, and unpaid wages represent a personal representative liability.', 'In Illustration 8 (April 30), the adjustment entry for unpaid wages is: Wages A/c Dr. ₹20,000 To Outstanding Wages A/c ₹20,000.'),
        ('acc11-03-mcq-0063', 3, 'A customer, Sanjay, who owed ₹1,000, becomes insolvent and only 50 paise in a rupee is recovered in cash as a final dividend. What is the journal entry?', 'Debit Cash A/c ₹500, Debit Discount Allowed A/c ₹500; Credit Sanjay''s A/c ₹1,000', 'Debit Cash A/c ₹1,000; Credit Sanjay''s A/c ₹500, Credit Bad Debts Recovered A/c ₹500', 'Debit Cash A/c ₹500, Debit Bad Debts A/c ₹500; Credit Sanjay''s A/c ₹1,000', 'Debit Bad Debts A/c ₹1,000; Credit Cash A/c ₹500, Credit Sanjay''s A/c ₹500', 'c', 3, 10, '50 paise per rupee means 50% cash received; the uncollectible 50% balance is recognized as Bad Debts.', 'In Illustration 8 / Problem 8, when a debtor pays 50 paise in a rupee on insolvency, cash received (50%) is debited to Cash A/c, irrecoverable amount (50%) is debited to Bad Debts A/c, and the debtor''s account is credited in full.'),
        ('acc11-03-mcq-0064', 3, 'Wages paid for the installation of new machinery should be debited to which account?', 'Wages A/c', 'Installation Expense A/c', 'Factory Overheads A/c', 'Machinery A/c', 'd', 2, 5, 'Refer to Exercise Q.3(7) and Q.8(4) regarding capital expenditure on installing fixed assets.', 'Wages paid for erecting or installing machinery form part of the capital cost necessary to put the asset into working condition and must be debited to Machinery A/c, not Wages A/c.'),
        ('acc11-03-mcq-0065', 3, 'When commission is paid to an agent, which account must be debited in the journal?', 'Commission A/c', 'Agent''s Personal A/c', 'Cash A/c', 'Drawings A/c', 'a', 1, 3, 'Check Exercise Q.3(8): commission is a nominal expense for services rendered.', 'As per Exercise Q.3(8), commission paid to an agent is an expense of the business and is debited to Commission A/c (Nominal Account). Debiting the agent''s account would imply a personal receivable.'),
        ('acc11-03-mcq-0066', 3, 'When a loan is taken from Dena Bank and credited to the business account, which account is credited?', 'Dena Bank Current A/c', 'Dena Bank Loan A/c', 'Capital A/c', 'Sundry Creditors A/c', 'b', 2, 5, 'Check Exercise Q.3(9): a bank loan creates a specific loan liability account.', 'In Exercise Q.3(9), borrowing funds from a bank creates a liability: Cash/Bank A/c Dr. To Dena Bank Loan A/c. The liability must be credited to Dena Bank Loan A/c.'),
        ('acc11-03-mcq-0067', 3, 'When rent of a business premises is paid to landlord Mr. Sharma, which account is debited?', 'Cash A/c', 'Landlord Mr. Sharma''s A/c', 'Rent A/c', 'Prepaid Rent A/c', 'c', 2, 5, 'Review Exercise Q.4(7): payments for nominal expenses are debited to the expense head, not the receiver.', 'In accounting, expense accounts are debited under nominal account rules. Paying rent requires debiting Rent A/c, not the landlord''s personal account (Exercise Q.4(7)).'),
        ('acc11-03-mcq-0068', 3, 'If a proprietor withdraws cash or goods from the business, how does this affect proprietor''s capital?', 'It increases capital', 'It has zero impact on capital', 'It doubles the capital reserve', 'It decreases capital', 'd', 1, 3, 'Review Exercise Q.4(9): drawings represent a return of capital to the owner.', 'Exercise Q.4(9) asks if drawings increase capital (False). Drawings made by the proprietor reduce the equity or capital invested in the business.'),
        ('acc11-03-mcq-0069', 3, 'When GST is paid on the purchase of goods, which tax account should be debited?', 'Input Tax A/c (Input CGST / Input SGST)', 'Output Tax A/c (Output CGST / Output SGST)', 'GST Expense A/c', 'Goods Account', 'a', 1, 3, 'Review Exercise Q.4(10): tax paid on inward purchases is called ''Input'' tax.', 'Exercise Q.4(10) confirms that on purchase of goods, GST paid is debited to Input Tax accounts (Input CGST A/c and Input SGST A/c) as an input tax credit.'),
        ('acc11-03-mcq-0070', 3, 'When income tax of the proprietor is paid by cheque from the business bank account, which account is debited?', 'Office Expense A/c', 'Drawings A/c', 'Bank A/c', 'Income Tax Expense A/c', 'b', 2, 5, 'Check Exercise Q.10 Row 1: personal income tax of an individual owner is a personal liability.', 'Income tax of a sole proprietor is a personal expense of the owner. When paid from business funds, it is treated as drawings: Drawings A/c Dr. To Bank A/c.'),
        ('acc11-03-mcq-0071', 3, 'A proprietor transfers ₹50,000 from their personal Fixed Deposit account into the business Bank account. What is the credit aspect of this transaction?', 'Drawings A/c', 'Fixed Deposit A/c', 'Capital A/c', 'Bank Loan A/c', 'c', 2, 5, 'Check Exercise Q.10 Row 5: introducing personal funds into the business represents additional capital.', 'Exercise Q.10 Row 5 illustrates: when personal funds (from proprietor''s personal FD) are introduced into the business bank account, Bank A/c is debited and Capital A/c is credited.'),
        ('acc11-03-mcq-0072', 3, 'When an existing piece of business furniture worth ₹30,000 is directly exchanged for a motor car of equal value, what journal entry is passed?', 'Debit Purchases A/c ₹30,000; Credit Furniture A/c ₹30,000', 'Debit Furniture A/c ₹30,000; Credit Motor Car A/c ₹30,000', 'Debit Motor Car A/c ₹30,000; Credit Sales A/c ₹30,000', 'Debit Motor Car A/c ₹30,000; Credit Furniture A/c ₹30,000', 'd', 2, 5, 'Apply the Real Account rule: debit what comes in (Motor Car) and credit what goes out (Furniture).', 'In Practical Problem 10 (April 30), exchanging furniture for a motor car means Motor Car comes in (Real A/c debited) and Furniture goes out (Real A/c credited) for ₹30,000.'),
        ('acc11-03-mcq-0073', 3, 'An old piece of office furniture having a book value of ₹20,000 is sold for ₹12,000 cash. What is the loss on sale, and how is it debited?', 'Loss of ₹8,000 debited to Loss on Sale of Furniture A/c (or Profit & Loss A/c)', 'Loss of ₹12,000 debited to Depreciation A/c', 'Loss of ₹8,000 debited to Sales Return A/c', 'No loss is recognized because the cash received is ₹12,000', 'a', 3, 10, 'Compare book value (₹20,000) with cash realized (₹12,000).', 'In Practical Problem 9 (April 28): Selling an asset of ₹20,000 for ₹12,000 yields a net loss of ₹8,000. Entry: Cash A/c Dr. ₹12,000, Loss on Sale of Furniture A/c Dr. ₹8,000 To Furniture A/c ₹20,000.'),
        ('acc11-03-mcq-0074', 3, 'A motor car is purchased from Tata & Company worth ₹2,00,000 at 18% GST. What is the total GST amount payable?', '₹28,000', '₹36,000', '₹18,000', '₹54,000', 'b', 2, 5, 'Check Exercise Q.9(1): calculate 18% of the purchase price ₹2,00,000.', 'Total GST = 18% of ₹2,00,000 = (18/100) * 2,00,000 = ₹36,000 (split as ₹18,000 CGST and ₹18,000 SGST).'),
        ('acc11-03-mcq-0075', 3, 'Transport charges of ₹10,000 are paid subject to 5% GST. What are the respective amounts of CGST and SGST?', 'CGST = ₹500 and SGST = ₹0', 'CGST = ₹500 and SGST = ₹500', 'CGST = ₹250 and SGST = ₹250', 'CGST = ₹125 and SGST = ₹125', 'c', 2, 5, 'Check Exercise Q.9(2): the total 5% GST is split equally into 2.5% CGST and 2.5% SGST.', 'Total GST at 5% on ₹10,000 = ₹500. CGST is 2.5% of ₹10,000 = ₹250, and SGST is 2.5% of ₹10,000 = ₹250.'),
        ('acc11-03-mcq-0076', 3, 'Goods worth ₹10,000 are bought from Ranjan at 5% GST and a 10% Cash Discount. According to the textbook rules, what is the cash discount amount?', '₹1,050', '₹500', '₹950', '₹1,000', 'd', 3, 10, 'Check Exercise Q.9(3) and Section 3.4: cash discount is calculated on the catalog/invoice price of goods.', 'In Exercise Q.9(3) and textbook explanatory notes (e.g. page 77), cash discount is computed on the basic value of goods: 10% of ₹10,000 = ₹1,000.'),
        ('acc11-03-mcq-0077', 3, 'A firm receives a cheque of ₹90,000 from Kiran in full settlement of his account of ₹1,00,000. What is the discount rate allowed to Kiran?', '10%', '11.11%', '5%', '9%', 'a', 2, 5, 'Check Exercise Q.9(4): compute discount amount as a percentage of the total debt of ₹1,00,000.', 'Discount allowed = ₹1,00,000 - ₹90,000 = ₹10,000. Rate of discount = (10,000 / 1,00,000) * 100 = 10%.'),
        ('acc11-03-mcq-0078', 3, 'Goods of ₹1,00,000 are sold at a 10% Trade Discount and 10% Cash Discount to Ram, who pays 50% of the net amount immediately by cheque. What is the amount of the cheque received?', '₹41,500', '₹40,500', '₹50,000', '₹45,000', 'b', 3, 10, 'Check Exercise Q.9(5): deduct trade discount first to get invoice price, take 50% eligible for cash payment, and deduct 10% cash discount from that half.', 'Step 1: List price = ₹1,00,000. Less 10% Trade Discount (₹10,000) = ₹90,000 invoice price. Step 2: 50% paid immediately = ₹45,000. Step 3: Cash discount on this payment = 10% of ₹45,000 = ₹4,500. Cheque received = ₹45,000 - ₹4,500 = ₹40,500.'),
        ('acc11-03-mcq-0079', 3, 'Sold goods to Salman for ₹20,000 at 18% GST on credit. What is the total debit amount entered against Salman''s Account?', '₹21,800', '₹25,400', '₹23,600', '₹20,000', 'c', 2, 5, 'Add 9% CGST and 9% SGST to the base price of ₹20,000.', 'In Illustration 8 (April 27): Goods value = ₹20,000; Output CGST (9%) = ₹1,800; Output SGST (9%) = ₹1,800. Total amount billed to Salman = ₹20,000 + ₹1,800 + ₹1,800 = ₹23,600.'),
        ('acc11-03-mcq-0080', 3, 'Goods costing ₹5,000 are sold at a loss of ₹1,000. What is the journal entry to record this sale?', 'Debit Cash A/c ₹4,000; Credit Sales A/c ₹4,000', 'Debit Cash A/c ₹5,000; Credit Sales A/c ₹4,000, Credit Profit A/c ₹1,000', 'Debit Sales A/c ₹5,000; Credit Cash A/c ₹4,000, Credit Loss A/c ₹1,000', 'Debit Cash A/c ₹4,000, Debit Loss on Sale A/c ₹1,000; Credit Sales A/c ₹5,000', 'd', 3, 10, 'Check Practical Problem 5 (August 30): cash received is ₹4,000, loss is ₹1,000, and original goods sold value is ₹5,000.', 'In Practical Problem 5 (August 30): Cash received = ₹5,000 - ₹1,000 = ₹4,000. Loss on Sale A/c is debited with ₹1,000, and Sales A/c is credited with ₹5,000 (or Cash A/c Dr. ₹4,000 To Sales A/c ₹4,000 where trading account absorbs the margin).'),
        ('acc11-03-mcq-0081', 3, 'When life insurance premium of the proprietor amounting to ₹17,000 is paid from business cash, which account is debited?', 'Drawings A/c', 'Proprietor''s Personal Asset A/c', 'Life Insurance Premium A/c', 'General Insurance A/c', 'a', 2, 5, 'Life insurance of the owner is a personal policy, distinct from fire or transit insurance of merchandise.', 'In Practical Problem 6 (Sept 23), Life Insurance Premium of the proprietor is a personal expense, debited to Drawings A/c: Drawings A/c Dr. ₹17,000 To Cash A/c ₹17,000.'),
        ('acc11-03-mcq-0082', 3, 'A business purchased machinery for ₹95,000 and incurred ₹5,000 on freight to transport it to the factory. At what amount is Machinery A/c debited?', '₹5,000', '₹1,00,000', '₹90,000', '₹95,000', 'b', 2, 5, 'Check Practical Problem 7 (October 1): freight paid on acquiring a fixed asset is a capital expenditure.', 'In Practical Problem 7 (October 1), freight of ₹5,000 incurred on bringing machinery to the premises is capitalized into the cost of the asset: Machinery A/c is debited for ₹1,00,000.'),
        ('acc11-03-mcq-0083', 3, '1,000 shares are sold at ₹100 each, and brokerage is paid at 1% on the total sale proceeds. What is the net amount credited to the bank account?', '₹90,000', '₹1,00,000', '₹99,000', '₹1,01,000', 'c', 3, 10, 'Check Practical Problem 8 (Nov 1): gross proceeds = 1,000 * ₹100 = ₹1,00,000; deduct 1% brokerage from the realization.', 'Gross proceeds = 1,000 shares * ₹100 = ₹1,00,000. Brokerage at 1% = ₹1,000. Net realization credited to the bank account = ₹1,00,000 - ₹1,000 = ₹99,000.'),
        ('acc11-04-mcq-0001', 4, 'In financial accounting, books of accounts are grouped into two primary divisions. Which book is officially designated as the ''Book of Final/Secondary Entry'' or ''Principal Book of Accounts''?', 'Journal', 'Purchase Day Book', 'Ledger', 'Petty Cash Book', 'c', 1, 3, 'Think of the book where transactions are posted to their final classified resting place rather than recorded first.', 'According to Chapter 4, while the Journal or Subsidiary Books are Books of Original/Primary Entry, the Ledger is the Principal Book of Accounts and is called the Book of Final/Secondary Entry.'),
        ('acc11-04-mcq-0002', 4, 'The word ''LEDGER'' is derived from which language and word, meaning ''to contain''?', 'Greek word ''Logos''', 'French word ''Leger''', 'Dutch word ''Legger''', 'Latin word ''Ledger''', 'd', 1, 3, 'Section 4.1 explicitly mentions the classical language origin and the literal meaning ''to contain''.', 'Section 4.1 states: ''The word ''LEDGER'' is derived from Latin word ''Ledger'' which means ''to contain'' As the ledger is the collection of all the accounts so ''it contains'' and hence the name signifies.'''),
        ('acc11-04-mcq-0003', 4, 'Which prominent definition describes a Ledger Account as ''a summary statement of all the transactions relating to persons, assets, expenses or incomes which have taken place during a given period of time and shows their net effect''?', 'Definition by the Oxford Dictionary', 'Definition by Eric L. Kohler (A Dictionary for Accountants)', 'Definition by S. P. Jain and K. L. Narang (Advanced Accountancy)', 'Definition by R. N. Carter', 'c', 1, 3, 'Identify the authors of ''Advanced Accountancy'' quoted in the definitions section of Chapter 4.', 'Under Section 4.1, S. P. Jain and K. L. Narang in ''Advanced Accountancy'' provide this definition highlighting the ''net effect'' of transactions over a given period.'),
        ('acc11-04-mcq-0004', 4, 'How does E. L. Kohler in ''A Dictionary for Accountants'' define a Ledger?', 'A periodic list of debit and credit balances used to test arithmetical accuracy', 'A computerized database storing only cash inflows and outflows', 'A book of primary entry where transactions are chronologically recorded with narrations', 'A ledger containing accounts in which all the transactions of a business enterprise or other accounting units are classified either in detail or in summary form', 'd', 1, 3, 'Look for the definition emphasizing classification ''either in detail or in summary form''.', 'Section 4.1 quotes E. L. Kohler''s definition: ''A Ledger containing accounts in which all the transactions of a business enterprises or other accounting units are classified either in detail or in summary form.'''),
        ('acc11-04-mcq-0005', 4, 'According to the Oxford Dictionary definition cited in the chapter, how may a ledger be maintained in modern accounting systems compared to traditional bound books?', 'As separate cards or computer records', 'As informal pocket diaries without serial page numbers', 'Exclusively as printed paper receipts bound in yearly volumes', 'Solely as bank passbooks maintained by financial institutions', 'a', 1, 3, 'Consider the electronic and card-based options replacing large traditional bound books.', 'The Oxford Dictionary states: ''Main record of the accounts of a business, traditionally, a ledger was a large book with separate pages for each account. In modern systems ledger may consist of separate cards or computer records.'''),
        ('acc11-04-mcq-0006', 4, 'Which practical limitation of the Journal does the Ledger specifically overcome?', 'The inability to quickly ascertain total expenditure on a specific head or the net amount due to/from a party', 'The inability to verify source documents like vouchers and invoices', 'The lack of equal debit and credit values for transactions', 'The inability to record transactions on the exact date they take place', 'a', 2, 5, 'The Journal records transactions day-by-day across all items, scattering information about a single person or expense.', 'The introduction to Chapter 4 explains that questions like ''what is the total amount spent on a particular expense?'' or ''what is the amount payable to a particular person?'' cannot be answered easily through the Journal. The Ledger groups all entries by account to overcome this.'),
        ('acc11-04-mcq-0007', 4, 'Why is the Ledger regarded as an effective ''control tool'' for business management?', 'It guarantees that no computational errors can be made by accountants', 'It replaces the necessity of maintaining physical source documents', 'It automatically executes payments when credit limits are reached', 'It shows individual accounts of various expenses along with their accumulated balances for comparison and monitoring', 'd', 2, 5, 'Management needs to track and limit expenditures by reviewing balances in specific expense heads.', 'Point 6 of ''Importance of Ledger'' specifies that the ledger serves as a control tool because it provides detailed accounts of various expenses along with their balances, enabling management to monitor costs and plan future actions.'),
        ('acc11-04-mcq-0008', 4, 'What does the term ''Ledger Folio'' (L.F.) signify in accounting records?', 'The voucher number supporting a cash transaction', 'The account code assigned to a customer in the sales ledger', 'The page number of the ledger on which a particular account appears', 'The serial number of the journal entry in the day book', 'c', 1, 3, 'The word ''folio'' means page number.', 'Under ''Contents of Ledger'', the textbook notes: ''For each account separate page is allotted. The page number of the ledger is called as ''Ledger Folio'' (L.F.).'''),
        ('acc11-04-mcq-0009', 4, 'How is the index of a physical Ledger prepared, and what information does it present?', 'In order of importance, listing asset accounts first and expense accounts last', 'In alphabetical order, showing the account name and its assigned page number for quick reference', 'In numerical order based on the account''s opening balance', 'In chronological order, showing transaction dates and amounts', 'b', 1, 3, 'Like the index of any reference book, it lists titles alphabetically with their page numbers.', 'Section 4.1 states: ''Every Ledger has an index. Index is prepared in the alphabetical order. The page number on which a particular account appears is shown against the name of the account shown in index. This facilitates quick reference.'''),
        ('acc11-04-mcq-0010', 4, 'What is the technical term for the name of the account written at the top center of each ledger account?', 'Ledger Caption', 'Title of Entry', 'Journal Folio', 'Head of Account', 'd', 1, 3, 'See Exercise Q.4(6); it is the official name designating the specific account on that page.', 'Exercise Q.4(6) specifies that the name of an account written on top of each account is called the ''Head of Account''.'),
        ('acc11-04-mcq-0011', 4, 'How is a traditional ledger account divided, and where are the abbreviations ''Dr.'' and ''Cr.'' positioned?', 'Left side is Credit (''Cr.'' on top left corner); Right side is Debit (''Dr.'' on top right corner)', 'Left side is Debit (''Dr.'' on top left corner); Right side is Credit (''Cr.'' on top right corner)', 'Upper section is Debit (''Dr.''); Lower section is Credit (''Cr.'')', 'Left side is Receipts (''Dr.''); Right side is Payments (''Cr.'') only for personal accounts', 'b', 1, 3, 'Debit is always on the left, credit is always on the right in standard double entry.', 'Section 4.1 explains: ''Each ledger account is divided into two sides. The left side is known as debit side and the right side is known as credit side. This is indicated by writing the abbreviations ''Dr.'' on the left side top corner and ''Cr.'' on the right side top corner.'''),
        ('acc11-04-mcq-0012', 4, 'What are the four columns present on each side (debit and credit) of a standard ''T'' form ledger account?', 'Date, Particulars, J.F., Amount (₹)', 'Date, Description, Voucher No., Net Balance', 'Date, Particulars, L.F., Amount (₹)', 'Date, Particulars, Cash (₹), Bank (₹)', 'a', 1, 3, 'In the ledger, the folio column references the book where the entry originated (Journal).', 'Both sides of a ''T'' form ledger have four identical columns: Date, Particulars, J.F. (Journal Folio), and Amount (₹).'),
        ('acc11-04-mcq-0013', 4, 'In manual ledger accounting, how do entries in the Particulars column conventionally begin on the Debit side and Credit side?', 'Debit side entries begin with ''Dr.'', and Credit side entries begin with ''Cr.''', 'Debit side entries begin with ''By'', and Credit side entries begin with ''To''', 'Both debit and credit side entries begin with ''For''', 'Debit side entries begin with ''To'', and Credit side entries begin with ''By''', 'd', 1, 3, '''To'' indicates the destination of value (debit), while ''By'' indicates the source or giving aspect (credit).', 'Section 4.1 explicitly states under the Particulars column: ''The posting on the debit side begins with ''To'' and on the credit side with ''By''.'''),
        ('acc11-04-mcq-0014', 4, 'What is the specific purpose of the ''Journal Folio'' (J.F.) column in a ledger account?', 'To record the corresponding page number of the ledger where the counterpart account is opened', 'To record the page number of the Journal from where the transaction has been transferred', 'To record the serial page number of the customer''s sales invoice', 'To indicate the bank voucher reference code', 'b', 1, 3, 'Folio means page number; in the ledger, it points back to the Journal page.', 'Section 4.1 states: ''In Journal Folio (J.F.) column, page number of journal from where we have transferred the entry into Ledger is to be written.'''),
        ('acc11-04-mcq-0015', 4, 'Which list of columns accurately describes the ''Statement form of an Account'' used in computerized accounting systems?', 'Date, Particulars, J.F., Gross Amount, Discount, Net Amount', 'Date, Description, Cheque No., Total (₹), Net Balance', 'Date, Particulars, J.F., Debit (₹), Credit (₹), Balance (₹), Initial, Remark', 'Date, Head of Account, L.F., Inward Invoice No., Debit (₹), Credit (₹)', 'c', 2, 5, 'The statement form maintains a continuous running balance and includes columns for initials and remarks.', 'Section 4.2 presents the specimen of the ''Statement form of an Account'' containing: Date, Particulars, J.F., Debit (₹), Credit (₹), Balance (₹), Initial, Remark.'),
        ('acc11-04-mcq-0016', 4, 'In Tally ERP software as illustrated in Chapter 4, what is the correct navigation path from the main gateway to create a single ledger?', 'Gateway of Tally -> Inventory Info -> Ledgers -> Create', 'Gateway of Tally -> Accounts Info. -> Ledgers -> Create (under Single Ledger)', 'Gateway of Tally -> Reports -> Accounts Info -> Single Ledger', 'Gateway of Tally -> Accounting Vouchers -> Ledgers -> Create', 'b', 2, 5, 'Ledgers are basic accounting masters located under Accounts Info.', 'The menu chart on page 91 shows: Gateway of Tally -> Masters -> Accounts Info. -> Ledgers -> Single Ledger -> Create.'),
        ('acc11-04-mcq-0017', 4, 'According to Activity 2 in Chapter 4, what is a Bank Pass Book from an accounting perspective?', 'It is a primary subsidiary book recording only cash discounts', 'It is the bank''s account maintained in the books of the customer', 'It is a trial balance prepared by the Reserve Bank of India', 'It is the customer''s account in the books of the bank, printed as a computerized ledger in statement form', 'd', 2, 5, 'When you deposit money in a bank, the bank credits your account in their books.', 'Activity 2 notes: ''Bank provides the details of all our transactions related to Bank in the Pass book. This book is nothing but our account (Customer''s A/c) in the books of bank. It is computerised ledger printed in statement form.'''),
        ('acc11-04-mcq-0018', 4, 'What is the precise definition of ''Posting'' in bookkeeping?', 'The process of entering initial transactions into the Journal from vouchers', 'The process of transferring entries from the Journal or Subsidiary Books into the appropriate accounts in the Ledger', 'The process of extracting net differences and comparing debit and credit totals', 'The physical dispatch of invoice copies to trade customers by post', 'b', 1, 3, 'It describes the migration of entries from primary books to the principal book.', 'Section 4.3 states: ''The process of transferring entries from the Journal or Subsidiary Books into the appropriate account in the Ledger is called ''Posting''.'''),
        ('acc11-04-mcq-0019', 4, 'When opening balances from a previous accounting period are recorded in an existing ledger account, how are they entered?', 'As ''To Capital A/c'' on the debit side and ''By Drawings A/c'' on the credit side', 'As ''To Profit & Loss A/c'' regardless of the account nature', 'As ''To Balance b/d'' on the debit side or ''By Balance b/d'' on the credit side', 'As ''To Balance c/d'' on the debit side or ''By Balance c/d'' on the credit side', 'c', 1, 3, 'Opening balances are brought down (''b/d'') from the prior period.', 'Step 3 of ''The Recording process'' in Section 4.3 states: ''If the opening balance of ledger account is given, it should be posted first, either as ''To balance b/d'' or ''By balance b/d''.'''),
        ('acc11-04-mcq-0020', 4, 'When posting a journal entry into an account''s ledger, which account name is written in its Particulars column?', 'The name of the counterpart account credited (if posting on the debit side) or debited (if posting on the credit side)', 'Only the voucher description without any account titles', 'The proprietor''s personal name for all debit and credit entries', 'The name of the account itself at every posting line', 'a', 2, 5, 'To preserve the double-entry reference, an account names the opposite account involved in the transaction.', 'Section 4.3 step 5 explains: ''In the particular column on the debit side of the ledger account the name of the account credited in the entry is written and on the credit side... the name of the account to be debited in the entry is written.'''),
        ('acc11-04-mcq-0021', 4, 'If a combined journal entry reads: Rent A/c Dr. ₹3,000, Salaries A/c Dr. ₹5,000 To Cash A/c ₹8,000, what entry appears in the Rent Account?', 'Debit side: ''To Cash A/c ₹8,000''', 'Debit side: ''To Cash A/c ₹3,000''', 'Debit side: ''To Salaries A/c ₹3,000''', 'Credit side: ''By Cash A/c ₹3,000''', 'b', 2, 5, 'Rent Account is debited only with its own transaction value (₹3,000), referencing Cash.', 'Illustration 2 specifies: ''Rent A/c and Salaries A/c are debited only with the amount against them in the Journal Entry.'' Thus, Rent A/c is debited with ₹3,000 writing ''To Cash A/c''.'),
        ('acc11-04-mcq-0022', 4, 'In the combined entry where Rent of ₹3,000 and Salaries of ₹5,000 are paid together in Cash (Total ₹8,000), how is the Cash Account posted?', 'Debit side: ''To Rent A/c ₹3,000'' and ''To Salaries A/c ₹5,000''', 'Credit side: ''By Total Expenses A/c ₹8,000''', 'Credit side: ''By Rent A/c ₹3,000'' and ''By Salaries A/c ₹5,000'' on separate lines', 'Credit side: ''By Sundries A/c ₹8,000'' as a single entry', 'c', 2, 5, 'Both expense accounts must be itemized on the credit side of Cash Account so the specific causes of cash outflow are recorded.', 'Illustration 2 states: ''Cash A/c is credited with ₹8,000 in Journal entry. But since it is on account of two different expenses, both have to be written in the credit side, the total of which is equal to ₹8,000'' (By Rent A/c ₹3,000 and By Salaries A/c ₹5,000).'),
        ('acc11-04-mcq-0023', 4, 'According to Chapter 4, which Goods and Services Taxes are levied on intra-state purchases and inter-state purchases respectively?', 'Intra-state: IGST; Inter-state: CGST and SGST', 'Intra-state: SGST only; Inter-state: CGST only', 'Intra-state: IGST and CGST; Inter-state: SGST', 'Intra-state: CGST and SGST; Inter-state: IGST', 'd', 1, 3, 'Intra-state sales within a state split tax between State (SGST) and Centre (CGST); cross-border sales use Integrated GST (IGST).', 'Under ''Do You Know?'' in Section 4.3, the chapter explains that currently there are three types of GST: SGST, CGST, and IGST. Intra-state trade attracts CGST and SGST, while inter-state trade attracts IGST.'),
        ('acc11-04-mcq-0024', 4, 'A trader purchases goods worth ₹40,000 intra-state paying 2.5% SGST and 2.5% CGST by cheque. What are the postings in Input SGST Account and Input CGST Account?', 'Credited with ₹1,000 each writing ''By Purchases A/c''', 'Debited with ₹2,000 in a combined GST Account writing ''To Purchases A/c''', 'Debited with ₹1,000 each writing ''To Bank A/c''', 'Credited with ₹1,000 each writing ''By Bank A/c''', 'c', 2, 5, 'Input GST paid on purchases is an asset/tax credit; hence debited with the counterpart being Bank A/c.', 'Illustration 3 shows that Purchases A/c is debited with ₹40,000, Input SGST A/c is debited with ₹1,000 (''To Bank A/c''), and Input CGST A/c is debited with ₹1,000 (''To Bank A/c''), while Bank A/c is credited with ₹42,000.'),
        ('acc11-04-mcq-0025', 4, 'Why does an enterprise that maintains a columnar Cash Book with Cash and Bank columns not maintain separate Cash and Bank accounts in the Ledger?', 'Because cash transactions do not follow double-entry rules', 'Because the Cash Book serves the function of both a book of original entry (Journal) and a book of final entry (Ledger)', 'Because accounting standards prohibit having cash accounts in secondary books', 'Because bank transactions are audited separately and omitted from the trial balance', 'b', 2, 5, 'The Cash Book has debit and credit sides with columns that function directly as ledger accounts.', 'Section 4.3 (''Posting from Cash Book'') states: ''Separate column of Cash and Bank will serve as Cash A/c and Bank A/c. So no need to open Cash A/c and Bank A/c, as the Cash Book serves the purpose of Journal as well as Ledger.'''),
        ('acc11-04-mcq-0026', 4, 'How are entries appearing on the debit (receipts) side and credit (payments) side of the Cash Book posted to ledger accounts?', 'Receipts on the debit side are posted to the credit of counterpart accounts; payments on the credit side are posted to the debit of counterpart accounts', 'Only credit transactions are posted; cash transactions are never posted to ledger accounts', 'All entries are posted exclusively to the credit side of the Capital Account', 'Receipts on the debit side are posted to the debit of counterpart accounts; payments to credit', 'a', 2, 5, 'Remember double entry: if Cash Book records a debit to Cash/Bank, the giving account must be credited in its ledger.', 'Section 4.3 explains: ''Entries posted on the debit side of the Cash Book are posted on credit side of Personal A/c, Real A/c or Nominal A/c. In the same way entries which are posted on credit side of Cash Book are shown on debit side of those ledger accounts.'''),
        ('acc11-04-mcq-0027', 4, 'When the chief cashier hands over initial imprest cash to the petty cashier, which journal entry is recorded and posted?', 'Petty Cash A/c Dr. To Cash/Bank A/c', 'Sundry Expenses A/c Dr. To Petty Cash A/c', 'Petty Cash A/c Dr. To Capital A/c', 'Cash/Bank A/c Dr. To Petty Cash A/c', 'a', 2, 5, 'Petty Cash receives funds from the main cash or bank account.', 'Section 4.3 (''Posting from Petty Cash Book'') states: ''Initially main cashier hands over some cash to petty cashier for that entry is Petty Cash A/c Dr. To Cash/Bank A/c.'''),
        ('acc11-04-mcq-0028', 4, 'When the petty cashier incurs expenses for travelling, postage, and sundry items, how are these posted to the Ledger?', 'Debited to each individual expense account and credited to Petty Cash Account', 'Debited to Petty Cash Account and credited to Main Cash Account', 'Credited to each individual expense account and debited to Profit & Loss Account', 'Debited to Chief Cashier''s Account and credited to Bank Account', 'a', 2, 5, 'Expense accounts increase (debit), and the petty cash fund decreases (credit).', 'Section 4.3 outlines: ''To record these various expenses journal entry will be Individual Expenses A/c Dr. To Petty Cash A/c. The ledger posting will be done in Individual Expenses account as well as in Petty Cash Account.'''),
        ('acc11-04-mcq-0029', 4, 'How is the periodic total of the Purchase Book posted in the Ledger, and how are individual supplier accounts treated?', 'Total is credited to Purchases Account as ''By Sundries as per Purchase Book'', and suppliers are debited', 'Total is debited to Purchases Account as ''To Sundries as per Purchase Book'', and individual suppliers are credited as ''By Purchases A/c''', 'Total is debited to Cash Account, and suppliers are debited with net amounts', 'Total is debited to Sales Account, and suppliers are credited', 'b', 2, 5, 'Credit purchases increase total purchases (debit) and increase creditors (credit).', 'Illustration 4 states: ''The total of Purchase Book for the month will be shown on debit side of Purchase Account and in suppliers account effect will be shown on credit side of each Supplier''s Account.'''),
        ('acc11-04-mcq-0030', 4, 'How is the monthly total of the Sales Book posted to the Sales Account, and how are individual customers posted?', 'Total is credited to Sales Account as ''By Sundries as per Sales Book'', and individual customers are debited as ''To Sales A/c''', 'Total is debited to Sales Account as ''To Sundries as per Sales Book'', and customers are credited', 'Total is credited to Debtors Account as a single block, and customers are not posted individually', 'Total is credited to Cash Account, and customers are debited', 'a', 2, 5, 'Sales is an income account (credit), while customers who owe money are debtors (debit).', 'Illustration 5 states: ''The total of Sales Book for the month will be shown on credit side of Sales Account and in customers account effect will be shown on debit side of each Customer''s Account.'''),
        ('acc11-04-mcq-0031', 4, 'How is the total of the Purchase Return Book (Return Outward Book) posted to the Purchase Return Account?', 'On the credit side of Sales Account as ''By Purchase Return''', 'On the debit side of Purchase Return Account as ''To Sundries as per Purchase Return Book''', 'On the credit side of Purchase Return Account as ''By Sundries as per Purchase Return Book''', 'On the debit side of Purchases Account as ''To Returns Outward''', 'c', 2, 5, 'Purchases have a debit balance; purchase returns reverse purchases, giving them a credit balance.', 'Illustration 6 states: ''The total of Purchase Return Book will be shown on credit side of Purchase Return Account and in suppliers account effect will be shown on debit side separately for each supplier.'''),
        ('acc11-04-mcq-0032', 4, 'How is the periodic total of the Sales Return Book (Return Inward Book) posted to the Sales Return Account?', 'On the debit side of Sales Return Account as ''To Sundries as per Sales Return book''', 'On the debit side of Cash Account as ''To Returns Inward''', 'On the credit side of Purchases Return Account', 'On the credit side of Sales Return Account as ''By Sundries as per Sales Return book''', 'a', 2, 5, 'Sales have a credit balance; sales returns reverse sales, giving them a debit balance.', 'Illustration 7 states: ''The total of Sales Return Book for the month will be posted on debit side of Sales Return Account and effect will be shown on credit side of each Customer''s Account.'''),
        ('acc11-04-mcq-0033', 4, 'Which transactions are recorded in the Journal Proper and how are their entries posted to the Ledger?', 'Credit sales of merchandise goods; posted only to the Sales Account', 'Petty expense disbursements; posted without entering individual accounts', 'All routine cash transactions; posted directly in summary form to the Balance Sheet', 'Transactions not covered by special subsidiary books (e.g. opening entries, credit purchase of assets); posted individually to respective ledger accounts', 'd', 2, 5, 'Journal Proper records residual transactions that do not fit into cash, purchase, or sales daybooks.', 'Under ''Posting of entries from Journal Proper'', the chapter notes that entries shown in Journal Proper are posted individually to their respective accounts in the Ledger.'),
        ('acc11-04-mcq-0034', 4, 'What does ''Balancing of Ledger accounts'' mean in bookkeeping?', 'Adding the total of the debit side and writing the same figure on the credit side without checking', 'Transferring all nominal accounts to the journal at the close of every month', 'Totalling both sides of an account, finding the difference between greater and smaller totals, and recording it on the smaller side', 'Ensuring that the total cash balance equals total capital at the end of every week', 'c', 1, 3, 'Balancing establishes parity between the two sides by inserting the net difference.', 'Section 4.4 defines: ''Balancing of Ledger accounts means totalling both the sides of Ledger Account, finding the difference between greater total and smaller total and recording the difference on the smaller side.'''),
        ('acc11-04-mcq-0035', 4, 'In ledger balancing, what does the abbreviation ''c/d'' indicate and represent?', 'Carried down, indicating the closing balance at the end of the period', 'Cash discount, indicating a reduction allowed for early payment', 'Carried down, indicating the opening balance at the beginning of the period', 'Credit difference, indicating an overdrawn bank balance', 'a', 1, 3, 'See Exercise Q.3(2); ''c/d'' stands for carried down and marks the closing balance.', 'Exercise Q.3(2) confirms: ''''c/d'' indicates Closing balance'' (carried down), while ''b/d'' indicates opening balance (brought down).'),
        ('acc11-04-mcq-0036', 4, 'What does the abbreviation ''b/d'' stand for when opening an account at the start of a new period?', 'Brought down, representing the opening balance brought forward from the prior period', 'Brought down, representing the closing balancing figure', 'Bank deposit, representing funds paid into the bank account', 'Bills discounted, representing promissory notes negotiated', 'a', 1, 3, 'It is the opposite partner of carried down (''c/d'') and marks the opening entry.', 'Exercise Q.5(6) and Section 4.4 establish that ''b/d'' means ''brought down'', representing the opening balance carried over from the previous period.'),
        ('acc11-04-mcq-0037', 4, 'When is an account said to have a ''Debit balance''?', 'When the account has zero balance on both sides', 'When the total of its credit side is greater than the total of its debit side', 'When the closing balance is posted on the debit side as ''To Balance c/d''', 'When the total of its debit side is greater than the total of its credit side', 'd', 1, 3, 'The nature of the balance takes the name of the side with the larger total.', 'The ''Do you know?'' box in Section 4.4 states: ''If the total of debit side of the account is higher than the total of credit side the account is said to have Debit balance and vice-versa.'''),
        ('acc11-04-mcq-0038', 4, 'When the credit side total of an account exceeds its debit side total, where is the closing balancing figure written, and what balance does it represent?', 'Written on the credit side as ''By Balance c/d''; represents a Debit balance', 'Written on the credit side as ''By Balance b/d''; represents a Liability balance', 'Written on the debit side as ''To Balance c/d''; represents a Credit balance', 'Written on the debit side as ''To Balance b/d''; represents an Expense balance', 'c', 2, 5, 'To make both totals equal, the difference must be placed on the smaller (debit) side, but the heavier side was credit.', 'Step 4 of Section 4.4 states: ''if the credit side total is higher than the debit side total then the difference amount is shown on debit side as ''To Balance c/d''... It indicates a credit balance.'''),
        ('acc11-04-mcq-0039', 4, 'In balancing a Personal Account, what does a debit balance signify versus a credit balance?', 'A debit balance signifies that the person is a Debtor; a credit balance signifies that the person is a Creditor', 'A debit balance signifies a Creditor; a credit balance signifies a Debtor', 'A debit balance signifies an income; a credit balance signifies an asset', 'A debit balance signifies that the account is settled; a credit balance signifies an active dispute', 'a', 1, 3, 'Debtors owe money to the business (assets, debit); creditors are owed money by the business (liabilities, credit).', 'Under ''Balancing of Personal Account'', the chapter states: ''A personal account having debit balance is a Debtor and credit balance is a Creditor. Balance of these accounts is carried forward.'''),
        ('acc11-04-mcq-0040', 4, 'When does a ledger account show a ''Nil balance''?', 'When no transactions have been entered during the entire financial year', 'When the total of the debit side is exactly equal to the total of the credit side', 'When the closing balance is carried down to the credit side as an even integer', 'When the account has been transferred to the Profit and Loss Account at year-end', 'b', 1, 3, 'Review Exercise Q.1(3); it occurs when both sides have identical sums with zero difference.', 'Exercise Q.1(3) defines that an account shows a nil balance when the total of the debit side equals the total of the credit side, leaving no difference.'),
        ('acc11-04-mcq-0041', 4, 'Which of the following statements is strictly TRUE regarding Real Accounts (such as Cash, Furniture, and Machinery)?', 'Real Accounts show a credit balance whenever assets are depreciated', 'Real Accounts always show a debit balance (or nil balance), never a credit balance', 'Real Accounts always show a credit balance at the end of each quarter', 'Real Accounts are closed at year-end by transfer to Profit and Loss Account', 'b', 1, 3, 'Physical assets and properties cannot have negative physical quantities.', 'Section 4.4 (''Balancing of Real Account'') explicitly states: ''Accounts which are related to assets and properties are real accounts... Real Account always shows a debit balance.'''),
        ('acc11-04-mcq-0042', 4, 'Why can a business''s Cash Account NEVER show a credit balance?', 'Because bank overdraft absorbs all negative cash amounts automatically', 'Because cash payments are recorded only in the Journal Proper', 'Because cash disbursements cannot exceed total cash available from opening balance and receipts', 'Because cash is classified as a nominal account under double entry', 'c', 2, 5, 'You cannot physically spend more currency notes than you have received.', 'Exercise Q.1(7) and Section 4.4 note that Cash Account can never show a credit balance because a business cannot pay more cash than it possesses; hence, total payments (credit) cannot exceed total receipts (debit).'),
        ('acc11-04-mcq-0043', 4, 'How are Nominal Accounts (expenses, losses, incomes, gains) treated at the close of an accounting year?', 'Their balances are balanced with ''c/d'' and carried forward as opening balances (''b/d'') to next year', 'They are closed by transferring their balances to Trading Account or Profit and Loss Account', 'Their balances are transferred to the Personal Account of the proprietor', 'They are carried forward as assets or liabilities on the Balance Sheet', 'b', 2, 5, 'Nominal accounts pertain only to the current accounting year to calculate periodic profit or loss.', 'Section 4.4 states: ''At the end of the accounting year the balances of all Nominal Accounts are transferred to Trading or Profit and Loss Account.'' Exercise Q.4(4) confirms they are not carried forward to the next year.'),
        ('acc11-04-mcq-0044', 4, 'Why is the Proprietor''s Capital Account treated as a liability of the business and shown with a credit balance?', 'Because the proprietor borrowed all capital funds from commercial banks', 'Because capital is a temporary expense that must be repaid within one operating cycle', 'Due to the Business Entity Concept, which treats the business as a separate distinct legal entity from its owner', 'Because the Indian Partnership Act mandates treating capital as an external debt', 'c', 2, 5, 'The business owes the invested capital back to the owner upon dissolution.', 'Exercise Q.1(6) explains that under the Business Entity Concept, the owner and the business enterprise are separate entities. The amount contributed by the proprietor is owed back by the enterprise to the proprietor, making it an internal liability with a credit balance.'),
        ('acc11-04-mcq-0045', 4, 'What is the normal balance of the Proprietor''s Drawings Account, and where is it shown in a Trial Balance?', 'Either debit or credit balance depending on annual sales revenue', 'Nil balance; omitted entirely from the Trial Balance', 'Credit balance; shown in the Credit Amount column', 'Debit balance; shown in the Debit Amount column', 'd', 1, 3, 'Drawings represent withdrawals of business resources by the owner, reducing equity.', 'Exercise Q.7(6) and Illustration 14 confirm that Drawings Account always shows a debit balance (Debit column in the Trial Balance), reflecting owner withdrawals.'),
        ('acc11-04-mcq-0046', 4, 'When rent is paid for the residential quarter of the proprietor from the business bank account, which account must be debited?', 'Building Maintenance Account', 'Drawings Account', 'Rent Account', 'Landlord''s Personal Account', 'b', 2, 5, 'Domestic or personal living expenses paid using firm funds cannot be recorded as business operating expenses.', 'Exercise Q.5(7) states: ''Rent paid for the residential quarter will be debited to Drawings account'' because it is a private expense of the proprietor rather than a business expense.'),
        ('acc11-04-mcq-0047', 4, 'When goods worth ₹2,000 are distributed as free samples to promote business sales, which account is debited in the Ledger?', 'Drawings Account', 'Advertisement Account (or Goods Distributed as Free Samples A/c)', 'Sales Account', 'Debtors Account', 'b', 2, 5, 'Free samples are distributed for sales promotion and publicity.', 'In Q.4 (July 12) and Q.7 (Feb 12), goods distributed as free samples are an advertisement/publicity expense; hence Advertisement Account (or Free Samples A/c) is debited, and Purchases / Goods Distributed as Free Samples A/c is credited.'),
        ('acc11-04-mcq-0048', 4, 'A customer whose account was previously written off as bad debts pays ₹950 in cash. Which account must be credited in the Ledger?', 'Customer''s Personal Account', 'Bad Debts Account', 'Bad Debts Recovered Account', 'Sales Account', 'c', 3, 10, 'The customer''s personal account was already credited and closed when written off; this unexpected recovery is a separate gain.', 'Practical Problem Q.4 (July 18) demonstrates that recovery of a previously written-off debt is credited to ''Bad Debts Recovered A/c'' (a nominal income/gain account), debited to Cash A/c. Crediting the customer''s personal account would erroneously create an artificial credit balance.'),
        ('acc11-04-mcq-0049', 4, 'A firm purchases 100 shares of Perfect Technologies at ₹55 per share and pays ₹250 brokerage by net banking. What total amount is debited to Investment in Shares Account?', '₹5,250', '₹5,500', '₹250', '₹5,750', 'd', 3, 10, 'Acquisition costs like brokerage paid at the time of purchasing investments are capitalized as part of the asset cost.', 'Practical Problem Q.6 (Aug 5) shows: Cost of shares = 100 * ₹55 = ₹5,500. Brokerage = ₹250. Total debited to Investment in Shares Account = ₹5,500 + ₹250 = ₹5,750.'),
        ('acc11-04-mcq-0050', 4, 'Sunil starts business with stock of goods worth ₹20,000 and Cash of ₹1,70,000, out of which ₹50,000 was borrowed from his friend Kedar. What is the credited balance of Sunil''s Capital Account?', '₹1,70,000', '₹1,90,000', '₹1,20,000', '₹1,40,000', 'd', 3, 10, 'Subtract the borrowed loan from total assets brought in: Capital = Total Assets - External Liabilities.', 'Practical Problem Q.7 (Feb 1): Total assets introduced = Stock ₹20,000 + Cash ₹1,70,000 = ₹1,90,000. Out of this, ₹50,000 is a loan from Kedar (liability). Therefore, Sunil''s own Capital = ₹1,90,000 - ₹50,000 = ₹1,40,000.'),
        ('acc11-04-mcq-0051', 4, 'Aparna was sold goods at a list price of ₹15,000 subject to a 10% Trade Discount. If she subsequently returns goods of ₹1,500 (Gross list price), what net amount is recorded in the Sales Return Account?', '₹1,500', '₹1,650', '₹1,350', '₹1,200', 'c', 3, 10, 'Trade discount applies equally to returns of merchandise originally sold under trade discount.', 'Practical Problem Q.5 (Jan 7): The goods were returned at ₹1,500 gross. Since a 10% Trade Discount was deducted at the time of sale, the return must also be recorded net of trade discount: ₹1,500 - 10% (₹150) = ₹1,350.'),
        ('acc11-04-mcq-0052', 4, 'What is a ''Trial Balance'' as defined in Section 4.5 of Chapter 4?', 'An abstract or list of all ledger accounts as on a specific date showing debit and credit balances', 'A summary register containing only real and personal accounts', 'A balance sheet prepared by an auditor before tax submission', 'A book of primary entry designed to verify supplier outward invoices', 'a', 1, 3, 'It is an abstract list of balances of all accounts prepared on a given date.', 'Section 4.5 defines: ''A Trial balance is an abstract or list of all the ledger accounts as on a specific date showing debit and credit balances of all Ledger Accounts.'''),
        ('acc11-04-mcq-0053', 4, 'What is the primary reason or utility for preparing a Trial Balance periodically?', 'To ascertain the arithmetical accuracy of the Books of Accounts', 'To replace the preparation of the final Balance Sheet', 'To prove that no fraudulent transactions occurred during the year', 'To calculate the net market value of fixed assets', 'a', 1, 3, 'It checks whether debits and credits equal each other mathematically.', 'Section 4.5 states: ''It is prepared to ascertain the arithmetical accuracy of Books of Accounts'' and lists utilities including proving arithmetical accuracy and aiding final accounts preparation.'),
        ('acc11-04-mcq-0054', 4, 'How does a ''Gross Trial Balance'' differ from a ''Net Trial Balance''?', 'Gross Trial Balance is prepared weekly; Net Trial Balance is prepared every five years', 'Gross Trial Balance lists only cash accounts; Net Trial Balance lists only credit accounts', 'Gross Trial Balance lists the debit and credit totals of each account; Net Trial Balance lists only the net balances and is the method used in practice', 'Gross Trial Balance includes depreciation; Net Trial Balance excludes depreciation', 'c', 2, 5, 'Gross shows two column totals for each account without finding the difference; Net shows the resulting single balance.', 'Section 4.5 distinguishes: In a Gross Trial Balance, the total of the debit side and credit side of each account are shown (not commonly used). In a Net Trial Balance, only the balances of each ledger account are shown against its name; this method is used in practice.'),
        ('acc11-04-mcq-0055', 4, 'What are the two structural methods/formats of preparing a Trial Balance shown in Chapter 4?', 'Single Entry form and Double Entry form', 'Analytical form and Petty Cash form', 'Asset form and Liability form', 'Vertical (Journal form) and Horizontal (Ledger form)', 'd', 1, 3, 'One format resembles a Journal with Debit and Credit columns; the other resembles a Ledger with Debit and Credit sides.', 'Section 4.5 details: ''There are two methods of preparing Trial Balance: (1) Vertical or Journal form of Trial Balance, and (2) Horizontal or Ledger form of Trial Balance.'''),
        ('acc11-04-mcq-0056', 4, 'Why is the statement ''Agreement of Trial Balance always proves accounting accuracy'' FALSE?', 'Because debit and credit totals in a Trial Balance are intentionally kept unequal', 'Because certain errors (like errors of principle, errors of omission, or compensating errors) do not disrupt the mathematical equality of debits and credits', 'Because Trial Balance only includes nominal accounts and ignores assets', 'Because Trial Balance is never based on the double-entry system', 'b', 2, 5, 'Think of transactions omitted entirely: both debit and credit are missing, so the totals still agree despite the error.', 'Exercise Q.4(7) confirms that agreement of a Trial Balance proves only arithmetical accuracy, not complete accounting accuracy, because errors of principle, complete omission, and compensating errors remain undetected by the Trial Balance.'),
        ('acc11-04-mcq-0057', 4, 'According to the ''Do You Know? How transaction travels?'' diagram in Chapter 4, what is the exact chronological sequence?', 'Source Documents -> Ledger -> Journal -> Trial Balance', 'Ledger -> Source Documents -> Journal -> Trial Balance', 'Journal -> Source Documents -> Trial Balance -> Ledger', 'Source Documents -> Journal -> Ledger -> Trial Balance', 'd', 1, 3, 'Everything originates with source documents like invoices, followed by primary entry, secondary posting, and trial balancing.', 'The flowchart on page 114 traces the transaction path: Source Documents -> Journal -> Ledger -> Trial Balance.'),
        ('acc11-04-mcq-0058', 4, 'Varma''s account shows a credit balance of ₹20,000 for furniture supplied. The firm pays ₹8,000 by net banking and later settles the remaining balance by paying ₹11,500 cash in full settlement. What amount is credited to Discount Received Account?', '₹1,500', '₹500', '₹1,000', '₹800', 'b', 3, 10, 'Calculate the balance before the second payment: ₹20,000 - ₹8,000 = ₹12,000. Full settlement was achieved with ₹11,500.', 'Illustration 13: Total debt to Varma = ₹20,000. Paid by net banking = ₹8,000. Balance remaining = ₹12,000. Settled by paying ₹11,500. The difference (₹12,000 - ₹11,500 = ₹500) represents cash discount received and is credited to Discount Received A/c.'),
        ('acc11-04-mcq-0059', 4, 'Goods were sold for ₹24,000 at a profit of 20% on cost. What was the purchase price (cost) of these goods?', '₹18,000', '₹21,600', '₹19,200', '₹20,000', 'd', 3, 10, 'Let Cost = C. Selling Price = C + 0.20*C = 1.20*C = ₹24,000. Solve for C.', 'Exercise Q.5(8): If cost is ₹100, profit is ₹20, making selling price ₹120. Cost = ₹24,000 * (100 / 120) = ₹20,000. Distractor ₹19,200 incorrectly deducts 20% from the selling price (₹24,000 - ₹4,800).'),
        ('acc11-04-mcq-0060', 4, 'Based on the classification table in Exercise Q.7, which of the following accounts carries a CREDIT balance?', 'Outstanding Salary', 'Prepaid Rent', 'Goodwill', 'Bills Receivable', 'a', 2, 5, 'Outstanding Salary is an expense that has been incurred but not yet paid, making it a liability.', 'Exercise Q.7 lists account balance natures: Goodwill, Bills Receivable, and Prepaid Rent are assets having Debit balances; Outstanding Salary is a liability having a Credit balance.'),
        ('acc11-05-mcq-0001', 5, 'What is the primary reason for sub-dividing the Journal into Special Journals as a business expands?', 'The volume of transactions becomes too large to be recorded in a single Journal', 'To eliminate the need for posting transactions into the Ledger', 'To avoid recording credit transactions in the books of accounts', 'To replace the double entry system with a single entry system', 'a', 1, 3, 'Consider the operational difficulties faced when transaction volume grows significantly in an expanding enterprise.', 'According to Section 5.1, as a business expands, the number of transactions becomes so large that a single Journal is insufficient, necessitating its sub-division into Special Journals called Subsidiary Books. Ledgers and double entry are not eliminated.'),
        ('acc11-05-mcq-0002', 5, 'Why are Subsidiary Books also referred to as ''Books of Original Entry'' or ''Books of Prime Entry''?', 'They are prepared directly from the Final Accounts at the end of the year', 'Transactions are first recorded in these books before being posted to the Ledger', 'They can only be audited and maintained by certified chartered accountants', 'They contain only confidential transactions of the business owners', 'b', 1, 3, 'Think about the sequence in which transactions are recorded in the accounting cycle.', 'Subsidiary Books are known as books of original or prime entries because transactions are first recorded in them before being posted into the Ledger.'),
        ('acc11-05-mcq-0003', 5, 'Which of the following is an operational advantage of maintaining Subsidiary Books that arises from assigning specialized staff to handle specific books?', 'Elimination of cash discount calculations', 'Automatic reconciliation of the bank statement with the passbook', 'Increase in work efficiency through specialization', 'Exemption from paying Goods and Services Tax (GST)', 'c', 1, 3, 'Reflect on how division of labor among clerks improves performance on repetitive accounting tasks.', 'When staff is appointed to handle the same type of work (e.g., maintaining the Purchase Book or Sales Book), it leads to specialization and an increase in efficiency.'),
        ('acc11-05-mcq-0004', 5, 'How does maintaining Subsidiary Books facilitate the internal check system within an organization?', 'It prevents the business from ever incurring any bad debts or trade losses', 'It removes the need for physical verification of cash and stock balances', 'It guarantees that no supplier ever issues a debit note or credit note', 'Verification of the correctness of accounting records can be made more effectively', 'd', 2, 5, 'Focus on how dividing accounting work allows cross-checking and verification.', 'Under the needs for maintaining subsidiary books, internal check enables the verification of correctness to be carried out more effectively because work is divided among different clerks.'),
        ('acc11-05-mcq-0005', 5, 'Which subsidiary book is used to record transactions relating to bills received from debtors when bill transactions are segregated?', 'Bills Receivable Book', 'Bills Payable Book', 'Return Inward Book', 'Journal Proper', 'a', 1, 3, 'Identify the specific special journal under Bill Transactions designed for incoming bills.', 'Under the classification chart of Subsidiary Books, bill transactions are divided into the Bills Receivable Book (for bills drawn/received) and the Bills Payable Book (for bills accepted).'),
        ('acc11-05-mcq-0006', 5, 'Why is the Cash Book described as serving a dual purpose in accounting?', 'It records both financial transactions and non-monetary barters simultaneously', 'It acts as both a Book of Original Entry (Journal) and a classified ledger account (Ledger)', 'It acts as both the Trial Balance and the Balance Sheet of the firm', 'It serves both the Income Tax department and the Sales Tax department', 'b', 2, 5, 'Consider why transactions entered here do not require a separate cash account in the ledger.', 'The Cash Book is a Journal because transactions are recorded in it directly as prime entries, and it is also a Ledger because it is maintained in ledger account form and provides the cash balance at any time.'),
        ('acc11-05-mcq-0007', 5, 'On which side and in which column is a cash receipt recorded in a Simple Cash Book?', 'Credit side (Payment side) in the Amount column', 'Debit side in the Receipt Number column only without amount', 'Debit side (Receipt side) in the Amount column', 'Credit side in the Voucher Number column', 'c', 1, 3, 'Recall the two sides of a Cash Book: left hand side is receipts and right hand side is payments.', 'In a Simple Cash Book, the left-hand side is the Receipt Side (Debit side) where all receipts of cash are recorded in the Amount column.'),
        ('acc11-05-mcq-0008', 5, 'Why can the Cash column of a Cash Book never show a credit balance?', 'Because banks prohibit businesses from holding physical currency in office safes', 'Because cash transactions are exempt from the double entry system rules', 'Because the Ledger Folio column balances the cash account automatically', 'Because a person or business cannot pay out more cash than what is available in hand', 'd', 2, 5, 'Think about the physical reality of spending currency coins and notes.', 'A business cannot spend more physical cash than it possesses. Total payments can never exceed total receipts plus opening cash in hand; hence, the cash column always has a debit balance or zero balance, never credit.'),
        ('acc11-05-mcq-0009', 5, 'M/s Sourabh Traders sold goods for Rs. 20,000 at an 8% Trade Discount for cash. What amount is entered on the Receipt side of the Simple Cash Book?', 'Rs. 18,400', 'Rs. 20,000', 'Rs. 1,600', 'Rs. 21,600', 'a', 2, 5, 'Remember that trade discount is deducted from the catalogue price before recording the transaction.', 'Trade discount of 8% on Rs. 20,000 is Rs. 1,600 (20,000 * 0.08). The net cash received is Rs. 20,000 - Rs. 1,600 = Rs. 18,400, which is entered on the receipt side as ''To Sales A/c''.'),
        ('acc11-05-mcq-0010', 5, 'A trader paid a Life Insurance Premium of Rs. 8,000 in cash. How is this transaction recorded in the Simple Cash Book?', 'Debit side as ''To Insurance Premium A/c''', 'Credit side as ''By Drawings A/c''', 'Credit side as ''By Life Insurance Corporation A/c''', 'Debit side as ''To Capital A/c''', 'b', 2, 5, 'Proprietor''s life insurance is a personal expense rather than a business expense.', 'Life insurance premium paid for the proprietor is treated as personal drawings. In the Cash Book, it is entered on the payment (credit) side as ''By Drawings A/c''.'),
        ('acc11-05-mcq-0011', 5, 'Which bank account is primarily preferred by businessmen because it imposes no restrictions on deposits/withdrawals and provides an overdraft facility?', 'Fixed Deposit Account', 'Recurring Deposit Account', 'Current Account', 'Savings Bank Account', 'c', 1, 3, 'Identify the business-oriented account that offers overdraft facilities and high transaction freedom.', 'A Current Account is suitable for businessmen as there is no restriction on the number of deposits and withdrawals, and an overdraft facility is made available, though generally no interest is paid.'),
        ('acc11-05-mcq-0012', 5, 'What does a credit balance in the Bank column of a two-column Cash Book indicate?', 'Cash in hand held at the registered branch', 'Unclaimed interest allowed by the bank', 'Surplus deposits invested in government bonds', 'Bank Overdraft', 'd', 1, 3, 'Recall what it means when withdrawals exceed deposits in a bank current account.', 'Since a Bank Account is a personal account, a credit balance (where payments exceed receipts) represents a Bank Overdraft, which is a short-term borrowing from the bank.'),
        ('acc11-05-mcq-0013', 5, 'How is an opening Bank Overdraft balance recorded in a two-column Cash Book?', 'On the credit side in the Bank column as ''By Balance b/d''', 'On the debit side in the Cash column as ''To Balance b/d''', 'On the debit side in the Bank column as ''To Balance b/d''', 'In the Journal Proper as an adjusting entry', 'a', 1, 3, 'An overdraft is a liability/credit balance, so it opens on the credit side.', 'An opening bank overdraft is a credit balance and is therefore recorded on the payment (credit) side of the Cash Book in the Bank column as ''By Balance b/d''.'),
        ('acc11-05-mcq-0014', 5, 'When a crossed cheque is received from a customer in settlement of his account, in which column of the two-column Cash Book is it entered?', 'Debit side in the Cash column', 'Debit side in the Bank column', 'Credit side in the Cash column', 'Credit side in the Bank column', 'b', 1, 3, 'Crossed cheques must be processed directly through a bank account, not cashed over the counter.', 'When a crossed cheque is received, it cannot be cashed directly at the counter; it must be cleared through the bank. Hence, it is recorded on the receipt (debit) side in the Bank column.'),
        ('acc11-05-mcq-0015', 5, 'When a bearer cheque is received from a debtor on 15th January and not deposited on the same day, how is it initially treated in the Cash Book?', 'Entered on the debit side in the Bank column', 'Recorded only in the Journal Proper as a bill of exchange', 'Treated as cash and entered on the debit side in the Cash column', 'Ignored until it is physically deposited into the bank', 'c', 2, 5, 'A bearer cheque can be cashed over the counter immediately, so accounting treats it like physical notes.', 'According to the chapter, a bearer cheque received is treated as cash. On the date of receipt, it is recorded on the receipt side in the Cash column as ''To Debtor''s A/c''.'),
        ('acc11-05-mcq-0016', 5, 'What is the accounting entry in the two-column Cash Book when a previously received bearer cheque is deposited into the bank on a subsequent date?', 'Debit Cash column and Credit Bank column', 'Debit Bank column and Credit Debtor''s Account', 'Record only on the credit side of the Bank column', 'Debit Bank column and Credit Cash column (Contra Entry)', 'd', 2, 5, 'This transaction increases bank balance while reducing cash in hand.', 'Since bearer cheques are treated as cash, depositing them on a later date means cash is going out and bank balance increases. It is a Contra Entry: debit Bank column (''To Cash A/c'') and credit Cash column (''By Bank A/c'') marked with ''C''.'),
        ('acc11-05-mcq-0017', 5, 'Within what validity period must a cheque be presented to the bank for collection from its date of drawing before it becomes worthless?', 'Three months', 'Thirty days', 'Six months', 'One calendar year', 'a', 1, 3, 'State the standard legal validity period for presenting cheques mentioned in section 5.3.3.', 'As stated in Section 5.3.3, a cheque received has to be presented to the bank for collection within three months from the date of drawing, otherwise it becomes worthless (stale).'),
        ('acc11-05-mcq-0018', 5, 'When a customer''s deposited cheque is returned dishonoured by the bank, what entry is passed in the two-column Cash Book?', 'Entered on the Receipt side in the Cash column as ''To Customer A/c''', 'Entered on the Payment side in the Bank column as ''By Customer A/c''', 'Entered on the Receipt side in the Bank column as ''To Dishonour A/c''', 'Entered on the Payment side in the Cash column as ''By Bank A/c''', 'b', 2, 5, 'To cancel the receipt effect previously recorded in the bank column, reverse the entry in the bank column.', 'When a customer''s cheque is dishonoured, the bank balance is reduced and the customer is made a debtor again. It is recorded on the payment side in the Bank column as ''By Person''s/Customer''s A/c''.'),
        ('acc11-05-mcq-0019', 5, 'If a cheque issued to a creditor (Dhanraj) is subsequently dishonoured, what is the correct journal entry in the books of the drawer?', 'Dhanraj A/c Dr. To Bank A/c', 'Bank Charges A/c Dr. To Dhanraj A/c', 'Bank A/c Dr. To Dhanraj A/c', 'Cash A/c Dr. To Bank A/c', 'c', 2, 5, 'When issued, Bank was credited. To cancel the dishonoured issued cheque, Bank must be debited.', 'When the cheque was originally issued, Dhanraj was debited and Bank was credited. Upon dishonour, this is reversed: Bank A/c is debited and Dhanraj A/c is credited (recorded on receipt side in Bank column).'),
        ('acc11-05-mcq-0020', 5, 'A trader withdraws Rs. 12,000 from the bank for office use. What type of entry is this in a two-column Cash Book?', 'Opening entry', 'Adjusting entry', 'Rectification entry', 'Contra entry', 'd', 2, 5, 'The transaction affects both Cash Account and Bank Account simultaneously with opposite effects.', 'Withdrawing cash from the bank for office use increases cash balance and decreases bank balance. Because both accounts appear in the two-column cash book, it is a Contra Entry denoted by ''C'' in the L.F. column.'),
        ('acc11-05-mcq-0021', 5, 'How is cash withdrawn from the bank by the proprietor for personal use recorded in a two-column Cash Book?', 'Payment side in the Bank column as ''By Drawings A/c''', 'Contra entry: Debit Cash column and Credit Bank column', 'Payment side in the Cash column as ''By Drawings A/c''', 'Receipt side in the Bank column as ''To Drawings A/c''', 'a', 2, 5, 'Only the bank balance is affected; cash in office remains unchanged.', 'Withdrawal for personal use is Drawings. It reduces the bank balance and does not involve office cash. Hence it is NOT a contra entry; it is entered on the payment side in the Bank column as ''By Drawings A/c''.'),
        ('acc11-05-mcq-0022', 5, 'When a bank charges interest on an overdraft facility, how is it treated by the trader in the Cash Book?', 'Income; entered on the Receipt side in the Bank column', 'Expenditure; entered on the Payment side in the Bank column', 'Contra entry; entered in both Cash and Bank columns', 'Non-cash item; entered only in the Journal Proper', 'b', 1, 3, 'Interest charged by the bank reduces your bank account balance and is an expense.', 'Interest on overdraft is charged by the bank for lending funds. It is an expenditure for the trader, decreasing the bank balance, and is entered on the payment side in the Bank column as ''By Interest on overdraft A/c''.'),
        ('acc11-05-mcq-0023', 5, 'Under a standing instruction, the bank pays an insurance premium of Rs. 1,000 on behalf of the trader. What is the entry in the Cash Book?', 'Receipt side in the Bank column as ''To Insurance Premium A/c''', 'Payment side in the Cash column as ''By Insurance Premium A/c''', 'Payment side in the Bank column as ''By Insurance Premium A/c''', 'Recorded in the Petty Cash Book under Miscellaneous Expenses', 'c', 1, 3, 'The bank makes the payment directly from the trader''s account.', 'When the bank makes payments under standing instructions, it debits the trader''s bank balance. The trader records this on the payment side in the Bank column as ''By Respective Expenses A/c'' (here, Insurance Premium).'),
        ('acc11-05-mcq-0024', 5, 'When a trader transfers Rs. 25,000 from his personal savings bank account into the business current account, how is it recorded?', 'Credit side of Cash Book in the Bank column as ''By Drawings A/c''', 'Both sides as a Contra Entry marked with ''C''', 'Credit side of Cash Book in the Cash column as ''By Capital A/c''', 'Debit side of Cash Book in the Bank column as ''To Capital A/c''', 'd', 2, 5, 'Personal funds introduced into the business bank account represent additional capital.', 'Transferring money from personal savings to the business current account is an introduction of additional capital. It increases the business bank balance, so it is debited on the receipt side in the Bank column as ''To Capital A/c''.'),
        ('acc11-05-mcq-0025', 5, 'Which letter is written in the Ledger Folio (L.F.) column of the Cash Book to signify a Contra Entry?', 'C', 'R', 'J', 'T', 'a', 1, 3, 'It is the first capital letter of the word ''Contra''.', 'In columnar cash books, contra entries that affect both cash and bank simultaneously are denoted by the capital letter ''C'' in the L.F. column.'),
        ('acc11-05-mcq-0026', 5, 'On 30th March, a trader''s total cash receipts equal Rs. 21,745 and cash payments up to that date equal Rs. 7,825. If the trader retains a closing cash balance of Rs. 3,920 and deposits the entire remaining excess cash into the bank, how much cash is deposited?', 'Rs. 13,920', 'Rs. 10,000', 'Rs. 6,095', 'Rs. 17,825', 'b', 3, 10, 'Calculate available cash balance first (Receipts - Payments), then subtract the required retained balance.', 'Available cash = Receipts (Rs. 21,745) - Payments (Rs. 7,825) = Rs. 13,920. Depositing cash in excess of Rs. 3,920 means: Rs. 13,920 - Rs. 3,920 = Rs. 10,000 deposited into the bank.'),
        ('acc11-05-mcq-0027', 5, 'Cash purchases of Rs. 60,000 are made at a 10% Trade Discount and 5% Cash Discount. Half the net payable amount is paid in cash and the remainder by cheque. What is the amount paid by cheque?', 'Rs. 27,000', 'Rs. 30,000', 'Rs. 25,650', 'Rs. 28,500', 'c', 3, 10, 'Deduct trade discount first, calculate cash discount on the balance, then divide the net amount payable equally.', 'Catalogue price = Rs. 60,000. Less 10% T.D. (Rs. 6,000) = Rs. 54,000. Cash discount at 5% on Rs. 54,000 = Rs. 2,700. Net amount payable = Rs. 54,000 - Rs. 2,700 = Rs. 51,300. Half paid by cheque = Rs. 51,300 / 2 = Rs. 25,650.'),
        ('acc11-05-mcq-0028', 5, 'The word ''Petty'' in Petty Cash Book is derived from which French word and what does it mean?', '''Petite'' meaning ''fast''', '''Porte'' meaning ''carry''', '''Prêt'' meaning ''ready''', '''Petit'' meaning ''small''', 'd', 1, 3, 'Check the etymology given in Section 5.4 of the chapter.', 'The term petty is derived from the French word ''Petit'', which means ''small''. The Petty Cash Book records small day-to-day expenses.'),
        ('acc11-05-mcq-0029', 5, 'Why do commercial business firms rarely use the Simple Petty Cash Book in practice?', 'It requires each transaction to be individually posted into respective expense ledger accounts, consuming excessive time and labour', 'It is legally banned by the Institute of Chartered Accountants of India', 'It does not permit recording payments made for postage or stationery', 'It can only be written by the Chief Cashier and not a junior clerk', 'a', 2, 5, 'Think about the ledger posting workload created when expenses are not pre-analyzed into columnar totals.', 'In a Simple Petty Cash Book, every individual petty payment must be posted to its respective ledger account, requiring substantial additional time and labour. Hence, firms prefer the Analytical Petty Cash Book.'),
        ('acc11-05-mcq-0030', 5, 'How does the Imprest System of Petty Cash Book operate?', 'The petty cashier is given a variable bonus based on the percentage of petty funds unspent', 'The petty cashier is reimbursed at the end of the period with an amount exactly equal to actual expenses spent, restoring the original advance', 'All petty expenses must be paid exclusively via crossed account payee cheques', 'The chief cashier surrenders full financial liability to the petty cashier permanently', 'b', 2, 5, 'Focus on how the petty cashier''s opening balance is replenished back to the fixed float amount.', 'Under the Imprest System, an estimate is made for petty expenses for a period. At the end of the period, after verifying vouchers, the chief cashier reimburses an amount equal to what was actually spent, restoring the float to its initial level.'),
        ('acc11-05-mcq-0031', 5, 'In an Analytical Petty Cash Book, which special column is provided to record payments made towards Personal or Real accounts rather than nominal expense heads?', 'Miscellaneous Expenses column', 'General Stores column', 'Ledger column', 'Drawings column', 'c', 1, 3, 'Identify the column on the payment side meant for items that must be posted to personal or real ledger folios.', 'Section 5.4 notes that the Ledger column is prepared in the Analytical Petty Cash Book for making payments towards Personal or Real accounts (e.g., advance given to peon, purchase of office chair/machinery).'),
        ('acc11-05-mcq-0032', 5, 'At the start of the month, a petty cashier had an opening cash balance of Rs. 400 and received an advance from the chief cashier. Total petty expenses paid during the month were Rs. 1,800, leaving a closing balance of Rs. 250. What was the amount received from the chief cashier?', 'Rs. 1,400', 'Rs. 1,800', 'Rs. 2,050', 'Rs. 1,650', 'd', 3, 10, 'Use the equation: Opening Balance + Cash Received - Expenses Paid = Closing Balance.', 'Opening balance (Rs. 400) + Cash received (X) - Expenses (Rs. 1,800) = Closing balance (Rs. 250). Therefore, X = 250 + 1,800 - 400 = Rs. 1,650.'),
        ('acc11-05-mcq-0033', 5, 'A petty cashier maintains an imprest float of Rs. 2,000. On 1st August, the opening petty balance is Rs. 150. What amount of cheque does the chief cashier issue on 1st August to restore the imprest?', 'Rs. 1,850', 'Rs. 2,000', 'Rs. 150', 'Rs. 2,150', 'a', 2, 5, 'Subtract the unspent opening balance from the total fixed imprest float.', 'To make up the fixed imprest float of Rs. 2,000 when Rs. 150 remains in hand, the chief cashier issues a cheque for Rs. 2,000 - Rs. 150 = Rs. 1,850.'),
        ('acc11-05-mcq-0034', 5, 'What is the monthly summary journal entry passed in the principal journal to post the expenses recorded in the Analytical Petty Cash Book?', 'Petty Cash A/c Dr. To Respective Expense Accounts', 'Respective Expense Accounts Dr. To Petty Cash A/c', 'Respective Expense Accounts Dr. To Bank A/c', 'Cash A/c Dr. To Petty Cash A/c', 'b', 2, 5, 'Expenses are nominal accounts and must be debited, while the petty cash fund asset is reduced.', 'At the end of the period, the totals of the various analytical expense columns are debited to their respective Expense Accounts (e.g., Courier & Postage, Printing & Stationery) and Petty Cash A/c is credited with the total expenses.'),
        ('acc11-05-mcq-0035', 5, 'Which of the following transactions is strictly recorded in the Purchase Book (Bought Day Book)?', 'Cash purchase of merchandise goods', 'Purchase of office furniture on credit', 'Credit purchase of goods meant for resale or manufacturing', 'Purchase of delivery machinery on credit', 'c', 1, 3, 'The Purchase Book only records goods dealt in on a credit basis.', 'Only credit purchases of goods (merchandise intended for resale or manufacturing) are recorded in the Purchase Book. Cash purchases go to the Cash Book, and credit purchases of capital assets go to Journal Proper.'),
        ('acc11-05-mcq-0036', 5, 'A cloth merchant buys office computers on credit from IBM Computers for Rs. 55,000. In which book should this transaction be recorded?', 'Purchase Book', 'Cash Book', 'Bills Payable Book', 'Journal Proper', 'd', 2, 5, 'Computers are fixed assets for a cloth merchant, not trading goods.', 'For a cloth merchant, computers are office equipment (assets), not goods. Since it is a credit purchase of an asset, it cannot be entered in the Purchase Book or Cash Book; it must be recorded in Journal Proper.'),
        ('acc11-05-mcq-0037', 5, 'What is the primary source document used for recording entries in the Purchase Book?', 'Inward Invoice', 'Outward Invoice', 'Debit Note', 'Cash Receipt Voucher', 'a', 1, 3, 'When you buy goods on credit, you receive a bill/invoice from the supplier.', 'When goods are bought on credit, the supplier sends an invoice (incoming bill) to the buyer. This bill is referred to as the Inward Invoice and is the source document for the Purchase Book.'),
        ('acc11-05-mcq-0038', 5, 'At what monetary value are credit purchases always recorded in the Purchase Book?', 'Gross catalogue price before deducting trade discount', 'Net value after deducting trade discount', 'Market selling price of the merchandise', 'Cost price plus anticipated net profit margin', 'b', 1, 3, 'Trade discount is never recorded in the accounts; transactions are entered net of trade discount.', 'As stated explicitly in Section 5.5: ''Goods purchased on credit are always recorded at net value'' (catalogue price less trade discount).'),
        ('acc11-05-mcq-0039', 5, 'Konika Electronics purchased 20 mini mobile phones @ Rs. 2,000 each and 12 home theatres @ Rs. 4,500 each from Seema Electronics at a 20% Trade Discount. What is the net amount entered in the Purchase Book?', 'Rs. 94,000', 'Rs. 18,800', 'Rs. 75,200', 'Rs. 84,600', 'c', 3, 10, 'Calculate the total gross price of mobiles and home theatres, then subtract 20% trade discount.', 'Gross amount = (20 * 2,000) + (12 * 4,500) = 40,000 + 54,000 = Rs. 94,000. Trade discount of 20% = Rs. 18,800. Net amount entered in the Purchase Book = Rs. 94,000 - Rs. 18,800 = Rs. 75,200.'),
        ('acc11-05-mcq-0040', 5, 'How is the periodic total of the Purchase Book posted to the Purchases Account in the Ledger?', 'Credit side as ''By Sundries as per Purchase Book''', 'Debit side of each individual creditor''s ledger account', 'Credit side of the Trading Account at the end of each week', 'Debit side as ''To Sundries as per Purchase Book''', 'd', 2, 5, 'Purchases represents an expenditure/asset addition and normally has a debit balance.', 'At the end of the month, the total of the Purchase Book is posted to the Debit side of the Purchases Account in the Ledger with the description ''To Sundries as per Purchase Book''.'),
        ('acc11-05-mcq-0041', 5, 'What is the alternative name for the Purchase Return Book?', 'Returns Outward Book', 'Returns Inward Book', 'Bought Day Book', 'Bills Payable Journal', 'a', 1, 3, 'Goods purchased earlier are now going out of the business back to the supplier.', 'When goods purchased are returned to suppliers, they move outward from the firm. Hence, the Purchase Return Book is also called the ''Returns Outward Book'' or ''Purchase Return Journal''.'),
        ('acc11-05-mcq-0042', 5, 'What source document is prepared by the buyer and sent to the supplier when returning defective goods?', 'Credit Note', 'Debit Note', 'Outward Invoice', 'Cheque Counterfoil', 'b', 1, 3, 'The document informs the supplier that their personal account has been debited in the buyer''s books.', 'A Debit Note is prepared by the buyer returning the goods and sent to the supplier. It indicates that the supplier''s account has been debited in the buyer''s books for the returned goods.'),
        ('acc11-05-mcq-0043', 5, 'A buyer returned defective goods having a catalogue (gross) value of Rs. 3,000 to a supplier from whom they were originally purchased at a 10% Trade Discount. At what value should the return be recorded in the Purchase Return Book?', 'Rs. 3,000', 'Rs. 3,300', 'Rs. 2,700', 'Rs. 300', 'c', 2, 5, 'Trade discount allowed on the initial purchase must also be deducted from the return value.', 'Since the goods were purchased at a 10% trade discount, the actual purchase cost recorded was net of discount. Therefore, returns must also be recorded net of trade discount: Rs. 3,000 - (10% of 3,000) = Rs. 2,700.'),
        ('acc11-05-mcq-0044', 5, 'How is the periodic total of the Purchase Return Book posted to the Purchase Return Account in the Ledger?', 'Debit side as ''To Sundries as per Purchase Return Book''', 'Debit side of the Head Cashier''s account', 'Credit side of the Debtors Control account', 'Credit side as ''By Sundries as per Purchase Return Book''', 'd', 2, 5, 'Purchase returns reduce the expense of purchases, so the account carries a credit balance.', 'Purchase returns represent a reduction in purchases (or goods going out). The periodic total of the Purchase Return Book is posted to the Credit side of the Purchase Return Account as ''By Sundries as per Purchase Return Book''.'),
        ('acc11-05-mcq-0045', 5, 'Which of the following transactions is entered in the Sales Book (Sales Journal)?', 'Credit sale of merchandise goods dealt in by the firm', 'Cash sales of merchandise goods', 'Credit sale of old factory machinery', 'Sale of old newspapers for cash', 'a', 1, 3, 'Only credit sales of regular merchandise goods are recorded in this book.', 'Only credit sales of goods (merchandise) are recorded in the Sales Book. Cash sales go to the Cash Book, and credit sales of assets go to Journal Proper.'),
        ('acc11-05-mcq-0046', 5, 'What is the primary source document prepared by the seller to record an entry in the Sales Book?', 'Inward Invoice', 'Outward Invoice', 'Debit Note', 'Petty Cash Voucher', 'b', 1, 3, 'The seller issues an outgoing bill to the customer.', 'When goods are sold on credit, the seller issues a sales bill called the Outward Invoice to the customer. This serves as the source document for the Sales Book.'),
        ('acc11-05-mcq-0047', 5, 'Bhairavanath Traders sold old office furniture to Avadhut on credit for Rs. 8,000. In which book should this transaction be recorded?', 'Sales Book', 'Cash Book', 'Journal Proper', 'Purchase Return Book', 'c', 2, 5, 'Furniture is a capital asset, not the trading merchandise of the trader.', 'Sale of an asset (furniture) on credit cannot be entered in the Sales Book (which only records credit sales of goods) or Cash Book. It must be recorded in Journal Proper.'),
        ('acc11-05-mcq-0048', 5, 'A trader sold 30 jackets @ Rs. 500 per jacket subject to an 8% Trade Discount on credit. What amount is entered in the Sales Book?', 'Rs. 15,000', 'Rs. 1,200', 'Rs. 16,200', 'Rs. 13,800', 'd', 2, 5, 'Multiply quantity by price to find gross sales, then subtract the 8% trade discount.', 'Gross sales = 30 * Rs. 500 = Rs. 15,000. Trade discount = 8% of 15,000 = Rs. 1,200. Net credit sales entered in the Sales Book = Rs. 15,000 - Rs. 1,200 = Rs. 13,800.'),
        ('acc11-05-mcq-0049', 5, 'How is the periodic total of the Sales Book posted to the Sales Account in the Ledger?', 'Credit side as ''By Sundries as per Sales Book''', 'Debit side as ''To Sundries as per Sales Book''', 'Debit side of the Customer''s Personal Account', 'Credit side of the Purchases Account', 'a', 2, 5, 'Sales is a revenue account and has a normal credit balance.', 'The monthly or periodic total of the Sales Book is posted to the Credit side of the Sales Account in the Ledger with the narration ''By Sundries as per Sales Book''.'),
        ('acc11-05-mcq-0050', 5, 'What is the alternative accounting name for the Sales Return Book?', 'Returns Outward Book', 'Returns Inward Book', 'Bought Day Book', 'Bills Receivable Journal', 'b', 1, 3, 'Goods sold to customers are now coming back inside the business.', 'When customers return goods previously sold to them, the goods come back inward. Hence, the Sales Return Book is also known as the Returns Inward Book or Sales Return Journal.'),
        ('acc11-05-mcq-0051', 5, 'Which source document is issued by the seller to a customer upon receiving defective goods returned by that customer?', 'Debit Note', 'Inward Invoice', 'Credit Note', 'Bank Advice', 'c', 1, 3, 'The document informs the buyer that their account has been credited in the seller''s books.', 'On receipt of goods returned by a customer, the seller prepares and sends a Credit Note, indicating that the customer''s personal account has been credited.'),
        ('acc11-05-mcq-0052', 5, 'Goods of Rs. 1,900 (Gross) previously sold at a 10% Trade Discount were returned by a customer (Ragini) as damaged. What amount is recorded in the Sales Return Book?', 'Rs. 1,900', 'Rs. 2,090', 'Rs. 190', 'Rs. 1,710', 'd', 2, 5, 'Trade discount allowed on sale must be deducted when computing the return value.', 'Gross return = Rs. 1,900. Less 10% Trade Discount = Rs. 190. The net amount recorded in the Sales Return Book is Rs. 1,900 - Rs. 190 = Rs. 1,710.'),
        ('acc11-05-mcq-0053', 5, 'How is the periodic total of the Sales Return Book posted to the Sales Return Account in the Ledger?', 'Debit side as ''To Sundries as per Sales Return Book''', 'Credit side as ''By Sundries as per Sales Return Book''', 'Credit side of the Customer''s personal account', 'Debit side of the Capital Account', 'a', 2, 5, 'Sales return represents a reduction of sales revenue, carrying a debit balance.', 'The monthly total of the Sales Return Book is posted to the Debit side of the Sales Return Account in the Ledger as ''To Sundries as per Sales Return Book''.'),
        ('acc11-05-mcq-0054', 5, 'When goods are purchased from an out-of-state supplier (inter-state purchase), which tax component is recorded in the analytical Purchase Book?', 'CGST and SGST in equal halves', 'Integrated GST (IGST)', 'Customs Duty only', 'Value Added Tax (VAT)', 'b', 2, 5, 'Under the GST regime, inter-state supplies attract a single integrated tax.', 'For inter-state transactions (e.g., Maharashtra trader buying from Delhi or Haryana as shown in Problem 5), Integrated GST (IGST) is charged instead of intra-state CGST/SGST.'),
        ('acc11-05-mcq-0055', 5, 'A trader in Maharashtra purchases 30 TV sets @ Rs. 10,000 each and 4 Home Theatres @ Rs. 12,500 each from Rama Delhi at a 10% Trade Discount, with 18% IGST applicable. What is the total invoice amount recorded in the analytical Purchase Book?', 'Rs. 3,50,000', 'Rs. 3,15,000', 'Rs. 3,71,700', 'Rs. 4,13,000', 'c', 3, 10, 'Gross cost is Rs. 3,50,000. Deduct 10% T.D., then add 18% IGST to the taxable purchase value.', 'Gross = (30*10,000) + (4*12,500) = Rs. 3,50,000. Less 10% T.D. (Rs. 35,000) = Rs. 3,15,000 (Purchase column). IGST @ 18% on Rs. 3,15,000 = Rs. 56,700. Total column = Rs. 3,15,000 + Rs. 56,700 = Rs. 3,71,700.'),
        ('acc11-05-mcq-0056', 5, 'A Maharashtra trader returns 3 TV sets (gross purchase price Rs. 10,000 each, originally bought at 10% Trade Discount with 18% IGST) to a Delhi supplier. What is the total debit recorded in the Purchase Return Book?', 'Rs. 30,000', 'Rs. 27,000', 'Rs. 35,400', 'Rs. 31,860', 'd', 3, 10, 'Compute taxable value of return after 10% T.D., then add proportional 18% IGST.', 'Gross value = 3 * Rs. 10,000 = Rs. 30,000. Less 10% T.D. = Rs. 3,000; taxable return = Rs. 27,000. Add IGST @ 18% (Rs. 4,860); Total amount = Rs. 31,860 (as detailed in Problem 5).'),
        ('acc11-05-mcq-0057', 5, 'What is the primary function of the Journal Proper?', 'To record transactions that do not find a place in any special subsidiary books', 'To record all cash transactions not recorded by the petty cashier', 'To record only transactions involving banking institutions', 'To prepare the final Trial Balance and Balance Sheet directly', 'a', 1, 3, 'Think of it as the residual book for transactions that cannot fit into special journals.', 'A book maintained to record transactions that do not find a place in any special subsidiary books (Cash Book, Purchase Book, Sales Book, Return Books, etc.) is known as Journal Proper.'),
        ('acc11-05-mcq-0058', 5, 'Which type of entry is passed in the Journal Proper at the beginning of a financial year to open asset and liability accounts?', 'Adjusting Entry', 'Opening Entry', 'Closing Entry', 'Rectification Entry', 'b', 1, 3, 'These entries bring forward balances of assets, liabilities, and capital at the start of the year.', 'At the beginning of a new accounting year, the record of opening balances of assets, liabilities, and capital is made in the Journal Proper by passing an Opening Entry.'),
        ('acc11-05-mcq-0059', 5, 'Given Cash Rs. 8,500, Bank Rs. 35,000, Plant & Machinery Rs. 1,10,000, Stock Rs. 37,000, Debtors Rs. 43,000, and Creditors Rs. 32,000; what is the Capital credited in the Opening Entry?', 'Rs. 2,33,500', 'Rs. 2,65,500', 'Rs. 2,01,500', 'Rs. 1,93,000', 'c', 2, 5, 'Capital is the excess of total assets over total liabilities (Capital = Assets - Liabilities).', 'Total Assets = 8,500 + 35,000 + 1,10,000 + 37,000 + 43,000 = Rs. 2,33,500. Liabilities (Creditors) = Rs. 32,000. Capital = Assets - Liabilities = Rs. 2,33,500 - Rs. 32,000 = Rs. 2,01,500.'),
        ('acc11-05-mcq-0060', 5, 'Why are adjusting entries passed in the Journal Proper at the end of the accounting period?', 'To record cash receipts that were forgotten by the cashier', 'To transfer goods from the godown to retail showrooms', 'To cancel bounced cheques issued to suppliers', 'To update ledger accounts on an accrual basis so Final Accounts reflect accurate results', 'd', 2, 5, 'Think about items like depreciation, outstanding expenses, and accrued incomes not yet in the trial balance.', 'Adjusting entries bring unrecorded items (like outstanding expenses, prepaid expenses, depreciation, further bad debts) into the books to update accounts on an accrual basis and ensure Final Accounts reflect true profit or loss.'),
        ('acc11-05-mcq-0061', 5, 'What is the adjusting entry passed in the Journal Proper to provide for depreciation on Building amounting to Rs. 31,500?', 'Depreciation A/c Dr. 31,500 To Building A/c 31,500', 'Building A/c Dr. 31,500 To Cash A/c 31,500', 'Building A/c Dr. 31,500 To Depreciation A/c 31,500', 'Profit & Loss A/c Dr. 31,500 To Cash A/c 31,500', 'a', 2, 5, 'Depreciation is an expense (debited) and reduces the asset value of building (credited).', 'Depreciation is a loss/expense, so Depreciation A/c is debited. Building is an asset whose value decreases, so Building A/c is credited: Depreciation A/c Dr. To Building A/c.'),
        ('acc11-05-mcq-0062', 5, 'Which account is debited in the Journal Proper when further bad debts of Rs. 3,750 are written off?', 'Debtors Account', 'Bad Debts Account', 'Sales Return Account', 'Cash Account', 'b', 1, 3, 'Bad debts represent an irrecoverable loss and nominal expense.', 'Writing off bad debts involves debiting Bad Debts A/c (nominal account loss) and crediting the Debtors A/c (reducing the asset).'),
        ('acc11-05-mcq-0063', 5, 'What entry is passed in the Journal Proper to close the Purchases Account (Rs. 2,95,000) at the end of the year?', 'Purchases A/c Dr. 2,95,000 To Trading A/c 2,95,000', 'Profit & Loss A/c Dr. 2,95,000 To Purchases A/c 2,95,000', 'Trading A/c Dr. 2,95,000 To Purchases A/c 2,95,000', 'Purchases A/c Dr. 2,95,000 To Capital A/c 2,95,000', 'c', 2, 5, 'Purchases has a debit balance; to close it, credit Purchases A/c and debit the Trading A/c.', 'Closing entries transfer revenue trading balances to the Trading Account. The Purchases A/c has a debit balance; to close it, Trading A/c is debited and Purchases A/c is credited.'),
        ('acc11-05-mcq-0064', 5, 'What entry is passed in the Journal Proper to transfer net profit of Rs. 87,500 to the proprietor''s Capital Account?', 'Capital A/c Dr. 87,500 To Profit & Loss A/c 87,500', 'Trading A/c Dr. 87,500 To Profit & Loss A/c 87,500', 'Drawings A/c Dr. 87,500 To Capital A/c 87,500', 'Profit & Loss A/c Dr. 87,500 To Capital A/c 87,500', 'd', 2, 5, 'Net profit increases the owner''s capital account.', 'Net profit is transferred from the Profit & Loss Account to the Capital Account, increasing capital. The entry is: Profit & Loss A/c Dr. To Capital A/c.'),
        ('acc11-05-mcq-0065', 5, 'Wages of Rs. 5,000 paid for the installation of new machinery were erroneously debited to the Wages Account. What is the rectification entry in the Journal Proper?', 'Machinery A/c Dr. 5,000 To Wages A/c 5,000', 'Wages A/c Dr. 5,000 To Machinery A/c 5,000', 'Machinery A/c Dr. 5,000 To Cash A/c 5,000', 'Installation Charges A/c Dr. 5,000 To Machinery A/c 5,000', 'a', 2, 5, 'Capital expenditure on installation belongs to the asset account, not regular revenue wages.', 'Installation wages are capital expenditure that must be added to the cost of Machinery. To rectify the error of debiting Wages A/c, Machinery A/c is debited and Wages A/c is credited.'),
        ('acc11-05-mcq-0066', 5, 'Where and how is Cash Discount Allowed (e.g., Rs. 650 allowed to Kunal Stores) recorded when a simple two-column cash book without a discount column is maintained?', 'In the Cash Book in the Bank column', 'In the Journal Proper: Discount Allowed A/c Dr. To Kunal Stores A/c', 'In the Sales Book as a trade discount deduction', 'In the Petty Cash Book under Miscellaneous Expenses', 'b', 2, 5, 'Cash discount is a non-cash adjustment and cannot be entered in a cash or bank column.', 'Cash discount is a non-cash transaction. When the cash book does not have discount columns, discount allowed is recorded in the Journal Proper: Discount Allowed A/c Dr. To Customer''s A/c.'),
        ('acc11-05-mcq-0067', 5, 'When goods worth Rs. 4,000 are withdrawn by the proprietor for personal domestic use, what journal entry is passed in the Journal Proper?', 'Purchases A/c Dr. 4,000 To Drawings A/c 4,000', 'Sales A/c Dr. 4,000 To Drawings A/c 4,000', 'Drawings A/c Dr. 4,000 To Goods / Purchases A/c 4,000', 'Drawings A/c Dr. 4,000 To Capital A/c 4,000', 'c', 2, 5, 'Drawings increases (debited) while goods in stock/purchases decrease at cost price.', 'Withdrawal of goods for personal use is debited to Drawings A/c and credited to Goods A/c (or Purchases A/c), as shown in Illustration 7 of Section 5.9.'),
        ('acc11-05-mcq-0068', 5, 'Goods costing Rs. 11,000 distributed as free samples to promote sales are recorded in the Journal Proper by debiting which account?', 'Sales Account', 'Charity Account', 'Drawings Account', 'Advertisement Account', 'd', 1, 3, 'Distributing free samples is a sales promotion / marketing expenditure.', 'Free samples are distributed to promote products and are treated as advertising expenses. The entry is Advertisement A/c Dr. To Goods distributed as Free Samples A/c (or Purchases A/c).'),
        ('acc11-05-mcq-0069', 5, 'When merchandise worth Rs. 8,500 is destroyed by fire, what journal entry is made in the Journal Proper?', 'Loss by Fire A/c Dr. 8,500 To Goods Destroyed by Fire A/c', 'Trading A/c Dr. 8,500 To Loss by Fire A/c 8,500', 'Fire Insurance Company A/c Dr. 8,500 To Cash A/c 8,500', 'Purchases A/c Dr. 8,500 To Sales A/c 8,500', 'a', 2, 5, 'Loss by fire is an abnormal nominal loss, and goods available for sale are reduced.', 'The loss is debited to Loss by Fire A/c and credited to Goods Destroyed by Fire A/c (or Purchases A/c) in the Journal Proper.'),
        ('acc11-05-mcq-0070', 5, 'A business purchased goods from Surabhi Stores for Rs. 15,000 and sold the same to Prachi at a profit of 25% on cost. What amount was entered in the Sales Book for the sale to Prachi?', 'Rs. 15,000', 'Rs. 18,750', 'Rs. 20,000', 'Rs. 16,500', 'b', 2, 5, 'Add 25% of the cost price (Rs. 15,000) to find the selling price.', 'Cost = Rs. 15,000. Profit = 25% of 15,000 = Rs. 3,750. Selling price entered in the Sales Book = Rs. 15,000 + Rs. 3,750 = Rs. 18,750.'),
        ('acc11-05-mcq-0071', 5, 'Prachi returns defective goods originally billed to her at Rs. 5,000 (which had been sold to her at a 25% profit on cost). The trader immediately returns these goods to the original supplier, Surabhi Stores. At what value should the return be recorded in the Purchase Return Book?', 'Rs. 5,000', 'Rs. 3,750', 'Rs. 4,000', 'Rs. 4,250', 'c', 3, 10, 'Use the formula given in the textbook working note: Cost = Selling Price * [100 / (100 + Profit %)].', 'As detailed in Illustration 8 working note: Value of goods returned to supplier = Selling Price * [100 / (100 + 25)] = 5,000 * (100 / 125) = Rs. 4,000.'),
        ('acc11-05-mcq-0072', 5, 'A trader purchased goods worth Rs. 1,60,000 at a 10% Trade Discount and a 5% Cash Discount. What is the amount of Net Purchases recorded in the books?', 'Rs. 1,60,000', 'Rs. 1,36,800', 'Rs. 1,52,000', 'Rs. 1,44,000', 'd', 2, 5, 'Net purchases is gross invoice price less trade discount; cash discount is a settlement deduction.', 'Net Purchases is recorded after deducting trade discount from the list price: Rs. 1,60,000 - (10% of 1,60,000) = Rs. 1,44,000. Cash discount is recorded separately upon payment.'),
        ('acc11-05-mcq-0073', 5, 'Given: Cash Purchases = Rs. 35,000, Credit Purchases = Rs. 55,000, and Net Purchases = Rs. 88,000. What is the value of Purchase Returns?', 'Rs. 2,000', 'Rs. 3,000', 'Rs. 5,000', 'Rs. 1,000', 'a', 2, 5, 'Total Purchases = Cash Purchases + Credit Purchases. Net Purchases = Total Purchases - Purchase Returns.', 'Total Purchases = Rs. 35,000 + Rs. 55,000 = Rs. 90,000. Purchase Returns = Total Purchases - Net Purchases = Rs. 90,000 - Rs. 88,000 = Rs. 2,000.'),
        ('acc11-05-mcq-0074', 5, 'Given: Credit Sales = Rs. 60,000, Sales Return = Rs. 3,000, and Net Total Sales = Rs. 1,02,000. What is the amount of Cash Sales?', 'Rs. 42,000', 'Rs. 45,000', 'Rs. 39,000', 'Rs. 48,000', 'b', 2, 5, 'Net Total Sales = Gross Sales - Sales Return. Gross Sales = Cash Sales + Credit Sales.', 'Gross Sales = Net Sales + Sales Return = Rs. 1,02,000 + Rs. 3,000 = Rs. 1,05,000. Cash Sales = Gross Sales - Credit Sales = Rs. 1,05,000 - Rs. 60,000 = Rs. 45,000.'),
        ('acc11-05-mcq-0075', 5, 'A business has Cash Receipts of Rs. 60,000, Cash Payments of Rs. 45,000, and a Closing Cash Balance of Rs. 23,000. What was the Opening Cash Balance?', 'Rs. 15,000', 'Rs. 38,000', 'Rs. 8,000', 'Rs. 12,000', 'c', 2, 5, 'Opening Balance + Receipts - Payments = Closing Balance.', 'Opening Cash Balance = Closing Balance + Payments - Receipts = Rs. 23,000 + Rs. 45,000 - Rs. 60,000 = Rs. 8,000.'),
        ('acc11-05-mcq-0076', 5, 'A firm''s Total Purchases amount to Rs. 1,90,000 and Total Creditors for credit purchases are Rs. 1,10,000. What is the value of Cash Purchases?', 'Rs. 3,00,000', 'Rs. 1,00,000', 'Rs. 90,000', 'Rs. 80,000', 'd', 2, 5, 'Total Purchases equals Cash Purchases plus Credit Purchases.', 'Cash Purchases = Total Purchases - Credit Purchases = Rs. 1,90,000 - Rs. 1,10,000 = Rs. 80,000.'),
        ('acc11-05-mcq-0077', 5, 'What is the primary difference between a Debit Note and a Credit Note in subsidiary book accounting?', 'A debit note is prepared by the buyer informing the seller of a debit; a credit note is prepared by the seller informing the buyer of a credit', 'Debit notes are used exclusively for cash purchases, while credit notes are used for credit purchases', 'Debit notes are sent to banks, while credit notes are submitted to the tax department', 'Debit notes represent revenue gains, while credit notes represent capital expenditures', 'a', 2, 5, 'Focus on who issues each document upon the return of goods.', 'As explained in Section 5.6 and 5.8: The difference between a credit note and a debit note is that the debit note is prepared by the buyer (who debits the supplier''s account), whereas the credit note is prepared by the seller (who credits the customer''s account).'),
        ('acc11-05-mcq-0078', 5, 'Which of the following accounts allows the account holder to deposit a fixed amount monthly up to a specified maturity period to earn higher interest than a savings account?', 'Current Account', 'Recurring Deposit Account', 'Fixed Deposit Account', 'Overdraft Account', 'b', 1, 3, 'Identify the account where regular monthly installments are saved over time.', 'In a Recurring Deposit Account, the account holder deposits a fixed amount monthly up to a decided period. It offers higher interest than savings accounts and lower interest than fixed deposits.'),
        ('acc11-05-mcq-0079', 5, 'A petty cashier starts with an opening balance of Rs. 300. The total petty expenses paid during the period are Rs. 2,250, and the closing balance is Rs. 150. What amount of cash was received from the chief cashier?', 'Rs. 2,250', 'Rs. 1,800', 'Rs. 2,100', 'Rs. 2,400', 'c', 2, 5, 'Opening Balance + Cash Received - Expenses Paid = Closing Balance.', 'Rs. 300 + Received - Rs. 2,250 = Rs. 150. Cash Received = Rs. 150 + Rs. 2,250 - Rs. 300 = Rs. 2,100.'),
        ('acc11-05-mcq-0080', 5, 'When a trader receives an order from a customer on 28th February to supply goods worth Rs. 37,000, on which date is the transaction recorded in the Sales Book?', 'On 28th February when the order was placed', 'At the end of the accounting year in Journal Proper', 'Immediately upon signing the purchase contract', 'On the date when the goods are actually dispatched and invoiced to the customer', 'd', 2, 5, 'Placing or receiving an order is not a financial transaction until executed.', 'Placing or receiving an order is an event, not a transaction. It is recorded in the Sales/Purchase Book only when the order is executed and the goods are invoiced.'),
        ('acc11-05-mcq-0081', 5, 'Which of the following errors is rectified through an entry in the Journal Proper?', 'Credit purchase of goods completely omitted from the books of accounts', 'Wrong totaling of the cash receipts column', 'Incorrect posting of a cash payment in the bank column', 'Petty expenses recorded in the wrong analytical column', 'a', 2, 5, 'Look for an omitted transaction between real/nominal accounts that requires a full journal entry.', 'As shown in Section 5.9 (Illustration 5), when goods purchased on credit are completely omitted from the books, the rectification entry (Purchases A/c Dr. To Supplier A/c) is recorded in Journal Proper.'),
        ('acc11-05-mcq-0082', 5, 'A customer, Bharat Patil, returned 20% of the goods originally bought by him on credit for Rs. 9,000 net, and the seller immediately gave him fresh goods of identical value in exchange. What entry is recorded in the Sales Return Book?', 'Bharat Patil debited with Rs. 1,800', 'No entry is made in the Sales Return Book because fresh replacement goods were given in exchange', 'Sales Return Book is debited with Rs. 1,800 and Sales Book is credited with Rs. 1,800', 'Journal Proper entry for barter exchange', 'b', 3, 10, 'Consider whether the return altered the net debt when replacement merchandise was supplied simultaneously.', 'When returned goods are immediately replaced with fresh goods of equal value, no net return or additional credit sale occurs in the customer''s ledger account; hence, it is treated as a direct exchange without affecting the Sales Return Book.'),
        ('acc11-05-mcq-0083', 5, 'Which of the following is NOT an advantage of maintaining subsidiary books?', 'Division of work among different accounting clerks', 'Time saving and economical accounting operations', 'Complete elimination of human error in ledger posting', 'Facilitation of internal checks and future reference', 'c', 1, 3, 'Subsidiary books improve efficiency, but no accounting system completely eliminates human error.', 'Subsidiary books offer specialization, time-saving, division of work, quick information, and internal check, but they cannot completely eliminate human error.'),
        ('acc11-05-mcq-0084', 5, 'When a cheque received from a debtor is deposited into the bank on the very same day it is received, how is it recorded in the two-column Cash Book?', 'Recorded as a Contra Entry in both Cash and Bank columns', 'Recorded on the Receipt side in the Cash column only', 'Recorded on the Payment side in the Bank column', 'Recorded on the Receipt side in the Bank column only', 'd', 2, 5, 'Since it goes directly into the bank on the day of receipt, office cash in hand is not touched.', 'When a cheque is received and deposited on the same day, the Bank Account is debited directly. It is recorded only on the receipt side in the Bank column as ''To Debtor''s A/c'', not as a contra entry.'),
        ('acc11-05-mcq-0085', 5, 'Which of the following statements is TRUE regarding Trade Discount and Cash Discount?', 'Trade discount is deducted on the invoice and not recorded separately; Cash discount is allowed for prompt payment and recorded in the books', 'Trade discount is recorded in the Cash Book, while Cash discount is deducted from the invoice', 'Both Trade discount and Cash discount are entered in the Journal Proper only', 'Neither Trade discount nor Cash discount is recognized in double-entry bookkeeping', 'a', 2, 5, 'One is a trade concession deducted from list price; the other is a financial incentive for early cash payment.', 'Trade discount is deducted directly from the gross catalogue price and never appears in ledger accounts. Cash discount is granted for prompt payment and is formally recorded in the books of accounts.'),
        ('acc11-05-mcq-0086', 5, 'In a two-column Cash Book, what does the balance brought down on the receipt side in the Cash column represent?', 'Bank Overdraft at the beginning of the period', 'Cash in hand available at the beginning of the period', 'Total credit sales made during the previous period', 'Total discount allowed to customers', 'b', 1, 3, 'An opening debit balance in the cash column represents actual currency held.', '''To Balance b/d'' in the cash column on the receipt (debit) side represents the opening balance of cash in hand available with the business at the beginning of the period.'),
        ('acc11-05-mcq-0087', 5, 'If the total of the payment side of the Bank column in a Cash Book exceeds the total of the receipt side at the end of the month, the difference is balanced by writing:', '''By Balance c/d'' on the payment side', '''By Overdraft Loss A/c'' on the payment side', '''To Balance c/d'' on the receipt side', '''To Capital A/c'' on the receipt side', 'c', 2, 5, 'To balance an account where credits exceed debits, the closing balancing figure is placed on the lighter (debit) side.', 'When payments (credits) exceed receipts (debits), there is a credit balance (overdraft). To close and balance the book, the balancing figure is entered on the receipt side as ''To Balance c/d'', and then brought down on the payment side of the next month as ''By Balance b/d''.'),
        ('acc11-05-mcq-0088', 5, 'Which of the following items requires an adjusting entry in the Journal Proper before final accounts can be accurately prepared?', 'Cash sales made during the regular course of business', 'Credit purchases of trading inventory', 'Cash deposited into the current bank account', 'Prepaid insurance and outstanding rent', 'd', 2, 5, 'Identify the accrual items that typically do not appear in the trial balance.', 'Accrual adjustments such as outstanding rent, prepaid insurance, accrued interest, and depreciation do not appear in the trial balance and require adjusting entries in the Journal Proper.'),
        ('acc11-05-mcq-0089', 5, 'A businessman transfers Rs. 15,000 from his Bank Loan Account to his Bank Current Account. How is this transaction recorded in the two-column Cash Book?', 'Debit side in the Bank column as ''To Bank Loan A/c''', 'Credit side in the Bank column as ''By Bank Loan A/c''', 'Both sides as a Contra Entry marked with ''C''', 'Recorded only in the Journal Proper', 'a', 2, 5, 'The current account balance increases, so the bank column must be debited.', 'Transferring funds from a Loan or Cash Credit account to the Current account increases the Current account balance. It is recorded on the receipt side in the Bank column as ''To Cash Credit / Loan A/c''.'),
        ('acc11-05-mcq-0090', 5, 'When a cheque previously issued to a creditor is dishonoured by the bank, which side of the Cash Book is affected and under which column?', 'Payment side in the Cash column', 'Receipt side in the Bank column', 'Payment side in the Bank column', 'Receipt side in the Cash column', 'b', 3, 10, 'Issuing a cheque was recorded on the payment side of the bank column. Canceling a dishonoured issued cheque reverses that entry.', 'When the cheque was issued, it was credited (payment side) in the bank column. When dishonoured, the bank did not pay out the money; to cancel the payment, it is recorded on the receipt side in the bank column as ''To Creditor''s A/c''.'),
        ('acc11-05-mcq-0091', 5, 'Which document is prepared by an employee or petty cashier to support each small expense payment before recording it in the Petty Cash Book?', 'Debit Note', 'Credit Note', 'Petty Cash Voucher', 'Inward Invoice', 'c', 1, 3, 'This internal receipt/document contains payment details and the signature of the receiver.', 'Every petty payment must be supported by a voucher showing date, particulars, and amount, duly verified. This is referred to as a Petty Cash Voucher.'),
        ('acc11-05-mcq-0092', 5, 'When closing the petty cash book at the end of the month, the excess of total cash received over total petty expenses paid is recorded as:', '''To Balance c/d'' on the receipt side', '''By Imprest Loss A/c'' on the payment side', '''To Chief Cashier A/c'' on the receipt side', '''By Balance c/d'' on the payment side', 'd', 1, 3, 'The closing unspent balance is placed on the payment side to balance the book.', 'The closing unspent petty cash balance is recorded on the payment side as ''By Balance c/d'' and carried forward to the beginning of the next month as ''To Balance b/d''.'),
        ('acc11-05-mcq-0093', 5, 'What happens when an analytical petty cash book contains a column for ''Ledger Accounts''?', 'Amounts in that column are posted individually to personal or real accounts in the ledger', 'It records the salaries of all senior corporate executives', 'It is totaled and posted to the Trading Account at the end of the year', 'It replaces the need for maintaining the main Cash Book', 'a', 2, 5, 'Personal advances and asset acquisitions require individual ledger postings.', 'Unlike expense columns whose totals are posted periodically, items entered in the Ledger column of an analytical petty cash book (such as an advance to an employee or purchase of an asset) must be posted individually to their respective ledger accounts.'),
        ('acc11-05-mcq-0094', 5, 'In which book of original entry is a transaction recorded when goods are purchased on credit from a supplier and trade discount is allowed?', 'Cash Book at full list price', 'Purchase Book at net invoice price', 'Journal Proper at gross price and Cash Book at discount value', 'Bills Payable Book at gross price', 'b', 1, 3, 'Trade purchases on credit go to the Purchase Book net of trade discount.', 'Credit purchases of goods are entered in the Purchase Book at net value (after deducting trade discount).'),
        ('acc11-05-mcq-0095', 5, 'If a trader sells goods costing Rs. 8,000 to Sunita at a 25% profit on cost, what is the credit entry made in the Sales Account upon ledger posting?', 'Rs. 8,000', 'Rs. 2,000', 'Rs. 10,000', 'Rs. 12,000', 'c', 2, 5, 'Cost Rs. 8,000 + (25% of 8,000) = Selling Price.', 'Cost = Rs. 8,000. Profit = 25% of 8,000 = Rs. 2,000. The invoice price is Rs. 10,000, which is entered in the Sales Book and subsequently posted to the credit of Sales Account.'),
        ('acc11-05-mcq-0096', 5, 'How is carriage of Rs. 250 paid in cash on the purchase of goods recorded when goods were bought on credit from Avadhoot Traders?', 'Added directly to the supplier''s bill in the Purchase Book', 'Debited to Avadhoot Traders in Journal Proper', 'Deducted from the purchase invoice value', 'Recorded in the Simple or Two-column Cash Book as ''By Carriage A/c''', 'd', 2, 5, 'Cash spent on carriage is an immediate cash payment, not a credit transaction with the supplier.', 'As noted in Illustration 7 working notes: Carriage paid in cash (Rs. 250) is a cash disbursement and must be recorded in the Cash Book, not added to the credit purchase book.'),
        ('acc11-05-mcq-0097', 5, 'When a trader receives a Credit Note from a supplier for goods previously returned, in which book does the trader record this return?', 'Purchase Return Book', 'Sales Return Book', 'Bills Payable Book', 'Journal Proper', 'a', 2, 5, 'The supplier issues a credit note to confirm acceptance of the goods returned to them.', 'When goods are returned by the trader to a supplier, the trader issues a Debit Note, and the supplier confirms acceptance by issuing a Credit Note. This return of purchased goods is recorded in the Purchase Return Book.'),
        ('acc11-05-mcq-0098', 5, 'Which of the following describes an inter-state credit sale transaction of readymade garments subject to 5% GST?', 'CGST @ 2.5% and SGST @ 2.5% are charged', 'IGST @ 5% is charged on the taxable value', 'IGST @ 10% is charged on the list price', 'No GST is charged on inter-state credit transactions', 'b', 2, 5, 'Sales between two different states attract Integrated GST at the full rate.', 'As illustrated in Problem 6 (sale to Mehul Bros, Delhi by a Maharashtra seller), inter-state sales attract Integrated GST (IGST) at the full combined rate of 5% on the net taxable sales value.'),
        ('acc11-06-mcq-0001', 6, 'What basic facts of a financial transaction are specifically described by an accounting document according to the chapter?', 'Future market value, inflation rate, and vendor profit margin', 'Banker''s specimen signature and income tax clearance certificate', 'Amount, recipient, purpose, and date of transaction', 'Depreciation rate, scrap value, and salvage estimate', 'c', 1, 3, 'Look at the four fundamental factual elements listed in the introduction of Section 6.1.', 'The chapter opens by defining accounting documents as describing all basic facts of transactions: the amount of transaction, to whom the amount was paid, the purpose of transaction, and the date of transaction. The other options refer to valuation or taxation concepts not in this definition.'),
        ('acc11-06-mcq-0002', 6, 'What primary evidentiary role do accounting documents play in the process of Book-Keeping?', 'They eliminate the requirement to maintain a journal or ledger', 'They act as negotiable credit instruments enforceable on demand', 'They provide evidence that a financial transaction has actually taken place', 'They serve as legal authority to alter audited financial statements', 'c', 1, 3, 'Consider why an accountant insists on having bills, receipts, or vouchers before passing entries.', 'The text explicitly states: ''This is essential in the process of Book Keeping as it provides evidence that a financial transaction has actually taken place.'' They do not replace journals or ledgers, nor do they permit altering audited books.'),
        ('acc11-06-mcq-0003', 6, 'Which modern banking method provides instant and automatic proof of payment and receipt for both parties without requiring a physical visit to the bank?', 'Manual withdrawal slip', 'Internet and mobile banking', 'Over-the-counter pay-in-slip', 'Postal clearing slip', 'b', 1, 3, 'Identify the electronic banking channel highlighted in Section 6.1 that creates immediate digital records.', 'Section 6.1 explains that internet and mobile banking play a prominent role in modern business because payments and receipts of cash through these methods generate instant and automatic proof for both parties.'),
        ('acc11-06-mcq-0004', 6, 'What is another commonly used name for a Pay-in-slip?', 'Withdrawal slip', 'Deposit slip', 'Credit note', 'Bank advice', 'b', 1, 3, 'Think of the document filled out when putting money into an account.', 'Under ''Types of Bank Documents (1)'', the text states: ''Pay-in-slip is also known as deposit slip. This slip is filled when the account holder deposits cheque or cash into his bank account.'''),
        ('acc11-06-mcq-0005', 6, 'A Pay-in-slip is divided into two parts. Which part is stamped, signed, dated by the receiving clerk, and returned to the customer as an acknowledgement?', 'The bank''s internal clearing voucher', 'The micro-perforated carbon copy', 'The left-hand side counterfoil', 'The right-hand side portion', 'c', 1, 3, 'Identify the specific term used for the customer''s retention side of the slip.', 'The chapter explains that a pay-in-slip is divided into two parts: the right-hand side is kept with the bank for their record, while the left-hand side, known as the counterfoil, is duly stamped, signed, dated by the clerk, and returned to the account holder as acknowledgement.'),
        ('acc11-06-mcq-0006', 6, 'Why is the counterfoil of a pay-in-slip vital for the business accountant?', 'It guarantees that the deposited cheque will never be dishonoured', 'It allows the account holder to withdraw cash without filling a withdrawal form', 'It replaces the need for maintaining a Cash Book bank column', 'It acts as legal evidence and forms the source document to record bank deposits in the books of accounts', 'd', 2, 5, 'Focus on the dual utilities of the counterfoil: source document for book entries and legal proof.', 'Under ''Importance and Utilities'' of pay-in-slip: (ii) Entries in respect of cash or cheque deposited are recorded in the books of accounts on the basis of pay-in-slip, and (iii) Counterfoil acts as legal evidence. It does not prevent cheque bounce or eliminate the Cash Book.'),
        ('acc11-06-mcq-0007', 6, 'Under statutory banking guidelines shown in the Pay-in-slip format, quoting a PAN card number is compulsory when cash deposit exceeds what amount?', 'Rs 1,00,000', 'Rs 25,000', 'Rs 20,000', 'Rs 50,000', 'd', 1, 3, 'Recall the monetary limit specified in the pay-in-slip specimen for cash deposits.', 'Contents item (x) and the pay-in-slip specimen explicitly specify: ''PAN card number if the amount of deposit is more than 50,000'' (or For Cash Deposit of 50,000 & Above).'),
        ('acc11-06-mcq-0008', 6, 'Which detail of cash currency must be specified on a pay-in-slip when depositing physical currency into a bank account?', 'Breakdown of denominations, specifying the count of Rs 100, Rs 200, Rs 500, and Rs 2000 notes', 'Serial numbers of every individual currency note deposited', 'The signature of the Reserve Bank Governor on each note', 'The year in which the currency notes were minted or printed', 'a', 1, 3, 'Think of the cash denomination table printed on the slip.', 'Contents item (vii) of Pay-in-slip states: ''Details of denomination, i.e. number of Rs 100, Rs 200, Rs 500, Rs 2000 notes etc. deposited.'' Serial numbers or mint dates are not required.'),
        ('acc11-06-mcq-0009', 6, 'How can a customer deposit a cheque along with a pay-in-slip in modern branches without waiting at the teller counter?', 'By sending a certified SMS to the branch manager', 'By attaching it to a withdrawal form at the ATM', 'By dropping it into the designated drop box placed in the bank', 'By submitting an online RTGS application form', 'c', 1, 3, 'Look for the note directly following Fig. 6.1(a) on page 179.', 'The chapter notes: ''In modern times, a cheque along with duly filled pay-in-slip can be simply dropped into the drop box placed in the bank for collection.'''),
        ('acc11-06-mcq-0010', 6, 'What is a Withdrawal Slip, and how does its record availability differ from a pay-in-slip?', 'It is an electronic statement emailed to the account holder each quarter', 'It is a form filled for withdrawing money from bank; a retained copy is not available to the customer, but the entry is reflected in the Pass Book', 'It is a slip issued by the clearing house confirming cheque dishonour', 'It is a negotiable instrument that provides a counterfoil to record entries in the Cash Book', 'b', 2, 5, 'Notice the explicit sentence about document copies under ''Withdrawal Slip: Meaning'' on page 179.', 'The text states: ''Form which is to be filled for withdrawing money from bank is known as withdrawal slip or form. A copy of this document is not available to record the transaction in the books of accounts but it is reflected in the Pass Book.'''),
        ('acc11-06-mcq-0011', 6, 'Which of the following restrictions applies to the use of a cash withdrawal slip according to its printed conditions?', 'It can be endorsed to third-party suppliers as payment for goods', 'It can be presented at any branch of any scheduled commercial bank nationwide', 'It can be used only when the account has an authorized overdraft limit', 'It is not a cheque, must accompany the Pass Book, and can be used at the home branch only', 'd', 2, 5, 'Read the notices printed across the top of the cash withdrawal slip format (Fig. 6.1b).', 'The specimen format specifically states: ''Pass Book must accompany with this withdrawal. Please sign overleaf. This withdrawal slip is not a cheque. Use at home branch only.'' Distractors A and C contradict these explicit rules.'),
        ('acc11-06-mcq-0012', 6, 'Why must an account holder sign both on the face and on the reverse side of a withdrawal slip?', 'To convert the form into a multi-currency draft', 'To authorise the bank to debit standing orders and bank commission', 'To waive the customer''s right to receive a Bank Statement', 'To allow the teller to match the signature with specimen signatures in the bank''s records, preventing malpractices', 'd', 2, 5, 'Consider the verification procedure performed by the bank clerk before disbursing cash.', 'Under Utilities of Withdrawal Slip: ''Account holder signs on the face of the slip and backside of the slip. Signature of the account holder is matched with his/her specimen signature recorded in the books of bank thereby avoiding malpractices.'''),
        ('acc11-06-mcq-0013', 6, 'When cash withdrawal using a withdrawal slip exceeds Rs 50,000, what additional document must be submitted by the account holder?', 'Photocopy of their PAN card', 'Duplicate copy of the current month''s Cash Book', 'A registered mortgage deed', 'A written indemnity bond counter-signed by an auditor', 'a', 1, 3, 'Recall the tax identification document required for high-value banking transactions.', 'The text states: ''If the amount of withdrawal is more than 50,000 account holder has to submit a photocopy of his PAN card.'''),
        ('acc11-06-mcq-0014', 6, 'What is the specific term used in the chapter for availing banking services through extensive use of information technology without physically walking into bank premises?', 'Branch clearing banking', 'Merchant banking', 'Virtual banking', 'Consortium banking', 'c', 1, 3, 'Look at the definition highlighted in the boxed callout on page 180.', 'The text defines: ''Availing banking services through an extensive use of information technology without physically walking into the bank premises is called virtual banking.'''),
        ('acc11-06-mcq-0015', 6, 'What is a Bank Pass Book fundamentally defined as?', 'A copy or extract of the ledger account of the account holder appearing in the books of the bank', 'A daily clearing memo issued by the Reserve Bank of India', 'A statutory register maintaining details of shareholders'' equity', 'A duplicate of the cash column of the business Cash Book', 'a', 1, 3, 'Notice whose books it is an extract of, and whose account it details.', 'Section 6.1(3) defines Pass Book as: ''a copy or extract of ledger account of account holder appearing in the books of bank. In this the bank provides the account holder with the details of all ledger entries appearing in the books of bank.'''),
        ('acc11-06-mcq-0016', 6, 'During which century did Bank Pass Books first appear, giving customers transaction records in their own hands?', '19th century', '18th century', '20th century', '15th century', 'b', 1, 3, 'Check the historical note at the end of Section 6.1(3) on page 181.', 'The chapter mentions: ''Pass Books appeared in the 18th century, allowing customers to have transaction information in their own hands for the first time. Prior to this, customers had no history of their own deposits and withdrawals.'''),
        ('acc11-06-mcq-0017', 6, 'What is the nature and purpose of IFSC as detailed in a Bank Pass Book?', 'It is a secret four-digit PIN code used to authorize ATM cash withdrawals', 'It is a barcode printed exclusively to calculate monthly interest charges', 'It is a 16-digit purely numeric code verifying international credit ratings', 'It is an alphanumeric code that facilitates electronic funds transfer like IMPS, NEFT, and RTGS', 'd', 1, 3, 'Focus on the code''s composition (letters and numbers) and its fund transfer facilitation role.', 'Under Contents of Pass Book: ''IFSC (Indian Financial System Code) It is an alphanumeric code that facilitates electronic funds transfer like IMPS, NEFT and RTGS.'' It is not a secret PIN or credit rating code.'),
        ('acc11-06-mcq-0018', 6, 'Why do commercial banks provide a periodic Bank Statement instead of a Pass Book to Current Account holders?', 'Because current accounts cannot legally be recorded in computerized banking systems', 'Because current accounts have zero deposits and are restricted to government transactions', 'Because Bank Statements are only issued when an account runs into overdraft', 'Because businessmen enjoy unlimited deposits and withdrawals, resulting in a large volume of transactions best summarised periodically', 'd', 2, 5, 'Consider the frequency and volume of transactions conducted by business firms.', 'The text explains under Section 6.1(4): ''Current account holders enjoy unlimited number of deposits and withdrawals and therefore the number of transactions is large. Businessmen like to know the details of transactions and the bank balance. Therefore, the bank issues a bank statement to them.'''),
        ('acc11-06-mcq-0019', 6, 'What direct operational and financial benefit does viewing, downloading, and printing electronic bank statements offer to banks and account holders?', 'It reduces the cost of paper and postage', 'It prevents cheques from being dishonoured', 'It guarantees an interest-free overdraft facility', 'It eliminates the need to maintain an internal Cash Book', 'a', 1, 3, 'Look for the specific cost-saving advantage cited on page 181.', 'The chapter states: ''Today with better access to the internet and online banking, bank statement also known as electronic statement can be viewed online, downloaded and printed by the account holder. This reduces the cost of paper and postage.'''),
        ('acc11-06-mcq-0020', 6, 'What is a ''Bank Advice'' as explained in the chapter?', 'A letter sent by the bank to an account holder in a prescribed form to inform them of debits/credits like dishonour, bank charges, or standing order payments', 'A formal notice served by tax authorities freezing an account', 'A letter sent by a customer requesting the bank to increase overdraft limits', 'A loan sanction letter detailing mortgage terms', 'a', 1, 3, 'Notice who sends the advice to whom and for what accounting purposes.', 'Section 6.1(5) defines Bank Advice as: ''a letter sent by the bank to customer / account holder in a prescribed form to inform them about dishonour of cheques... bank charges debited, dishonour of Bills receivable discounted... interest charged and allowed... dividend collected... and payments made according to standing instructions.'''),
        ('acc11-06-mcq-0021', 6, 'Which contemporary technology has largely overtaken the role of physical Bank Advices for updating account holders?', 'Telegram dispatches', 'Bank passbook drop boxes', 'Monthly certified post receipts', 'SMS alerts and notifications on registered mobile numbers', 'd', 1, 3, 'Recall what message arrives instantly on a mobile phone after making a transaction.', 'The chapter highlights: ''SMS alerts and notifications have overtaken bank advice today. Account holder receives SMS on their registered mobile number giving updates of their latest banking transactions.'''),
        ('acc11-06-mcq-0022', 6, 'Which electronic funds transfer system is available 24/7 throughout the year, including bank holidays, for immediate fund transfers?', 'Demand Draft (DD)', 'Immediate Payment Service (IMPS)', 'Cheque Clearing House', 'Physical Pay Order', 'b', 1, 3, 'Look for the instant payment interbank service mentioned in the callout on page 186.', 'The text explains: ''IMPS (Immediate Payment Service) is an instant payment interbank electronic funds transfer system in India. When an account holder needs to transfer funds immediately, IMPS can be used because this service is available 24/7 throughout the year including bank holidays.'''),
        ('acc11-06-mcq-0023', 6, 'According to the chapter, for which transfer amounts are NEFT and RTGS respectively considered suitable?', 'NEFT is suitable for transfers greater than Rs 10 Lakhs, while RTGS is for transfers up to Rs 50,000', 'NEFT is suitable only for international transfers, while RTGS is for local branch deposits', 'NEFT is suitable for transfers less than Rs 2 Lakhs, while RTGS is suitable for larger transfers greater than Rs 2 Lakhs', 'NEFT is suitable for cash withdrawals, while RTGS is exclusively for cheques', 'c', 1, 3, 'Recall the monetary dividing line of Rs 2 Lakhs cited on page 186.', 'The chapter states: ''NEFT (National Electronic Funds Transfer) is suitable for small money transfers (less than 2 Lakhs) and RTGS (Real Time Gross Settlement) is suitable for larger money transfers (greater than 2 Lakhs).'''),
        ('acc11-06-mcq-0024', 6, 'In a business ledger, what does the bank column of the Cash Book represent?', 'The capital account contributed by partners', 'Physical cash in hand kept in the office safe', 'The bank current account maintained by the businessman', 'The loans and advances ledger of suppliers', 'c', 1, 3, 'Look at the definition in Section 6.2 explaining the Cash Book with bank column.', 'Section 6.2 states: ''A businessman maintains a Cash Book with bank column in his ledger, wherein he records all banking transactions. The bank column in his Cash Book represents bank current account.'''),
        ('acc11-06-mcq-0025', 6, 'When a businessman deposits money or cheques into the bank, how is the entry recorded in the Cash Book and Pass Book respectively?', 'Debit side of Cash Book and Debit side of Pass Book', 'Credit side of Cash Book (Payment) and Debit side of Pass Book (Payment)', 'Credit side of Cash Book and Credit side of Pass Book', 'Debit side of Cash Book (Receipt) and Credit side of Pass Book (Receipt)', 'd', 2, 5, 'To the firm, bank is a debit receipt; to the bank, the customer deposit is a credit liability.', 'The chapter states: ''When businessman deposits money or cheque into bank for collection it is recorded in the Cash Book on the debit or receipt side. Bank records this on the credit or receipt side of Pass Book.'''),
        ('acc11-06-mcq-0026', 6, 'When a businessman issues a cheque to pay a supplier, on which side of the Cash Book and Pass Book is the transaction entered?', 'Debit side of Cash Book and Credit side of Pass Book', 'Debit side of Cash Book and Debit side of Pass Book', 'Credit side of Cash Book (Payment) and Debit side of Pass Book (Payment)', 'Credit side of Cash Book and Credit side of Pass Book', 'c', 2, 5, 'Payment reduces the firm''s bank asset (credit) and reduces the bank''s liability to the customer (debit).', 'Section 6.2 states: ''Similarly, when businessman issues cheque for making payments, it is recorded on the credit or payment side of Cash Book. Bank records this transaction on the debit side or payment side of Pass Book / bank statement.'''),
        ('acc11-06-mcq-0027', 6, 'Under ideal conditions with no pending differences or errors, what is the reciprocal relationship between the balances of Cash Book and Pass Book?', 'If the Cash Book has a debit balance, the Pass Book will have an equal credit balance, and vice versa', 'Both books will reflect a debit balance of equal amount', 'Both books will reflect a credit balance of equal amount', 'The Pass Book balance will always be exactly double the Cash Book balance', 'a', 1, 3, 'Remember that the two books record mirror perspectives of the same transactions.', 'The chapter states: ''Ideally then, Cash Book bank balance and Pass Book balance should be the same. The only difference would be that if Cash Book has a debit balance the Pass Book will have a credit balance and vice versa.'''),
        ('acc11-06-mcq-0028', 6, 'Which of the following defines a ''Bank Reconciliation Statement'' according to the chapter?', 'A letter sent by the bank manager detailing interest rate adjustments', 'A statement showing the causes of disagreement between the balance shown by the bank Pass Book and the balance shown by the Cash Book under the bank column at the end of a specific period', 'A journal voucher used to write off irrecoverable debts from customers', 'A statutory balance sheet prepared by commercial banks for regulatory audits', 'b', 1, 3, 'Look for the formal definition provided in Section 6.2.', 'Section 6.2 defines BRS as: ''A statement showing the causes of disagreement between the balance shown by the bank Pass Book and the balance shown by the Cash Book under the bank column at the end of the specific period or month, is called Bank Reconciliation Statement.'''),
        ('acc11-06-mcq-0029', 6, 'Who is responsible for preparing the Bank Reconciliation Statement?', 'The statutory government tax auditor', 'The businessman / account holder', 'The commercial bank holding the account', 'The Reserve Bank of India clearing house', 'b', 1, 3, 'Exercise Q.4(5): ''Bank Reconciliation Statement is prepared by...''', 'BRS is prepared by the businessman (account holder) to reconcile internal Cash Book records with the bank statement received from the bank. The bank does not prepare a BRS for individual account holders.'),
        ('acc11-06-mcq-0030', 6, 'Which of the following is NOT an advantage or need for preparing a Bank Reconciliation Statement listed in Section 6.2?', 'It serves as an important mechanism of internal check and provides information on cash inflows and outflows', 'It helps in detecting errors and omissions made in Pass Book and Cash Book', 'It permanently exempts the business entity from external audits and tax liabilities', 'It reduces the chance of fraud by staff dealing in cash', 'c', 2, 5, 'Look for an unrealistic legal/tax claim that has nothing to do with internal financial control.', 'Section 6.2 lists six reasons for the need and importance of BRS: explaining disagreements, detecting errors, reducing fraud, checking bank entries, moral check on staff, and acting as an internal check mechanism. It does NOT exempt any firm from audit or taxation.'),
        ('acc11-06-mcq-0031', 6, 'How does regular preparation of a BRS exercise a ''moral check'' on the accounting staff of a business?', 'It guarantees annual bonuses to all accounting clerks', 'It encourages staff to keep Cash Book records accurate and up to date because omissions and misappropriations will be promptly revealed', 'It transfers disciplinary powers from the employer to the commercial bank', 'It allows clerks to record personal household expenses in the business ledger', 'b', 2, 5, 'Think of how transparent reconciliation deters negligence and dishonesty among cash-handling employees.', 'Under Need and Importance item (v): ''It helps to have a moral check on the staff of business organisations to keep Cash Book up to date'' and (iii) reduces the chance of fraud by staff dealing in cash.'),
        ('acc11-06-mcq-0032', 6, 'What are the two major broad categories of reasons causing differences between Cash Book balance and Pass Book balance?', 'Capital expenditures, and revenue expenditures', 'Time difference, and Errors and omissions made by bank or businessman', 'Currency exchange rate fluctuations, and trade discounts', 'Bad debts written off, and provision for depreciation', 'b', 1, 3, 'Refer to the main classification heading in Section 6.3 and Figure 6.3(a).', 'Section 6.3 divides the reasons for difference into two categories: ''i) Time difference'' and ''ii) Errors and omission made by businessman or bank.'''),
        ('acc11-06-mcq-0033', 6, 'When a cheque is issued to a creditor but has NOT yet been presented to the bank for payment by the reconciliation date, what is the comparative effect on the two books?', 'Pass Book balance will be higher than the balance as per Cash Book', 'Pass Book will show an overdraft, while Cash Book shows zero', 'Cash Book balance will be higher than the balance as per Pass Book', 'Both balances will decrease immediately', 'a', 2, 5, 'Issuing a cheque immediately credits (deducts) the Cash Book, but the bank has not yet debited (deducted) it.', 'Section 6.3(I)(a)(i) states: ''As soon as a cheque is issued, it is entered on the credit side of the Cash Book but the bank makes no entry for cheque until it is presented for payment... the balance in the Pass Book will be higher than the balance as per Cash Book on that date.'''),
        ('acc11-06-mcq-0034', 6, 'When cheques are deposited into the bank but not yet cleared and collected by the bank, what is the relative state of the two balances?', 'Pass Book balance is higher than Cash Book balance', 'Both books show identical balances', 'Cash Book balance is higher than Pass Book balance', 'Cash Book reflects a credit balance and Pass Book reflects an overdraft', 'c', 2, 5, 'Depositing a cheque immediately debits (increases) the Cash Book, but the bank credits it only after clearing.', 'Section 6.3(I)(a)(ii) states: ''As soon as cheques are received and deposited... they are recorded in the Cash Book on debit side which increase the balance at bank as per Cash Book but bank does not give credit... until it is cleared and collected... Therefore, balance as per Cash Book is higher.'''),
        ('acc11-06-mcq-0035', 6, 'When the bank credits interest on deposit in the Pass Book, what is the effect on the balances before the customer receives intimation?', 'Both books reflect an automatic overdraft', 'Cash Book balance is higher than Pass Book balance', 'Pass Book balance remains unchanged while Cash Book increases', 'Pass Book balance is higher than Cash Book balance', 'd', 2, 5, 'Interest credited by the bank increases the funds in the bank account first.', 'Section 6.3(I)(b)(i) states: ''If the bank allows interest to customer it credits the customer account and the bank balance as per Pass Book will increase... Until then the balance as per Pass Book would be more than the balance as per Cash Book.'''),
        ('acc11-06-mcq-0036', 6, 'When a bank collects dividend, interest, or rent directly on behalf of a customer under standing instructions, why does a difference arise?', 'Because the bank credits the customer''s account immediately, but the customer enters it in the Cash Book only upon receiving the statement or advice', 'Because the Cash Book must record dividend only at the end of the financial year', 'Because dividend collection is illegal without prior court sanction', 'Because the bank debits the customer''s account without sending an advice', 'a', 2, 5, 'The money enters the bank first; the customer learns of it only when reviewing bank statements or SMS.', 'Section 6.3(I)(b)(ii) explains that the bank collects and credits the customer''s account directly, increasing the Pass Book balance. The customer records it in the Cash Book only upon receiving the statement/intimation, creating a timing difference where Pass Book > Cash Book.'),
        ('acc11-06-mcq-0037', 6, 'When the bank pays insurance premiums, electricity bills, or loan instalments under standing instructions, what is the effect on relative balances before intimation?', 'Cash Book balance will decrease automatically without any intimation', 'Pass Book balance will be less than Cash Book balance', 'Pass Book will reflect an overcast balance', 'Pass Book balance will be higher than Cash Book balance', 'b', 2, 5, 'Direct payment deducts money from the bank account before the firm''s accountant records it.', 'Section 6.3(I)(b)(iii) states: ''As soon as such payments are made bank debits customer account in bank Pass Book / bank statement but the customer has no information... Till then balance as per Pass Book / bank statement will be less than balance as per Cash Book.'''),
        ('acc11-06-mcq-0038', 6, 'How do bank charges, commission, and interest on overdraft debited by the bank affect the Pass Book balance on the reconciliation date?', 'They cause Pass Book balance to be higher than Cash Book balance', 'They have no effect on either book balance', 'They increase the cash column of the Cash Book', 'They cause Pass Book balance to be less than Cash Book balance', 'd', 2, 5, 'Debits in the Pass Book represent deductions made by the bank.', 'Section 6.3(I)(b)(iv) states: ''Bank debits the customer''s account for such facilities time to time. However, the firm will know about these charges... only when it goes through the bank Pass Book... So, on the date of reconciliation balance as per Pass Book will be less than that of Cash Book.'''),
        ('acc11-06-mcq-0039', 6, 'When a customer''s debtor deposits money directly into the businessman''s bank account via NEFT or cash, what is the effect on the two books before the bank statement is received?', 'Balance shown in Pass Book will be more than balance shown in Cash Book', 'The debtor''s personal account in the business ledger is automatically credited by the bank', 'Balance shown in Cash Book will be more than balance shown in Pass Book', 'Cash Book will show a credit balance while Pass Book shows zero', 'a', 2, 5, 'The deposit is already sitting in the bank account, but unentered in the Cash Book.', 'Section 6.3(I)(b)(vi) states: ''bank records the receipt in customers account but the same is not recorded in the businessman''s Cash Book. As a result, the balance shown in bank Pass Book will be more than the balance shown in Cash Book.'''),
        ('acc11-06-mcq-0040', 6, 'When a bill of exchange discounted with the bank is dishonoured on the due date, what entry does the bank make in the Pass Book?', 'Bank debits the customer''s account in the Pass Book', 'Bank issues a new bill of exchange automatically', 'Bank writes off the bill against its statutory bad debt reserves', 'Bank credits the customer''s account to return the discount charge', 'a', 2, 5, 'The bank recovers the unpaid funds from the customer who discounted the bill.', 'Section 6.3(I)(b)(v) states: ''When cheque or Bill of exchange discounted with the bank is dishonoured, the same is debited in the Pass Book / bank statement but not given effect in the Cash Book until intimation is received.'''),
        ('acc11-06-mcq-0041', 6, 'If a cheque issued by a businessman to make a payment is returned dishonoured, how does the bank cancel the earlier debit entry in the Pass Book?', 'Bank deletes the transaction from the electronic database completely', 'Bank credits the customer''s account in the Pass Book', 'Bank debits the customer''s account a second time', 'Bank freezes the customer''s overdraft facility permanently', 'b', 2, 5, 'To reverse a previous debit, what accounting entry must be passed?', 'Section 6.3(I)(b)(v) explains: ''when customer makes the payment by cheque and if it is dishonoured, bank credits the same in Pass Book / bank statement to cancel the earlier effect of cheque but will not give effect of dishonour of cheque in the Cash Book until the intimation is received.'''),
        ('acc11-06-mcq-0042', 6, 'Bank charges of Rs 540 debited by the bank were mistakenly entered in the Cash Book as Rs 450. What type of cause of discrepancy does this illustrate?', 'Omission of a transaction by the bank', 'Statutory deduction of tax at source', 'Error committed by the businessman in recording the wrong amount', 'Timing difference due to clearing delay', 'c', 1, 3, 'Look at the specific numerical illustration given in Section 6.3(ii) on page 185.', 'Section 6.3(ii) cites this exact example: ''Differences in balance may also arise due to errors committed by bank or businessman. For example, bank charges debited by bank 540 is recorded as 450 in Cash Book. Here the transaction appears in both the books but with wrong amount.'''),
        ('acc11-06-mcq-0043', 6, 'A customer deposit of Rs 26,200 into the bank was mistakenly entered in the CASH column instead of the BANK column of the Cash Book. What is the effect on the Bank Reconciliation Statement?', 'It creates no difference in the Bank Reconciliation Statement', 'The Cash Book bank column omitted this deposit, so the Cash Book bank balance is Rs 26,200 lower than the Pass Book', 'The Pass Book balance is Rs 26,200 lower than the Cash Book bank balance', 'The cash in hand is understated by Rs 26,200', 'b', 2, 5, 'See Illustration 10 Item (iii): The bank collected the deposit, but the Cash Book BANK column did not record it.', 'Because the cash deposit was entered in the cash column rather than the bank column, the bank column of the Cash Book failed to reflect the deposit. The bank credited it in the Pass Book, so the Cash Book bank balance is Rs 26,200 lower than the Pass Book balance.'),
        ('acc11-06-mcq-0044', 6, 'A cheque of Rs 4,250 received from Akash was deposited into the bank for collection but was NOT yet collected by the bank. The accountant mistakenly recorded the entry in the CASH column of the Cash Book. Why does this item NOT appear in the BRS?', 'Because cheques under Rs 5,000 are exempt from reconciliation', 'Because the cheque was issued by a debtor rather than a supplier', 'Because it was omitted from the Cash Book bank column and has also not yet been credited in the Pass Book, thus creating zero difference between the two bank records', 'Because cash transactions are strictly prohibited from being reconciled', 'c', 3, 10, 'Review the Note to Illustration 7: Does the transaction appear in either bank account record?', 'As noted in Illustration 7 (Note to Item vi): ''This does not create any difference in the balance of the two books because it has not been recorded in the Bank column of cash-book and it does not appear in the Pass Book too since it has not been collected by bank.'' Hence no discrepancy exists between the two bank balances.'),
        ('acc11-06-mcq-0045', 6, 'If the debit (receipt) side of the bank column in the Cash Book is overcast by Rs 100, what is the direct effect on the Cash Book balance?', 'The Pass Book balance is overstated by Rs 100', 'The Cash Book bank balance is overstated by Rs 100', 'The Pass Book overdraft is reduced by Rs 100', 'The Cash Book bank balance is understated by Rs 100', 'b', 2, 5, 'Overcasting means calculating a column total higher than its true sum.', 'Overcasting receipts (debit side) of the Cash Book inflates total receipts, thereby artificially overstating the closing Cash Book bank balance by Rs 100 relative to the true bank balance.'),
        ('acc11-06-mcq-0046', 6, 'What is the effect on the Cash Book balance if the credit (payment) side of the bank column in the Cash Book is undercast by Rs 350?', 'Cash Book balance is overstated by Rs 350', 'Pass Book overdraft increases by Rs 350', 'Pass Book balance is understated by Rs 350', 'Cash Book balance is understated by Rs 350', 'a', 2, 5, 'Undercasting payments means total deductions are smaller than they should be.', 'When the payment side is undercast, payments are totalled to a smaller sum than actual. Deducting less from receipts causes the resulting Cash Book closing balance to be overstated (higher) by Rs 350.'),
        ('acc11-06-mcq-0047', 6, 'If the debit (withdrawal) side of the Bank Pass Book is overcast by Rs 300, how does this affect the Pass Book balance?', 'Pass Book balance is understated by Rs 300', 'Cash Book balance is understated by Rs 300', 'Pass Book balance is overstated by Rs 300', 'Pass Book reflects a zero balance', 'a', 2, 5, 'Pass Book debit side records withdrawals. Adding them up too high deducts too much from the account.', 'Pass Book debit entries represent withdrawals. If total withdrawals are overcast (totalled too high by Rs 300), the calculated Pass Book balance will be understated by Rs 300 (or the overdraft will be overstated by Rs 300).'),
        ('acc11-06-mcq-0048', 6, 'If the credit (receipt) side of the Bank Pass Book is undercast by Rs 1,000, what is the effect on the Pass Book balance?', 'Pass Book balance is overstated by Rs 1,000', 'Pass Book reflects an unpresented cheque of Rs 1,000', 'Pass Book balance is understated by Rs 1,000', 'Cash Book balance is understated by Rs 1,000', 'c', 2, 5, 'Undercasting deposits means showing fewer total deposits than actually occurred.', 'The credit side of the Pass Book records deposits. If this side is undercast by Rs 1,000, total deposits are short by Rs 1,000, causing the Pass Book balance to be understated by Rs 1,000.'),
        ('acc11-06-mcq-0049', 6, 'An electricity bill of Rs 6,200 paid directly by the bank was erroneously debited TWICE in the Pass Book. What is the effect on the Pass Book balance?', 'Pass Book balance is understated by Rs 12,400', 'Cash Book balance is understated by Rs 6,200', 'Pass Book balance is overstated by Rs 6,200', 'Pass Book balance is understated by Rs 6,200', 'd', 2, 5, 'The bank subtracted Rs 6,200 one extra time.', 'Because the bank debited the Rs 6,200 payment twice instead of once, an extra deduction of Rs 6,200 was made from the customer''s account, causing the Pass Book balance to be understated by Rs 6,200.'),
        ('acc11-06-mcq-0050', 6, 'A business proprietor purchased furniture for Rs 25,000 and paid using a business debit card. The accountant omitted to enter this payment in the Cash Book. What is the effect on the Cash Book balance?', 'Cash Book balance remains overstated by Rs 25,000 compared to the actual bank balance', 'Cash Book balance is understated by Rs 25,000', 'Pass Book balance is overstated by Rs 25,000', 'Cash Book reflects an automatic overdraft of Rs 25,000', 'a', 2, 5, 'Money left the bank via the card swipe, but the Cash Book has not subtracted it.', 'A debit card payment is debited immediately by the bank in the Pass Book. Since it was omitted from the Cash Book, the Cash Book has not subtracted the Rs 25,000, leaving its balance higher (overstated) than the Pass Book by Rs 25,000.'),
        ('acc11-06-mcq-0051', 6, 'A cheque of Rs 1,500 issued to a supplier ABC & Co. by business debit card was recorded on the payment side of the Cash Book as Rs 150. What is the resulting error in the Cash Book balance?', 'Cash Book balance is understated by Rs 1,350', 'Cash Book balance is understated by Rs 150', 'Cash Book balance is overstated by Rs 1,350', 'Pass Book balance is overstated by Rs 1,350', 'c', 2, 5, 'Actual payment deducted by bank = Rs 1,500; payment deducted in Cash Book = only Rs 150.', 'The bank deducted the full Rs 1,500, but the Cash Book subtracted only Rs 150 (short deduction of Rs 1,350). By subtracting Rs 1,350 less than actual, the Cash Book balance remains overstated by Rs 1,350.'),
        ('acc11-06-mcq-0052', 6, 'A cheque of Rs 975 deposited into the bank was correctly credited by the bank, but entered on the debit side of the Cash Book as Rs 795. What is the effect on the Cash Book balance?', 'Cash Book balance is overstated by Rs 180', 'Cash Book balance is understated by Rs 180', 'Cash Book balance is understated by Rs 975', 'Pass Book balance is understated by Rs 180', 'b', 2, 5, 'Actual receipt = Rs 975; receipt entered in Cash Book = Rs 795. The debit was short by Rs 180.', 'The Cash Book recorded a receipt of Rs 795 instead of Rs 975 (975 - 795 = 180 short). Entering a smaller receipt causes the Cash Book balance to be understated by Rs 180 compared to the Pass Book.'),
        ('acc11-06-mcq-0053', 6, 'Why is the last day of the month generally selected for preparing a Bank Reconciliation Statement?', 'Because commercial banks close all business current accounts on that day', 'Because banking laws make reconciliation invalid if done mid-month', 'Because interest on fixed deposits is calculated strictly every 30 days', 'Because Cash Book balance and Pass Book balance are readily available on that date', 'd', 1, 3, 'Refer to Step 5 of the preparation procedure in Section 6.5.', 'Section 6.5 Step 5 explicitly states: ''The date for the preparation of the Bank Reconciliation Statement is generally chosen as the last day of the month because Cash Book balance and Pass Book balance are readily available on that date.'''),
        ('acc11-06-mcq-0054', 6, 'In the alternative Plus (+) and Minus (-) column method of preparing BRS, in which column is a ''Credit balance as per Pass Book'' entered?', 'Suspense column', 'Overdraft column only', 'Plus (+) column', 'Minus (-) column', 'c', 1, 3, 'In the Pass Book, a credit balance represents deposits belonging to the customer (favourable).', 'Under ''Alternate Presentation'' in Section 6.4: ''Credit balance of Pass Book is written in plus column. Debit balance of Pass Book or overdraft is written in minus column.'''),
        ('acc11-06-mcq-0055', 6, 'In the alternative Plus and Minus method, where is an ''Overdraft as per Cash Book'' (credit balance) recorded?', 'Minus (-) column', 'It is omitted until the end of the year', 'Plus (+) column', 'Both Plus and Minus columns equally', 'a', 1, 3, 'An overdraft in the Cash Book is a credit balance (unfavourable).', 'Section 6.4 specifies: ''Credit balance of Cash Book or overdraft is written in minus column. Debit balance of Cash Book is written in plus column.'''),
        ('acc11-06-mcq-0056', 6, 'According to the general rule of plus and minus in Section 6.5, when ''Bank Balance as per Cash Book'' is given as the starting point, what is the rule for adjustments?', 'Add all Pass Book entries; ignore Cash Book entries', 'Add debits in Cash Book or in Pass Book; Less credits in Cash Book or in Pass Book', 'Add credits in Cash Book or in Pass Book; Less debits in Cash Book or in Pass Book', 'Deduct credits and add debits', 'c', 2, 5, 'Review Step 8(a) of Section 6.5.', 'Section 6.5 Step 8(a) states: ''When balance as per Cash Book is given: Add credits in Cash Book or in Pass Book; Less debits in Cash Book or in Pass Book.'''),
        ('acc11-06-mcq-0057', 6, 'According to Section 6.5 Step 8(b), when ''Bank Balance as per Pass Book'' is given as the starting point, how are adjustments made?', 'Add only unpresented cheques and deduct direct collections', 'Add credits in Cash Book or in Pass Book; Less debits in Cash Book or in Pass Book', 'Add debits in Cash Book or in Pass Book; Less credits in Cash Book or in Pass Book', 'Add uncleared deposits and add direct payments', 'c', 2, 5, 'Pass Book balance behaves oppositely to Cash Book balance.', 'Section 6.5 Step 8(b) explicitly provides: ''When balance as per Pass Book is given: Add debits in Cash Book or in Pass Book; Less credits in Cash Book or in Pass Book.'''),
        ('acc11-06-mcq-0058', 6, 'When ''Overdraft as per Cash Book'' is the starting point in a BRS, what is the adjustment rule prescribed in Step 8(c)?', 'Add debits in Cash Book or in Pass Book; Less credits in Cash Book or in Pass Book', 'Deduct all bank charges and add interest allowed', 'Add unpresented cheques and deduct uncredited cheques', 'Add credits in Cash Book or in Pass Book; Less debits in Cash Book or in Pass Book', 'a', 2, 5, 'Overdraft as per Cash Book follows the opposite rule of normal Cash Book balance.', 'Section 6.5 Step 8(c) states: ''When overdraft as per Cash Book is given: Add debits in Cash Book or in Pass Book; Less credits in Cash Book or in Pass Book.'''),
        ('acc11-06-mcq-0059', 6, 'When ''Overdraft as per Pass Book'' is given as the starting point, what is the adjustment rule under Step 8(d)?', 'Deduct all dishonoured cheques and deduct bank charges', 'Add debits in Cash Book or in Pass Book; Less credits in Cash Book or in Pass Book', 'Add credits in Cash Book or in Pass Book; Less debits in Cash Book or in Pass Book', 'Add uncredited cheques and add standing order payments', 'c', 2, 5, 'Overdraft as per Pass Book follows the same rule as normal Cash Book balance.', 'Section 6.5 Step 8(d) states: ''When overdraft as per Pass Book is given: Add credits in Cash Book or in Pass Book; Less debits in Cash Book or in Pass Book.'''),
        ('acc11-06-mcq-0060', 6, 'When extracts of Cash Book and Pass Book are provided for a COMMON period (e.g., both for October 2018), which items must be considered to prepare the BRS?', 'All transactions from both books without exception', 'Only opening balances of both books', 'Only uncommon (unticked) items that appear in one book but not the other', 'Only common items appearing in both books', 'c', 2, 5, 'See Section 6.5(A): Items appearing in both books during the same month do not create differences.', 'Section 6.5(A) states: ''Entries appearing in both the books in the same period do not create any difference in the balance of the two books, thus are to be ignored. The items which appear in Cash Book but does not appear in Pass Book and vice versa will only create difference... These are entered in the Bank Reconciliation Statement.'''),
        ('acc11-06-mcq-0061', 6, 'When extracts of Cash Book and Pass Book are given for UNCOMMON / DIFFERENT periods (e.g., Cash Book for January and Pass Book for February), which items create discrepancies for the BRS as on 31st January?', 'Opening balances only', 'All transactions recorded in February Pass Book that do not appear in January Cash Book', 'Only uncommon items appearing solely in the January Cash Book', 'Only the common items appearing in both books', 'd', 2, 5, 'Refer to Section 6.5(B) and Exercise Q.4(9).', 'Section 6.5(B) explicitly states: ''When extract is given for uncommon period, consider only common items appearing in both the books. Common items only create discrepancies in the balance of the two books which are to be adjusted in the Bank Reconciliation Statement.'' (Because appearing in February proves they were pending on 31st January).'),
        ('acc11-06-mcq-0062', 6, 'The bank balance as per Cash Book is Rs 22,380 as on 30th April 2019. Cheques issued to Atul & Sons of Rs 2,600 were not presented for payment. Dividend of Rs 2,000 collected by the bank appeared in the Pass Book only. Cheques deposited but not collected amounted to Rs 13,900. Insurance premium paid by bank was Rs 6,500 and bank charges were Rs 800 (neither recorded in Cash Book). What is the Bank Balance as per Pass Book?', 'Rs 15,200', 'Rs 5,780', 'Rs 8,980', 'Rs 22,380', 'b', 3, 10, 'Review Illustration 1: Starting Cash Book balance 22,380 + additions (2,600 + 2,000) - deductions (13,900 + 6,500 + 800).', 'Starting balance = Rs 22,380. Add: Cheque unpresented (Rs 2,600) + Dividend collected (Rs 2,000) = Rs 4,600. Total = Rs 26,980. Less: Cheques uncollected (Rs 13,900) + Insurance premium (Rs 6,500) + Bank charges (Rs 800) = Rs 21,200. Bank balance as per Pass Book = 26,980 - 21,200 = Rs 5,780.'),
        ('acc11-06-mcq-0063', 6, 'On 31st January 2019, Cash Book bank balance was Rs 81,000. Cheques issued to Hemant (Rs 19,500), Pravin (Rs 9,900), and Vidya (Rs 27,000) were not presented for payment in January. Cheques deposited for Sangeeta (Rs 75,000) and Shruti (Rs 24,000) were cleared by the bank only in February. What was the Bank Balance as per Pass Book on 31st January 2019?', 'Rs 81,000', 'Rs 42,600', 'Rs 1,37,400', 'Rs 38,400', 'd', 3, 10, 'Review Illustration 2: Starting balance 81,000 + unpresented cheques 56,400 - uncleared cheques 99,000.', 'Starting balance as per Cash Book = Rs 81,000. Add unpresented cheques: 19,500 + 9,900 + 27,000 = Rs 56,400. Total = Rs 1,37,400. Less uncleared cheques: 75,000 + 24,000 = Rs 99,000. Balance as per Pass Book = 1,37,400 - 99,000 = Rs 38,400.'),
        ('acc11-06-mcq-0064', 6, 'The Cash Book shows a bank balance of Rs 57,400 as on 31st March 2019. Discrepancies identified include:
- Cheque of Rs 6,350 deposited but not collected
- Electricity bill paid by bank Rs 9,700 (not in Cash Book)
- Cheque issued Rs 15,100 not presented
- Interest on investment collected by bank Rs 8,800 (not in Cash Book)
- Bank charges Rs 650 debited in Pass Book
- Debtor Tanmay directly deposited Rs 12,000 into bank
What is the Bank balance as per Pass Book?', 'Rs 93,300', 'Rs 60,800', 'Rs 57,400', 'Rs 76,600', 'd', 3, 10, 'Review Illustration 3: Starting with 57,400; Add: 15,100 + 8,800 + 12,000 = 35,900; Less: 6,350 + 9,700 + 650 = 16,700.', 'Cash Book balance = Rs 57,400. Additions: Cheque unpresented (15,100) + Interest collected (8,800) + Direct deposit (12,000) = Rs 35,900. Total = Rs 93,300. Deductions: Cheque uncollected (6,350) + Electricity bill (9,700) + Bank charges (650) = Rs 16,700. Bank balance as per Pass Book = 93,300 - 16,700 = Rs 76,600.'),
        ('acc11-06-mcq-0065', 6, 'From the following details, find the Bank Balance as per Cash Book as on 30th June 2019:
- Balance as per Pass Book: Rs 14,000
- Cheques deposited Rs 16,400, but only Rs 6,400 cleared (Rs 10,000 uncleared)
- Cash withdrawn for personal use Rs 5,500 not in Cash Book
- Bank incidental charges Rs 350 debited in Pass Book only
- Cheque dishonoured debited in Pass Book only Rs 7,500
- Two cheques of Rs 8,900 and Rs 10,700 issued, but only Rs 8,900 presented (Rs 10,700 unpresented)
- Interest credited in Pass Book only Rs 425', 'Rs 14,000', 'Rs 37,350', 'Rs 26,225', 'Rs 15,100', 'c', 3, 10, 'Review Illustration 4: Pass Book balance 14,000 + Additions (10,000 + 5,500 + 350 + 7,500 = 23,350) - Deductions (10,700 + 425 = 11,125).', 'Pass Book balance = Rs 14,000. Add debits: Cheque uncleared (10,000) + Drawings omitted in Cash Book (5,500) + Incidental charges (350) + Cheque dishonoured (7,500) = Rs 23,350. Total = Rs 37,350. Less credits: Unpresented cheque (10,700) + Interest credited (425) = Rs 11,125. Balance as per Cash Book = 37,350 - 11,125 = Rs 26,225.'),
        ('acc11-06-mcq-0066', 6, 'Cash Book of Kunal showed an Overdraft of Rs 36,280 on 31st July 2019. The differences include:
- Direct deposit by customer Manish: Rs 18,700
- Cheque of Rs 18,900 deposited was debited in Cash Book as Rs 19,800 (excess debit Rs 900)
- Cheque issued for salary Rs 25,000 presented in August
- Cash withdrawn from ATM for office use Rs 20,000 not in Cash Book
- Debit side of Cash Book overcast by Rs 100
- Office rent paid by bank Rs 19,500
- Commission collected by bank Rs 3,750
What is the Bank Overdraft as per Pass Book?', 'Rs 47,450', 'Rs 29,330', 'Rs 76,780', 'Rs 36,280', 'b', 3, 10, 'Review Illustration 5: Overdraft as per Cash Book 36,280 + Add (900 + 20,000 + 100 + 19,500 = 40,500) - Less (18,700 + 25,000 + 3,750 = 47,450).', 'Starting Overdraft = Rs 36,280. Add items that increase overdraft: Excess debit in CB (900) + ATM withdrawal omitted (20,000) + Overcast of CB debit (100) + Office rent paid (19,500) = Rs 40,500. Total = Rs 76,780. Less items that decrease overdraft: Direct deposit (18,700) + Cheque unpresented (25,000) + Commission collected (3,750) = Rs 47,450. Overdraft as per Pass Book = 76,780 - 47,450 = Rs 29,330.'),
        ('acc11-06-mcq-0067', 6, 'Pass Book of Mr. Bhuvaneshwar shows an Overdraft of Rs 53,970 on 31st Oct 2018. Discrepancies:
- Wrong credit given by bank in Pass Book: Rs 17,070
- Cheques issued but not presented: Rs 40,000
- Annual subscription paid by bank not in Cash Book: Rs 6,000
- Payment side of Cash Book undercast: Rs 350
- Interest on overdraft charged: Rs 1,530
- Cash deposit of Rs 23,000 not recorded in Pass Book
What is the Bank Overdraft as per Cash Book?', 'Rs 30,880', 'Rs 53,970', 'Rs 1,11,040', 'Rs 80,160', 'd', 3, 10, 'Review Illustration 6: Starting Overdraft as per Pass Book 53,970 + Add (17,070 + 40,000 = 57,070) - Less (6,000 + 350 + 1,530 + 23,000 = 30,880).', 'Overdraft as per Pass Book = Rs 53,970. Add credits in Pass Book/Cash Book: Wrong credit in PB (17,070) + Unpresented cheques (40,000) = Rs 57,070. Total = Rs 1,11,040. Less debits: Subscription paid (6,000) + Undercast CB payment (350) + Interest on overdraft (1,530) + Deposit uncredited (23,000) = Rs 30,880. Overdraft as per Cash Book = 1,11,040 - 30,880 = Rs 80,160.'),
        ('acc11-06-mcq-0068', 6, 'Cash Book of Pankaj shows a credit balance (overdraft) of Rs 32,490 on 30th Sept 2018. Discrepancies:
- Cheques deposited Rs 36,000, only Rs 11,360 credited (Rs 24,640 uncleared)
- Cheques issued but unencashed: Rs 93,000
- Cheque book charges Rs 250 & SMS alert charges Rs 170 in Pass Book only
- Customer NEFT transfer Rs 1,23,200 entered in Cash Book as Rs 12,320 (Rs 1,10,880 under-recorded)
- Receipt side of Pass Book undercast by Rs 1,000
- Dividend collected by bank: Rs 12,500
What is the final bank position as per Pass Book?', 'Overdraft of Rs 58,550', 'Favourable Bank balance of Rs 32,490', 'Overdraft of Rs 1,57,830', 'Favourable Bank balance of Rs 1,57,830', 'd', 3, 10, 'Review Illustration 8: Overdraft 32,490 + Additions (26,060) = 58,550. Deductions = 93,000 + 1,10,880 + 12,500 = 2,16,380. Because deductions exceed the overdraft, it becomes a positive credit balance.', 'Starting Overdraft as per Cash Book = Rs 32,490. Add items increasing overdraft: Uncleared cheques (24,640) + Cheque book charges (250) + SMS charges (170) + Undercast PB receipt (1,000) = Rs 26,060. Total minus items = Rs 58,550. Less items reducing overdraft: Unpresented cheques (93,000) + Excess NEFT receipt (1,10,880) + Dividend (12,500) = Rs 2,16,380. Net result = 58,550 - 2,16,380 = - Rs 1,57,830. A negative result converts overdraft into a favourable Bank Balance as per Pass Book of Rs 1,57,830.'),
        ('acc11-06-mcq-0069', 6, 'Bank Pass Book of Mr. Ravi showed a credit balance of Rs 16,700 on 31st March 2018. Discrepancies:
- Cheques deposited Rs 27,000, only Rs 23,000 credited (Rs 4,000 uncleared)
- Discounted Bill Receivable dishonoured: Rs 11,700
- Pass Book debit side overcast: Rs 300
- Savings cash Rs 8,500 drawn shown under current account in Cash Book
- Cheques issued Rs 40,500, only Rs 1,500 presented (Rs 39,000 unpresented)
- Insurance premium Rs 14,400 entered twice in Cash Book
- Interest allowed by bank Rs 800 in Pass Book only
What is the Bank Overdraft as per Cash Book?', 'Rs 16,700', 'Rs 30,000', 'Rs 62,700', 'Rs 32,700', 'b', 3, 10, 'Review Illustration 9: Balance as per Pass Book 16,700 + Additions (4,000 + 11,700 + 300 = 16,000) = 32,700. Deductions (8,500 + 39,000 + 14,400 + 800 = 62,700). Difference = 32,700 - 62,700 = -30,000.', 'Pass Book balance = Rs 16,700. Add debits in PB/CB: Uncleared cheques (4,000) + Dishonoured bill (11,700) + Overcast PB debit (300) = Rs 16,000. Total = Rs 32,700. Less credits: Savings withdrawal in CB (8,500) + Unpresented cheques (39,000) + Duplicate insurance debit in CB (14,400) + Interest allowed (800) = Rs 62,700. Net result = 32,700 - 62,700 = - Rs 30,000. Negative answer converts favourable balance into Bank Overdraft as per Cash Book of Rs 30,000.'),
        ('acc11-06-mcq-0070', 6, 'What is the primary definition and concept of Vendor Reconciliation (reconciliation of debtors and creditors)?', 'Verifying the physical inventory count in the vendor''s warehouse', 'Verifying the completeness and accuracy of accounting records by comparing the debtor''s ledger in our books with our ledger in the debtor''s books to identify and fix errors', 'Reconciling bank accounts with currency reserves held by foreign suppliers', 'Negotiating new credit periods and cash discounts with trade associations', 'b', 1, 3, 'Read the opening paragraph under ''Reconciliation of Debtors and Creditors'' on page 202.', 'The text explains: ''Reconciliation helps us to identify and fix accounting errors. Reconciliation is carried out to verify the completeness and accuracy of a particular part of accounting records by comparing it with another record. Reconciliation Statement can also be prepared for vendor reconciliation i.e. reconciliation of debtors and creditors. Debtors represent money owed to us and creditors represent money owed by us. Here we compare debtor''s ledger in our books with our ledger in the debtor''s book and reconcile the differences if any.'''),
        ('acc11-06-mcq-0071', 6, 'What is the precise procedural sequence followed for Reconciliation of Debtors and Creditors as detailed in Section 6.5?', 'Prepare reconciliation statement -> Group differences -> Request debtor''s ledger -> File a recovery lawsuit -> Send demand notice', 'Sum all invoices -> Deduct cash receipts -> Post the net figure to capital reserve', 'Write off unmatched items to bad debts -> Inform bank manager -> Close debtor''s ledger account', 'Request counterparty ledger -> Prepare our ledger in Excel -> Copy-paste into one Excel file -> Compare and match entries -> List non-matching items -> Group differences -> Prepare reconciliation statement', 'd', 2, 5, 'Review the 7 numbered steps on page 202 under ''Procedure for Reconciliation of Debtors and Creditors''.', 'The chapter lists the 7 steps: 1. Request debtor to give our ledger account in their books, 2. Prepare debtor''s ledger in Excel, 3. Copy-paste both in one Excel file, 4. Compare and match entries, 5. Prepare list for non-matching entries, 6. Group similar differences and give headings, 7. Prepare vendor reconciliation statement. The correct option matches this exact chronological workflow.'),
        ('acc11-06-mcq-0072', 6, 'In financial terms as stated in the chapter, what do ''Debtors'' and ''Creditors'' represent respectively?', 'Debtors represent money owed by us; Creditors represent money owed to us', 'Debtors represent long-term bank loans; Creditors represent cash deposited with banks', 'Debtors represent statutory tax obligations; Creditors represent prepaid expenses', 'Debtors represent money owed to us; Creditors represent money owed by us', 'd', 1, 3, 'Check the exact sentence under Section 6.5 on page 202 defining both terms.', 'The chapter explicitly defines: ''Debtors represent money owed to us and creditors represent money owed by us.'' The other options reverse these fundamental roles or misclassify them as loans or taxes.'),
        ('acc11-06-mcq-0073', 6, 'A business issued a cheque of Rs 20,000 to a creditor, but only Rs 8,000 was presented to the bank before month-end. When preparing BRS starting with ''Bank balance as per Cash Book'', how much is added?', 'Rs 12,000', 'Rs 8,000', 'Rs 20,000', 'Rs 28,000', 'a', 2, 5, 'Only the unpresented portion causes a disagreement between the two books.', 'Out of Rs 20,000 issued, Rs 8,000 was presented and cleared in both books. Only the unpresented portion of Rs 12,000 (20,000 - 8,000) causes a difference, and is added to the Cash Book balance.'),
        ('acc11-06-mcq-0074', 6, 'Cheques sent to bank for collection totaled Rs 2,00,000, out of which cheques of Rs 80,000 only were credited by the bank during the month. When reconciling starting from ''Bank balance as per Cash Book'', what amount should be deducted?', 'Rs 2,80,000', 'Rs 2,00,000', 'Rs 1,20,000', 'Rs 80,000', 'c', 2, 5, 'Deduct only the uncredited portion that has not yet appeared in the Pass Book.', 'Total deposited = Rs 2,00,000. Credited by bank = Rs 80,000. The amount not yet credited is Rs 1,20,000 (2,00,000 - 80,000). Starting from Cash Book balance, uncleared cheques of Rs 1,20,000 must be deducted.'),
        ('acc11-06-mcq-0075', 6, 'A customer''s debtor directly deposited Rs 1,500 into the bank account, but the accountant mistakenly recorded the transaction in the CASH column of the Cash Book. How should this be treated when reconciling starting from ''Overdraft as per Cash Book''?', 'It is deducted from the overdraft as a credit not entered in the Cash Book bank column', 'It is added to the overdraft because it was recorded in the Cash Book', 'It is ignored completely because the cash column was already debited', 'It is treated as a dishonoured cheque and debited to the debtor', 'a', 3, 10, 'Look at Practical Problem 9 Item 7: The bank column in the Cash Book omitted the deposit, so the bank received funds that reduce the overdraft.', 'Recording the receipt in the cash column means the bank column of the Cash Book has no record of the Rs 1,500 deposit. The bank credited it in the Pass Book, reducing the overdraft. When starting from Overdraft as per Cash Book, credits in the Pass Book reduce the overdraft and must be deducted (Less item).'),
        ('acc11-06-mcq-0076', 6, 'Under standing instructions, the bank transferred Rs 2,500 from the business current account to the personal savings account of the proprietor, but no entry was made in the Cash Book. How is this treated when reconciling starting from ''Overdraft as per Cash Book''?', 'Ignored because it represents proprietor''s drawings', 'Multiplied by two and subtracted', 'Deducted from the overdraft', 'Added to the overdraft', 'd', 3, 10, 'The bank debited the current account for Rs 2,500, increasing the overdraft at the bank.', 'The bank transfer is a withdrawal (debit) from the current account, increasing the bank overdraft. The Cash Book has not recorded this payment. Starting with Overdraft as per Cash Book, debits in the Pass Book must be ADDED to arrive at the Pass Book overdraft.'),
        ('acc11-06-mcq-0077', 6, 'A Bill of Exchange for Rs 3,500 discounted with the bank in December 2018 returned dishonoured in January 2019. When preparing the Bank Reconciliation Statement as on 31st December 2018, how should this bill be treated?', 'It will NOT appear in the December 2018 BRS because the dishonour occurred after 31st December 2018', 'It must be deducted as an unpresented cheque', 'It must be added to both Cash Book and Pass Book balances', 'It must be debited to the Pass Book in the December BRS', 'a', 3, 10, 'Look at Practical Problem 10 Item 5: Check the exact date of dishonour relative to the reconciliation date.', 'On 31st December 2018, the bill had not yet been dishonoured (it was dishonoured in January 2019). As on 31st December 2018, neither the bank nor the Cash Book had any entry for dishonour, so no discrepancy existed on that date.'),
        ('acc11-06-mcq-0078', 6, 'In Exercise Q.2, what single accounting term is defined as: ''Excess of bank deposits over withdrawals by businessman in bank current account''?', 'Bank Balance (Favourable Balance)', 'Bank Overdraft', 'Cash Credit', 'Capital Reserve', 'a', 1, 3, 'When deposits exceed withdrawals, the customer has positive funds in the bank.', 'Exercise Q.2(10) defines: ''Excess of bank deposits over withdrawals by businessman in bank current account'' as Bank Balance (or Favourable Bank Balance). When withdrawals exceed deposits, it is an overdraft.'),
        ('acc11-06-mcq-0079', 6, 'In Exercise Q.4, what happens when an entry is debited in the Cash Book?', 'It cancels previous receipts', 'It increases the cash/bank balance', 'It creates an automatic overdraft', 'It decreases the cash/bank balance', 'b', 1, 3, 'Cash Book is an asset account: debits represent receipts.', 'Exercise Q.4(4) states: ''Debiting an entry in Cash Book increases cash balance.'' (Since Cash Book is an asset account where receipts are debited).'),
        ('acc11-06-mcq-0080', 6, 'Which type of bank account holder is granted the ''Bank Overdraft'' facility by commercial banks?', 'Fixed deposit account holder', 'Current account holder', 'Recurring deposit account holder', 'Savings account holder', 'b', 1, 3, 'Refer to Exercise Q.4(7) and Section 6.1(4).', 'Exercise Q.4(7) states: ''Bank gives overdraft facility to Current account holder.'' Overdraft facilities are not provided on standard savings or recurring accounts.'),
        ('acc11-06-mcq-0081', 6, 'Payments credited in the Cash Book are recorded on which side of the Bank Pass Book?', 'Entered in the particulars column only', 'Debited in Pass Book', 'Credited in Pass Book', 'Ignored in Pass Book', 'b', 1, 3, 'Look at Exercise Q.5(1): ''Payments credited in Cash Book are _____ in Pass Book.''', 'Payments credited in the Cash Book represent withdrawals from the bank account. When the bank clears and pays these amounts, it debits the customer''s account in the Pass Book.'),
        ('acc11-06-mcq-0082', 6, 'While preparing a Bank Reconciliation Statement, which specific column of the Cash Book is considered?', 'Bank column only', 'Both Cash and Bank columns combined', 'Discount column only', 'Cash column only', 'a', 1, 3, 'Exercise Q.5(2): ''While preparing Bank Reconciliation Statement only _____ column of Cash Book is considered.''', 'BRS specifically reconciles banking transactions between the bank column of the Cash Book and the Pass Book. The cash and discount columns are excluded.'),
        ('acc11-06-mcq-0083', 6, 'When a cheque is issued to a creditor, in which book does the entry appear FIRST?', 'Cash Book', 'Bank Advice', 'Pass Book', 'Sales Day Book', 'a', 1, 3, 'Exercise Q.5(3): ''Cheques issued to creditors appear first in _____ book.''', 'As soon as a businessman writes and signs a cheque to a creditor, it is immediately entered on the credit side of the Cash Book. It appears in the Pass Book only later when the creditor presents it for clearing.'),
        ('acc11-06-mcq-0084', 6, 'Interest on overdraft charged by the bank is entered on which side of the Bank Pass Book?', 'Suspended in Pass Book', 'Posted to counterfoil', 'Credited in Pass Book', 'Debited in Pass Book', 'd', 1, 3, 'Exercise Q.5(7): ''Interest on overdraft charged by bank is _____ in Pass Book.''', 'Interest on overdraft is an expense/charge imposed by the bank on the customer, which increases the debt owed to the bank. The bank enters this by debiting the customer''s account in the Pass Book.'),
        ('acc11-07-mcq-0001', 7, 'The term ''depreciation'' is derived from which Latin word?', 'Depretium', 'Damnum', 'Diminutio', 'Debitum', 'a', 1, 3, 'Look for the Latin root meaning ''reduction''.', 'According to the chapter, the word depreciation is derived from the Latin word ''Depretium'', which means reduction.'),
        ('acc11-07-mcq-0002', 7, 'What is the literal meaning of the Latin root word ''Depretium''?', 'Valuation', 'Reduction', 'Appreciation', 'Division', 'b', 1, 3, 'It denotes a fall or decline in monetary value.', 'The chapter explicitly states that the Latin word ''Depretium'' means reduction.'),
        ('acc11-07-mcq-0003', 7, 'Why does a business concern acquire fixed assets for its trading activities?', 'With the intention of immediate resale at profit', 'To convert them directly into liquid cash within a year', 'For permanent use in the business and not for resale', 'Exclusively to distribute them among partners', 'c', 1, 3, 'Consider whether fixed assets are bought for continuous operational utility or trading stock.', 'Fixed assets are purchased for business with an intention of permanent use in trading activity and not for resale.'),
        ('acc11-07-mcq-0004', 7, 'The purchase of a fixed asset represents which type of expenditure?', 'Recurring revenue expenditure', 'Operating loss', 'Deferred tax expense', 'Capital expenditure', 'd', 1, 3, 'It is a long-term investment, not a recurring daily expense.', 'The text states that the purchase of an asset is a capital expenditure and not a recurring expenditure.'),
        ('acc11-07-mcq-0005', 7, 'What is the accounting process of spreading the cost of fixed assets over their useful life termed as?', 'Depreciation', 'Amortisation of capital', 'Asset revaluation', 'Capital budgeting', 'a', 1, 3, 'It refers to allocating the asset''s cost across the periods benefitting from its use.', 'The process of spreading the cost of fixed assets over a number of years during their useful life is termed ''Depreciation''.'),
        ('acc11-07-mcq-0006', 7, 'Which of the following fixed assets is never depreciated because its area neither increases nor decreases and its value often appreciates?', 'Building', 'Land', 'Machinery', 'Office Furniture', 'b', 1, 3, 'Think of natural surface property that does not wear out with time.', 'The chapter notes that the working life of all fixed assets decreases except Land; Land is never depreciated and many a times it is appreciated.'),
        ('acc11-07-mcq-0007', 7, 'Under accounting principles, when must depreciation be charged by a business concern?', 'Only when the firm generates sufficient net profit', 'Only when the market value drops below 50% of cost', 'Every year whether the business earns a profit or suffers a loss', 'Only in years when new replacement assets are purchased', 'c', 1, 3, 'Depreciation is an unavoidable operational cost regardless of business performance.', 'Depreciation is charged every year whether the business concern is earning profit or suffering a loss, because true financial position cannot be shown without it.'),
        ('acc11-07-mcq-0008', 7, 'Who defined depreciation as ''the gradual decrease in the value of an asset from any cause''?', 'William Pickles', 'R.G. Williams', 'The Institute of Chartered Accountants of India', 'R.N. Carter', 'd', 1, 3, 'This author''s concise definition mentions gradual decrease from ''any cause''.', 'According to the textbook, R.N. Carter defined depreciation as ''the gradual decrease in the value of an asset from any cause''.'),
        ('acc11-07-mcq-0009', 7, 'According to R.G. Williams, how is depreciation defined?', 'A gradual deterioration in the value due to use', 'Allocation of depreciable amount over useful life', 'Permanent and continuing diminution in quality, quantity or value', 'Wearing out arising exclusively from market price changes', 'a', 1, 3, 'This definition specifically links deterioration directly to ''use''.', 'R.G. Williams defines depreciation as ''a gradual deterioration in the value due to use''.'),
        ('acc11-07-mcq-0010', 7, '''Depreciation may be defined as permanent and continuing diminution in the quality, quantity or the value of an asset.'' Who gave this definition?', 'R.N. Carter', 'William Pickles', 'ICAI', 'R.G. Williams', 'b', 1, 3, 'The author focuses on diminution in ''quality, quantity or value''.', 'William Pickles defined depreciation as ''permanent and continuing diminution in the quality, quantity or the value of an asset''.'),
        ('acc11-07-mcq-0011', 7, 'How does The Institute of Chartered Accountants of India (ICAI) describe depreciation?', 'Periodic reserve set aside solely for future expansion', 'Reduction in physical count of stock items due to market changes', 'A measure of wearing out, consumption or other loss of value arising from use, effluxion of time or obsolescence', 'A write-off allowed only when an asset is damaged by calamities', 'c', 2, 5, 'Look for the formal statement highlighting use, effluxion of time, and obsolescence.', 'ICAI defines depreciation as ''A measure of the wearing out, consumption or other loss of a value of a depreciable asset arising from use, effluxion of time or obsolescence through technology and market changes.'''),
        ('acc11-07-mcq-0012', 7, 'According to the International Accounting Standard Committee (IASC), depreciation is charged to income:', 'Only at the time of final asset disposal', 'Only after obtaining tax department pre-approval', 'Exclusively through a direct debit to the Capital Account', 'Either directly or indirectly for the accounting period', 'd', 2, 5, 'Check how the IASC defines the allocation of the depreciable amount to income.', 'The IASC defines depreciation as the allocation of the depreciable amount over useful life, charged to income ''either directly or indirectly''.'),
        ('acc11-07-mcq-0013', 7, 'Which cause of depreciation describes the physical deterioration resulting directly from actual operation or constant usage?', 'Normal and Natural Wear and Tear', 'Obsolescence', 'Depletion', 'Effluxion of time', 'a', 1, 3, 'More the use of an asset, more is this type of wear.', 'Normal and Natural Wear and Tear is caused by actual use in the business; more the use of an asset, more the wear and tear.'),
        ('acc11-07-mcq-0014', 7, 'Certain assets like Patents, Trademarks, Copyrights, and Leases lose value even if they are not put to active use. What is this cause called?', 'Depletion', 'Passage of Time (Effluxion of Time)', 'Physical exhaustion', 'Accidental damage', 'b', 2, 5, 'Their legal or contractual lifespan expires as days and years roll on.', 'Fixed assets like Patents, Trademarks, Copyrights, and Leases depreciate due to passage (effluxion) of time, even if not actively used.'),
        ('acc11-07-mcq-0015', 7, 'When an existing asset becomes out-dated due to technological development or improved production techniques, the cause of its value reduction is known as:', 'Depletion', 'Impairment', 'Obsolescence', 'Fluctuation', 'c', 1, 3, 'Think of older computers or television models replaced by modern versions.', 'Obsolescence occurs when technological development or changes in production techniques make existing assets out-dated (e.g., computers, TVs).'),
        ('acc11-07-mcq-0016', 7, 'What term refers to the reduction in value of wasting assets such as mines, quarries, oil-wells, and forests due to continuous extraction?', 'Amortisation', 'Wear and tear', 'Obsolescence', 'Depletion', 'd', 1, 3, 'The word literally means ''to empty''.', '''To deplete means to empty.'' Depletion is the cause of decrease in value of wasting assets like mines, quarries, and oil-wells.'),
        ('acc11-07-mcq-0017', 7, 'Sudden damage to or loss of fixed assets caused by earthquakes, floods, fire, or cyclones is accounted for under:', 'Natural Calamities / Impairment of an Asset', 'Depletion of wasting assets', 'Effluxion of legal rights', 'Normal operational attrition', 'a', 1, 3, 'These are unpredicted environmental or catastrophic events.', 'The text identifies Natural Calamities/Impairment (storms, earthquakes, fire, floods, accidents) as a cause of reduction in asset value.'),
        ('acc11-07-mcq-0018', 7, 'When the release of iPhone 8 caused a drop in the utility and market value of iPhone 7, which cause of depreciation does this exemplify?', 'Depletion', 'Invention', 'Passage of Time', 'Natural wear and tear', 'b', 2, 5, 'The textbook specifically links this example to the arrival of newly invented machines/models.', 'Under ''Invention'', the text notes that when new machines are invented, earlier assets lose utility and value, e.g., iPhone 8 reducing the value of iPhone 7.'),
        ('acc11-07-mcq-0019', 7, 'When the market value of an asset falls below its cost due to prevailing economic conditions, it leads to depreciation through which factor?', 'Legal expiration', 'Depletion', 'Market Value changes', 'Physical obsolescence', 'c', 1, 3, 'Prevailing supply and demand conditions alter current price.', 'Market Value changes according to prevailing conditions; when market value decreases below cost, it causes depreciation.'),
        ('acc11-07-mcq-0020', 7, 'In Book-Keeping, Depreciation Account is classified as which type of account?', 'Real Account', 'Personal Account', 'Representative Personal Account', 'Nominal Account', 'd', 1, 3, 'It represents an expense or loss to the business.', 'The textbook explicitly states: ''Depreciation is Cost/Loss to the business. It is a non-cash expenditure. It is a Nominal Account.'''),
        ('acc11-07-mcq-0021', 7, 'Why is depreciation termed a ''non-cash expenditure''?', 'It involves an internal accounting write-off without an immediate outflow of cash', 'It is paid exclusively via promissory notes', 'It can only be settled by issuing equity shares', 'It is reimbursed completely by the government', 'a', 2, 5, 'No money leaves the firm''s bank account when depreciation is booked.', 'Depreciation is an internal book entry representing cost/loss; no physical cash is paid to any external party when charging it.'),
        ('acc11-07-mcq-0022', 7, 'What will happen to the financial statements if depreciation is NOT charged on fixed assets?', 'Assets will be undervalued and profits will be understated', 'Assets will be overvalued and the true and fair financial position cannot be ascertained', 'Liabilities will be overstated and cash balance will decrease', 'Tax liability to the government will automatically become zero', 'b', 2, 5, 'Think about what happens to balance sheet asset values if wear and tear is ignored.', 'The chapter highlights that if depreciation is not provided, assets will be overvalued and we cannot find out the true and fair financial position of the business.'),
        ('acc11-07-mcq-0023', 7, 'How does charging depreciation help a business in its dealings with the Government?', 'It eliminates the requirement of filing annual tax returns', 'It grants complete exemption from Goods and Services Tax', 'It enables the business to compute and pay the correct amount of tax', 'It guarantees an unconditional cash subsidy from the state', 'c', 1, 3, 'Depreciation is an allowable expense that ensures profits are accurately stated for tax purposes.', 'One of the key needs for depreciation listed in the textbook is: ''It enables the business to compute and pay correct amount of tax to the Government.'''),
        ('acc11-07-mcq-0024', 7, 'Why is it essential to calculate depreciation and provide equivalent funds each year?', 'To pay higher dividends to shareholders during early years', 'To convert the fixed asset into intangible goodwill', 'To artificially inflate the net profit of the enterprise', 'So that at the end of its useful life, the asset can be easily replaced', 'd', 2, 5, 'Old machinery eventually wears out and must be substituted with new equipment.', 'Depreciation ensures the business makes provision for replacement of old assets so that sufficient funds are available when their working life ends.'),
        ('acc11-07-mcq-0025', 7, 'Which of the following represents the three basic factors considered while computing depreciation?', 'Cost of asset, Estimated economic life, and Estimated terminal value', 'Market value, Bank balance, and Scrap value', 'Sales turnover, Inflation rate, and Historical cost', 'Purchase price, Tax slab, and Insurance premium', 'a', 1, 3, 'Check the factor chart in section 7.2 of the chapter.', 'The three factors are: (1) Cost of Asset, (2) Estimated Economic Life of Asset, and (3) Estimated Terminal Value.'),
        ('acc11-07-mcq-0026', 7, 'Which of the following expenditures is NOT included in the Original Cost of a fixed asset?', 'Transit insurance and custom duty', 'Routine annual maintenance and operating fuel incurred after operations begin', 'Wages paid for fixation/installation of the machine', 'Amount spent on reconditioning a second-hand asset before use', 'b', 2, 5, 'Only incidental costs incurred up to bringing the asset into working condition are capitalised.', 'Original Cost includes purchase price plus installation/incidental charges (freight, custom duty, transit insurance, installation wages, reconditioning). Regular maintenance after operations start is a revenue expense.'),
        ('acc11-07-mcq-0027', 7, 'What is meant by the ''Useful or Estimated Economic Life'' of an asset?', 'The physical duration until the metal completely corrodes', 'The statutory minimum warranty period provided by the manufacturer', 'The period over which the business expects to obtain useful service and earn profit from its use', 'The time required to settle the loan taken to purchase the asset', 'c', 1, 3, 'It relates to economic utility rather than mere physical existence.', 'Useful life means the expected period or working life in years during which the business expects to get useful service from the asset and earn profit.'),
        ('acc11-07-mcq-0028', 7, 'How is the Estimated Terminal or Scrap Value of an asset accurately calculated?', 'Sale value of the asset plus subsequent replacement cost', 'Insured value agreed upon at the date of purchase', 'Cost of the asset minus all accumulated interest charges', 'Realisable net value at the end of its life, after deducting disposal and removal costs', 'd', 2, 5, 'Net proceeds realised upon discarding the equipment at the end of its useful life.', 'Scrap Value is the net realisable value of the asset at the end of its economic life, calculated after deducting disposal and removal costs from the sale value.'),
        ('acc11-07-mcq-0029', 7, 'The Straight Line Method of depreciation is also known as:', 'Fixed Instalment Method or Original Cost Method', 'Reducing Balance Method or Annuity Method', 'Revaluation Method or Machine Hour Method', 'Depreciation Fund Method or Sinking Fund Method', 'a', 1, 3, 'Under this method, the annual instalment remains constant and is based on initial cost.', 'The Straight Line Method is synonymously known as the ''Fixed Instalment Method'' or ''Original Cost Method''.'),
        ('acc11-07-mcq-0030', 7, 'Which formula correctly computes annual depreciation under the Fixed Instalment Method?', '(Original Cost + Scrap Value) / Estimated Life', '(Original Cost - Scrap Value) / Estimated Life (in years)', '(Original Cost - Scrap Value) × Estimated Life', 'Original Cost / (Scrap Value × Estimated Life)', 'b', 1, 3, 'Depreciable amount (Cost less scrap) is divided by useful years.', 'The chapter gives the formula: Depreciation (p.a.) = (Original Cost - Scrap Value) / Estimated life of the asset (in years).'),
        ('acc11-07-mcq-0031', 7, 'If the annual amount of depreciation under the Straight Line Method is plotted on a graph against years, what does the curve show?', 'A line sloping upward from left to right', 'A line sloping downward towards the X-axis', 'A line parallel to the X-axis', 'A bell-shaped normal distribution curve', 'c', 1, 3, 'The depreciation amount is constant each year.', 'Since the annual depreciation amount remains constant every year under SLM, joining the points on a graph reveals a line parallel to the X-axis.'),
        ('acc11-07-mcq-0032', 7, 'Under which method of depreciation can the book value of an asset be reduced exactly to zero (or to its scrap value)?', 'Written Down Value Method', 'Diminishing Balance Method', 'Reducing Balance Method', 'Fixed Instalment Method', 'd', 1, 3, 'Equal amounts are written off each year against the original cost.', 'Under the Fixed Instalment (Straight Line) Method, the asset account can be reduced to nil (zero) or to its scrap value at the end of its life.'),
        ('acc11-07-mcq-0033', 7, 'Under the Written Down Value Method, depreciation is calculated each year on:', 'The balance / book value brought forward on the opening date of each year', 'The original cost of the asset throughout its life', 'The estimated future replacement cost', 'The market scrap value assessed at each year-end', 'a', 1, 3, 'It is calculated on the reducing opening balance of the asset.', 'Under WDV, depreciation is calculated at a specific percentage on the opening balance of the asset brought forward from the previous year.'),
        ('acc11-07-mcq-0034', 7, 'How does the annual depreciation charge behave over the life of an asset under the Written Down Value Method?', 'It remains constant every year', 'It goes on decreasing gradually each year', 'It increases gradually year after year', 'It fluctuates randomly depending on gross sales', 'b', 1, 3, 'As the base value shrinks, the percentage yields a smaller figure.', 'Because the opening book balance decreases every year, the amount of depreciation charged under WDV goes on decreasing gradually.'),
        ('acc11-07-mcq-0035', 7, 'What is the shape of the depreciation curve on a graph under the Written Down Value Method?', 'Vertical line parallel to the Y-axis', 'Parallel to the X-axis', 'Slopes downward from left to right', 'Slopes upward from left to right', 'c', 1, 3, 'The annual depreciation amount drops with each passing year.', 'Under the Written Down Value Method, the annual depreciation amount declines over time, resulting in a curve that slopes downward from left to right.'),
        ('acc11-07-mcq-0036', 7, 'Can the book value of an asset ever reach absolute zero mathematically under the Written Down Value Method?', 'Yes, precisely at the end of the second year', 'Yes, whenever a loss is reported in Profit & Loss Account', 'Yes, when scrap value is zero', 'No, the value of the fixed asset cannot be reduced to zero under this method', 'd', 2, 5, 'A fixed percentage applied to a positive fractional balance will never produce zero.', 'Under the WDV method, calculating a percentage on a remaining balance can never mathematically reduce the book value to zero.'),
        ('acc11-07-mcq-0037', 7, 'Compared to the Written Down Value Method, reported profits in the earlier years under the Fixed Instalment Method are:', 'Higher', 'Lower', 'Identical in every year', 'Negative always', 'a', 2, 5, 'Under WDV, early depreciation charges are highest, reducing early reported profits.', 'As shown in the textbook comparison table: Under Fixed Instalment Method, profits are more during the earlier years than later years, whereas under WDV, profits are less during earlier years.'),
        ('acc11-07-mcq-0038', 7, 'Which depreciation method is recognized by Tax Authorities and Law?', 'Fixed Instalment Method', 'Written Down Value Method', 'Straight Line Method', 'Original Cost Method', 'b', 1, 3, 'Review the ''Recognition by Tax/Law'' row in the comparison table.', 'According to the comparative table in the chapter, the Written Down Value Method is recognized by Tax/Law, whereas the Fixed Instalment Method is not.'),
        ('acc11-07-mcq-0039', 7, 'Why is the Written Down Value Method considered more suitable for assets where repair charges increase in later years?', 'It guarantees zero repairs during the first five years', 'Repair charges are legally added back to capital under WDV', 'The combined burden of depreciation and repairs remains almost even over the asset''s life', 'It allows charging double depreciation when repairs occur', 'c', 2, 5, 'High depreciation + low repairs early on balances with low depreciation + high repairs later.', 'Under WDV, high depreciation in early years combines with low repairs, and lower depreciation in later years combines with higher repairs, keeping the total P&L charge equitable.'),
        ('acc11-07-mcq-0040', 7, 'When wages or incidental expenses are paid to erect and install a new machine, which account is debited?', 'Wages Account', 'Installation Expenses Account', 'Profit & Loss Account', 'Machinery Account (Asset Account)', 'd', 2, 5, 'Such expenses are capitalised as part of the asset''s cost.', 'Installation and incidental charges incurred to put an asset into operation are capital expenditure and debited directly to the Asset A/c (e.g., Machinery A/c).'),
        ('acc11-07-mcq-0041', 7, 'What is the correct journal entry to record annual depreciation charged on a fixed asset?', 'Debit Depreciation A/c; Credit Asset A/c', 'Debit Asset A/c; Credit Depreciation A/c', 'Debit Profit & Loss A/c; Credit Cash A/c', 'Debit Depreciation A/c; Credit Bank A/c', 'a', 1, 3, 'Depreciation is an expense (debit) and reduces the asset''s book value (credit).', 'The entry for charging depreciation is: Depreciation A/c Dr. To Asset A/c.'),
        ('acc11-07-mcq-0042', 7, 'At the end of the accounting year, the balance of Depreciation Account is transferred by which journal entry?', 'Debit Asset A/c; Credit Profit and Loss A/c', 'Debit Profit and Loss A/c; Credit Depreciation A/c', 'Debit Trading A/c; Credit Depreciation A/c', 'Debit Depreciation A/c; Credit Balance Sheet', 'b', 1, 3, 'Nominal accounts are closed to Profit and Loss at year end.', 'The transfer entry is: Profit and Loss A/c Dr. To Depreciation A/c.'),
        ('acc11-07-mcq-0043', 7, 'When a fixed asset is purchased on credit from a vendor, the journal entry is:', 'Debit Cash A/c; Credit Supplier''s A/c', 'Debit Purchases A/c; Credit Supplier''s A/c', 'Debit Asset A/c; Credit Supplier''s/Party''s A/c', 'Debit Supplier''s A/c; Credit Asset A/c', 'c', 1, 3, 'The asset comes into the business and the supplier becomes a creditor.', 'The journal entry for purchasing an asset on credit is: Asset A/c Dr. To Supplier''s/Party''s A/c.'),
        ('acc11-07-mcq-0044', 7, 'When an asset is sold exactly at its Written Down Value (Book Value), the credit entry is made to:', 'Sales A/c', 'Profit & Loss A/c', 'Depreciation A/c', 'Asset A/c', 'd', 1, 3, 'The asset is going out of the business.', 'When an asset is sold at book value, Bank A/c is debited and Asset A/c is credited.'),
        ('acc11-07-mcq-0045', 7, 'When a fixed asset is sold for an amount exceeding its Written Down Value, which account is credited for the gain?', 'Profit on Sale of Asset A/c', 'Loss on Sale of Asset A/c', 'Depreciation Fund A/c', 'General Reserve A/c', 'a', 2, 5, 'Income and gains are credited under nominal account rules.', 'The entry is Bank A/c Dr. To Asset A/c (WDV) To Profit on Sale of Asset A/c.'),
        ('acc11-07-mcq-0046', 7, 'Which journal entry is passed to transfer the profit on sale of an asset at the end of the period?', 'Debit Profit and Loss A/c; Credit Profit on Sale of Asset A/c', 'Debit Profit on Sale of Asset A/c; Credit Profit and Loss A/c', 'Debit Asset A/c; Credit Profit on Sale of Asset A/c', 'Debit Profit on Sale of Asset A/c; Credit Bank A/c', 'b', 2, 5, 'Close the credit balance of Profit on Sale into Profit and Loss Account.', 'To transfer the profit, Profit on Sale of Asset A/c is debited and Profit & Loss A/c is credited.'),
        ('acc11-07-mcq-0047', 7, 'When an asset is sold at a loss, the deficiency (WDV minus selling price) is debited to:', 'Profit on Sale of Asset A/c', 'Depreciation A/c', 'Loss on Sale of Asset A/c', 'Capital Reserve A/c', 'c', 2, 5, 'Losses and expenses are debited.', 'When sold at a loss, the entry is: Bank A/c Dr., Loss on Sale of Asset A/c Dr., To Asset A/c.'),
        ('acc11-07-mcq-0048', 7, 'Loss on sale of a fixed asset is ultimately transferred to:', 'Credit side of Profit & Loss A/c', 'Debit side of Manufacturing A/c', 'Credit side of Trading A/c', 'Debit side of Profit & Loss A/c', 'd', 2, 5, 'Expenses and losses appear on the debit side of the P&L Account.', 'The entry is Profit and Loss A/c Dr. To Loss on Sale of Asset A/c, transferring the loss to the debit of P&L.'),
        ('acc11-07-mcq-0049', 7, 'When an asset is purchased or sold mid-year, how should depreciation be calculated for that accounting year?', 'Proportionately for the specific period the asset was used in the business', 'Always charged for the full 12 months regardless of purchase date', 'Depreciation is waived completely for that entire year', 'Charged at double rate to compensate for mid-year acquisition', 'a', 2, 5, 'Review the note on time-basis / period of use.', 'The chapter emphasizes: ''At the time of calculation of depreciation amount, the period for which the asset is used in the business during the current Accounting year should be considered.'''),
        ('acc11-07-mcq-0050', 7, 'A machine costing ₹23,000 has an estimated useful life of 7 years and an estimated scrap value of ₹2,000. What is the annual depreciation under SLM?', '₹3,571 p.a.', '₹3,000 p.a.', '₹3,285 p.a.', '₹2,500 p.a.', 'b', 2, 5, 'Subtract scrap value from cost and divide by useful life.', 'Depreciation = (Original Cost - Scrap Value) / Life = (23,000 - 2,000) / 7 = 21,000 / 7 = ₹3,000 p.a.'),
        ('acc11-07-mcq-0051', 7, 'A machine costing ₹15,000 is purchased and installation charges of ₹3,000 are paid. Its estimated life is 10 years and scrap value is ₹2,000. What is the annual depreciation?', '₹1,800 p.a.', '₹1,300 p.a.', '₹1,600 p.a.', '₹1,500 p.a.', 'c', 2, 5, 'Total Cost = Purchase Price + Installation Charges.', 'Total Cost = 15,000 + 3,000 = ₹18,000. Depreciation = (18,000 - 2,000) / 10 = 16,000 / 10 = ₹1,600 p.a.'),
        ('acc11-07-mcq-0052', 7, 'If a computer costs ₹40,000 and depreciation is charged at 8% p.a., what is the annual depreciation amount?', '₹4,000', '₹3,600', '₹2,400', '₹3,200', 'd', 1, 3, 'Multiply cost by 8/100.', 'Depreciation = 40,000 × 8 / 100 = ₹3,200.'),
        ('acc11-07-mcq-0053', 7, 'Mr. X purchased furniture on 1st Oct 2015 for ₹2,80,000 and spent ₹20,000 on installation. He provides depreciation at 6% p.a. under SLM on 31st March 2016. What is the depreciation amount for 2015-16?', '₹9,000', '₹18,000', '₹8,400', '₹12,000', 'a', 2, 5, 'Total cost is ₹3,00,000, and the asset was used for 6 months (October to March).', 'Total Cost = 2,80,000 + 20,000 = ₹3,00,000. Annual depreciation = 3,00,000 × 6% = ₹18,000. For 6 months = 18,000 × 6/12 = ₹9,000.'),
        ('acc11-07-mcq-0054', 7, 'A machine was purchased on 1st Jan 2016 for ₹2,00,000. The firm writes off depreciation @ 10% p.a. on Reducing Balance Method on 31st March every year. What is the WDV of the machine as on 31st March 2017?', '₹1,80,000', '₹1,75,500', '₹1,71,000', '₹1,62,000', 'b', 3, 10, 'First year has 3 months of depreciation; second year has a full year on the remaining balance.', 'Year 1 (1-1-16 to 31-3-16, 3 mos): 2,00,000 × 10% × 3/12 = ₹5,000. WDV on 31-3-16 = 1,95,000. Year 2 (2016-17, 12 mos): 1,95,000 × 10% = ₹19,500. WDV on 31-3-17 = 1,95,000 - 19,500 = ₹1,75,500.'),
        ('acc11-07-mcq-0055', 7, 'A machine purchased on 1st April 2015 for ₹10,000 was sold on 1st July 2016 for ₹7,000. Depreciation is charged @ 10% p.a. on original cost on 31st March each year. What is the profit or loss on sale?', 'Profit of ₹1,750', 'Loss of ₹2,000', 'Loss of ₹1,750', 'Profit of ₹1,250', 'c', 3, 10, 'Calculate depreciation for 2015-16 (1 year = ₹1,000) and for 3 months in 2016-17 (₹250).', 'Depreciation to date of sale = 1,000 (1st year) + 250 (3 mos) = ₹1,250. WDV on 1-7-2016 = 10,000 - 1,250 = ₹8,750. Sale proceeds = ₹7,000. Loss on sale = 8,750 - 7,000 = ₹1,750.'),
        ('acc11-07-mcq-0056', 7, 'Prabhune & Sons made furniture for office use, spending ₹72,000 on materials and ₹32,000 on wages. Estimated life is 10 years and scrap value is ₹24,000. What is the annual depreciation?', '₹10,400 p.a.', '₹6,400 p.a.', '₹7,200 p.a.', '₹8,000 p.a.', 'd', 2, 5, 'Total cost = 72,000 + 32,000 = ₹1,04,000.', 'Total cost = ₹1,04,000. Annual Depreciation = (1,04,000 - 24,000) / 10 = 80,000 / 10 = ₹8,000 p.a.'),
        ('acc11-07-mcq-0057', 7, 'An asset costing ₹80,000 is depreciated at 10% p.a. under the Written Down Value Method. What are the depreciation amounts for the 1st year and 2nd year respectively?', '₹8,000 and ₹7,200', '₹8,000 and ₹8,000', '₹7,200 and ₹6,480', '₹8,000 and ₹6,480', 'a', 2, 5, 'First year is on ₹80,000; second year is on (80,000 - 8,000) = ₹72,000.', 'Year 1: 80,000 × 10% = ₹8,000 (WDV becomes ₹72,000). Year 2: 72,000 × 10% = ₹7,200.'),
        ('acc11-07-mcq-0058', 7, 'When calculating depreciation under the Straight Line Method formula, what effect does an increase in estimated residual (scrap) value have on annual depreciation?', 'It increases annual depreciation', 'It reduces annual depreciation', 'It has no mathematical effect on annual depreciation', 'It doubles the depreciation rate', 'b', 2, 5, 'Scrap value is subtracted from cost in the numerator.', 'Since formula is (Cost - Scrap Value) / Life, a higher scrap value reduces the depreciable amount, thereby decreasing the annual depreciation charge.'),
        ('acc11-07-mcq-0059', 7, 'Which of the following is listed in the chapter as one of the other methods of depreciation, even though not detailed in the syllabus?', 'Weighted Average Price Method', 'First-In-First-Out Method', 'Machine Hour Rate Method', 'Perpetual Inventory Method', 'c', 1, 3, 'Review the list of 7 methods in section 7.3.', 'Section 7.3 lists: Straight Line, WDV, Annuity, Depreciation Fund, Revaluation, Insurance Policy, and Machine Hour Rate Method.'),
        ('acc11-07-mcq-0060', 7, 'At the end of an accounting year, the credit balance entry ''By Balance c/d'' in an Asset Account represents:', 'The total cash collected from sales during the year', 'The scrap value realised on discarding old machines', 'The cumulative profit earned from using the asset', 'The written down value (closing book value) of the asset carried to the next year', 'd', 2, 5, 'It is the net balance brought down as opening balance on the first day of next year.', 'The closing balance (''By Balance c/d'') in the Asset Account represents its net book value (WDV) at year-end, which is carried forward into the following accounting period.'),
        ('acc11-08-mcq-0001', 8, 'What primary purpose does the preparation of a Trial Balance serve in bookkeeping?', 'To evaluate the operational efficiency and solvency of the business', 'To calculate the net profit or loss of the enterprise', 'To determine the exact market value of all enterprise assets', 'To check the arithmetical accuracy of transactions recorded and posted', 'd', 1, 3, 'Consider what mathematical or clerical check is performed after ledger balances are drawn.', 'A Trial Balance is prepared specifically to check the arithmetical accuracy of transactions recorded in a Journal, posted into the ledger, and balanced. Evaluating profit is done via the Profit and Loss Account.'),
        ('acc11-08-mcq-0002', 8, 'Why is the agreement of a Trial Balance considered only partial proof of accounting accuracy?', 'Because the Trial Balance does not take cash balances into consideration', 'Because it only records personal accounts and ignores nominal accounts', 'Because certain errors may still exist even if both sides of the Trial Balance tally', 'Because a Trial Balance is prepared before journal entries are finalized', 'c', 2, 5, 'Think about errors that do not affect the debit and credit equality.', 'Even if a Trial Balance agrees, there may still be errors such as errors of complete omission, principle, or compensating errors in the accounting records. Hence, agreement is only partial proof.'),
        ('acc11-08-mcq-0003', 8, 'According to the chapter, which of the following is an unavoidable reality in accounting despite shifting from manual to computerized systems?', 'Calculation of depreciation', 'Valuation of closing stock', 'Preparation of vouchers', 'Occurrence of errors in accounting records', 'd', 1, 3, 'Recall what the text notes about human input and system shifts in modern business.', 'The chapter highlights that even though many business units have shifted to computerized accounting, errors in accounting are unavoidable and must be located and rectified.'),
        ('acc11-08-mcq-0004', 8, 'Which of the following is NOT listed in the chapter as a primary reason for the occurrence of errors?', 'Lack of accounting knowledge', 'Incorrect arithmetical calculations', 'Fluctuations in market exchange rates', 'Wrong data collections and wrong recording', 'c', 1, 3, 'Identify the external economic factor rather than an internal bookkeeping clerical mistake.', 'The four reasons for errors listed in the chapter are: lack of accounting knowledge, wrong data collection, wrong recording, and incorrect arithmetical calculations. Market rate fluctuations are external economic changes, not bookkeeping errors.'),
        ('acc11-08-mcq-0005', 8, 'Rectification of errors is fundamentally necessary prior to finalizing financial statements in order to:', 'Artificially inflate gross profit to secure bank financing', 'Avoid making ledger postings into the nominal accounts', 'Eliminate the requirement of auditing books of accounts', 'Find out the real profit or loss and determine the accurate financial position', 'd', 1, 3, 'Look at the core objectives mentioned under the ''Need of Rectification'' section.', 'Errors must be located and rectified so that corrected figures are used to prepare the Profit & Loss Account (finding true profit/loss) and Balance Sheet (showing the true financial position).'),
        ('acc11-08-mcq-0006', 8, 'Which of the following represents the four broad categories of errors classified in the chapter?', 'Clerical errors, Systemic errors, Primary errors, and Secondary errors', 'Single entry errors, Double entry errors, Balance Sheet errors, and Profit errors', 'Internal errors, External errors, Valuation errors, and Estimation errors', 'Errors of Omission, Errors of Commission, Errors of Principle, and Compensating Errors', 'd', 1, 3, 'Focus on the classification diagram presented on page 249 of the chapter.', 'The textbook classifies errors into four main categories: Errors of Omission, Errors of Commission, Errors of Principle, and Compensating Errors.'),
        ('acc11-08-mcq-0007', 8, 'What is an Error of Omission?', 'Committing an arithmetical mistake in calculating compound interest', 'Recording a transaction on the correct side but in a wrong class of account', 'An error arising when a transaction is partially or completely omitted from being recorded', 'Posting an entry twice to both the debit and credit sides', 'c', 1, 3, 'Think of the root word ''omit''—forgetting to record either part or whole of a transaction.', 'An error of omission arises when a transaction is partially or completely omitted to be recorded in the books of accounts.'),
        ('acc11-08-mcq-0008', 8, 'Goods sold to Aditya on credit were completely omitted from the Sales Book. What impact will this error have on the Trial Balance?', 'The Trial Balance debit column will exceed the credit column by the sales amount', 'The Trial Balance credit column will exceed the debit column', 'The agreement of the Trial Balance will not be affected', 'The Trial Balance will fail to agree and require a Suspense Account', 'c', 2, 5, 'Consider whether any debit or credit entry was made in any ledger account.', 'In an error of complete omission, neither the debit entry nor the credit entry is posted. Because both sides are equally missing, the agreement of the Trial Balance is not affected.'),
        ('acc11-08-mcq-0009', 8, 'Goods sold to Aditya on credit were recorded in the Sales Book but not posted to Aditya''s Account. This is an example of:', 'Partial omission', 'Error of principle', 'Error of complete omission', 'Compensating error', 'a', 2, 5, 'Notice that one aspect of the transaction was processed while the other was omitted.', 'When a transaction is recorded in the subsidiary book (Sales Book) so Sales A/c is credited, but omitted from being posted to the customer''s personal account, it is a partial omission and affects the Trial Balance.'),
        ('acc11-08-mcq-0010', 8, 'Which of the following errors is classified as an Error of Commission?', 'Complete omission of credit purchases from the Purchase Book', 'Repairs to old building debited to Building Account', 'Wrong totalling or wrong balancing of ledger accounts', 'Wages paid for installation of machinery debited to Wages Account', 'c', 1, 3, 'Errors of commission are clerical mistakes involving recording, posting, casting, or carrying forward.', 'Errors of commission arise due to wrong entries, wrong posting, wrong totalling, wrong balancing, or wrong casting. Violating capital vs revenue distinctions is an error of principle.'),
        ('acc11-08-mcq-0011', 8, 'Goods purchased from Chaitanya for ₹850 were recorded as ₹580 in the Purchase Book. What is the effect of this error on the Trial Balance?', 'The Trial Balance will show an excess credit of ₹270', 'The Trial Balance will show an excess debit of ₹270', 'The Trial Balance will be out of balance by ₹850', 'It will not affect the agreement of the Trial Balance', 'd', 2, 5, 'Check what amount gets posted to both the Purchase Account and Chaitanya''s Account.', 'Because the wrong amount (₹580) was entered in the book of original entry (Purchase Book), the same amount is posted to both the debit of Purchase A/c and credit of Chaitanya''s A/c, leaving the Trial Balance in agreement.'),
        ('acc11-08-mcq-0012', 8, 'If the Purchase Book has been undercast by ₹500, how does it immediately affect the Trial Balance?', 'Trial Balance will still balance without any difference', 'Debit side of the Trial Balance will be more by ₹500', 'Credit side of the Trial Balance will be less by ₹500', 'Debit side of the Trial Balance will be less by ₹500', 'd', 2, 5, 'The total of the Purchase Book is posted to the debit of the Purchase Account.', 'Undercasting the Purchase Book means its periodic total is short by ₹500. This results in Purchase A/c being debited less by ₹500, decreasing the debit side of the Trial Balance by ₹500.'),
        ('acc11-08-mcq-0013', 8, 'When a Creditors Account in the ledger has been undercast by ₹700, what is the resulting effect on the Trial Balance?', 'Both debit and credit totals will increase by ₹700', 'Debit balance of Trial Balance will be less by ₹700', 'Credit balance of Trial Balance will be less by ₹700', 'Credit balance of Trial Balance will be more by ₹700', 'c', 2, 5, 'Creditors maintain a credit balance in the ledger.', 'Creditors account normally has a credit balance. If it is undercast by ₹700, its credit balance is reported short by ₹700, causing the credit total of the Trial Balance to be less by ₹700.'),
        ('acc11-08-mcq-0014', 8, 'The total of the Purchase Book of ₹1,500 is carried forward as ₹1,250 to the next page. What type of clerical error is this?', 'Error of complete omission', 'Compensating error', 'Error of principle', 'Error of carrying forward', 'd', 1, 3, 'Look at the specific sub-type of commission error where page totals are forwarded.', 'Carrying forward a total incorrectly from one page to the next (₹1,500 carried forward as ₹1,250) is specifically classified as an Error of Carrying Forward under errors of commission.'),
        ('acc11-08-mcq-0015', 8, 'Goods sold to Rohan for ₹900 were posted to the credit of Rohan''s Account instead of his debit side. What type of posting error has occurred?', 'Posting to the wrong side but correct account', 'Posting to the correct side but wrong account', 'Complete omission of posting', 'Posting twice in an account', 'a', 2, 5, 'Identify whether the account name was correct and what side received the entry.', 'Rohan''s account was correctly identified, but the amount was posted to the credit side instead of the debit side, which is ''Posting to the wrong side but correct account''.'),
        ('acc11-08-mcq-0016', 8, 'What is an Error of Principle?', 'Carrying forward an incorrect page balance in a subsidiary book', 'Recording transactions without following accounting principles and rules, such as confusing capital and revenue items', 'An arithmetical error where debit mistakes equal credit mistakes', 'A clerical omission of posting a journal entry to the ledger', 'b', 1, 3, 'Think about fundamental accounting concepts like capital vs revenue expenditure.', 'Transactions recorded without following accounting principles and rules (especially incorrect classification between capital and revenue) are known as Errors of Principle.'),
        ('acc11-08-mcq-0017', 8, 'Wages paid for the installation of new machinery were debited to Wages Account instead of Machinery Account. Does this error affect the Trial Balance?', 'Yes, because Wages Account has a higher debit balance', 'No, because both cash and machinery are asset accounts', 'Yes, because installation wages cannot be debited anywhere', 'No, because a debit was still made for the correct amount, though in the wrong account', 'd', 2, 5, 'Check whether equal debits and credits were placed in the ledger books.', 'An error of principle does not affect the Trial Balance because the debit amount was placed on the correct side (debit), even though it was charged to an incorrect account (Wages instead of Machinery).'),
        ('acc11-08-mcq-0018', 8, 'An amount of ₹500 paid for repairs to old machinery was debited to Machinery Account instead of Repairs Account. This is an example of:', 'Treating Capital expenditure as Revenue expenditure', 'Compensating error', 'Treating Revenue expenditure as Capital expenditure', 'Error of partial omission', 'c', 2, 5, 'Repairs are routine operational expenses, whereas Machinery is a fixed asset.', 'Routine repair of old machinery is a revenue expenditure. Debiting it to Machinery Account treats a revenue item as a capital item, violating accounting principles.'),
        ('acc11-08-mcq-0019', 8, 'Which of the following defines Compensating Errors?', 'Errors that are automatically rectified at the end of the year by closing entries', 'Errors resulting strictly from the ignorance of capital and revenue distinctions', 'Errors that occur when a single transaction is entered twice in the journal', 'Errors where two or more mistakes are committed such that their net effect on debit and credit is nil', 'd', 1, 3, 'Notice how one error offsets or counterbalances the effect of another.', 'Compensating errors occur when two or more errors are committed in such a way that the net effect of these errors on the debit and credit of accounts is nil or nullified.'),
        ('acc11-08-mcq-0020', 8, 'A sum of ₹3,000 paid to Ashok was posted as ₹300 to his debit, and ₹300 paid to Kumar was posted as ₹3,000 to his debit. What type of error is this?', 'Compensating error', 'Error of principle', 'Error of complete omission', 'Partial omission', 'a', 2, 5, 'Ashok''s debit was short by ₹2,700, while Kumar''s debit was excess by ₹2,700.', 'The under-debit of ₹2,700 in Ashok''s account is counterbalanced by an over-debit of ₹2,700 in Kumar''s account, making the net effect on the debit total zero. This is a compensating error.'),
        ('acc11-08-mcq-0021', 8, 'What is the key distinguishing characteristic of a One-Sided Error?', 'It affects only one account and affects the agreement of the Trial Balance', 'It arises solely from treating capital items as revenue items', 'It can never be rectified once books are closed', 'It affects two or more accounts and does not affect the Trial Balance', 'a', 1, 3, 'Consider how many accounts are touched and whether debits still equal credits.', 'One-sided errors affect only one account and consequently disturb the agreement of the Trial Balance.'),
        ('acc11-08-mcq-0022', 8, 'How is a one-sided error rectified if it is located BEFORE the preparation of the Trial Balance?', 'By giving an explanatory note for debiting or crediting the affected account in the ledger', 'By directly adjusting the proprietor''s Capital Account', 'By passing a compound journal entry in the Cash Book', 'By opening a temporary Suspense Account', 'a', 2, 5, 'At this stage, no Trial Balance or Suspense Account has been created yet.', 'If a one-sided error is located before preparing the Trial Balance, no journal entry through Suspense Account is passed; it is rectified simply by writing an explanatory note to debit or credit the affected account.'),
        ('acc11-08-mcq-0023', 8, 'When one-sided errors are located AFTER the preparation of the Trial Balance, they are rectified with the help of:', 'Trading Account', 'Reserve Fund Account', 'Profit & Loss Appropriation Account', 'Suspense Account', 'd', 1, 3, 'Recall the temporary holding account created when a Trial Balance does not balance.', 'When one-sided errors are detected after the Trial Balance has been prepared, the discrepancy in the Trial Balance is held in a Suspense Account, which is used to pass rectifying journal entries.'),
        ('acc11-08-mcq-0024', 8, 'In which book of original entry are rectification journal entries recorded?', 'Purchase Book', 'Sales Book', 'Journal Proper', 'Cash Book', 'c', 1, 3, 'This subsidiary book is reserved for entries that cannot be accommodated in specialized day books.', 'As noted explicitly in the chapter: ''Rectified entries are recorded in Journal Proper.'''),
        ('acc11-08-mcq-0025', 8, 'Which formula is provided in the chapter''s working notes to determine a Rectifying Entry for two-sided errors?', 'Rectifying Entry = Correct Entry - Reverse Entry', 'Rectifying Entry = Reverse Entry + Correct Entry', 'Rectifying Entry = Wrong Entry + Correct Entry', 'Rectifying Entry = Suspense Entry + Cash Entry', 'b', 2, 5, 'To cancel a wrong entry, you reverse it, and then you combine it with the correct entry.', 'The textbook explicitly states the working note formula: ''Rectifying Entry = Reverse Entry + Correct Entry''.'),
        ('acc11-08-mcq-0026', 8, 'According to Section 8.3 of the chapter, what are the three distinct stages of detecting errors?', 'During recording, During posting, and During balancing', 'Internal audit stage, External audit stage, and Tax assessment stage', 'Before Trial Balance; After Trial Balance but before Final Accounts; and After Final Accounts', 'Before Journalizing; Before Ledger Posting; and Before Vouching', 'c', 1, 3, 'Look at the timeline relative to Trial Balance preparation and final accounts closure.', 'Section 8.3 defines the three stages as: Stage 1 - Before preparation of Trial Balance; Stage 2 - After preparation of the Trial Balance but before preparing Final Accounts; Stage 3 - After preparing Final Accounts.'),
        ('acc11-08-mcq-0027', 8, 'According to the ''Effects of Errors'' diagram in the chapter, accounting errors directly impact which three core components?', 'Sales Book, Purchase Book, and Journal Proper', 'Inventory Ledger, Asset Register, and Payroll', 'Cash Flow, Bank Statement, and Pass Book', 'Trial Balance, Profit & Loss Account, and Balance Sheet', 'd', 1, 3, 'Look at the triangular diagram illustrated on page 256.', 'The Effects of Errors triangle shows Trial Balance at the apex, with Profit & Loss Account and Balance Sheet at the base corners.'),
        ('acc11-08-mcq-0028', 8, 'Salaries of ₹2,500 paid to Shrikant were wrongly debited to his personal account in the ledger. What is the correct rectifying entry?', 'Debit Shrikant''s A/c ₹2,500; Credit Cash A/c ₹2,500', 'Debit Shrikant''s A/c ₹2,500; Credit Salary A/c ₹2,500', 'Debit Salary A/c ₹2,500; Credit Shrikant''s A/c ₹2,500', 'Debit Salary A/c ₹2,500; Credit Suspense A/c ₹2,500', 'c', 2, 5, 'Salary is an expense that should be debited; Shrikant''s personal account was wrongly debited and must now be credited to cancel it.', 'The correct debit should have been to Salary Account. Since Shrikant''s personal account was wrongly debited, crediting Shrikant''s A/c cancels the error and debiting Salary A/c establishes the expense.'),
        ('acc11-08-mcq-0029', 8, 'Sale of old furniture for ₹2,000 was wrongly recorded as a sale of goods (credited to Sales Account). What is the rectifying journal entry?', 'Debit Sales A/c ₹2,000; Credit Suspense A/c ₹2,000', 'Debit Furniture A/c ₹2,000; Credit Sales A/c ₹2,000', 'Debit Sales A/c ₹2,000; Credit Furniture A/c ₹2,000', 'Debit Cash A/c ₹2,000; Credit Furniture A/c ₹2,000', 'c', 2, 5, 'Sales Account was wrongly credited and must be debited; Furniture Account should have been credited.', 'Selling an asset should reduce the asset balance (Credit Furniture A/c). Because Sales A/c was wrongly credited, it must be debited by ₹2,000 to reverse it, and Furniture A/c credited by ₹2,000.'),
        ('acc11-08-mcq-0030', 8, 'An amount of ₹7,000 withdrawn by the proprietor for personal use was debited to Trade Expenses Account. How is this error rectified?', 'Debit Drawings A/c ₹7,000; Credit Trade Expenses A/c ₹7,000', 'Debit Trade Expenses A/c ₹7,000; Credit Drawings A/c ₹7,000', 'Debit Drawings A/c ₹7,000; Credit Cash A/c ₹7,000', 'Debit Capital A/c ₹7,000; Credit Suspense A/c ₹7,000', 'a', 2, 5, 'Personal withdrawals belong to Drawings, not operating trade expenses.', 'Drawings Account should have been debited. To remove the incorrect debit from Trade Expenses Account, credit Trade Expenses A/c ₹7,000 and debit Drawings A/c ₹7,000.'),
        ('acc11-08-mcq-0031', 8, 'Cash received from Mr. Sawant ₹500 was wrongly credited to Mr. Shinde''s Account. What is the journal entry to rectify this mistake?', 'Debit Cash A/c ₹500; Credit Sawant A/c ₹500', 'Debit Shinde A/c ₹500; Credit Sawant A/c ₹500', 'Debit Shinde A/c ₹500; Credit Cash A/c ₹500', 'Debit Sawant A/c ₹500; Credit Shinde A/c ₹500', 'b', 2, 5, 'Debit the person who was mistakenly credited, and credit the actual payer.', 'Mr. Shinde was mistakenly credited; therefore, Shinde''s A/c must be debited with ₹500 to cancel the credit. Mr. Sawant gave the cash, so Sawant''s A/c must be credited with ₹500.'),
        ('acc11-08-mcq-0032', 8, 'An amount of ₹1,500 received as interest was wrongly credited to Commission Account. What is the proper rectifying entry?', 'Debit Commission A/c ₹1,500; Credit Interest A/c ₹1,500', 'Debit Commission A/c ₹1,500; Credit Suspense A/c ₹1,500', 'Debit Cash A/c ₹1,500; Credit Interest A/c ₹1,500', 'Debit Interest A/c ₹1,500; Credit Commission A/c ₹1,500', 'a', 2, 5, 'Cancel the wrong income credit by debiting it, then credit the true income account.', 'Commission Account was credited by mistake, so it must be debited by ₹1,500. The correct revenue account to credit is Interest Account for ₹1,500.'),
        ('acc11-08-mcq-0033', 8, 'A payment of ₹5,000 for the purchase of a computer was charged to Office Expenses Account. What entry rectifies this error of principle?', 'Debit Computer A/c ₹5,000; Credit Office Expenses A/c ₹5,000', 'Debit Office Expenses A/c ₹5,000; Credit Computer A/c ₹5,000', 'Debit Computer A/c ₹5,000; Credit Cash A/c ₹5,000', 'Debit Purchases A/c ₹5,000; Credit Computer A/c ₹5,000', 'a', 2, 5, 'A computer is a capital asset, not an operational office expense.', 'The computer is an asset and must be debited. The incorrect debit to Office Expenses A/c is eliminated by crediting Office Expenses A/c by ₹5,000.'),
        ('acc11-08-mcq-0034', 8, 'Carriage paid of ₹500 on the purchase of a new machine was debited to Carriage Account. What rectifying entry is needed?', 'Debit Carriage A/c ₹500; Credit Cash A/c ₹500', 'Debit Carriage A/c ₹500; Credit Machinery A/c ₹500', 'Debit Machinery A/c ₹500; Credit Carriage A/c ₹500', 'Debit Machinery A/c ₹500; Credit Cash A/c ₹500', 'c', 2, 5, 'Carriage incurred to bring a new machine to the premises is capitalized into the asset cost.', 'Expenses incurred on acquiring and installing a capital asset must be capitalized to the asset account. Hence, Machinery A/c is debited and Carriage A/c is credited with ₹500.'),
        ('acc11-08-mcq-0035', 8, 'Before the preparation of the Trial Balance, it was found that the Return Inward Book was overcast by ₹200. How should this error be rectified?', 'By passing a journal entry: Suspense A/c Dr. ₹200 to Return Inward A/c ₹200', 'By passing a journal entry: Return Inward A/c Dr. ₹200 to Debtors A/c ₹200', 'No journal entry is required; Return Inwards A/c is simply credited with ₹200 in the ledger', 'No journal entry is required; Return Inwards A/c is debited with ₹200 in the ledger', 'c', 2, 5, 'Before the Trial Balance, single-sided errors are corrected by an explanatory ledger note.', 'Before the Trial Balance is prepared, single-account errors require no journal entry. Return Inward normally has a debit balance; being overcast (excess debit), it is corrected by crediting Returns Inwards A/c with ₹200.'),
        ('acc11-08-mcq-0036', 8, 'Goods sold to Mr. Abhiraj for ₹350 were wrongly entered in the Purchases Day Book as ₹530. What is the correct rectifying journal entry?', 'Debit Purchases A/c ₹530; Credit Sales A/c ₹350; Credit Abhiraj A/c ₹180', 'Debit Abhiraj A/c ₹180; Credit Suspense A/c ₹180', 'Debit Sales A/c ₹350; Debit Purchases A/c ₹530; Credit Abhiraj A/c ₹880', 'Debit Abhiraj A/c ₹880; Credit Purchases A/c ₹530; Credit Sales A/c ₹350', 'd', 3, 10, 'Abhiraj should be debited with ₹350, Purchases wrongly debited with ₹530 must be credited, and Sales must be credited with ₹350.', 'To rectify: Reverse the wrong purchase debit by crediting Purchases A/c ₹530. Record the true credit sale by crediting Sales A/c ₹350. Debit Abhiraj with the total (₹530 wrongly credited + ₹350 correct debit = ₹880).'),
        ('acc11-08-mcq-0037', 8, 'Before the Trial Balance is prepared, commission received of ₹200 was posted to the debit of Commission Account instead of its credit. How should it be rectified?', 'Credit Commission Account with ₹200 in the ledger', 'Credit Commission Account with ₹400 in the ledger', 'Debit Commission Account with ₹400 in the ledger', 'Pass a journal entry: Commission A/c Dr. ₹400 to Suspense A/c ₹400', 'b', 3, 10, 'A wrong debit of ₹200 requires ₹200 to neutralize plus ₹200 to record the actual credit.', 'Because this one-sided error is detected before the Trial Balance, no journal entry is passed. To cancel the wrong debit of ₹200 and provide the required credit of ₹200, Commission A/c is credited with ₹400.'),
        ('acc11-08-mcq-0038', 8, 'A cheque for ₹320 issued to Mr. Ram was wrongly entered in the cash column of the Cash Book instead of the bank column. What is the rectifying entry?', 'Debit Cash A/c ₹320; Credit Bank A/c ₹320', 'Debit Ram A/c ₹320; Credit Bank A/c ₹320', 'Debit Bank A/c ₹320; Credit Cash A/c ₹320', 'Debit Cash A/c ₹320; Credit Ram A/c ₹320', 'a', 2, 5, 'Cash was credited when bank should have been credited. To cancel cash credit, debit cash.', 'Entering a cheque payment in the cash column credited Cash Account instead of Bank Account. To correct this, Cash A/c is debited with ₹320 (restoring cash) and Bank A/c is credited with ₹320.'),
        ('acc11-08-mcq-0039', 8, 'A factory electricity bill of ₹7,000 paid in cash was recorded twice in the books. What is the rectifying entry?', 'Debit Factory Electricity A/c ₹7,000; Credit Cash A/c ₹7,000', 'Debit Cash A/c ₹7,000; Credit Factory Electricity A/c ₹7,000', 'Debit Factory Electricity A/c ₹14,000; Credit Cash A/c ₹14,000', 'Debit Suspense A/c ₹7,000; Credit Factory Electricity A/c ₹7,000', 'b', 2, 5, 'To reverse an entire duplicate payment entry, flip the original entry once.', 'Since the entry was made twice (two debits to Electricity and two credits to Cash), reversing one instance by debiting Cash A/c ₹7,000 and crediting Factory Electricity A/c ₹7,000 rectifies the duplicate recording.'),
        ('acc11-08-mcq-0040', 8, 'Before the Trial Balance is prepared, paid rent of ₹825 was posted to the Rent Account as ₹325. How is this error rectified?', 'Pass an entry: Suspense A/c Dr. ₹500 to Rent A/c ₹500', 'Rent Account should be credited with ₹500 by an explanatory note', 'Pass an entry: Rent A/c Dr. ₹500 to Suspense A/c ₹500', 'Rent Account should be debited with ₹500 by an explanatory note', 'd', 2, 5, 'Rent was under-debited by ₹825 - ₹325 = ₹500.', 'Because this one-sided error is discovered before preparing the Trial Balance, no journal entry is required; Rent Account is simply debited with the deficit amount of ₹500.'),
        ('acc11-08-mcq-0041', 8, 'Wages of ₹9,900 paid for the extension of an office building were charged to Wages Account. What is the rectifying entry?', 'Debit Repairs A/c ₹9,900; Credit Wages A/c ₹9,900', 'Debit Wages A/c ₹9,900; Credit Building A/c ₹9,900', 'Debit Building A/c ₹9,900; Credit Wages A/c ₹9,900', 'Debit Building A/c ₹9,900; Credit Cash A/c ₹9,900', 'c', 2, 5, 'Wages paid for extending a permanent asset must be added to the asset''s value.', 'Building extension is capital expenditure. The Wages Account was wrongly debited, so Building A/c must be debited by ₹9,900 and Wages A/c credited by ₹9,900 to rectify the error of principle.'),
        ('acc11-08-mcq-0042', 8, 'Life insurance premium of the proprietor amounting to ₹1,500 was wrongly debited to Insurance Account. What is the proper rectifying entry?', 'Debit Drawings A/c ₹1,500; Credit Cash A/c ₹1,500', 'Debit Insurance A/c ₹1,500; Credit Drawings A/c ₹1,500', 'Debit Drawings A/c ₹1,500; Credit Insurance A/c ₹1,500', 'Debit Profit and Loss A/c ₹1,500; Credit Insurance A/c ₹1,500', 'c', 2, 5, 'A life insurance policy for the owner is a personal expense, not a business risk policy.', 'The life insurance premium of the proprietor is a personal expense treated as Drawings. Debiting Insurance A/c treated it as a business expense; hence, debit Drawings A/c ₹1,500 and credit Insurance A/c ₹1,500.'),
        ('acc11-08-mcq-0043', 8, 'Goods of ₹2,000 returned by Sumit & Co. were included in stock, but no entry was passed in the books. What is the rectifying entry?', 'Debit Stock A/c ₹2,000; Credit Purchases A/c ₹2,000', 'Debit Sumit & Co. ₹2,000; Credit Sales Return A/c ₹2,000', 'Debit Purchases Return A/c ₹2,000; Credit Sumit & Co. ₹2,000', 'Debit Sales Return A/c ₹2,000; Credit Sumit & Co. ₹2,000', 'd', 2, 5, 'Goods returned by a customer represent Sales Return (Return Inward).', 'Returns by customers are Sales Returns. Complete omission is rectified by recording the original entry: Debit Sales Return A/c ₹2,000 and Credit Sumit & Co. ₹2,000.'),
        ('acc11-08-mcq-0044', 8, 'Goods purchased for ₹1,200 were erroneously entered in the Purchases Book as ₹12,000. What is the rectifying journal entry?', 'Debit Suspense A/c ₹10,800; Credit Purchases A/c ₹10,800', 'Debit Creditors A/c ₹10,800; Credit Purchases A/c ₹10,800', 'Debit Creditors A/c ₹12,000; Credit Purchases A/c ₹1,200; Credit Suspense A/c ₹10,800', 'Debit Purchases A/c ₹10,800; Credit Creditors A/c ₹10,800', 'b', 3, 10, 'Both Purchases and Creditors were overstated by ₹12,000 - ₹1,200 = ₹10,800.', 'Entering ₹12,000 instead of ₹1,200 caused Purchases to be debited excess by ₹10,800 and Creditors to be credited excess by ₹10,800. The reversal entry is: Debit Creditors A/c ₹10,800 and Credit Purchases A/c ₹10,800.'),
        ('acc11-08-mcq-0045', 8, 'Goods purchased from Sujit for ₹3,000 were recorded in the Sales Book. What is the rectifying journal entry?', 'Debit Purchases A/c ₹3,000; Credit Sales A/c ₹3,000', 'Debit Purchases A/c ₹3,000, Debit Sales A/c ₹3,000; Credit Sujit''s A/c ₹6,000', 'Debit Purchases A/c ₹3,000; Credit Sujit''s A/c ₹3,000', 'Debit Sujit''s A/c ₹6,000; Credit Purchases A/c ₹3,000, Credit Sales A/c ₹3,000', 'b', 3, 10, 'You must record the purchase debit, cancel the sales credit, and credit Sujit with the combined amount.', 'Purchases A/c must be debited by ₹3,000. Sales A/c was wrongly credited by ₹3,000, so it must be debited by ₹3,000. Sujit''s A/c was wrongly debited by ₹3,000 and should have been credited by ₹3,000, so Sujit is credited with ₹6,000.'),
        ('acc11-08-mcq-0046', 8, 'Goods for ₹5,200 sold to Sachin were mistakenly passed through the Purchase Book. What is the rectifying entry?', 'Debit Purchases A/c ₹5,200, Debit Sales A/c ₹5,200; Credit Sachin''s A/c ₹10,400', 'Debit Sachin''s A/c ₹10,400; Credit Sales A/c ₹5,200, Credit Purchases A/c ₹5,200', 'Debit Sachin''s A/c ₹5,200; Credit Purchases A/c ₹5,200', 'Debit Sachin''s A/c ₹5,200; Credit Sales A/c ₹5,200', 'b', 3, 10, 'Sachin''s credit of ₹5,200 from purchase book must be undone and he must be debited for the sale.', 'The rectifying entry debits Sachin''s A/c by ₹10,400 (₹5,200 to cancel the wrong credit + ₹5,200 for the actual sale debit) and credits Sales A/c ₹5,200 and Purchases A/c ₹5,200 (to cancel wrong purchase debit).'),
        ('acc11-08-mcq-0047', 8, 'A customer returned goods worth ₹800, but the return was recorded in the Purchase Return Book. What is the rectifying journal entry?', 'Debit Purchases Return A/c ₹800; Credit Customer''s A/c ₹800', 'Debit Customer''s A/c ₹1,600; Credit Sales Return A/c ₹800, Credit Purchases Return A/c ₹800', 'Debit Sales Return A/c ₹800; Credit Purchases Return A/c ₹800', 'Debit Sales Return A/c ₹800, Debit Purchases Return A/c ₹800; Credit Customer''s A/c ₹1,600', 'd', 3, 10, 'Sales Return must be debited, Purchase Return credit must be cancelled by debiting it, and Customer must be credited.', 'Sales Return A/c is debited ₹800 to record the inward return; Purchases Return A/c is debited ₹800 to cancel the incorrect credit; Customer''s A/c is credited ₹1,600 (canceling the wrong debit and posting the true credit).'),
        ('acc11-08-mcq-0048', 8, 'A credit sale of ₹240 to Ajit was entered in the Sales Book as ₹420. What is the rectifying entry?', 'Debit Ajit''s A/c ₹180; Credit Sales A/c ₹180', 'Debit Sales A/c ₹420; Credit Ajit''s A/c ₹420', 'Debit Sales A/c ₹180; Credit Ajit''s A/c ₹180', 'Debit Suspense A/c ₹180; Credit Sales A/c ₹180', 'c', 2, 5, 'Sales and customer were both overstated by ₹420 - ₹240 = ₹180.', 'Both Sales A/c and Ajit''s A/c were overstated by ₹180 (₹420 - ₹240). Reversing the excess requires debiting Sales A/c with ₹180 and crediting Ajit''s A/c with ₹180.'),
        ('acc11-08-mcq-0049', 8, 'When the credit total of a Trial Balance is higher than the debit total, to which side of the Suspense Account is the difference transferred?', 'Directly to the Profit and Loss Account', 'Debit side', 'Credit side', 'Neither side; it is transferred to Capital Account', 'b', 2, 5, 'The difference is placed on the lighter side to make the columns tally temporarily.', 'When the credit column total is higher than the debit column total, the shortage is on the debit side; hence, the difference is placed on the debit side of the Suspense Account.'),
        ('acc11-08-mcq-0050', 8, 'What happens to the Suspense Account once all one-sided errors have been located and rectified?', 'It permanently maintains a debit balance transferred to the Balance Sheet', 'Its balance is transferred to General Reserve', 'It is converted into a Nominal Account', 'It automatically closes with a nil balance', 'd', 1, 3, 'Suspense Account is purely a temporary holding account for discrepancies.', 'As stated in Section 8.4: ''When all one sided errors are located and rectified Suspense Account automatically closes.'''),
        ('acc11-08-mcq-0051', 8, 'An amount of ₹840 received from M/s Singh & Co. was posted to their debit as ₹50. What is the rectifying entry through Suspense Account?', 'Debit Suspense A/c ₹790; Credit M/s Singh & Co. ₹790', 'Debit M/s Singh & Co. ₹890; Credit Suspense A/c ₹890', 'Debit Cash A/c ₹840; Credit M/s Singh & Co. ₹840', 'Debit Suspense A/c ₹890; Credit M/s Singh & Co. ₹890', 'd', 3, 10, 'Singh & Co. needs a credit of ₹50 to clear the wrong debit, plus ₹840 for the true credit.', 'Singh & Co. should have been credited with ₹840, but was debited with ₹50. To correct their account, they must be credited with ₹50 + ₹840 = ₹890, and Suspense Account is debited with ₹890.'),
        ('acc11-08-mcq-0052', 8, '₹530 spent for repairs to machinery was posted to the debit of Machinery Account as ₹150. What is the rectifying entry through Suspense Account?', 'Repairs to Machinery A/c Dr. ₹380; To Suspense A/c ₹380', 'Suspense A/c Dr. ₹380; To Machinery A/c ₹380', 'Machinery A/c Dr. ₹380; To Repairs to Machinery A/c ₹380', 'Repairs to Machinery A/c Dr. ₹530; To Machinery A/c ₹150, To Suspense A/c ₹380', 'd', 3, 10, 'Debit Repairs with full ₹530, credit Machinery with ₹150 to remove wrong debit, and balance with Suspense.', 'Repairs Account must be debited with the actual amount ₹530. The incorrect debit of ₹150 in Machinery Account is cancelled by crediting Machinery A/c ₹150. The remaining difference of ₹380 is credited to Suspense A/c.'),
        ('acc11-08-mcq-0053', 8, 'A discount of ₹25 allowed by Shah & Co. to us (discount received) was posted to their credit. What is the rectifying entry using Suspense Account?', 'Debit Shah & Co. ₹50; Credit Suspense A/c ₹50', 'Debit Discount Allowed A/c ₹25; Credit Shah & Co. ₹25', 'Debit Shah & Co. ₹25; Credit Discount Received A/c ₹25', 'Debit Suspense A/c ₹50; Credit Shah & Co. ₹50', 'a', 3, 10, 'Shah & Co. should have been debited by ₹25, but was credited by ₹25.', 'Shah & Co. should be debited by ₹25 to cancel the incorrect credit and debited another ₹25 to record the proper discount debit (total debit ₹50). The corresponding credit goes to Suspense Account for ₹50.'),
        ('acc11-08-mcq-0054', 8, 'An amount of ₹730 paid to Chetan & Co. was wrongly credited to Lalit & Co. as ₹250. What entry rectifies this mistake via Suspense Account?', 'Chetan & Co. Dr. ₹730, Lalit & Co. Dr. ₹250; To Suspense A/c ₹980', 'Chetan & Co. Dr. ₹730; To Lalit & Co. ₹250, To Suspense A/c ₹480', 'Lalit & Co. Dr. ₹250; To Chetan & Co. ₹250', 'Suspense A/c Dr. ₹980; To Chetan & Co. ₹730, To Lalit & Co. ₹250', 'a', 3, 10, 'Debit Chetan & Co. ₹730, cancel Lalit & Co.''s credit by debiting ₹250, and credit the total to Suspense.', 'Chetan & Co. was not debited, so debit Chetan & Co. ₹730. Lalit & Co. was mistakenly credited with ₹250, so debit Lalit & Co. ₹250. Credit Suspense Account with the total ₹980.'),
        ('acc11-08-mcq-0055', 8, 'The total of Purchase Returns Book of ₹3,150 was carried forward as ₹1,530. What is the rectifying entry through Suspense Account?', 'Debit Purchase Return A/c ₹3,150; Credit Suspense A/c ₹3,150', 'Debit Suspense A/c ₹1,620; Credit Purchase Return A/c ₹1,620', 'Debit Suspense A/c ₹1,530; Credit Purchase Return A/c ₹1,530', 'Debit Purchase Return A/c ₹1,620; Credit Suspense A/c ₹1,620', 'b', 3, 10, 'Purchase Return Book has a credit balance; it was under-credited by ₹3,150 - ₹1,530 = ₹1,620.', 'Purchase Return Book has a normal credit total. Carrying forward ₹1,530 instead of ₹3,150 undercast the credit by ₹1,620. To rectify, Purchase Return A/c is credited ₹1,620 and Suspense A/c is debited ₹1,620.'),
        ('acc11-08-mcq-0056', 8, 'Cash paid to Shweta ₹7,500 was debited to Ankita''s Account as ₹7,000. What is the rectifying journal entry?', 'Debit Shweta''s A/c ₹7,500; Credit Ankita''s A/c ₹7,000, Credit Suspense A/c ₹500', 'Debit Shweta''s A/c ₹500; Credit Suspense A/c ₹500', 'Debit Shweta''s A/c ₹7,500; Credit Ankita''s A/c ₹7,500', 'Debit Ankita''s A/c ₹7,000, Debit Suspense A/c ₹500; Credit Shweta''s A/c ₹7,500', 'a', 3, 10, 'Shweta needs a debit of ₹7,500; Ankita''s debit of ₹7,000 must be cancelled by credit; difference goes to Suspense.', 'Shweta''s Account must be debited with the correct payment ₹7,500. Ankita''s account was wrongly debited with ₹7,000, so credit Ankita''s A/c ₹7,000. The ₹500 shortage on the credit side is posted to Suspense A/c.'),
        ('acc11-08-mcq-0057', 8, 'Amount paid on the registration of a newly acquired motor car of ₹800 was recorded as legal charges. What is the rectifying journal entry?', 'Debit Motor Car A/c ₹800; Credit Legal Charges A/c ₹800', 'Debit Legal Charges A/c ₹800; Credit Motor Car A/c ₹800', 'Debit Motor Car A/c ₹800; Credit Cash A/c ₹800', 'Debit Motor Car A/c ₹800; Credit Suspense A/c ₹800', 'a', 2, 5, 'Registration charges on a vehicle acquisition must be capitalized to the vehicle account.', 'Registration expenses of a motor car are capital expenditures to be added to Motor Car Account. To remove the incorrect charge to Legal Charges Account, credit Legal Charges A/c ₹800 and debit Motor Car A/c ₹800.'),
        ('acc11-08-mcq-0058', 8, 'Repairs of ₹1,000 paid for overhauling a second-hand machine purchased were debited to Repairs Account. What is the correct rectifying entry?', 'Debit Repairs A/c ₹1,000; Credit Machinery A/c ₹1,000', 'Debit Machinery A/c ₹1,000; Credit Cash A/c ₹1,000', 'Debit Suspense A/c ₹1,000; Credit Repairs A/c ₹1,000', 'Debit Machinery A/c ₹1,000; Credit Repairs A/c ₹1,000', 'd', 2, 5, 'Overhauling a second-hand asset to put it into working condition is a capital expense.', 'Cost of overhauling second-hand machinery before putting it into use is capitalized into Machinery Account. Debiting Repairs was an error of principle, rectified by debiting Machinery A/c ₹1,000 and crediting Repairs A/c ₹1,000.'),
        ('acc11-08-mcq-0059', 8, 'Materials worth ₹90,000 and wages of ₹10,000 used for the construction of a building were not recorded in the books. What is the rectifying entry?', 'Debit Building A/c ₹1,00,000; Credit Purchases A/c ₹90,000, Credit Wages A/c ₹10,000', 'Debit Building A/c ₹1,00,000; Credit Suspense A/c ₹1,00,000', 'Debit Purchases A/c ₹90,000, Debit Wages A/c ₹10,000; Credit Cash A/c ₹1,00,000', 'Debit Building A/c ₹1,00,000; Credit Cash A/c ₹1,00,000', 'd', 3, 10, 'Combine both material and wages into the capital asset being constructed.', 'Both material (₹90,000) and wages (₹10,000) incurred on constructing a building form part of the building''s capital cost. The complete omission entry is: Debit Building A/c ₹1,00,000; Credit Cash A/c ₹1,00,000.'),
        ('acc11-08-mcq-0060', 8, 'Furniture purchased for ₹6,000 was posted to Purchases Account as ₹400. What is the rectifying entry through Suspense Account?', 'Debit Furniture A/c ₹5,600; Credit Suspense A/c ₹5,600', 'Debit Furniture A/c ₹6,000; Credit Purchases A/c ₹400, Credit Suspense A/c ₹5,600', 'Debit Suspense A/c ₹5,600; Credit Purchases A/c ₹5,600', 'Debit Furniture A/c ₹6,000; Credit Purchases A/c ₹6,000', 'b', 3, 10, 'Furniture must be debited with full ₹6,000, Purchases credit must cancel ₹400, and Suspense balances the entry.', 'Furniture A/c is debited ₹6,000 (correct asset debit); Purchases A/c is credited ₹400 (reversing wrong debit); and Suspense A/c is credited with the difference of ₹5,600.'),
        ('acc11-08-mcq-0061', 8, 'What is the term used for taking the total more than actual while closing books of accounts?', 'Undercasting', 'Cross-casting', 'Balancing', 'Overcasting', 'd', 1, 3, 'Look at the terminology tested in Exercise Q.2(2).', 'Overcasting means taking the total more than the actual sum when totalling subsidiary books or ledger accounts.'),
        ('acc11-08-mcq-0062', 8, 'Which of the following statements is TRUE regarding Suspense Account?', 'All accounting errors can only be rectified through a Suspense Account', 'A Suspense Account is a permanent nominal account that appears in the Trading Account', 'There is no need to open a Suspense Account if the Trial Balance agrees', 'A Suspense Account is always opened before the Trial Balance is prepared', 'c', 2, 5, 'Suspense Account is only opened when there is a discrepancy between Trial Balance totals.', 'If the Trial Balance agrees, there is no difference in totals, so no Suspense Account is opened. Furthermore, two-sided errors are rectified through Journal Proper without touching Suspense Account.'),
        ('acc11-08-mcq-0063', 8, 'Unintentional omission or commission of amounts and accounts while recording transactions is termed as an:', 'Fraud', 'Appropriation', 'Error', 'Adjustment', 'c', 1, 3, 'Review Exercise Q.5(1) regarding unintentional bookkeeping inaccuracies.', 'The unintentional omission or commission of amounts and accounts while recording transactions is defined as an error (as opposed to fraud, which is intentional).'),
        ('acc11-08-mcq-0064', 8, 'Purchases of goods from Siddhant Traders for ₹12,000 paid in cash was wrongly debited to Siddhant Traders Account. What is the rectifying entry?', 'Debit Purchases A/c ₹12,000; Credit Siddhant Traders A/c ₹12,000', 'Debit Purchases A/c ₹12,000; Credit Cash A/c ₹12,000', 'Debit Purchases A/c ₹12,000; Credit Suspense A/c ₹12,000', 'Debit Siddhant Traders A/c ₹12,000; Credit Purchases A/c ₹12,000', 'a', 2, 5, 'In cash purchases, the supplier''s personal account is not debited; Purchases Account is debited.', 'For cash purchases, Purchases A/c should be debited, not the supplier''s personal account. To correct this, debit Purchases A/c ₹12,000 and credit Siddhant Traders A/c ₹12,000.'),
        ('acc11-08-mcq-0065', 8, 'Received interest of ₹700 from Bank was wrongly credited to Bank Account instead of Interest Account. What is the rectifying journal entry?', 'Debit Bank A/c ₹700; Credit Interest A/c ₹700', 'Debit Bank A/c ₹1,400; Credit Interest A/c ₹1,400', 'Debit Bank A/c ₹1,400; Credit Interest A/c ₹700, Credit Suspense A/c ₹700', 'Debit Interest A/c ₹700; Credit Bank A/c ₹700', 'b', 3, 10, 'Bank was credited by ₹700 when it should have been debited by ₹700.', 'Bank should have been debited with ₹700 (incoming interest) and Interest credited with ₹700. Since Bank was mistakenly credited with ₹700, Bank A/c must be debited with ₹1,400 to cancel the credit and record the debit, while crediting the respective revenue/rectification accounts.'),
        ('acc11-08-mcq-0066', 8, 'A printer purchased for ₹10,000 was wrongly passed through the Purchase Book. What is the journal entry to rectify this error?', 'Debit Printer A/c ₹10,000; Credit Office Expenses A/c ₹10,000', 'Debit Purchase A/c ₹10,000; Credit Printer A/c ₹10,000', 'Debit Printer A/c ₹10,000; Credit Purchase A/c ₹10,000', 'Debit Printer A/c ₹10,000; Credit Cash A/c ₹10,000', 'c', 2, 5, 'Printer is an office equipment/asset; Purchase Book is only for trading merchandise.', 'Passing an asset purchase through the Purchase Book wrongly debited Purchases Account. Rectification requires debiting Printer A/c ₹10,000 and crediting Purchases A/c ₹10,000.'),
        ('acc11-08-mcq-0067', 8, 'A credit purchase of goods from Sheetal amounting to ₹2,000 was wrongly passed through the Sales Book. What is the rectifying entry?', 'Debit Purchases A/c ₹2,000; Credit Sheetal A/c ₹2,000', 'Debit Sheetal''s A/c ₹4,000; Credit Purchases A/c ₹2,000, Credit Sales A/c ₹2,000', 'Debit Purchases A/c ₹2,000, Debit Sales A/c ₹2,000; Credit Sheetal''s A/c ₹4,000', 'Debit Sales A/c ₹2,000; Credit Purchases A/c ₹2,000', 'c', 3, 10, 'Purchases must be debited, Sales credit cancelled by debit, and Sheetal credited for both.', 'To rectify: Debit Purchases A/c ₹2,000 (recording purchase), Debit Sales A/c ₹2,000 (canceling wrong credit sale), and Credit Sheetal''s A/c ₹4,000 (reversing wrong debit of ₹2,000 and crediting actual purchase of ₹2,000).'),
        ('acc11-08-mcq-0068', 8, 'A return of goods worth ₹500 to Umesh was wrongly passed through the Sales Return Book. What is the rectifying journal entry?', 'Debit Purchase Return A/c ₹500; Credit Sales Return A/c ₹500', 'Debit Sales Return A/c ₹500, Debit Purchase Return A/c ₹500; Credit Umesh''s A/c ₹1,000', 'Debit Umesh''s A/c ₹500; Credit Purchase Return A/c ₹500', 'Debit Umesh''s A/c ₹1,000; Credit Purchase Return A/c ₹500, Credit Sales Return A/c ₹500', 'd', 3, 10, 'Umesh was credited via Sales Return; he should have been debited. Also credit Purchase Return and cancel Sales Return.', 'Return to Umesh is Purchase Return (credit). Entering it in Sales Return debited Sales Return and credited Umesh. To rectify: Debit Umesh ₹1,000 (₹500 to cancel credit + ₹500 correct debit), Credit Purchase Return A/c ₹500, and Credit Sales Return A/c ₹500.'),
        ('acc11-08-mcq-0069', 8, 'A return of goods worth ₹900 by Ganesh was entered in the Purchase Return Book. What is the rectifying entry?', 'Debit Sales Return A/c ₹900, Debit Purchase Return A/c ₹900; Credit Ganesh''s A/c ₹1,800', 'Debit Purchase Return A/c ₹900; Credit Sales Return A/c ₹900', 'Debit Ganesh''s A/c ₹1,800; Credit Sales Return A/c ₹900, Credit Purchase Return A/c ₹900', 'Debit Sales Return A/c ₹900; Credit Ganesh''s A/c ₹900', 'a', 3, 10, 'Goods returned by a customer are Sales Returns; cancel the Purchase Return credit and credit the customer.', 'Debit Sales Return A/c ₹900 to record inward return, Debit Purchase Return A/c ₹900 to cancel the wrong credit, and Credit Ganesh''s A/c ₹1,800 (reversing wrong debit of ₹900 and recording true credit of ₹900).'),
        ('acc11-08-mcq-0070', 8, 'Credit purchases from Neha of ₹10,000 were recorded in the Purchase Book as ₹11,000. What is the rectifying entry?', 'Debit Purchases A/c ₹1,000; Credit Neha''s A/c ₹1,000', 'Debit Neha''s A/c ₹1,000; Credit Purchases A/c ₹1,000', 'Debit Purchases A/c ₹11,000; Credit Neha''s A/c ₹11,000', 'Debit Suspense A/c ₹1,000; Credit Purchases A/c ₹1,000', 'b', 2, 5, 'Both purchases and creditor were recorded with an excess of ₹1,000.', 'Both Purchases and Neha were overstated by ₹1,000 (₹11,000 - ₹10,000). The reversal of this excess requires debiting Neha''s A/c ₹1,000 and crediting Purchases A/c ₹1,000.'),
        ('acc11-08-mcq-0071', 8, 'The monthly total of ₹100 for discount allowed to customers was credited to Discount Account in the ledger. How is this rectified using Suspense Account?', 'Debit Suspense A/c ₹200; Credit Discount Allowed A/c ₹200', 'Debit Discount Allowed A/c ₹100; Credit Suspense A/c ₹100', 'Debit Suspense A/c ₹100; Credit Discount Allowed A/c ₹100', 'Debit Discount Allowed A/c ₹200; Credit Suspense A/c ₹200', 'd', 3, 10, 'Discount allowed is an expense (normal debit balance) that was mistakenly credited.', 'Discount allowed is an expense requiring a debit of ₹100. Crediting it created an error of ₹200. To rectify: Debit Discount Allowed A/c ₹200 (₹100 to cancel credit + ₹100 true debit) and Credit Suspense A/c ₹200.'),
        ('acc11-08-mcq-0072', 8, 'An item of ₹450 relating to Prepaid Rent Account was completely omitted to be brought forward. What is the rectifying entry through Suspense Account?', 'Debit Suspense A/c ₹450; Credit Prepaid Rent A/c ₹450', 'Debit Prepaid Rent A/c ₹450; Credit Rent A/c ₹450', 'Debit Prepaid Rent A/c ₹450; Credit Suspense A/c ₹450', 'Debit Rent A/c ₹450; Credit Prepaid Rent A/c ₹450', 'c', 2, 5, 'Prepaid rent is an asset with a debit balance that was omitted from the ledger opening.', 'Prepaid Rent is an asset carrying a debit balance. Because it was omitted to be brought forward, debiting Prepaid Rent A/c ₹450 and crediting Suspense A/c ₹450 restores the balance and resolves the difference.'),
        ('acc11-08-mcq-0073', 8, 'Amount payable to Subhash for repairs done to printer ₹180 and a new printer supplied for ₹1,920 were entered in the Purchase Book as ₹2,000. What is the rectifying entry?', 'Printer A/c Dr. ₹2,000; To Purchases A/c ₹2,000', 'Repairs A/c Dr. ₹180, Printer A/c Dr. ₹1,920; To Subhash A/c ₹2,100', 'Repairs A/c Dr. ₹180, Printer A/c Dr. ₹1,920; To Purchases A/c ₹2,000', 'Purchases A/c Dr. ₹2,000; To Repairs A/c ₹180, To Printer A/c ₹1,920', 'c', 3, 10, 'Cancel the entire Purchase Book charge of ₹2,000 and classify into Repairs and Printer Asset.', 'Subhash was credited correctly with ₹2,000 in total (₹180 + ₹1,920), but the debit went entirely to Purchases A/c. Rectification: Debit Repairs A/c ₹180, Debit Printer A/c ₹1,920, and Credit Purchases A/c ₹2,000.'),
        ('acc11-09-mcq-0001', 9, 'What is the primary aim of accounting according to Chapter 9?', 'To determine tax liability exclusively for filing returns with the government', 'To maintain secret records of confidential proprietor transactions', 'Assessment of business performance for the benefit of all stakeholders', 'To physically verify and count goods stored in warehouse godowns', 'c', 1, 3, 'Consider the foundational definition of accounting given at the start of Section 9.1.', 'According to Section 9.1, the primary aim of accounting is the assessment of business performance for the benefit of all stakeholders (such as owners, employees, suppliers, customers, and financiers) to help them form opinions on financial position.'),
        ('acc11-09-mcq-0002', 9, 'Final Accounts are best described as financial statements that:', 'Validate and explain working results and financial status for a specific period on a particular date', 'Record daily cash inflows and outflows on an ongoing chronological basis', 'List the personal assets and personal household expenses of the business owner', 'Summarize non-monetary agreements and employee performance ratings', 'a', 1, 3, 'Focus on the definition explaining working results and financial status at the end of a financial year.', 'Final Accounts are financial statements prepared at the end of every financial year that validate and explain the working results and financial status of the business for a specific period on a particular date.'),
        ('acc11-09-mcq-0003', 9, 'The balancing figure of a Trading Account represents which of the following?', 'Net Profit or Net Loss', 'Gross Profit or Gross Loss', 'Operating Cash Flow', 'Net Capital Employed', 'b', 1, 3, 'Recall the direct outcome of summarizing trading activities and direct expenses.', 'The balancing figure of the Trading Account is Gross Profit (when credit exceeds debit) or Gross Loss (when debit exceeds credit). Net Profit/Loss is the balancing figure of the Profit and Loss Account.'),
        ('acc11-09-mcq-0004', 9, 'The balancing figure of the Profit and Loss Account reveals:', 'Net Profit or Net Loss', 'Gross Profit or Gross Loss', 'Total Outstanding Liabilities', 'Net Purchases for the year', 'a', 1, 3, 'This final figure accounts for all indirect incomes and indirect expenses.', 'Section 9.1 specifies that in the case of the Profit and Loss Account, the balancing figure is Net Profit or Net Loss, which is ultimately transferred to the Capital Account.'),
        ('acc11-09-mcq-0005', 9, 'What is the primary function of a Balance Sheet in Final Accounts?', 'To show the financial position of assets and liabilities at a given period of time', 'To calculate the gross trading margin earned during the accounting year', 'To list all nominal ledger accounts closed during the period', 'To record daily sales transactions in chronological sequence', 'a', 1, 3, 'The Balance Sheet is a positional statement rather than an operating account.', 'The Balance Sheet is a statement showing the true financial position of assets and liabilities of a business concern on a specified date.'),
        ('acc11-09-mcq-0006', 9, 'Which of the following is NOT an objective of preparing Final Accounts as listed in the chapter?', 'To determine Gross Profit/Gross Loss and Net Profit/Net Loss during the financial year', 'To show the true and correct financial position of the business', 'To enable effective control over the financial activities of the business', 'To eliminate the necessity of recording primary transactions in journals', 'd', 2, 5, 'Final accounts depend on journal entries rather than replacing them.', 'The stated objectives include determining profit/loss, showing true financial position, informing stakeholders, and controlling financial activities. Eliminating primary journal books is incorrect because Final Accounts are drafted from ledger balances originating from journals.'),
        ('acc11-09-mcq-0007', 9, 'Final Accounts are important for tax compliance because they help provide a clear break-up of amounts payable to the government for:', 'Customs penalties only', 'Proprietor''s personal residential property taxes', 'Foreign trade tariffs on domestic production', 'Various taxes like Income Tax and GST', 'd', 1, 3, 'Look under Section 9.1(C) for specific examples of statutory taxes mentioned.', 'Section 9.1(C) states that Final Accounts help obtain a clear break-up of amounts payable to the government as various taxes, such as Income Tax and GST.'),
        ('acc11-09-mcq-0008', 9, 'Which chronological sequence correctly depicts the accounting process ending in Final Accounts?', 'Business Transactions -> Trial Balance -> Ledger Posting -> Journal Entries -> Final Accounts', 'Journal Entries -> Business Transactions -> Balancing the ledger -> Trial Balance -> Final Accounts', 'Trial Balance -> Balancing the ledger -> Ledger Posting -> Business Transactions -> Final Accounts', 'Business Transactions -> Journal Entries -> Ledger Posting -> Balancing the ledger -> Trial Balance -> Final Accounts', 'd', 2, 5, 'Trace the step-by-step workflow chart shown on page 273.', 'Page 273 illustrates the accounting process as: Business Transactions -> Journal Entries -> Ledger Posting -> Balancing the ledger -> Trial Balance -> Final Accounts at the end of every year.'),
        ('acc11-09-mcq-0009', 9, 'According to the syllabus note in Chapter 9, which components are specifically included in Final Accounts for XI Commerce?', 'Manufacturing Account and Profit & Loss Appropriation Account only', 'Trading Account and Manufacturing Account only', 'Trading Account, Profit and Loss Account, and Balance Sheet', 'Cash Flow Statement and Profit & Loss Appropriation Account', 'c', 1, 3, 'Check the syllabus note explicitly mentioning what is included and excluded for XI Commerce.', 'A syllabus note on page 273 explains that Manufacturing Account and Profit & Loss Appropriation Account are not included in the XI Commerce syllabus; Final Accounts consist only of Trading Account, Profit and Loss Account, and Balance Sheet.'),
        ('acc11-09-mcq-0010', 9, 'Trading Account is classified under which type of account?', 'Real Account', 'Personal Account', 'Nominal Account', 'Representative Personal Account', 'c', 1, 3, 'It deals with revenues, expenses, purchases, and direct costs.', 'Page 273 explicitly states: ''Trading Account is a Nominal Account.'' It records expenses and losses on the debit side and revenues/goods movements on the credit side.'),
        ('acc11-09-mcq-0011', 9, 'Which of the following items is credited to the Trading Account?', 'Goods distributed as free sample', 'Freight and Carriage Inward', 'Custom Duty', 'Motive Power and Fuel', 'a', 2, 5, 'Think of items representing outward movements or deductions of goods from business stock.', 'Outward movements of goods such as sales, goods distributed as free samples, goods withdrawn by proprietor for personal use, and closing stock are credited to the Trading Account.'),
        ('acc11-09-mcq-0012', 9, 'In trading terminology, unsold goods at the beginning of an accounting year are called:', 'Closing Stock', 'Reserve Stock', 'Dead Stock', 'Opening Stock', 'd', 1, 3, 'This refers to the unsold goods carried forward from the preceding period.', 'Under important terms of Trading Account (page 274), goods that are unsold are called Stock, and unsold goods at the beginning of the year are specifically referred to as Opening Stock.'),
        ('acc11-09-mcq-0013', 9, 'Closing Stock is always valued in the Final Accounts at:', 'Market price only', 'Cost price only', 'Cost or market price, whichever is more', 'Cost or market price, whichever is less', 'd', 1, 3, 'This is rooted in the accounting convention of conservatism/prudence.', 'Section 9.2 states that closing stock is always valued at cost or market price, whichever is less (conservatism principle).'),
        ('acc11-09-mcq-0014', 9, 'If closing stock is valued at Cost Price ₹46,000 and Market Price ₹40,000, what amount will appear in the Trading Account and Balance Sheet?', '₹46,000', '₹40,000', '₹86,000', '₹43,000', 'b', 2, 5, 'Apply the rule: cost price or market price, whichever is less.', 'Closing stock is valued at cost or market price, whichever is less. Between ₹46,000 and ₹40,000, the lower figure is ₹40,000 (as illustrated in Illustration 3).'),
        ('acc11-09-mcq-0015', 9, 'Which of the following transactions must be debited to Purchases Account and included in the Trading Account?', 'Purchase of office furniture for business use', 'Purchase of plant and machinery on credit', 'Purchase of merchandise/goods meant for resale', 'Purchase of government debentures as an investment', 'c', 2, 5, 'Purchases in Trading Account includes only goods, not capital assets.', 'Page 274 states: ''Purchases: This includes the purchases of goods and not purchases of assets.'' Fixed asset acquisitions are capitalized to their respective asset accounts.'),
        ('acc11-09-mcq-0016', 9, 'Return Outwards is another accounting name for:', 'Sales Returns', 'Purchase Returns', 'Goods returned by customers', 'Drawings of goods by proprietor', 'b', 1, 3, 'These are goods sent out back to suppliers.', 'Purchase Returns are also called Return Outwards. They are deducted from total purchases to record net purchases on the debit side of the Trading Account.'),
        ('acc11-09-mcq-0017', 9, 'How are Return Inwards treated in the preparation of the Trading Account?', 'Added to Purchases on the debit side', 'Shown as an asset in the Balance Sheet', 'Deducted from gross Sales on the credit side', 'Debited to Profit and Loss Account as an indirect loss', 'c', 2, 5, 'Return Inward represents goods coming back in from buyers.', 'Return Inwards (Sales Returns) are deducted from gross sales on the credit side of the Trading Account to determine net sales.'),
        ('acc11-09-mcq-0018', 9, 'Direct expenses in final accounts are defined as expenses incurred for:', 'Office management and executive staff salaries', 'Selling and advertising goods across regional markets', 'Purchase of goods, production of goods, and purchase expenses', 'Financing bank loans and servicing interest', 'c', 1, 3, 'Think of expenses directly tied to manufacturing or bringing goods to the trading location.', 'Direct expenses are defined in Section 9.2 as expenses incurred for the purchase of goods, production of goods, and purchase expenses (e.g., wages, freight inward, coal, gas, dock dues).'),
        ('acc11-09-mcq-0019', 9, 'Carriage Inward and Carriage Outward are treated respectively in:', 'Debit of Profit and Loss Account and Debit of Trading Account', 'Credit of Trading Account and Debit of Balance Sheet', 'Both debited to Trading Account', 'Debit of Trading Account and Debit of Profit and Loss Account', 'd', 2, 5, 'Inward carriage relates to buying goods, while outward carriage relates to delivering goods sold.', 'Carriage Inward is a direct expense incurred on bringing goods purchased to the business premises (debited to Trading A/c). Carriage Outward is a selling and distribution expense (debited to Profit and Loss A/c).'),
        ('acc11-09-mcq-0020', 9, 'When an item appears as ''Wages & Salaries'' in the Trial Balance, where should it be debited?', 'Profit & Loss Account', 'Trading Account', 'Balance Sheet under Assets', 'Directly deducted from Capital', 'b', 2, 5, 'The first named term dictates the primary nature of the composite expense.', 'When ''Wages'' appears first (i.e., ''Wages & Salaries''), it is treated as a productive/direct factory expense and debited to the Trading Account. If ''Salaries & Wages'' appears, it is debited to the Profit & Loss Account.'),
        ('acc11-09-mcq-0021', 9, 'In practical final accounts, Productive Wages and Unproductive Wages are debited respectively to:', 'Profit and Loss Account and Trading Account', 'Trading Account and Profit and Loss Account', 'Both to Trading Account', 'Both to Profit and Loss Account', 'b', 2, 5, 'Productive wages are linked to factory production, while unproductive wages relate to general/administrative operations.', 'As seen in practical problem 6, Productive Wages are directly tied to manufacturing and debited to Trading A/c, whereas Unproductive Wages are indirect operational costs debited to Profit & Loss A/c.'),
        ('acc11-09-mcq-0022', 9, 'What is the correct journal entry to close Opening Stock, Purchases, and Direct Expenses to the Trading Account?', 'Opening Stock A/c Dr., Purchases A/c Dr., Direct Expenses A/c Dr. To Trading A/c', 'Profit & Loss A/c Dr. To Trading A/c', 'Trading A/c Dr. To Opening Stock A/c, To Purchases A/c, To Direct Expenses A/c', 'Trading A/c Dr. To Capital A/c', 'c', 2, 5, 'Trading Account is debited to close debit balances of direct expense and stock accounts.', 'Section 9.2 gives the closing entry: Trading A/c Dr. To Opening Stock A/c, To Direct Expenses A/c, To Purchases A/c.'),
        ('acc11-09-mcq-0023', 9, 'Which journal entry is passed to transfer Sales to the Trading Account at the end of the year?', 'Trading A/c Dr. To Sales A/c', 'Sales A/c Dr. To Profit & Loss A/c', 'Sales A/c Dr. To Trading A/c', 'Sales A/c Dr. To Sundry Debtors A/c', 'c', 2, 5, 'Sales Account has a credit balance, so it is debited to close and transfer it.', 'To transfer the credit balance of Sales Account to Trading Account, the entry is: Sales A/c Dr. To Trading A/c.'),
        ('acc11-09-mcq-0024', 9, 'When the Trading Account reveals a Gross Profit, which closing entry is passed?', 'Trading A/c Dr. To Profit & Loss A/c', 'Profit & Loss A/c Dr. To Trading A/c', 'Capital A/c Dr. To Trading A/c', 'Trading A/c Dr. To Capital A/c', 'a', 2, 5, 'Gross profit is transferred from the debit side of Trading A/c to the credit of Profit & Loss A/c.', 'Gross Profit represents a credit excess in Trading A/c. To transfer it to P&L A/c, Trading A/c is debited and Profit & Loss A/c is credited: Trading A/c Dr. To Profit & Loss A/c.'),
        ('acc11-09-mcq-0025', 9, 'Given: Opening Stock ₹5,000, Purchases ₹15,500, Purchases Returns ₹500, Carriage Inward ₹1,200, Sales ₹30,000, Closing Stock ₹18,000. What is the Gross Profit?', '₹25,800', '₹27,800', '₹26,800', '₹28,800', 'c', 2, 5, 'Calculate Credit side total (Sales + Closing Stock) and subtract Debit side total (Opening Stock + Net Purchases + Carriage Inward).', 'Credit side = Sales (₹30,000) + Closing Stock (₹18,000) = ₹48,000. Debit side = Opening Stock (₹5,000) + Net Purchases (₹15,500 - ₹500 = ₹15,000) + Carriage Inward (₹1,200) = ₹21,200. Gross Profit = ₹48,000 - ₹21,200 = ₹26,800.'),
        ('acc11-09-mcq-0026', 9, 'What type of account is the Profit and Loss Account, and what does it ascertain?', 'Personal Account; ascertains proprietor''s personal net worth', 'Real Account; ascertains the market value of tangible assets', 'Valuation Account; ascertains accumulated depreciation', 'Nominal Account; ascertains Net Profit or Net Loss', 'd', 1, 3, 'It records indirect expenses/losses and revenues/gains.', 'Page 276 states: ''Profit and Loss Account is a Nominal Account'' maintained to ascertain Net Profit or Net Loss, providing the final working results of the business.'),
        ('acc11-09-mcq-0027', 9, 'Which group consists exclusively of expenses debited to the Profit and Loss Account?', 'Wages, Freight Inward, Royalties, Custom Duty', 'Opening Stock, Purchases, Motive Power, Factory Lighting', 'Bills Payable, Creditors, Bank Loan, Capital', 'Salaries, Audit Fees, Advertisement, Printing & Stationery', 'd', 2, 5, 'Look for office, administrative, and selling expenses rather than factory costs or liabilities.', 'Salaries, audit fees, advertisement, and printing & stationery are indirect administrative and selling expenses debited to Profit and Loss Account. The items in A and C are direct expenses debited to Trading Account.'),
        ('acc11-09-mcq-0028', 9, 'When the credit side of the Profit and Loss Account exceeds its debit side, the resulting balance is:', 'Gross Profit', 'Net Loss', 'Net Profit', 'Gross Loss', 'c', 1, 3, 'Credit side reflects indirect revenues/gains, while debit side reflects indirect expenses/losses.', 'When total credit (incomes) exceeds total debit (expenses) in the Profit and Loss Account, the excess is Net Profit. An excess of debit over credit is Net Loss.'),
        ('acc11-09-mcq-0029', 9, 'Which journal entry is passed to transfer Net Profit to the proprietor''s Capital Account?', 'Capital A/c Dr. To Profit & Loss A/c', 'Profit & Loss A/c Dr. To Capital A/c', 'Trading A/c Dr. To Capital A/c', 'Profit & Loss A/c Dr. To Drawings A/c', 'b', 2, 5, 'Net Profit increases the proprietor''s capital, meaning Capital Account must be credited.', 'Net Profit is transferred by debiting Profit & Loss Account and crediting Capital Account: Profit & Loss A/c Dr. To Capital A/c.'),
        ('acc11-09-mcq-0030', 9, 'What is the journal entry for transferring a Net Loss to the Capital Account?', 'Profit & Loss A/c Dr. To Capital A/c', 'Net Loss A/c Dr. To Trading A/c', 'Balance Sheet A/c Dr. To Capital A/c', 'Capital A/c Dr. To Profit & Loss A/c', 'd', 2, 5, 'Net Loss reduces capital, so the Capital Account must be debited.', 'A net loss reduces proprietor''s equity. The transfer entry is: Capital A/c Dr. To Profit & Loss A/c.'),
        ('acc11-09-mcq-0031', 9, 'Why does a Balance Sheet NOT have ''To'' or ''By'' written against its items?', 'Because it is an informal estimation of assets', 'Because it is a statement of financial position and not a ledger account', 'Because it records only cash transactions', 'Because it only contains credit balances of personal accounts', 'b', 2, 5, 'Note the distinction between an account and a statement.', 'Section 9.4 explains that the Balance Sheet has no debit or credit side because it is a statement and not an account. Hence, words like ''To'' and ''By'' are not used.'),
        ('acc11-09-mcq-0032', 9, 'Which category of accounts NEVER appears in the Balance Sheet?', 'Nominal Accounts', 'Real Accounts', 'Personal Accounts', 'Tangible Asset Accounts', 'a', 1, 3, 'These accounts represent revenues and expenses and are already closed into Trading and P&L Accounts.', 'Page 280 explicitly notes: ''No Nominal Account will appear in the Balance Sheet.'' All nominal accounts are closed to Trading A/c or Profit & Loss A/c. Only Personal and Real accounts appear in the Balance Sheet.'),
        ('acc11-09-mcq-0033', 9, 'In a Balance Sheet, debit balances and credit balances are recorded respectively on the:', 'Liability side (left) and Asset side (right)', 'Asset side (right) and Liability side (left)', 'Debit side (left) and Credit side (right)', 'Asset side (left) and Liability side (right)', 'b', 2, 5, 'Personal/real debit balances are assets (right hand side), credit balances are liabilities (left hand side).', 'Debit balances of Personal and Real accounts appear on the Asset side (right-hand side), while credit balances of Personal accounts appear on the Liability side (left-hand side).'),
        ('acc11-09-mcq-0034', 9, 'What is the primary difference in treatment between an item given in the Trial Balance and an item given in the Adjustments?', 'Trial Balance items have at least two effects, while adjustments have only one effect', 'Trial Balance items have only one effect, while every adjustment has at least two effects', 'Trial Balance items are debited to Balance Sheet, while adjustments are credited to Trading A/c', 'Both Trial Balance items and adjustments must always have three effects', 'b', 1, 3, 'Recall the True/False section and general rule regarding double-entry bookkeeping for unrecorded information.', 'Every item in the Trial Balance has already completed its double entry and receives only one effect in Final Accounts, whereas every adjustment represents an unrecorded item requiring at least two effects.'),
        ('acc11-09-mcq-0035', 9, 'Depreciation is defined in Chapter 9 as:', 'Sudden accidental destruction of goods by fire or natural calamity', 'Failure of credit debtors to pay their overdue accounts', 'Gradual and continuous decrease or reduction in the value of fixed assets', 'A cash allowance granted to customers for prompt settlement', 'c', 1, 3, 'Review the definition under Section 9.5, item 2.', 'Section 9.5 defines depreciation as: ''gradual and continuous decrease or reduction in the value of assets. This amount of depreciation is charged on fixed assets.'''),
        ('acc11-09-mcq-0036', 9, 'What are the two accounting effects of depreciation provided on fixed assets in Final Accounts?', 'Debited to Trading Account and added to Asset in Balance Sheet', 'Debited to Profit & Loss Account and deducted from respective Asset in Balance Sheet', 'Credited to Profit & Loss Account and added to Liabilities in Balance Sheet', 'Debited to Capital Account and credited to Trading Account', 'b', 2, 5, 'Depreciation is a non-cash business loss that lowers the book value of the asset.', 'Depreciation is debited to the Profit & Loss Account (as an indirect operating loss/expense) and deducted from the respective asset on the Asset side of the Balance Sheet.'),
        ('acc11-09-mcq-0037', 9, 'Machinery of ₹35,500 is purchased on 1st July 2018, and ₹4,500 is spent on its installation on the same day. What is the depreciation at 7% p.a. for the accounting year ending 31st March 2019 (9 months)?', '₹2,100', '₹2,800', '₹2,485', '₹1,864', 'a', 3, 10, 'Add installation expenses to the purchase cost to get total capital cost, then calculate 7% for 9/12 of the year.', 'Total machinery cost = ₹35,500 + ₹4,500 = ₹40,000. For 9 months (1st July 2018 to 31st March 2019): Depreciation = ₹40,000 * (7/100) * (9/12) = ₹2,800 * 0.75 = ₹2,100.'),
        ('acc11-09-mcq-0038', 9, 'Plant & Machinery balance is ₹1,80,000, which includes ₹40,000 for new machinery purchased on 1st October. If depreciation is 10% p.a. and year ends on 31st March, total depreciation is:', '₹16,000', '₹18,000', '₹14,000', '₹20,000', 'a', 3, 10, 'Depreciate the old machinery (₹1,40,000) for full 12 months and new machinery (₹40,000) for 6 months.', 'Old machinery = ₹1,80,000 - ₹40,000 = ₹1,40,000; 10% for full year = ₹14,000. New machinery = ₹40,000; 10% for 6 months = ₹2,000. Total depreciation = ₹14,000 + ₹2,000 = ₹16,000 (Illustration 9).'),
        ('acc11-09-mcq-0039', 9, 'Expenses incurred during the current accounting year but not yet paid are known as:', 'Prepaid Expenses', 'Accrued Incomes', 'Outstanding Expenses', 'Deferred Revenue Incomes', 'c', 1, 3, 'They represent unpaid obligations for benefits already consumed.', 'Section 9.5 defines Outstanding expenses as: ''The expenses which have been incurred but not paid during the year are unpaid expenses.'''),
        ('acc11-09-mcq-0040', 9, 'What are the two accounting effects of Outstanding Expenses given in adjustments?', 'Deducted from the respective expense in Trading/P&L Account and shown on the Asset side', 'Credited to Trading Account and debited to Capital Account', 'Debited to Balance Sheet and credited to Cash Account', 'Added to the respective expense in Trading/P&L Account and shown on the Liability side of the Balance Sheet', 'd', 2, 5, 'They increase the current year''s expense and represent a pending obligation.', 'Outstanding expenses are added to the particular expense on the Trading or Profit & Loss Account and shown on the Liability side of the Balance Sheet as a current liability.'),
        ('acc11-09-mcq-0041', 9, 'Expenses paid during the current year in advance for the subsequent period are termed:', 'Prepaid (Unexpired) Expenses', 'Outstanding Expenses', 'Accrued Income', 'Capital Expenditure', 'a', 1, 3, 'These are expenses whose economic benefit extends beyond the balance sheet date.', 'Under Section 9.5, expenses paid in advance of the current year are defined as Prepaid expenses or Unexpired expenses.'),
        ('acc11-09-mcq-0042', 9, 'How are Prepaid Expenses treated in Final Accounts?', 'Added to respective expense in Trading/P&L A/c and shown on Liability side', 'Credited to P&L A/c and deducted from Capital', 'Deducted from respective expense in Trading/P&L A/c and shown on Asset side of Balance Sheet', 'Debited to Trading A/c and credited to Cash A/c', 'c', 2, 5, 'They reduce current year expenses and represent future service/benefits owned.', 'Prepaid expenses are deducted from the respective expense on the debit side of the Trading or Profit & Loss Account and shown on the Asset side of the Balance Sheet.'),
        ('acc11-09-mcq-0043', 9, 'An annual insurance premium of ₹8,000 is paid on 1st December 2018. For the accounting year ending 31st March 2019, how much insurance is prepaid?', '₹2,667', '₹5,333', '₹4,000', '₹3,000', 'b', 3, 10, 'The policy runs for 12 months up to 30th November 2019. Determine how many months fall after 31st March 2019.', 'The premium covers 12 months (1st Dec 2018 to 30th Nov 2019). The current year uses 4 months (Dec to March = ₹8,000 * 4/12 = ₹2,667). The prepaid portion is for the remaining 8 months: ₹8,000 * 8/12 = ₹5,333.'),
        ('acc11-09-mcq-0044', 9, 'Income earned during the accounting year but not yet received by the year-end is classified as:', 'Pre-received Income', 'Accrued Income (Outstanding Income)', 'Unearned Revenue', 'Contingent Asset', 'b', 1, 3, 'The earning process is complete, but cash settlement remains pending.', 'Section 9.5 defines Accrued Income (or Outstanding Income) as income that has been earned during the accounting year but not yet received.'),
        ('acc11-09-mcq-0045', 9, 'What are the two effects of Accrued Income in Final Accounts?', 'Deducted from income in P&L A/c and shown on Liability side', 'Added to sales in Trading A/c and added to Debtors', 'Added to particular income on credit side of P&L A/c and shown on Asset side of Balance Sheet', 'Debited to P&L A/c and deducted from Capital', 'c', 2, 5, 'It represents earned revenue for the year and an asset receivable.', 'Accrued income is added to the respective income on the credit side of Profit & Loss Account and shown on the Asset side of the Balance Sheet.'),
        ('acc11-09-mcq-0046', 9, 'How is income received in advance (relating to the next accounting period) treated in Final Accounts?', 'Deducted from particular income on credit side of P&L A/c and shown on Liability side of Balance Sheet', 'Added to income in P&L A/c and shown on Asset side', 'Debited to Trading A/c and shown on Asset side', 'Credited to Trading A/c and deducted from Creditors', 'a', 2, 5, 'It does not belong to the current year''s earnings and creates an obligation/liability.', 'Income received in advance is deducted from the respective income on the credit side of Profit & Loss Account and shown as a liability on the Liability side of the Balance Sheet.'),
        ('acc11-09-mcq-0047', 9, 'In accounting, debts that are irrecoverable from customers are called:', 'Bad Debts', 'Doubtful Debts', 'Trade Discounts', 'Cash Discounts', 'a', 1, 3, 'Recovery of this amount is completely ruled out.', 'Page 281 states: ''The Debts which are irrecoverable is called Bad-debts. The amount of Bad debts is loss to business.'''),
        ('acc11-09-mcq-0048', 9, 'What journal entry is passed when Bad Debts are written off from debtors?', 'Sundry Debtors A/c Dr. To Bad Debts A/c', 'Profit & Loss A/c Dr. To Cash A/c', 'Bad Debts A/c Dr. To Capital A/c', 'Bad Debts A/c Dr. To Sundry Debtors A/c', 'd', 2, 5, 'Bad Debts is a loss (debited) and reduces debtors (credited).', 'When bad debts are written off, the entry is: Bad Debts A/c Dr. To Sundry Debtors A/c. Subsequently, Bad Debts is transferred to Profit & Loss A/c.'),
        ('acc11-09-mcq-0049', 9, 'Why is a Reserve for Doubtful Debts (R.D.D.) created in final accounts?', 'To record debts that are already settled and received in cash', 'To provide for anticipated loss on debtors whose recovery is doubtful based on past experience', 'To offer prompt cash settlement bonuses to suppliers', 'To comply with mandatory company dividend reserve regulations', 'b', 2, 5, 'It addresses potential, expected non-realization rather than established bad debts.', 'Section 9.5 states that recovery of some debtors is doubtful. Based on previous years'' experience, a provision is created for this anticipated loss, known as Reserve for Doubtful Debts.'),
        ('acc11-09-mcq-0050', 9, 'According to the chapter notes, R.D.D. appearing in the Trial Balance is referred to as:', 'New R.D.D.', 'Contingent Reserve', 'General Reserve', 'Old R.D.D. (Existing R.D.D.)', 'd', 1, 3, 'Check Note 2 under Section 9.5 on page 282.', 'Note 2 on page 282 explicitly states: ''When R.D.D. is given in Trial Balance, it is known as old R.D.D. [Existing R.D.D.]. When R.D.D. is given in adjustment, it is called New R.D.D.'''),
        ('acc11-09-mcq-0051', 9, 'When New Bad Debts, New R.D.D., and Provision for Discount on Debtors are all given in adjustments, in what order must they be computed?', 'Discount on Debtors first, then R.D.D., then Bad Debts', 'New R.D.D. first, then Bad Debts, then Discount on Debtors', 'All three calculated simultaneously on gross Sundry Debtors', 'New Bad Debts first, then New R.D.D. on the remaining balance, then Provision for Discount on Debtors on the net balance', 'd', 3, 10, 'You must deduct actual uncollectible amounts first, provide for doubtful debts second, and discount only good debtors.', 'Page 282 notes that Provision for Discount on Debtors is calculated after deducting New Bad Debts and New R.D.D. First deduct New Bad Debts from Sundry Debtors, compute New R.D.D. on the balance, and finally compute discount on the remaining good balance.'),
        ('acc11-09-mcq-0052', 9, 'Sundry Debtors in Trial Balance is ₹20,250. Adjustments specify: Write off ₹1,000 as bad debts, provide 2% R.D.D. on debtors, and provide 3% discount on creditors (Creditors = ₹18,500). What is the New R.D.D. amount?', '₹405', '₹385', '₹370', '₹555', 'b', 3, 10, 'Deduct bad debts (₹1,000) from Debtors (₹20,250) before applying the 2% rate.', 'Debtors after bad debts = ₹20,250 - ₹1,000 = ₹19,250. New R.D.D. = 2% of ₹19,250 = ₹385 (Working Note, Illustration 4). ₹555 is discount on creditors.'),
        ('acc11-09-mcq-0053', 9, 'Which adjustment is specifically identified in Chapter 9 as the ''only exception to the convention of conservatism''?', 'Reserve for Doubtful Debts', 'Provision for Discount on Creditors', 'Depreciation on fixed assets', 'Valuing closing stock at cost or market price whichever is less', 'b', 2, 5, 'This provision anticipates a prospective gain/profit from suppliers before it is actually realized.', 'Page 282 explicitly states: ''Provision/Reserve for Discount on Creditors: ...discount received from creditors is treated as Profit or gain. So it is to be credited to Profit & Loss A/c and to be deducted from creditors from Balance Sheet. It is the only exception to the convention of conservatism.'''),
        ('acc11-09-mcq-0054', 9, 'What are the two accounting effects of creating a Provision for Discount on Creditors?', 'Debited to P&L A/c and added to Creditors in Balance Sheet', 'Credited to Trading Account and deducted from Debtors', 'Credited to Profit & Loss Account and deducted from Sundry Creditors in Balance Sheet', 'Debited to Capital Account and added to Bills Payable', 'c', 2, 5, 'It is treated as an expected gain and reduces the payable amount.', 'Section 9.5 (Adjustment 10) provides that Provision for Discount on Creditors is credited to the Profit & Loss Account and deducted from Sundry Creditors on the Liabilities side of the Balance Sheet.'),
        ('acc11-09-mcq-0055', 9, 'If Old R.D.D. in Trial Balance is ₹2,500, New Bad Debts is ₹0, Old Bad Debts is ₹600, and New R.D.D. is ₹1,500, where and how is the excess ₹400 shown?', 'Debited to Profit & Loss Account', 'Deducted from Capital on the Liability side', 'Credited to Profit & Loss Account as a gain', 'Added to Sundry Debtors in the Balance Sheet', 'c', 3, 10, 'When existing provision exceeds required provision plus bad debts, the surplus is a gain.', 'As demonstrated in Illustration 12 Working Note: Old R.D.D. (₹2,500) > [New R.D.D. (₹1,500) + Bad Debts (₹600) = ₹2,100]. The excess provision of ₹400 is credited to Profit and Loss Account as a gain.'),
        ('acc11-09-mcq-0056', 9, 'What are the two accounting effects when goods are withdrawn by the proprietor for personal use?', 'Debited to Trading A/c and credited to Cash A/c', 'Debited to P&L A/c and added to Debtors in Balance Sheet', 'Credited to Trading A/c (or deducted from purchases) and deducted from Capital on the Liability side', 'Credited to Sales A/c and added to Capital on the Liability side', 'c', 2, 5, 'Goods leave the business without generating sales, and proprietor''s investment decreases.', 'Goods withdrawn for personal use reduce the cost of trading inventory (credited to Trading A/c or deducted from Purchases) and are treated as drawings (deducted from Capital on the Liability side).'),
        ('acc11-09-mcq-0057', 9, 'Distribution of goods as a free sample is an advertisement. What are its two accounting effects?', 'Debited to Trading A/c and added to Debtors in Balance Sheet', 'Credited to Trading A/c (or deducted from purchases) and debited to Profit & Loss Account under Advertisement', 'Credited to Profit & Loss Account and deducted from Creditors', 'Debited to Capital Account and credited to Sales A/c', 'a', 2, 5, 'It reduces goods available for sale and represents an advertising expense.', 'Section 9.5 (Adjustment 12) explains that goods given as free samples reduce merchandise stock (credited to Trading A/c or deducted from purchases) and are debited to Profit & Loss Account as Advertisement expense.'),
        ('acc11-09-mcq-0058', 9, 'Interest allowed on Capital is treated in Final Accounts as:', 'Credited to Profit & Loss Account and deducted from Capital', 'Debited to Trading Account and added to Cash at Bank', 'Debited to Capital and credited to Drawings', 'Debited to Profit & Loss Account and added to Capital in Balance Sheet', 'd', 2, 5, 'From the business''s viewpoint, it is an expense paid to the owner, increasing the owner''s total capital claim.', 'Interest on capital is an expense to the business concern (debited to Profit & Loss Account) and an addition to the proprietor''s investment (added to Capital on the Liability side of the Balance Sheet).'),
        ('acc11-09-mcq-0059', 9, 'What are the two effects of Interest on Drawings in Final Accounts?', 'Credited to Profit & Loss Account and deducted from Capital (or added to Drawings)', 'Debited to P&L A/c and added to Capital', 'Debited to Trading A/c and added to Cash in hand', 'Credited to Balance Sheet and debited to Bank Loan', 'a', 2, 5, 'Interest charged on drawings is an income for the business and reduces the owner''s equity.', 'Section 9.5 (Adjustment 14) states that Interest on Drawings is credited to the Profit & Loss Account (as an indirect income/gain) and deducted from Capital (or added to Drawings) on the Liability side of the Balance Sheet.'),
        ('acc11-09-mcq-0060', 9, 'When the specific date of drawings is not mentioned in the Trial Balance or adjustment, interest on drawings is charged for:', 'The full twelve months', 'Three months only', 'An average period of six months', 'Nine months', 'c', 1, 3, 'Recall Question 3(10) of the Chapter Exercises and the note in Illustration 8.', 'The chapter note in Illustration 8 and Exercise Q.3(10) explicitly state: ''When specific date is not given, in that case interest on drawing is charged for 6 months.'''),
        ('acc11-09-mcq-0061', 9, 'Drawings given in Trial Balance is ₹2,500. Rate of interest on drawings is 7% p.a. No date of withdrawal is mentioned. What is the amount of interest on drawings?', '₹175', '₹88', '₹120', '₹105', 'b', 3, 10, 'Calculate 7% on ₹2,500 and then take half (6 months).', 'Annual interest = ₹2,500 * (7/100) = ₹175. Since no date is given, interest is charged for 6 months: ₹175 / 2 = ₹87.50, rounded to ₹88 (as shown in Illustration 8).'),
        ('acc11-09-mcq-0062', 9, 'Given: Building ₹20,000, Furniture ₹15,000, Debtors ₹30,000, Investments ₹10,000, Cash at Bank ₹5,000, Plant & Machinery ₹20,000; Bills Payable ₹18,000, Creditors ₹20,700, Outstanding Wages ₹1,250. What is Capital?', '₹1,00,000', '₹39,950', '₹42,000', '₹60,050', 'd', 3, 10, 'Total Assets minus Total External Liabilities equals Capital.', 'Total Assets = 20,000 + 15,000 + 30,000 + 10,000 + 5,000 + 20,000 = ₹1,00,000. Total Liabilities = 18,000 + 20,700 + 1,250 = ₹39,950. Capital = Assets - Liabilities = ₹1,00,000 - ₹39,950 = ₹60,050.'),
        ('acc11-09-mcq-0063', 9, 'A 6% Bank Loan of ₹50,000 was taken on 1st October 2017. If the accounting year ends on 31st March 2018 and no interest appears in the Trial Balance, what is the outstanding interest on loan?', '₹3,000', '₹750', '₹2,000', '₹1,500', 'd', 3, 10, 'Apply 6% p.a. for the 6 months elapsed between October 1 and March 31.', 'Loan was borrowed on 1st October 2017, so interest is chargeable for 6 months (Oct to March). Interest = ₹50,000 * 6% * (6/12) = ₹1,500 (Illustration 6 Working Note).'),
        ('acc11-09-mcq-0064', 9, 'In a Trial Balance for the year ending 31st March, Salaries appears as ''₹5,000 (for 10 months)''. What is the outstanding salary to be added in Profit & Loss A/c and shown in Balance Sheet?', '₹500', '₹1,200', '₹2,000', '₹1,000', 'd', 2, 5, 'Determine monthly salary by dividing ₹5,000 by 10, then find the amount for the remaining 2 months.', 'Monthly salary = ₹5,000 / 10 = ₹500 per month. Outstanding period = 12 - 10 = 2 months. Outstanding amount = 2 * ₹500 = ₹1,000 (Illustration 4 Working Note).'),
        ('acc11-09-mcq-0065', 9, 'How is Goodwill classified in the Balance Sheet?', 'Current Liability', 'Fictitious Asset', 'Nominal Loss', 'Intangible Fixed Asset (not a fictitious asset)', 'd', 1, 3, 'Check the True/False question discussing whether goodwill is a fictitious asset.', 'Exercise Q.4(4) confirms that ''Goodwill is not a fictitious asset.'' It is an intangible real asset shown on the Asset side of the Balance Sheet.'),
        ('acc11-09-mcq-0066', 9, 'Bank Overdraft is classified and shown in the Balance Sheet as a/an:', 'Current / External Liability', 'Internal Liability to the proprietor', 'Current Asset', 'Contingent Asset', 'a', 1, 3, 'It is an amount owed to the bank, repayable on demand.', 'Bank Overdraft is a short-term external loan payable to the bank and is shown under Liabilities in the Balance Sheet. Disagreeing with ''Bank Overdraft is an internal liability'' is confirmed in Exercise Q.7(4).'),
        ('acc11-09-mcq-0067', 9, 'Bills Receivable and Bills Payable appear respectively in the Balance Sheet under:', 'Liabilities and Assets', 'Both under Assets', 'Assets and Liabilities', 'Both under Liabilities', 'c', 1, 3, 'Receivables represent claims owned; payables represent claims owed.', 'Bills Receivable is an asset (debt claim due to the business), whereas Bills Payable is a liability (debt owed by the business).'),
        ('acc11-09-mcq-0068', 9, 'An advance given to workers appearing as an adjustment (e.g., ''Wages include ₹800 advance to workers'') is treated as:', 'Deducted from Wages in Trading A/c and shown as an Asset in Balance Sheet', 'Added to Wages in Trading A/c and shown on Liability side', 'Debited to P&L A/c and credited to Cash', 'Credited to Sales A/c and added to Debtors', 'a', 2, 5, 'Advances are pre-payments, not current expenses, and represent amounts recoverable or adjustable against future work.', 'Advance to workers is prepaid labor cost: it is deducted from Wages in Trading Account and shown on the Asset side of the Balance Sheet (Illustration 11).'),
        ('acc11-09-mcq-0069', 9, 'In Final Accounts, Factory Rent and Office Rent are recorded respectively in:', 'Trading Account and Profit & Loss Account', 'Profit & Loss Account and Trading Account', 'Both in Profit & Loss Account', 'Both in Trading Account', 'a', 2, 5, 'Factory expenses relate to manufacturing goods, while office expenses relate to administrative operations.', 'Factory Rent is a direct manufacturing expense debited to Trading Account, whereas Office Rent is an administrative indirect expense debited to Profit & Loss Account.'),
        ('acc11-09-mcq-0070', 9, 'In a Trial Balance containing Trade Expenses, Salaries, and Office Expenses, Trade Expenses should be:', 'Debited to Profit & Loss Account', 'Credited to Trading Account', 'Deducted from Sales', 'Capitalized to Machinery', 'a', 2, 5, 'In the specimen and textbook illustrations (e.g., Illustration 10 and Practical Problem 6), Trade Expenses is treated as an indirect expense.', 'In Chapter 9 illustrations and practical problems (such as Illustration 10 and Practical Problem 6), Trade Expenses is classified as an indirect operating expense and debited to the Profit & Loss Account.'),
        ('acc11-09-mcq-0071', 9, 'Motive Power, Fuel, Gas, and Water are recorded in:', 'Credit side of Profit and Loss Account', 'Debit side of Trading Account', 'Asset side of Balance Sheet', 'Debit side of Profit and Loss Account', 'b', 1, 3, 'These are direct factory operating utilities required to run machinery.', 'Motive power, coal, gas, fuel, and water are direct manufacturing expenses debited to the Trading Account (Section 9.2 specimen and Illustration 1).'),
        ('acc11-09-mcq-0072', 9, 'Royalties paid on production/goods are debited to:', 'Profit & Loss Account', 'Trading Account', 'Balance Sheet under Intangible Assets', 'Drawings Account', 'b', 1, 3, 'Royalties are direct expenses incurred in the acquisition or production of goods.', 'Section 9.2 specimen and Illustration 1 clearly show Royalties debited to the Trading Account as a direct production cost.'),
        ('acc11-09-mcq-0073', 9, 'Discount received from creditors on prompt payment is an indirect income and is transferred to:', 'Credit side of Trading Account', 'Credit side of Profit & Loss Account', 'Debit side of Profit & Loss Account', 'Liability side of Balance Sheet as an addition to creditors', 'b', 1, 3, 'Incomes and gains are credited to the Profit and Loss Account.', 'Exercise Q.3(2) and Section 9.3 state: ''Discount earned is transferred to credit side of Profit & Loss account'' as an indirect revenue/gain.'),
        ('acc11-09-mcq-0074', 9, 'Trial Balance shows Salaries ₹18,000 with note: ''2/3rd for factory''. What amount of salaries will be debited to Trading Account and Profit & Loss Account respectively?', '₹12,000 to Trading Account and ₹6,000 to Profit & Loss Account', '₹18,000 to Trading Account and ₹0 to P&L Account', '₹6,000 to Trading Account and ₹12,000 to Profit & Loss Account', '₹9,000 to Trading Account and ₹9,000 to Profit & Loss Account', 'a', 3, 10, 'Factory portion (2/3) goes to Trading Account as direct expense, and remaining 1/3 goes to P&L Account as indirect expense.', 'Factory salaries = 2/3 of ₹18,000 = ₹12,000 (debited to Trading A/c). The remaining office portion = 1/3 of ₹18,000 = ₹6,000 (debited to Profit & Loss A/c), as seen in Practical Problem 4.'),
        ('acc11-09-mcq-0075', 9, 'When an item ''Loss by fire ₹1,650'' appears directly as a debit balance in the Trial Balance, how is it treated?', 'Debited to Profit & Loss Account only', 'Debited to Trading Account only', 'Credited to Trading Account and shown as Asset in Balance Sheet', 'Deducted from Capital and credited to Purchases', 'a', 2, 5, 'Items inside the Trial Balance have only one effect.', 'Since ''Loss by fire'' is already inside the Trial Balance (as in Illustration 8), it represents an established loss and has only ONE effect: it is debited to the Profit and Loss Account.'),
        ('acc11-10-mcq-0001', 10, 'Which of the following best describes the Single Entry System of book-keeping?', 'A modern digital ledger system replacing the dual aspect concept', 'A double entry system in an incomplete and unscientific form', 'A scientific method that strictly follows all accounting rules', 'A specialized accounting system designed exclusively for large joint-stock companies', 'b', 1, 3, 'Look at how the introductory text contrasts Single Entry with the scientific Double Entry method.', 'According to the chapter, the Single Entry System is not a particular system of accounting, but rather a Double Entry System in an incomplete and unscientific form.'),
        ('acc11-10-mcq-0002', 10, 'For which type of business organization is the Single Entry System considered most suitable?', 'Public sector undertakings and government departments', 'Large multinational corporations with thousands of daily transactions', 'Commercial banking institutions and insurance firms', 'Small size business concerns with a limited number of transactions', 'd', 1, 3, 'Consider the size and volume of transactions mentioned in the introduction and suitability section.', 'The text explicitly states that Single Entry System is suitable and useful for small size business concerns where the number of transactions is small and assets and liabilities are very few.'),
        ('acc11-10-mcq-0003', 10, 'Under the Single Entry System, which primary books and accounts are usually maintained?', 'Cash Book and personal accounts of debtors and creditors', 'Fixed asset ledgers, Investment ledgers, and Depreciation reserve accounts', 'Manufacturing account, Trading account, and Profit & Loss account', 'Only Real accounts and Nominal accounts', 'a', 1, 3, 'Recall which two types of records Kohler and the chapter emphasize as being maintained.', 'Under the Single Entry System, only the Cash Book and personal accounts of debtors and creditors are maintained. Real and Nominal accounts are ignored.'),
        ('acc11-10-mcq-0004', 10, 'Which classes of accounts are completely omitted or not maintained under the Single Entry System?', 'Cash account and bank records', 'Real and Nominal accounts', 'Personal accounts of creditors and debtors', 'Proprietor''s capital account and drawings records', 'b', 1, 3, 'Think of the three traditional classifications of accounts (Personal, Real, Nominal) and which two are neglected.', 'The chapter highlights that under Single Entry, Real accounts (assets/properties) and Nominal accounts (expenses, losses, incomes, gains) are not maintained.'),
        ('acc11-10-mcq-0005', 10, 'How did Kohler define the Single Entry System?', 'A scientific mechanism to balance debits and credits accurately across periods', 'A system of Book Keeping in which as a rule only records of cash and of personal accounts are maintained. It is always incomplete double entry varying with the circumstances.', 'An autonomous self-balancing ledger framework designed for small retail shops', 'A method that ignores the twofold aspect and fails to provide financial position', 'b', 1, 3, 'Focus on the specific definition attributed to Kohler citing ''varying with the circumstances''.', 'Kohler defined it as: ''A system of Book Keeping in which as a rule only records of cash and of personal accounts are maintained. It is always incomplete double entry varying with the circumstances.'''),
        ('acc11-10-mcq-0006', 10, 'According to Carter''s definition, what is the major deficiency of the Single Entry method?', 'It requires excessively expensive software and highly trained accountants', 'It overstates the net profit due to excessive provision for doubtful debts', 'It fails to record any cash receipts and cash payments made in the business', 'It ignores the twofold aspect and consequently fails to provide the businessman with the information necessary for him to be able to ascertain his financial position', 'd', 1, 3, 'Carter''s definition centers on the consequence of ignoring the twofold aspect.', 'Carter defined Single Entry as ''a method or variety of methods, employed for the recording of transactions, which ignores the two fold aspect and consequently fails to provide the businessman with the information necessary for him to be able to ascertain his financial position.'''),
        ('acc11-10-mcq-0007', 10, 'Single Entry System is described in the text as an unsystematic combination of which of the following?', 'Cash basis, Accrual basis, and Hybrid basis', 'Single entry, Double entry, and No Entry', 'Double entry, Triple entry, and Reverse entry', 'Direct entry, Indirect entry, and Contra entry', 'b', 1, 3, 'Some transactions have one aspect recorded, some two, and some are not recorded at all.', 'The chapter explicitly states: ''Single entry system is a combination of Single entry, Double entry and No Entry.'''),
        ('acc11-10-mcq-0008', 10, 'Which of the following is an advantage/suitability factor of the Single Entry System mentioned in the text?', 'It is officially certified and considered authentic by government authorities and tax departments', 'It automatically generates a complete Balance Sheet reflecting a true and fair view', 'It enables the exact arithmetical verification of ledger postings through a Trial Balance', 'It is less expensive because the time and labour involved is less', 'd', 1, 3, 'Identify which feature makes it economical for a sole trader with modest resources.', 'The chapter lists that Single Entry is less expensive as compared to Double Entry Book Keeping because the time and labour involved is less, and it does not require specialized skills.'),
        ('acc11-10-mcq-0009', 10, 'Why can a Trial Balance NOT be prepared under the Single Entry System?', 'Because cash transactions are never entered in any book', 'Because the Government prohibits small concerns from preparing trial balances', 'Because of incomplete accounting information and absence of dual aspect recording', 'Because debtors and creditors ledger balances cancel each other out', 'c', 2, 5, 'A trial balance requires every debit to have a matching credit.', 'Under the Single Entry System, each transaction is not recorded with dual aspect, and Real and Nominal accounts are omitted. Because of this incomplete information, a Trial Balance cannot be prepared, and arithmetical accuracy cannot be verified.'),
        ('acc11-10-mcq-0010', 10, 'How do government authorities view the authenticity of accounts maintained under the Single Entry System compared to Double Entry?', 'The Government authorities do not consider this system as authentic, whereas Double Entry is considered authentic', 'They treat both systems as having identical legal authenticity and standing', 'They consider Single Entry as fully authentic and legally binding', 'They consider Single Entry superior for tax assessments of large corporations', 'a', 1, 3, 'Review point 8 (''Authenticity'') in the comparative table between Single Entry and Double Entry.', 'Under the differences table, point 8 explicitly states: ''The Government authorities do not consider this system as authentic'' for Single Entry, whereas Double Entry is considered authentic.'),
        ('acc11-10-mcq-0011', 10, 'What type of financial position is revealed by a Statement of Affairs compared to a Balance Sheet?', 'A strictly legal liquidation position, whereas a Balance Sheet gives a going concern position', 'An exact and audited position, whereas a Balance Sheet gives an estimated position', 'A historical cost position with zero subjective estimations', 'An estimated financial position, whereas a Balance Sheet gives a true and fair financial position', 'd', 2, 5, 'Look at the ''Financial Position'' row in the comparison table.', 'Under Single Entry, Statement of Affairs provides an ''estimated financial position'' because records are incomplete, whereas a Balance Sheet prepared under Double Entry provides a ''true and fair financial position''.'),
        ('acc11-10-mcq-0012', 10, 'What statement is prepared under the Single Entry System to ascertain the financial results (profit or loss) of the business instead of a Profit and Loss Account?', 'Income and Expenditure Summary', 'Trial Balance of Operations', 'Statement of Profit or Loss', 'Receipts and Payments Account', 'c', 1, 3, 'The chapter outlines the preparation of Statement of Affairs and this specific performance statement.', 'Under Single Entry, a Profit and Loss Account cannot be prepared due to absence of nominal accounts; instead, a ''Statement of Profit or Loss'' is prepared.'),
        ('acc11-10-mcq-0013', 10, 'What is a Statement of Affairs?', 'A report detailing the disciplinary affairs and conduct of business employees', 'A statement of Assets and Liabilities prepared under the Single Entry System', 'A statement of all cash receipts and payments during a financial year', 'A list of personal accounts of debtors only', 'b', 1, 3, 'It is described as being ''as good as a Balance Sheet''.', 'Section 10.3 defines: ''A Statement of Affairs is a statement of Assets and Liabilities. It is as good as Balance Sheet.'''),
        ('acc11-10-mcq-0014', 10, 'In the format of a Statement of Affairs, which items are recorded on the left-hand side and right-hand side, respectively?', 'Left-hand side records Liabilities; Right-hand side records Assets', 'Left-hand side records Cash receipts; Right-hand side records Cash payments', 'Left-hand side records Incomes; Right-hand side records Expenses', 'Left-hand side records Assets; Right-hand side records Liabilities', 'a', 1, 3, 'Check the layout: Liabilities are on the left, Assets on the right.', 'The chapter specifies: ''Right hand side is used for recording Assets and left hand is used recording for Liabilities.'''),
        ('acc11-10-mcq-0015', 10, 'How is Capital ascertained in a Statement of Affairs?', 'As the sum total of all cash transactions in the Cash Book', 'As the balancing figure representing the excess of total Assets over total Liabilities', 'By multiplying total debtors by the prevailing market interest rate', 'By adding drawings to total liabilities and deducting assets', 'b', 1, 3, 'Capital is derived from the difference between the two sides of the statement.', 'The chapter states: ''The difference between the total of Assets and total of Liabilities is considered as the amount of capital (Balancing figure).'''),
        ('acc11-10-mcq-0016', 10, 'What is the formula to calculate Opening Capital under the Single Entry System?', 'Opening Capital = Closing Capital + Drawings - Additional Capital', 'Opening Capital = Opening Assets + Opening Liabilities', 'Opening Capital = Opening Assets - Opening Liabilities', 'Opening Capital = Opening Liabilities - Opening Assets', 'c', 1, 3, 'Assets minus liabilities at the start of the year.', 'Section 10.3 states: ''Opening Capital = Opening Assets - Opening Liabilities''.'),
        ('acc11-10-mcq-0017', 10, 'What is the formula to determine Closing Capital at the end of the accounting year?', 'Closing Capital = Closing Liabilities - Closing Assets', 'Closing Capital = Closing Assets + Drawings', 'Closing Capital = Opening Capital + Net Profit - Net Loss', 'Closing Capital = Closing Assets - Closing Liabilities', 'd', 1, 3, 'Similar to opening capital, but using end-of-year figures.', 'Section 10.3 gives the exact formula: ''Closing Capital = Closing Assets - Closing Liabilities''.'),
        ('acc11-10-mcq-0018', 10, 'Which of the following items appears on the Liabilities side of a Statement of Affairs?', 'Prepaid Expenses', 'Plant and Machinery', 'Bills Receivable', 'Bank Overdraft', 'd', 1, 3, 'Identify the liability owed to the bank among asset items.', 'In the format of the Statement of Affairs, Bank Overdraft, Sundry Creditors, Bills Payable, Outstanding Expenses, and Bank Loan appear on the Liabilities side.'),
        ('acc11-10-mcq-0019', 10, 'Which of the following items appears on the Assets side of a Statement of Affairs?', 'Prepaid Expenses', 'Bank Loan', 'Bills Payable', 'Outstanding Expenses', 'a', 1, 3, 'Expenses paid in advance represent future economic benefits to the business.', 'In the Statement of Affairs format, Prepaid Expenses is listed on the Assets side, whereas Outstanding Expenses, Bank Loan, and Bills Payable are liabilities.'),
        ('acc11-10-mcq-0020', 10, 'What are the two recognized methods of calculating profit or loss when books are maintained under Single Entry, as noted in the text?', 'Direct Method and Indirect Method', 'Net Worth Method and Conversion Method', 'Cash Flow Method and Fund Flow Method', 'Gross Margin Method and Net Contribution Method', 'b', 1, 3, 'One is covered in standard 11th syllabus, and the other is excluded from standard 11th.', 'Section 10.4 states: ''profit made during the year is calculated by the following methods: i) Net Worth Method ii) Conversion Method''.'),
        ('acc11-10-mcq-0021', 10, 'Why is the Conversion Method not explained in detail in this textbook chapter?', 'Because it has been declared illegal by the Companies Act', 'Because it cannot determine profit or loss accurately', 'Because it applies only to foreign partnership firms', 'Because it is not included in the 11th standard syllabus', 'd', 1, 3, 'A specific note in Section 10.4 clarifies why Conversion Method is omitted.', 'Section 10.4 includes the note: ''(Note: The second method is not included the 11th standard syllabus, so it is not explained here)''.'),
        ('acc11-10-mcq-0022', 10, 'In the Net Worth Method, before accounting for adjustments, what indicates a Profit?', 'Closing Capital is less than Opening Capital', 'Drawings are greater than Closing Capital', 'Closing Capital is more than Opening Capital', 'Closing Capital is equal to Opening Capital', 'c', 1, 3, 'If wealth has increased from beginning to end of the period, what does that signify?', 'The chapter states: ''If the Closing Capital is more than the Opening Capital the difference is Profit. If the Closing Capital is less than the Opening Capital the difference is Loss.'''),
        ('acc11-10-mcq-0023', 10, 'What is the accounting definition of ''Additional Capital'' (or Further Capital)?', 'Cash or assets of any kind brought by proprietor into the business during the accounting year', 'Accumulated reserve created for doubtful debts and bad debts', 'Short-term loans borrowed from commercial banks without interest', 'Net profit earned and reinvested from the previous three financial years', 'a', 1, 3, 'It represents fresh personal resources introduced by the owner during the year.', 'Under Adjustments, point 1 states: ''During Accounting Year, amount of cash or assets of any kind brought by proprietor into the business is called Additional Capital or Further Capital.'''),
        ('acc11-10-mcq-0024', 10, 'How is Additional Capital treated in the Statement of Profit or Loss?', 'It is divided equally between cash in hand and sundry debtors', 'It is ignored completely in profit calculation', 'It is added to Closing Capital', 'It is deducted from Closing Capital', 'd', 1, 3, 'Fresh capital introduced artificially inflates closing capital and must be subtracted to find true profit.', 'The textbook states: ''Additional Capital is deducted from the Closing Capital in the Statement of Profit or Loss'' to arrive at Adjusted Closing Capital.'),
        ('acc11-10-mcq-0025', 10, 'Why are Drawings added back to Closing Capital in the Statement of Profit or Loss?', 'Because drawings are a liability owed to sundry creditors', 'Because drawings represent an operational income generated by sales', 'Because drawings reduced closing capital for personal use, so adding them back restores the true trading surplus generated', 'Because the Government mandates tax on personal withdrawals', 'c', 2, 5, 'Think about why withdrawals for personal use made the ending capital smaller than it otherwise would have been.', 'Proprietor''s withdrawals reduce the closing capital. To determine what capital would have been from business operations alone, drawings made during the year (in cash or kind) are added back to Closing Capital.'),
        ('acc11-10-mcq-0026', 10, 'In what forms can Drawings be made by a proprietor as presented in the format of Statement of Profit or Loss?', 'Only in physical inventory', 'Only in government securities', 'Only in bank cheques', 'In Cash and In Kind', 'd', 1, 3, 'Check the sub-items under ''Add: Drawings made during the year'' in the statement format.', 'The Statement of Profit or Loss format explicitly specifies adding Drawings ''In Cash'' and ''In Kind'' (goods taken for personal/household use).'),
        ('acc11-10-mcq-0027', 10, 'How is Depreciation on fixed assets treated in the Statement of Profit or Loss?', 'It is ignored because Single Entry only deals with cash', 'It is added to Additional Capital', 'It is deducted as an expense and loss', 'It is added as an income and gain', 'c', 1, 3, 'Depreciation represents loss in value of fixed assets through wear and tear.', 'Under Adjustments: ''The amount of depreciation is a charge against Profit or Loss and is to be deducted'' in the Statement of Profit or Loss under Expenses and Losses.'),
        ('acc11-10-mcq-0028', 10, 'What are Bad Debts and how are they treated in the Statement of Profit or Loss?', 'Loans taken from banks; added in Statement of Profit or Loss', 'Unclaimed dividends; added to adjusted closing capital', 'Debts not recovered from a debtor; deducted in Statement of Profit or Loss', 'Discounts allowed by creditors; deducted from opening capital', 'c', 1, 3, 'Uncollectible receivables constitute a loss to the business.', 'The text states: ''The debts which are not recovered from a debtor is called Bad Debts. Hence it should be deducted in the statement of Profit or Loss.'''),
        ('acc11-10-mcq-0029', 10, 'Where does Reserve for Doubtful Debts (R.D.D.) appear in the Statement of Profit or Loss?', 'As a deduction from Drawings', 'Under Expenses and Losses (to be deducted)', 'Under Incomes and Gains (to be added)', 'As an addition to Opening Capital', 'b', 1, 3, 'Providing for doubtful debts reduces the distributable profit.', 'Reserve for bad and doubtful debts (R.D.D.) represents an anticipated loss/expense and is deducted under ''Less: Expenses and Losses during the accounting year''.'),
        ('acc11-10-mcq-0030', 10, 'If an asset is undervalued in the books of accounts, what is the required adjustment in the Statement of Profit or Loss?', 'It should be deducted from profit because it reduces current capital', 'It should be added in the Statement of Profit or Loss because undervaluation means capital was shown lower than actual', 'It should be divided equally between drawings and loans', 'No adjustment is required as historical cost is unchanged', 'b', 2, 5, 'Undervaluation means the asset was recorded too low; increasing it adds to profit/capital.', 'Section 10.5(6)(A) explains: ''Undervaluation means lower capital which required to be adjusted and it is added in Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0031', 10, 'If an asset is overvalued in the books of accounts, how must it be adjusted in the Statement of Profit or Loss?', 'Added directly to Opening Capital', 'Added to profit because overvalued assets imply greater wealth', 'Subtracted from Sundry Creditors balance', 'Deducted in the Statement of Profit or Loss because overvaluation means capital was overstated', 'd', 2, 5, 'Correcting an overstatement requires reducing the profit.', 'Section 10.5(6)(B) states: ''Overvaluation means higher capital which requires to be adjusted it is deducted in Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0032', 10, 'What is the formula given in the chapter to calculate the Actual Value of an asset when it is overvalued?', 'Actual Value = Book Value / (100 - % of overvaluation) * 100', 'Actual Value = Book Value - (% of overvaluation * Book Value)', 'Actual Value = [Book Value / (100 + % of Overvaluation)] * 100', 'Actual Value = Book Value * (100 + % of overvaluation) / 100', 'c', 2, 5, 'Check the Working Notes of Problem 6 or Problem 10 for stock valuation.', 'The working note in Problem 6 & 10 explicitly provides the formula: Actual Value = [Book Value / (100 + % of Overvaluation)] * 100.'),
        ('acc11-10-mcq-0033', 10, 'What is the formula given in the chapter to find the Actual Value of a liability when it is undervalued?', 'Actual Value = [Book Value / (100 - % of undervaluation)] * 100', 'Actual Value = [Book Value / (100 + % of undervaluation)] * 100', 'Actual Value = Book Value * (1 - % of undervaluation)', 'Actual Value = Book Value + (% of undervaluation / 100)', 'a', 2, 5, 'Check Working Note 2 of Problem 10 for creditors undervaluation.', 'Problem 10 Working Note 2 gives: Actual Value = [Book Value / (100 - % of undervaluation)] * 100.'),
        ('acc11-10-mcq-0034', 10, 'How is Undervaluation of Liabilities treated in the Statement of Profit or Loss?', 'Deducted in the Statement of Profit or Loss because actual liabilities are higher than recorded', 'Ignored until creditors demand repayment', 'Added to profit because liabilities are smaller', 'Added to Additional Capital', 'a', 2, 5, 'If liabilities were understated, bringing them to true higher values causes an additional loss.', 'Section 10.5(6)(C) states: ''Undervaluation means liabilities are recorded at lesser amount which is to be adjusted. It is deducted from Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0035', 10, 'How is Overvaluation of Liabilities treated in the Statement of Profit or Loss?', 'Added in the Statement of Profit or Loss because the true liability is lower than recorded', 'Credited directly to drawings account', 'Deducted from profit as an unexpired loss', 'Subtracted from Cash at Bank', 'a', 2, 5, 'Overvaluing liabilities means you recorded greater obligations than you actually have; fixing it brings a gain.', 'Section 10.5(6)(D) states: ''Overvaluation means the liabilities are recorded at higher amount which to be adjusted it is to be added in the Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0036', 10, 'How is Interest on Loan treated in the Statement of Profit or Loss, and why?', 'Deducted, because interest on loan is an expenditure to the business', 'Deducted from drawings because the owner pays it directly', 'Added to opening capital as owner equity', 'Added, because loan interest is an asset belonging to the firm', 'a', 1, 3, 'The chapter classifies interest on loan as a business expenditure.', 'Section 10.5(7) states: ''Interest on loan is the expenditure to the business, hence it is to be deducted in Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0037', 10, 'On which capital balances is Interest on Capital calculated?', 'On Opening Capital and also the amount of Additional Capital, which is utilized by the business', 'Only on Closing Capital at the year end', 'Only on Drawings made during the first quarter', 'On the difference between debtors and creditors', 'a', 2, 5, 'Consider what capital the business had at the beginning versus fresh capital brought in mid-year.', 'Section 10.5(8) states: ''Interest on Capital is to be calculated on Opening Capital and also the amount of Additional Capital, which is utilized by the business.'''),
        ('acc11-10-mcq-0038', 10, 'How is Interest on Capital treated in the Statement of Profit or Loss?', 'Added under Incomes and Gains', 'Added to Opening Capital in the Statement of Affairs', 'Deducted under Expenses and Losses', 'Subtracted from Cash in Hand', 'c', 1, 3, 'From the perspective of the business entity, paying interest on capital is an expenditure.', 'Section 10.5(8) states: ''Interest on capital is expenditure to the business. Hence it is to be deducted from the Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0039', 10, 'How is Interest on Drawings treated in the Statement of Profit or Loss?', 'Added as an income to the business', 'Deducted as an operational expenditure', 'Deducted from Additional Capital', 'Subtracted from Closing Capital before drawings', 'a', 1, 3, 'The proprietor pays interest to the business on personal withdrawals, representing income to the business.', 'Section 10.5(9) states: ''It is the income to the business; hence to be added in the Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0040', 10, 'What rule applies when calculating Interest on Drawings if the rate of interest is given but the specific date of drawings is NOT mentioned?', 'Interest is calculated for one month only', 'No interest on drawings can be charged', 'Interest on drawings is to be calculated for six months', 'Interest is charged for the full 12 months', 'c', 1, 3, 'An average period convention is applied.', 'Section 10.5(9) explicitly states: ''If the date of drawings is not given and rate of interest is given, then interest on drawings is to be calculated for six months.'''),
        ('acc11-10-mcq-0041', 10, 'How are Outstanding (unpaid) Expenses treated in the Statement of Profit or Loss?', 'Deducted from Drawings', 'Deducted under Expenses and Losses', 'Added under Incomes and Gains', 'Added to Closing Capital', 'b', 1, 3, 'Outstanding expenses represent expenses incurred but not yet settled in cash.', 'Section 10.5(10) states: ''The expenses due but not paid during the year are known as Outstanding Expenses. It is to be deducted in Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0042', 10, 'How are Prepaid Expenses (Unexpired Expenses) treated in the Statement of Profit or Loss?', 'Deducted from Opening Capital', 'Added in the Statement of Profit or Loss', 'Deducted under Expenses and Losses', 'Added to Sundry Creditors', 'b', 1, 3, 'They relate to the subsequent period and their advance payment must be credited back to current profits.', 'Section 10.5(11) states: ''Such expenses are not related with current year; hence it is added in Statement of Profit or Loss.'''),
        ('acc11-10-mcq-0043', 10, 'When proprietor sells personal household property (such as furniture) and deposits the proceeds into the business bank account, how is it treated?', 'As a short-term sundry creditor liability', 'As Additional Capital introduced during the year', 'As an extraordinary operating revenue from trading', 'As business drawings', 'b', 2, 5, 'Private assets converted to business funds constitute fresh capital.', 'As demonstrated in Problems 8 and Problem 5, selling household/private assets and utilizing the proceeds in business constitutes Additional Capital introduced during the year.'),
        ('acc11-10-mcq-0044', 10, 'If a proprietor withdraws funds from the business account to pay for their daughter''s marriage or personal flat rent, how are these transactions classified?', 'Additional capital introduced into the firm', 'Trade expenses deductible in Statement of Profit or Loss', 'Capital expenditures to be capitalized as Building', 'Drawings to be added to Closing Capital', 'd', 2, 5, 'Personal family expenditures drawn from business are classified under this specific term.', 'In Problems 4, 10, and Practical Problem 2, funds withdrawn for domestic rent or family marriage are personal expenses, hence classified as Drawings.'),
        ('acc11-10-mcq-0045', 10, 'What is the sequential procedure to compute Reserve for Discount on Debtors when Bad Debts and R.D.D. are also present?', 'Deduct Bad Debts first, calculate and deduct R.D.D., and compute Reserve for Discount on the remaining balance', 'Calculate Reserve for Discount directly on total Debtors before deducting bad debts', 'Deduct Reserve for Discount first, and then calculate Bad Debts and R.D.D.', 'Add R.D.D. to Debtors and compute discount on the inflated amount', 'a', 3, 10, 'Review Problem 7: Debtors (35,000) - Bad debts (1,000) = 34,000; RDD @ 5% = 1,700; then 2% on (34,000 - 1,700).', 'Problem 7 shows that Bad Debts are deducted first from Debtors (35,000 - 1,000 = 34,000), R.D.D. is calculated on that net balance (5% on 34,000 = 1,700), and Reserve for Discount on Debtors is calculated on the remainder (2% on 32,300 = 646).'),
        ('acc11-10-mcq-0046', 10, 'In Problem 5 (Shubham), which alternative method was used to incorporate adjustments for depreciation?', 'Depreciation was added to Opening Capital in the Opening Statement of Affairs', 'Depreciation was completely ignored in profit calculation', 'A formal double-entry Depreciation Account was opened in the general ledger', 'Depreciation was shown and deducted in the Closing Statement of Affairs directly', 'd', 2, 5, 'Check the note at the end of Problem 5 regarding the alternative presentation.', 'Problem 5 presents an alternative method wherein depreciation adjustments (Equipment 5%, Furniture 10%) are deducted directly in the Closing Statement of Affairs to determine closing capital, rather than listing them separately in the Statement of Profit or Loss.'),
        ('acc11-10-mcq-0047', 10, 'What is the effect of Income Received in Advance in the Statement of Profit or Loss?', 'It is ignored as it represents cash already received', 'It is deducted under Expenses and Losses during the accounting year', 'It is added to Opening Capital', 'It is added under Incomes and Gains', 'b', 2, 5, 'Check the list under ''Less: Expenses and Losses during the accounting year'' in the master format.', 'Under the master format of Statement of Profit or Loss (page 340), item 8 under ''Less: Expenses and Losses during the accounting year'' lists ''Income received in advance'' because it does not pertain to current year income.'),
        ('acc11-10-mcq-0048', 10, 'Opening Capital is ₹90,000, Closing Capital is ₹1,50,000, Drawings made during the year are ₹15,000, and Additional Capital introduced is ₹10,000. What is the Net Profit for the year?', '₹65,000', '₹75,000', '₹55,000', '₹45,000', 'a', 2, 5, 'Apply the core formula: (Closing Capital + Drawings - Additional Capital) - Opening Capital.', 'Closing Capital (1,50,000) + Drawings (15,000) = 1,65,000. Deduct Additional Capital (10,000) = Adjusted Closing Capital of 1,55,000. Deduct Opening Capital (90,000) = Net Profit of ₹65,000 (Example on page 337).'),
        ('acc11-10-mcq-0049', 10, 'Capital as on 31.03.2017 was ₹80,000; Capital as on 31.03.2018 was ₹1,00,000; Drawings were ₹3,000; Additional Capital was ₹8,000. What was the Net Profit for the year ended 31st March 2018?', '₹19,000', '₹25,000', '₹15,000', '₹11,000', 'c', 2, 5, 'Problem 1 from text: 1,00,000 + 3,000 - 8,000 - 80,000.', 'Closing Capital (1,00,000) + Drawings (3,000) - Additional Capital (8,000) = Adjusted Closing Capital (95,000). Less Opening Capital (80,000) = Net Profit of ₹15,000.'),
        ('acc11-10-mcq-0050', 10, 'Given Opening Capital ₹62,000, Drawings ₹5,000, Additional Capital ₹9,000, and Closing Capital ₹50,000, what is the trading result for the year?', 'Net Loss of ₹16,000', 'Net Loss of ₹7,000', 'Net Profit of ₹2,000', 'Net Profit of ₹16,000', 'a', 2, 5, 'Problem 2 from text: Closing Capital + Drawings - Additional Capital gives an Adjusted Closing Capital lower than Opening Capital.', 'Closing Capital (50,000) + Drawings (5,000) = 55,000. Less Additional Capital (9,000) = 46,000. Less Opening Capital (62,000) = Net Loss of ₹16,000.'),
        ('acc11-10-mcq-0051', 10, 'In Problem 3 (Arjun), the proprietor withdrew ₹2,500 every month for private purposes. What was the total amount of drawings to be added in the Statement of Profit or Loss?', '₹15,000', '₹30,000', '₹2,500', '₹25,000', 'b', 2, 5, 'Multiply the monthly withdrawal amount by the 12 months of the financial year.', 'Problem 3 solution calculates: Drawings during the year = ₹2,500 * 12 months = ₹30,000.'),
        ('acc11-10-mcq-0052', 10, 'Opening Capital on 31.03.2017 was ₹1,50,000. Additional Capital introduced on 01.10.2017 was ₹40,000. At 10% p.a., what is the total interest on capital for the year ending 31.03.2018?', '₹15,000', '₹16,000', '₹17,000', '₹19,000', 'c', 2, 5, 'Calculate full year''s interest on opening capital, and 6 months'' interest on additional capital.', 'Interest on Opening Capital = 10% on 1,50,000 = ₹15,000. Interest on Additional Capital = 10% on 40,000 for 6 months = ₹2,000. Total Interest = 15,000 + 2,000 = ₹17,000 (Example on page 338).'),
        ('acc11-10-mcq-0053', 10, 'In Problem 6 (Jyoti), Closing Stock is reported at ₹90,000, which is overvalued by 20% in the books. What is the actual value of stock and the resulting loss to be deducted?', 'Actual Value ₹75,000; Loss to be deducted ₹15,000', 'Actual Value ₹70,000; Loss to be deducted ₹20,000', 'Actual Value ₹1,08,000; Gain to be added ₹18,000', 'Actual Value ₹72,000; Loss to be deducted ₹18,000', 'a', 3, 10, 'Actual Value = 90,000 / (100 + 20) * 100.', 'Actual Value = (90,000 / 120) * 100 = ₹75,000. Overvaluation = ₹90,000 - ₹75,000 = ₹15,000. This is a loss deducted in the Statement of Profit or Loss.'),
        ('acc11-10-mcq-0054', 10, 'In Problem 10 (Mr. Raj), Creditors are shown in the books at ₹60,000 and are undervalued by 20%. What is their actual value and the adjustment amount?', 'Actual Value ₹72,000; Adjustment ₹12,000', 'Actual Value ₹48,000; Adjustment of ₹12,000 to be added', 'Actual Value ₹50,000; Adjustment of ₹10,000 to be added', 'Actual Value ₹75,000; Adjustment of ₹15,000 to be deducted', 'd', 3, 10, 'Actual Value = [60,000 / (100 - 20)] * 100. Undervaluation of a liability increases the liability, which is a loss.', 'Actual Value = (60,000 / 80) * 100 = ₹75,000. The creditors are higher by ₹15,000 (75,000 - 60,000). This undervaluation of liabilities is deducted as an expense/loss in the Statement of Profit or Loss.'),
        ('acc11-10-mcq-0055', 10, 'In Exercise Q.3 (8), Opening Capital is ₹30,000, Closing Capital is ₹60,000, Withdrawals are ₹5,000, and Further Capital brought in is ₹3,000. What is the Profit?', '₹22,000', '₹45,000', '₹32,000', '₹35,000', 'c', 2, 5, 'Profit = Closing Capital + Withdrawals - Further Capital - Opening Capital.', 'Closing Capital (60,000) + Drawings (5,000) = 65,000. Less Further Capital (3,000) = 62,000. Less Opening Capital (30,000) = ₹32,000.'),
        ('acc11-10-mcq-0056', 10, 'In Exercise Q.8 (5), given Cash in Hand ₹10,000, Cash at Bank ₹5,000, Sundry Debtors ₹8,000, and Bills Payable ₹4,000, what is the Capital balance?', '₹27,000', '₹15,000', '₹19,000', '₹23,000', 'c', 2, 5, 'Capital = Total Assets - Total Liabilities.', 'Total Assets = Cash in Hand (10,000) + Cash at Bank (5,000) + Sundry Debtors (8,000) = 23,000. Total Liabilities = Bills Payable (4,000). Capital = 23,000 - 4,000 = ₹19,000.'),
        ('acc11-10-mcq-0057', 10, 'In Exercise Q.8 (4), if Drawings are ₹15,000, Opening Capital is ₹20,000, and Profit is ₹20,000, what is the Closing Capital (assuming no additional capital)?', '₹40,000', '₹25,000', '₹55,000', '₹35,000', 'b', 3, 10, 'Adjusted Closing Capital = Opening Capital + Profit = 40,000. Closing Capital = Adjusted Closing Capital - Drawings.', 'Profit = Adjusted Closing Capital - Opening Capital => 20,000 = Adjusted Closing Capital - 20,000 => Adjusted Closing Capital = 40,000. Since Adjusted Closing Capital = Closing Capital + Drawings (15,000), Closing Capital = 40,000 - 15,000 = ₹25,000.'),
        ('acc11-10-mcq-0058', 10, 'In Exercise Q.7 (''Find the odd one''), why is ''Outstanding Expenses'' the odd one in the group: Interest on Drawings, Outstanding Expenses, Undervaluation of Assets, Prepaid Expenses?', 'Because Outstanding Expenses is deducted under expenses/losses, while the other three are added to profit in the Statement of Profit or Loss', 'Because Outstanding Expenses is only paid to banks', 'Because Outstanding Expenses is shown on the asset side of Statement of Affairs', 'Because Outstanding Expenses is a real account', 'a', 2, 5, 'Consider which items are added versus deducted in the Statement of Profit or Loss.', 'In the Statement of Profit or Loss, Interest on Drawings, Undervaluation of Assets, and Prepaid Expenses are items added to profit, whereas Outstanding Expenses is deducted as an expense/loss.'),
        ('acc11-10-mcq-0059', 10, 'In Exercise Q.7 (''Find the odd one''), why is ''Overvaluation of Liabilities'' the odd one in: Interest on Capital, Interest on Loan, Overvaluation of Liabilities, Depreciation on Assets?', 'Because it relates only to company liquidation', 'Because it is recorded in the Cash Book', 'Because Overvaluation of Liabilities is added under incomes/gains, whereas the other three are expenses/losses deducted from profit', 'Because it is an asset account', 'c', 2, 5, 'Look at the master format for additions versus deductions.', 'Overvaluation of liabilities represents a reduction in liability and is added to profit, while Interest on Capital, Interest on Loan, and Depreciation on Assets are expenses deducted in the Statement of Profit or Loss.'),
        ('acc11-10-mcq-0060', 10, 'In Exercise Q.7 (''Find the odd one''), why is ''Stock in Trade'' the odd one in: Creditors, Bills Payable, Bank Overdraft, Stock in Trade?', 'Because Stock in Trade cannot be depreciated', 'Because Stock in Trade is a personal account', 'Because Stock in Trade appears on the debit side of the Cash Book', 'Because Stock in Trade is an Asset, while Creditors, Bills Payable, and Bank Overdraft are Liabilities', 'd', 1, 3, 'Three are obligations owed to outsiders; one is goods/property owned.', 'Stock in Trade is an asset appearing on the right-hand side of the Statement of Affairs, whereas Creditors, Bills Payable, and Bank Overdraft are liabilities appearing on the left-hand side.')
    ) AS v (question_code, chapter_no, prompt, option_a, option_b, option_c, option_d, correct_option, difficulty, points, hint, explanation)
    JOIN chapters c ON c.chapter_no = v.chapter_no
    JOIN subjects sub ON sub.id = c.subject_id AND sub.code = 'accounts'
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.chapter_id, t.prompt, t.option_a, t.option_b, t.option_c, t.option_d, t.correct_option, t.difficulty, t.points, t.hint, t.explanation) IS DISTINCT FROM (s.chapter_id, s.prompt, s.option_a, s.option_b, s.option_c, s.option_d, s.correct_option, s.difficulty, s.points, s.hint, s.explanation) THEN
    UPDATE SET chapter_id = s.chapter_id, prompt = s.prompt, option_a = s.option_a, option_b = s.option_b, option_c = s.option_c, option_d = s.option_d, correct_option = s.correct_option, difficulty = s.difficulty, points = s.points, hint = s.hint, explanation = s.explanation
WHEN NOT MATCHED THEN
    INSERT (question_code, chapter_id, prompt, option_a, option_b, option_c, option_d, correct_option, difficulty, points, hint, explanation) VALUES (s.question_code, s.chapter_id, s.prompt, s.option_a, s.option_b, s.option_c, s.option_d, s.correct_option, s.difficulty, s.points, s.hint, s.explanation)
WHEN NOT MATCHED BY SOURCE AND t.chapter_id IN (SELECT c.id FROM chapters c JOIN subjects sub ON sub.id = c.subject_id WHERE sub.code = 'accounts') THEN
    DELETE;
